const M={te:{vi:"Thing Explainer — Randall Munroe",en:"Thing Explainer — Randall Munroe"},tp:{vi:"Thinking Physics — Lewis Epstein",en:"Thinking Physics — Lewis Epstein"},tl:{vi:"Thinking, Fast and Slow — Daniel Kahneman",en:"Thinking, Fast and Slow — Daniel Kahneman"},gv:{vi:"The Invisible Gorilla — Chabris & Simons",en:"The Invisible Gorilla — Chabris & Simons"},dw:{vi:"Mindset — Carol Dweck",en:"Mindset — Carol Dweck"}},n=(h,e,a,s,i,o,u,c)=>({id:h,bac:e,nguon:a,dung:u,canh:{vi:s[0],en:s[1]},cau:{vi:i[0],en:i[1]},dap:o.map(([m,d])=>({vi:m,en:d})),vi:{vi:c[0],en:c[1]}}),t=(h,e,a,s)=>({id:h,hoi:s.map((i,o)=>({h:i,i:o})).sort((i,o)=>i.h.bac-o.h.bac||i.i-o.i).map(i=>i.h),title:{vi:e[0],en:e[1]},hint:{vi:a[0],en:a[1]}}),V=h=>h.trim().split(/\s+/).filter(Boolean).length,y=[t("roi-xuong",["Rơi Xuống","Falling Down"],["Cái gì quyết định một vật rơi nhanh hay chậm","What decides how fast a thing falls"],[n("roi-ong-hut",1,"tp",["Một ống thuỷ tinh dài đã hút sạch không khí bên trong. Trong ống có một viên bi sắt và một cái lông chim. Lật ngược ống lên, cả hai cùng rơi.","A long glass tube with every bit of air pumped out. Inside sit an iron ball and a feather. Flip the tube and both start to fall."],["Cái nào chạm đáy trước?","Which reaches the bottom first?"],[["Viên bi sắt, vì nó nặng hơn","The iron ball — it is heavier"],["Cả hai cùng lúc","Both at the same moment"],["Cái lông chim, vì nó nhẹ nên bay nhanh","The feather — light things move easily"]],1,["Trái Đất kéo viên bi mạnh hơn kéo cái lông thật. Nhưng viên bi cũng ì hơn đúng bấy nhiêu lần — nặng gấp trăm thì cũng khó làm cho chuyển động gấp trăm. Hai cái lớn lên cùng nhau nên khử nhau, còn lại đúng một tốc độ rơi chung cho mọi vật. Trong không khí cái lông thua là vì không khí cản nó, không phải vì nó nhẹ.","The Earth does pull harder on the ball than on the feather. But the ball is exactly that much harder to get moving — a hundred times the weight is a hundred times the stubbornness. The two grow together and cancel, leaving one falling speed for everything. In air the feather loses to the air pushing back, not to its own lightness."]),n("dinh-cua-cu-nem",2,"tp",["Bạn ném thẳng một quả bóng lên trời. Nó lên chậm dần, rồi có đúng một khoảnh khắc nó đứng yên ở trên đỉnh trước khi rơi xuống.","You throw a ball straight up. It slows, and for one instant at the very top it hangs still before coming back down."],["Đúng khoảnh khắc đó, lực Trái Đất kéo quả bóng bằng bao nhiêu?","At that instant, how hard is the Earth pulling on the ball?"],[["Bằng không — nó đang đứng yên mà","Zero — it is not moving"],["Yếu đi, rồi mạnh dần lại lúc rơi","Weakest there, then building up as it falls"],["Vẫn mạnh y như lúc mới rời tay","Exactly as hard as the moment it left your hand"]],2,["Trái Đất không biết quả bóng đang đi lên, đi xuống hay đứng yên — nó kéo mọi thứ như nhau, lúc nào cũng vậy. Cái đổi ở đỉnh là VẬN TỐC, không phải lực. Vận tốc đi qua số không, còn lực thì không bao giờ đi qua số không. Đứng yên một khoảnh khắc mà vẫn bị kéo, đó chính là lý do khoảnh khắc ấy không kéo dài được.","The Earth does not know whether the ball is rising, falling or hanging — it pulls the same, always. What passes through zero at the top is the SPEED, never the pull. That is exactly why the instant of stillness cannot last: something is still pulling."]),n("gap-bon-lan-cao",2,"tp",["Thả một hòn đá từ độ cao một mét, nó chạm đất với một tốc độ nào đó. Bây giờ thả hòn đá y hệt từ độ cao bốn mét.","Drop a stone from one metre and it lands at some speed. Now drop the same stone from four metres."],["Lần này nó chạm đất nhanh gấp mấy?","How much faster does it land this time?"],[["Gấp bốn — cao gấp bốn thì nhanh gấp bốn","Four times — four times the height"],["Gấp đôi","Twice"],["Gấp tám","Eight times"]],1,["Rơi gấp bốn quãng đường thì tốc độ chỉ gấp đôi, vì trong lúc rơi vật mỗi lúc một nhanh: nửa sau của đường rơi đi qua rất nhanh nên không tốn thêm bao nhiêu thời gian. Muốn chạm đất nhanh gấp ba thì phải leo lên cao gấp chín. Đây là lý do một cú ngã từ tầng hai không nguy hiểm gấp đôi cú ngã từ tầng một — nó nguy hiểm hơn thế nhiều.","Four times the drop gives only twice the landing speed, because a falling thing keeps speeding up: the second half of the fall goes by fast and costs little extra time. To land three times as fast you must climb nine times as high. This is why falling from the second floor is not twice as bad as the first — it is worse than that."]),n("dan-ban-ngang",3,"tp",["Trên một bãi phẳng, đúng một lúc: một khẩu súng bắn viên đạn đi ngang, và một viên đạn y hệt được thả rơi từ đúng nòng súng đó.","On flat ground, at the same instant: a gun fires a bullet horizontally, and an identical bullet is simply dropped from the muzzle."],["Viên nào chạm đất trước?","Which bullet reaches the ground first?"],[["Viên thả rơi — nó đi thẳng xuống, đường ngắn hơn nhiều","The dropped one — it takes the short way straight down"],["Viên bắn ra — nó đang đi rất nhanh","The fired one — it is moving so much faster"],["Cả hai chạm đất cùng lúc","Both land at the same moment"]],2,["Trái Đất chỉ kéo XUỐNG. Nó không hề quan tâm viên đạn đang đi ngang nhanh cỡ nào, vì đi ngang không phải việc của nó. Nên hai viên tụt xuống hệt nhau từng khoảnh khắc một — viên bắn ra chỉ tình cờ tụt xuống ở một chỗ cách đây tám trăm mét. Tách một chuyển động thành phần ngang và phần dọc rồi xét riêng từng phần: đó là mẹo mạnh nhất trong cả môn này.","The Earth pulls DOWN only. It takes no interest in how fast the bullet is going sideways, because sideways is not its business. So the two bullets sink identically, moment by moment — the fired one just happens to do its sinking eight hundred metres away. Splitting a motion into its sideways part and its downward part and treating them separately is the strongest trick in the whole subject."]),n("roi-trong-khong-khi",3,"tp",["Bây giờ bỏ cái ống đi. Đứng ngoài trời thật, cầm một viên bi sắt và một cái lông chim, buông cả hai cùng lúc.","Now throw the tube away. Standing outdoors in real air, hold an iron ball and a feather and let go of both together."],["Cái nào chạm đất trước?","Which lands first?"],[["Vẫn cùng lúc — luật rơi đâu có đổi","Still together — the falling law has not changed"],["Viên bi, và bỏ xa cái lông","The ball, by a long way"],["Cái lông, vì gió nâng nó đi nhanh hơn","The feather — the air carries it along"]],1,["Luật ở câu đầu vẫn đúng nguyên: Trái Đất kéo hai vật này rơi hệt nhau. Cái xen vào là KHÔNG KHÍ, và không khí thì không cản theo cân nặng — nó cản theo bề mặt. Cái lông có bề mặt lớn mà lại rất nhẹ, nên chỉ một chút cản cũng đủ giữ nó lại; viên bi bề mặt nhỏ mà nặng, nên chừng ấy cản chẳng là gì. Một luật đúng vẫn có thể cho kết quả sai, khi có thứ khác chen vào giữa — và việc của người nghĩ là chỉ ra được thứ chen vào ấy tên là gì.","The first law still holds exactly: the Earth drops these two identically. What steps in is the AIR, and air does not resist by weight — it resists by surface. The feather is all surface and almost no weight, so a little resistance holds it; the ball is little surface and much weight, so the same resistance is nothing to it. A true law can still give a wrong prediction when something else steps in between — and naming that something is the whole job."])]),t("day-va-keo",["Đẩy & Kéo","Push & Pull"],["Lực không bao giờ đi một mình — luôn có cái đẩy lại","A force never comes alone — something always pushes back"],[n("day-thung-di-deu",1,"tp",["Bạn đẩy một thùng gỗ nặng trên sàn nhà. Thùng đi tới đều đều, không nhanh dần lên. Bạn vẫn phải đẩy suốt, buông tay ra là nó dừng.","You push a heavy crate across the floor. It slides along steadily, not speeding up. You have to keep pushing; let go and it stops."],["Vì sao phải đẩy suốt mà thùng vẫn không nhanh dần?","Why must you keep pushing if it never speeds up?"],[["Vì muốn đi thì phải có lực đẩy — hết đẩy là hết đi","Because moving needs a push — no push, no motion"],["Vì sàn nhà đẩy lại đúng bằng lực tay bạn","Because the floor pushes back exactly as hard as you push"],["Vì cái thùng quá nặng","Because the crate is simply too heavy"]],1,["Sàn nhà không nằm im chịu trận — nó cào lại. Bạn đẩy mười thì ma sát cào lại đúng mười, cộng vào bằng không, nên thùng đi ĐỀU. Muốn thùng nhanh dần phải đẩy mạnh hơn mười. Buông tay ra thì chỉ còn cái cào lại, nên thùng chậm dần rồi dừng. Ở ngoài vũ trụ, nơi không có gì cào lại, đẩy một cái là vật đi mãi.","The floor is not passive — it scrapes back. Push with ten and friction scrapes with ten; they add to nothing, so the crate moves STEADILY. To speed it up you must beat the ten. Let go and only the scraping is left, so it slows and stops. Out in space, where nothing scrapes, one push lasts forever."]),n("keo-co-voi-tuong",2,"tp",["Một sợi dây có cái đồng hồ đo lực ở giữa. Bạn kéo một đầu, đầu kia buộc chặt vào tường. Bạn kéo hết sức, đồng hồ chỉ 300.","A rope with a force meter in the middle. You pull one end; the other end is tied to a wall. You pull with everything you have and the meter reads 300."],["Bây giờ tháo dây khỏi tường, đưa cho một người bạn khoẻ đúng bằng bạn cùng kéo. Đồng hồ chỉ bao nhiêu?","Now untie the wall and hand that end to a friend exactly as strong as you, pulling too. What does the meter read?"],[["600 — hai người kéo thì cộng lại","600 — two pullers add up"],["Vẫn 300","Still 300"],["150 — mỗi người chịu một nửa","150 — each takes half"]],1,["Bức tường vẫn kéo lại bạn đúng 300 suốt từ đầu — nó chỉ không nói ra thôi. Một sợi dây căng thì hai đầu bắt buộc bằng nhau, không thì đầu nào yếu hơn đã bị lôi đi rồi. Thay tường bằng người bạn là thay một thứ kéo lại 300 bằng một thứ khác cũng kéo lại 300. Đây là chỗ mà kéo co thật sự được quyết định: không phải ai kéo dây mạnh hơn, mà ai ĐẠP XUỐNG ĐẤT chắc hơn.","The wall was pulling back with 300 the whole time — it just never said so. A taut rope must have equal pulls at both ends, or the weaker end would already have been dragged along. Swapping the wall for your friend swaps one 300-puller for another. This is where a tug of war is really decided: not by who pulls the rope harder, but by who PUSHES THE GROUND better."]),n("dap-xe-xuoi-gio",2,"tp",["Gió thổi một chiều, đều đặn, đúng 15 km một giờ. Bạn đạp xe xuôi theo chiều gió, và đúng lúc này tốc độ xe của bạn cũng là 15 km một giờ.","A steady wind blows one way at exactly 15 km an hour. You cycle downwind, and right now your bicycle is doing exactly 15 km an hour too."],["Lúc đó tóc và mặt bạn cảm thấy gió thế nào?","What does the wind feel like on your face and hair?"],[["Gió vẫn đẩy sau lưng, dễ đạp hơn hẳn","Still pushing your back — pedalling feels easy"],["Hoàn toàn lặng, như không có gió","Dead calm, as if there were no wind at all"],["Gió tạt ngang qua tai","A wind sliding past sideways"]],1,["Gió chỉ tồn tại khi không khí và bạn đi khác nhau. Đi bằng đúng tốc độ gió thì bạn và không khí thành một khối cùng trôi, và trong khối ấy chẳng có gió nào cả — hệt như trong một khoang máy bay đang bay 900 km một giờ mà cốc nước vẫn đứng yên. Muốn đạp nhanh hơn 15 nữa thì từ giây đó trở đi bạn lại phải rẽ gió, và gió ngược sẽ thổi vào mặt bạn.","Wind only exists where the air and you are moving differently. Match the wind exactly and you and the air travel as one body, and inside that body there is no wind at all — just as a cup of water sits still in a cabin doing 900 km an hour. Push past 15 and from that second on you are cutting air again, and the wind is in your face."]),n("ngua-keo-xe",3,"tp",["Con ngựa kéo cái xe. Ai cũng biết cái xe kéo lại con ngựa đúng bằng ngần ấy — hai lực bằng nhau và ngược chiều.","A horse pulls a cart. Everyone agrees the cart pulls back on the horse exactly as hard — equal and opposite."],["Vậy hai lực bằng nhau ngược chiều, sao cái xe vẫn đi được?","So with equal and opposite pulls, how does the cart go anywhere?"],[["Vì con ngựa kéo mạnh hơn một chút, nên thắng","The horse pulls a bit harder and so wins"],["Hai lực ấy đặt lên HAI vật khác nhau, nên không bao giờ khử nhau","The two pulls sit on TWO different bodies, so they never cancel"],["Vì lực xe kéo lại chỉ xuất hiện sau khi xe đã đi","The cart only pulls back once it is already rolling"]],1,["Hai lực chỉ khử nhau khi cùng đặt lên MỘT vật. Ở đây lực ngựa-kéo-xe đặt lên cái xe, lực xe-kéo-ngựa đặt lên con ngựa — hai sổ sách riêng, không cộng chung được. Muốn biết cái xe có đi không thì chỉ nhìn sổ của cái xe: ngựa kéo tới, mặt đất cào lui, ngựa kéo mạnh hơn, xe đi. Còn con ngựa đi được là nhờ nó đạp lùi xuống đất và đất đẩy nó tới. Bỏ mặt đất đi — cho ngựa đứng trên băng trơn — thì cả hai đứng nguyên tại chỗ.","Two forces only cancel when they act on ONE body. Here horse-pulls-cart acts on the cart and cart-pulls-horse acts on the horse — two separate accounts that cannot be added. To ask whether the cart moves, read only the cart account: horse forward, ground scraping back, horse wins, cart rolls. The horse itself moves by shoving the ground backwards and being shoved forwards in return. Take the ground away — stand the horse on smooth ice — and nothing goes anywhere."]),n("lo-ruoi-tren-can",3,"tp",["Một cái lọ thuỷ tinh đậy kín, bên trong có mấy con ruồi, đặt trên cân. Lúc đầu ruồi đậu hết dưới đáy lọ, cân chỉ 200 gam. Rồi cả đàn ruồi bay lên lơ lửng giữa lọ.","A sealed glass jar with several flies inside, sitting on a scale. At first the flies rest on the bottom and the scale reads 200 grams. Then all of them take off and hover in the middle of the jar."],["Lúc cả đàn đang lơ lửng, cân chỉ bao nhiêu?","While they are all hovering, what does the scale read?"],[["Nhẹ hơn 200 — mấy con ruồi đâu còn tì lên đáy","Less than 200 — the flies are no longer resting on anything"],["Vẫn đúng 200","Exactly 200, still"],["Nặng hơn 200 — cánh ruồi quạt xuống thêm","More than 200 — the beating wings press down"]],1,["Con ruồi lơ lửng được là nhờ quạt không khí xuống. Muốn treo mình lại thì luồng khí nó quạt xuống phải nặng đúng bằng chính nó — không thì nó đã tụt xuống hoặc bay vọt lên. Luồng khí ấy đi xuống, đập vào đáy lọ, và đè lên cân đúng bằng cân nặng của con ruồi. Trong một cái lọ ĐẬY KÍN thì không có gì thoát ra ngoài được, nên cân không thể nào đổi số. Nếu mở nắp lọ ra, một phần luồng khí ấy thoát ra ngoài và cân sẽ nhẹ đi thật.","A hovering fly holds itself up by pushing air down. To hang still, the air it drives down must weigh exactly what the fly weighs — otherwise it would sink or climb. That air goes down, hits the bottom of the jar, and presses on the scale with exactly the fly’s weight. In a SEALED jar nothing gets out, so the reading cannot change. Open the lid and some of that downwash escapes, and then the scale really does drop."])]),t("da-va-suc",["Đà & Sức","Momentum & Energy"],["Cùng một cú va, đổi thời gian thì đổi cả lực","One collision — stretch the time and you change the force"],[n("nem-va-xi-mang",1,"tp",["Nhảy từ trên tường xuống. Rơi xuống tấm nệm dày thì không sao; rơi xuống nền xi măng, cùng độ cao đó, thì gãy chân.","Jump down off a wall. Land on a thick mattress and you are fine; land on concrete from the very same height and you break something."],["Cả hai lần bạn rơi cùng độ cao, chạm đất cùng tốc độ. Cái gì khác nhau?","Both times you fall the same height and hit at the same speed. So what is different?"],[["Nệm mềm nên hút bớt tốc độ trước khi bạn chạm đáy","The mattress soaks up some of your speed before you reach the bottom"],["Nệm kéo dài thời gian dừng lại, nên lực nhỏ đi","The mattress stretches out the stopping, so the force is smaller"],["Nền xi măng đẩy ngược lên bạn, còn nệm thì không","Concrete pushes back up at you and a mattress does not"]],1,["Hai lần đều phải dừng từ cùng một tốc độ về không, nên cùng phải bỏ đi đúng ngần ấy đà. Cái đổi là bỏ trong bao lâu. Xi măng làm việc đó trong một phần nghìn giây, nệm làm trong hai phần mười giây — dài gấp hai trăm lần, nên lực chỉ còn một phần hai trăm. Túi khí ô tô, mũ bảo hiểm, giày chạy bộ, thùng các-tông chèn đồ dễ vỡ: tất cả chỉ làm đúng một việc, là kéo dài cái khoảnh khắc dừng ra.","Both times you must go from that speed to nothing, so both times the same momentum has to be shed. What changes is how long you take to shed it. Concrete does it in a thousandth of a second, the mattress in two tenths — two hundred times longer, so one two-hundredth of the force. Airbags, helmets, running shoes, the padding in a parcel: every one of them does the same single job of stretching the stop."]),n("phanh-gap-doi",2,"tp",["Một chiếc xe đang chạy 20 km một giờ, phanh gấp, trượt thêm 4 mét rồi dừng. Bây giờ vẫn xe ấy, vẫn mặt đường ấy, nhưng chạy 40 km một giờ.","A car doing 20 km an hour brakes hard and skids 4 metres before stopping. Now the same car on the same road is doing 40 km an hour."],["Lần này nó trượt bao xa mới dừng?","How far does it skid this time?"],[["8 mét — nhanh gấp đôi thì xa gấp đôi","8 metres — twice the speed, twice the distance"],["16 mét","16 metres"],["Vẫn 4 mét, vì phanh vẫn là cái phanh đó","Still 4 metres — the brakes have not changed"]],1,["Nhanh gấp đôi thì trong xe có gấp BỐN lần cái phải bỏ đi, vì sức của một vật đang chạy tính theo tốc độ nhân với chính nó. Phanh thì vẫn cào lại từng ấy trên mỗi mét, nên phải cào gấp bốn số mét. Đây là con số mà mọi người lớn đều đoán sai khi phóng nhanh trong ngõ: đi 60 thay vì 30 không phải là dừng chậm hơn một chút, mà là trượt xa gấp bốn.","Twice the speed means FOUR times as much to get rid of, because what a moving thing carries goes as the speed multiplied by itself. The brakes scrape away the same amount per metre, so they need four times the metres. This is the number every adult misjudges in a narrow lane: doing 60 instead of 30 is not stopping a little later, it is skidding four times as far."]),n("bong-nay-va-dat-set",2,"tp",["Ném vào một cánh cửa đang khép hờ: một quả bóng cao su nảy bật ngược trở lại, và một cục đất sét cùng cân nặng, cùng tốc độ, đập vào rồi dính luôn ở đó.","Thrown at a door standing ajar: a rubber ball that bounces straight back, and a lump of clay of the same weight and speed that hits and sticks."],["Cái nào đẩy cánh cửa mạnh hơn?","Which one shoves the door harder?"],[["Cục đất sét — nó dồn hết vào cửa chứ không nảy đi mất","The clay — it gives everything to the door instead of bouncing away"],["Quả bóng cao su","The rubber ball"],["Bằng nhau, vì cùng cân nặng và cùng tốc độ","The same — same weight, same speed"]],1,["Cục đất sét đi tới rồi dừng: cửa phải lấy đi một phần đà. Quả bóng đi tới rồi quay NGƯỢC lại: cửa phải lấy đi phần đà đó, rồi đẩy thêm chừng ấy nữa theo chiều ngược — tổng cộng gấp đôi. Cái nảy lại không phải là bằng chứng quả bóng đã tha cho cánh cửa, mà là bằng chứng nó vừa đòi cánh cửa làm gấp đôi việc.","The clay arrives and stops: the door must take away that much momentum. The ball arrives and leaves BACKWARDS: the door must take that away and then supply the same again in the other direction — twice the total. Bouncing is not evidence that the ball went easy on the door; it is evidence that it made the door do double the work."]),n("xe-con-dam-xe-tai",3,"tp",["Một xe con và một xe tải chở đầy hàng đâm thẳng vào nhau. Sau cú đâm, xe con nát bét, xe tải chỉ móp cái cản trước.","A small car and a fully loaded truck crash head on. Afterwards the car is wrecked and the truck has a dented bumper."],["Trong lúc va chạm, xe nào tác dụng lực lớn hơn lên xe kia?","During the crash, which vehicle pushed on the other with the greater force?"],[["Xe tải, hiển nhiên — nhìn hai cái xe thì biết","The truck, obviously — just look at the two of them"],["Hai xe đẩy nhau bằng đúng một lực như nhau","Each pushed on the other with exactly the same force"],["Xe con, vì nó đang chạy nhanh hơn","The car, because it was going faster"]],1,["Chỗ hai cái cản chạm nhau chỉ có MỘT cái ép, và cái ép ấy ép cả hai bên bằng nhau — không có cách nào để nó mạnh ở bên này mà yếu ở bên kia. Cái khác nhau không nằm ở lực mà ở chỗ ai chịu nổi nó: cùng một lực đẩy vào một vật nhẹ thì làm nó đổi tốc độ rất nhiều, đẩy vào một vật nặng thì gần như không xi nhê. Xe con nát không phải vì bị đẩy mạnh hơn, mà vì nó nhẹ hơn nhiều lần.","Where the two bumpers meet there is only ONE squeeze, and a squeeze presses both sides equally — there is no way for it to be strong on one face and weak on the other. The difference is not in the force but in who can survive it: one and the same force changes the speed of a light thing enormously and barely troubles a heavy one. The car is wrecked not because it was pushed harder but because it is many times lighter."]),n("bua-dong-coc",3,"tp",["Đóng cọc xuống đất bằng một quả búa thả rơi. Lần thứ nhất: búa 10 kg thả từ độ cao 1 mét. Lần thứ hai: búa 5 kg thả từ độ cao 2 mét.","Driving a post into the ground with a dropped weight. First: a 10 kg weight dropped from 1 metre. Second: a 5 kg weight dropped from 2 metres."],["Lần nào đóng cọc xuống sâu hơn?","Which drive sinks the post deeper?"],[["Búa 10 kg, vì nặng gấp đôi","The 10 kg weight — twice the mass"],["Búa 5 kg, vì rơi từ cao gấp đôi nên chạm nhanh hơn","The 5 kg weight — twice the drop, so it arrives faster"],["Sâu như nhau","Both sink it the same"]],2,["Cái đóng cọc xuống là công, và công cất được trong quả búa nhấc lên tính bằng cân nặng nhân với độ cao: 10 nhân 1 và 5 nhân 2 ra cùng một số. Xuống tới đất thì cùng ngần ấy công phải đổ ra đẩy cọc chống lại lực giữ của đất, nên cùng độ sâu. Búa nhẹ đúng là chạm nhanh hơn thật — nhanh gấp căn hai — nhưng nó cũng nhẹ đi đúng một nửa, và hai cái đó bù trừ hết. Cân nặng và độ cao ở đây đổi cho nhau được; đó là lý do người ta có thể chọn búa nhẹ mà giàn cao, hay búa nặng mà giàn thấp, tuỳ chỗ đứng.","What drives the post is work, and the work stored by lifting the weight is its mass multiplied by the height: 10 times 1 and 5 times 2 come to the same number. At the ground the same work must be spent pushing the post against the soil holding it, so the same depth. The lighter weight does arrive faster — faster by the square root of two — but it is also exactly half as heavy, and the two cancel. Here mass and height trade against each other, which is why a rig can be built tall and light or short and heavy to suit the site."])]),t("quay-tron",["Quay Tròn","Going Round"],["Đi vòng tròn là liên tục bị kéo vào tâm","Going in a circle means being pulled inward the whole time"],[n("ngua-go-vanh-ngoai",1,"tp",["Vòng đu quay ngựa gỗ ở hội làng. Có hàng ngựa sát trục ở giữa và hàng ngựa ngoài cùng vành. Cả vòng quay một khối.","The wooden carousel at a village fair. There is a row of horses close to the middle post and a row right out at the rim. The whole thing turns as one piece."],["Con ngựa nào đi nhanh hơn?","Which horse is travelling faster?"],[["Ngựa ngoài vành","The horse at the rim"],["Ngựa gần trục","The horse near the post"],["Bằng nhau, vì cả vòng quay cùng một tốc độ","The same — the whole carousel turns at one speed"]],0,["Trong một phút thì mọi con ngựa đều quay đúng ngần ấy vòng — chỗ này thì bằng nhau thật. Nhưng con ngoài vành phải đi hết một đường tròn lớn hơn nhiều trong đúng thời gian đó, nên nó phải đi nhanh hơn. Đây là lý do đứng ở vành thì gió tạt vào mặt còn ngồi gần trục thì không, và cũng là lý do một điểm ở xích đạo đang chạy hơn 1600 km một giờ trong khi một điểm gần cực gần như đứng yên — dù cả Trái Đất chỉ quay đúng một vòng một ngày.","In one minute every horse goes round the same number of times — that much really is equal. But the outer horse must cover a far bigger circle in that same time, so it must go faster. This is why the rim gets wind in your face and the middle does not, and why a point on the equator is doing over 1600 km an hour while a point near the pole barely moves — although the whole Earth turns just once a day."]),n("buong-day-quay",2,"tp",["Buộc hòn đá vào đầu sợi dây, quay tròn trên đầu cho thật nhanh, rồi buông tay đúng lúc hòn đá đang ở phía trước mặt bạn.","Tie a stone to a string, whirl it flat above your head, and let go at the instant the stone is straight in front of you."],["Hòn đá bay theo hướng nào?","Which way does the stone fly?"],[["Thẳng ra xa bạn, theo hướng sợi dây đang chỉ","Straight away from you, along the line the string was pointing"],["Theo đúng hướng nó đang đi lúc buông, tức là ngang qua trước mặt bạn","Along the way it was already travelling — straight across in front of you"],["Vẫn cong thêm một đoạn rồi mới thẳng ra","Curving on for a bit and only then straightening out"]],1,['Sợi dây không hề đẩy hòn đá ra ngoài — nó KÉO hòn đá vào trong, và đó là việc duy nhất nó làm. Không có cái kéo vào ấy thì hòn đá đã đi thẳng từ lâu; chính cái kéo vào liên tục mới bẻ đường thẳng thành đường tròn. Nên buông tay ra là hết cái bẻ, và hòn đá làm cái nó vẫn luôn muốn làm: đi thẳng theo hướng đang đi, tức là chạm vào đường tròn rồi rời ra. Đây là chỗ mà chữ "lực ly tâm" đánh lừa gần như tất cả mọi người.',"The string never pushes the stone outward — it PULLS the stone inward, and that is the only thing it does. Without that inward pull the stone would have gone straight long ago; the constant inward pull is what bends a straight line into a circle. Let go and the bending stops, so the stone does what it always wanted: carry straight on the way it was going, leaving the circle at a tangent. This is where the phrase about a force flinging things outward fools nearly everybody."]),n("xo-nuoc-quay-dung",3,"tp",["Cầm quai một xô nước, quay thật nhanh thành vòng tròn thẳng đứng. Ở đỉnh vòng, cái xô lộn ngược hoàn toàn — miệng xô chúc xuống đất — mà nước không đổ ra.","Swing a bucket of water fast in a vertical circle. At the top the bucket is completely upside down, mouth pointing at the ground, and no water falls out."],["Ở đúng đỉnh đó, nước không đổ vì sao?","At that top point, why does the water stay in?"],[["Có một lực ném nước ra ngoài, ép nó vào đáy xô","A force flings the water outward and presses it into the bucket bottom"],["Ở đỉnh thì trọng lực không còn tác dụng lên nước nữa","At the top gravity no longer acts on the water"],["Nước vẫn đang rơi — nhưng cái xô cũng rơi theo đúng đường ấy, nên nước không kịp rời xô","The water is falling — but the bucket is falling along the same path, so the water never leaves it"]],2,["Ở đỉnh vòng, Trái Đất vẫn kéo nước xuống bình thường, và nước quả thật đang rơi. Chuyện là ở chỗ: rơi xuống, đối với một vật đang bay ngang rất nhanh, chính là đi theo đường vòng — và bạn đã lo sẵn cho cái xô đi đúng đường vòng ấy. Nước không đuổi kịp mặt đất vì cái xô luôn ở dưới nó. Quay chậm lại thì đường rơi của nước cong gấp hơn đường của xô, nước rời đáy xô, và bạn ướt. Cùng cái lý ấy giữ cho Mặt Trăng khỏi rơi vào Trái Đất: nó vẫn đang rơi, chỉ là rơi trượt qua.","At the top the Earth pulls the water down as usual, and the water really is falling. The point is that falling, for something already moving fast sideways, means following a curve — and you have arranged for the bucket to follow that same curve. The water never catches the ground because the bucket is always beneath it. Swing slower and the falling curve of the water is tighter than the path of the bucket, the water leaves the bottom, and you get wet. The same reasoning keeps the Moon from landing on us: it is falling, it just keeps missing."]),n("thu-tay-xoay-nhanh",2,"tp",["Một người trượt băng đang xoay tại chỗ, hai tay dang rộng. Không ai đẩy thêm, không đạp thêm cái nào, người đó chỉ khép hai tay sát vào ngực.","A skater spins on the spot with both arms stretched wide. Nobody pushes, no extra kick off the ice — the skater simply folds both arms in against the chest."],["Chuyện gì xảy ra?","What happens?"],[["Xoay nhanh hẳn lên","The spin speeds up sharply"],["Xoay chậm lại, vì thu người vào thì nhỏ hơn","The spin slows, because a smaller shape moves less"],["Không đổi, vì không ai thêm sức đẩy nào","Nothing changes — no new push was added"]],0,["Có một thứ được giữ nguyên trong lúc xoay, và nó không phải tốc độ xoay: nó là tốc độ xoay nhân với việc khối lượng nằm xa trục bao nhiêu. Dang tay thì hai bàn tay ở rất xa trục, tính vào rất nặng phần; thu tay lại thì phần đó tụt xuống, nên để cái tích kia không đổi, tốc độ xoay phải vọt lên bù vào. Người trượt băng không thêm sức nào cả — chỉ dời chỗ để khối lượng của chính mình.","Something is held fixed while a body spins, and it is not the spin rate: it is the spin rate multiplied by how far the mass sits from the axis. Arms out puts the hands far from the axis and they count heavily; arms in cuts that down, so for the product to stay put, the spin rate must jump to make up for it. The skater adds no effort at all — only moves their own mass to a new place."]),n("vong-va-dia-lan-doc",3,"tp",["Một cái vòng sắt và một cái đĩa sắt đặc, đúng bằng nhau về cân nặng và đường kính, cùng đặt trên đỉnh một cái dốc rồi buông ra cùng lúc, cả hai đều lăn chứ không trượt.","An iron hoop and a solid iron disc, exactly equal in weight and diameter, are set at the top of a slope and released together. Both roll rather than slide."],["Cái nào xuống tới chân dốc trước?","Which reaches the bottom first?"],[["Cái vòng, vì khối lượng ở xa tâm nên nó lăn trơn hơn","The hoop — its mass is out at the rim, so it rolls more freely"],["Cái đĩa đặc","The solid disc"],["Cùng lúc, vì nặng bằng nhau và dốc như nhau","Together — same weight, same slope"]],1,["Cái dốc phát cho hai vật đúng ngần ấy sức, nhưng sức đó phải chia làm hai việc: đi tới, và tự quay quanh mình. Cái vòng dồn hết sắt ra vành, mà sắt ở vành thì rất khó bắt quay — nên nó phải cắt một phần lớn cho việc quay, còn lại ít cho việc đi tới. Cái đĩa có sắt rải đều tới tận tâm, dễ quay hơn, nên dành được nhiều hơn cho việc chạy xuống dốc. Đây cũng là lý do một quả bóng đặc luôn thắng một quả bóng rỗng, và là lý do bánh xe đua được làm nhẹ ở VÀNH chứ không phải nhẹ ở moay-ơ.","The slope hands both the same amount of energy, but it has to be split between two jobs: travelling down, and turning about itself. The hoop keeps all its iron at the rim, and iron at the rim is very hard to get spinning — so a large share goes to spinning and little is left for travelling. The disc spreads its iron all the way in, spins up easily, and keeps more for the journey. It is also why a solid ball always beats a hollow one, and why racing wheels are made light at the RIM rather than at the hub."])]),t("troi-keo",["Trời Kéo","What the Sky Pulls"],["Cái giữ Mặt Trăng trên trời cũng là cái làm quả táo rụng","What holds the Moon up is what makes an apple fall"],[n("bua-va-long-tren-mat-trang",1,"te",["Năm 1971 một phi hành gia đứng trên Mặt Trăng, một tay cầm cái búa, một tay cầm cái lông chim, rồi buông cả hai cùng lúc trước ống kính. Trên Mặt Trăng không có không khí.","In 1971 an astronaut stood on the Moon holding a hammer in one hand and a feather in the other, and let go of both on camera. There is no air on the Moon."],["Chuyện gì đã xảy ra?","What happened?"],[["Cái búa chạm đất trước","The hammer landed first"],["Cả hai chạm đất cùng lúc","They landed together"],["Cái lông đứng lơ lửng, vì Mặt Trăng hút quá yếu","The feather hung in place — the Moon pulls too weakly"]],1,['Cả hai rơi xuống cùng lúc, và cả hai rơi chậm hơn ở Trái Đất khoảng sáu lần, vì Mặt Trăng nhỏ nên kéo yếu hơn. Điều đáng nói không phải là chuyện chậm — mà là suốt mấy trăm năm người ta chỉ nói được rằng "nếu không có không khí thì hai vật rơi như nhau", vì trên Trái Đất chỗ nào cũng có không khí. Đó là một trong rất ít lần loài người bay tới tận nơi để làm một thí nghiệm mà lẽ ra chỉ cần nghĩ là đủ.',"Both landed together, and both fell about six times more gently than they would here, because the Moon is small and pulls weakly. The remarkable part is not the gentleness — it is that for centuries the claim could only be stated as a supposition, since there is air everywhere on Earth. It is one of the very few times people flew somewhere to run an experiment that thinking alone had already settled."]),n("phi-hanh-gia-lo-lung",2,"te",["Trong trạm vũ trụ, phi hành gia lơ lửng giữa khoang, bút chì thả ra thì đứng yên tại chỗ. Trạm bay cách mặt đất khoảng 400 km.","Inside the space station the crew float about the cabin and a released pencil simply hangs there. The station orbits about 400 km up."],["Vì sao mọi thứ trong đó lơ lửng?","Why does everything in there float?"],[["Vì ở ngoài đó không còn lực hút của Trái Đất nữa","Because out there the Earth no longer pulls"],["Vì cả trạm lẫn người đều đang rơi quanh Trái Đất, rơi mãi mà không chạm","Because the station and the crew are all falling around the Earth, and never arriving"],["Vì trạm bay đủ nhanh nên lực hút bị gió vũ trụ thổi bạt đi","Because at that speed the pull is blown aside"]],1,["Trạm và mọi thứ trong nó đều đang rơi — cùng một hướng, cùng một nhịp. Mà khi bạn và cái sàn dưới chân cùng rơi như nhau thì cái sàn không còn ép vào chân bạn nữa, và chính cái ép ấy mới là thứ ta gọi là cảm giác nặng. Bạn cũng thấy đúng cảm giác đó trong nửa giây đầu của một cú nhảy cầu, hay khi thang máy tụt xuống hơi nhanh. Khác biệt duy nhất là trạm bay ngang nhanh tới mức mặt đất cong đi kịp lúc, nên cú rơi ấy không bao giờ kết thúc.","The station and everything in it are falling — same direction, same rate. And when you and the floor under you fall alike, the floor stops pressing on your feet, and that press is exactly what we call the feeling of weight. You feel the same thing in the first half second off a diving board, or when a lift drops a little too quickly. The only difference is that the station moves sideways fast enough for the ground to curve away in time, so the fall never ends."]),n("nem-du-manh",2,"tp",["Đứng trên một ngọn núi rất cao, ném một hòn đá đi ngang. Ném nhẹ thì nó rơi cách chân núi vài mét. Ném mạnh hơn thì rơi xa hơn. Mạnh hơn nữa thì rơi xa hơn nữa, và mặt đất thì cong.","Standing on a very tall mountain, throw a stone horizontally. A gentle throw lands a few metres out. A harder throw lands further. Harder still, further still — and the ground is curved."],["Nếu ném đủ mạnh thì sao?","And if you throw hard enough?"],[["Nó bay thẳng ra khỏi Trái Đất và không quay lại","It leaves the Earth in a straight line and never returns"],["Nó vẫn rơi, nhưng mặt đất cong đi kịp — nên nó rơi vòng quanh Trái Đất mãi","It keeps falling, but the ground curves away in time — so it falls all the way round"],["Tới một tốc độ nào đó thì lực hút buông nó ra","Past some speed the pull lets go of it"]],1,["Đây là hình vẽ nổi tiếng của Newton, và nó là chỗ nối hai thứ mà trước ông không ai nối: quả táo rụng và Mặt Trăng trên trời hoá ra là CÙNG MỘT chuyện. Một vệ tinh không phải thứ đã thoát khỏi lực hút; nó là thứ rơi hoài mà cứ trượt qua. Ở độ cao của trạm vũ trụ, tốc độ phải ném là khoảng 28 nghìn km một giờ, và đó là toàn bộ việc mà một quả tên lửa phải làm — không phải đưa đồ lên cao, mà đưa đồ đi ngang cho đủ nhanh.","This is the famous drawing by Newton, and it joins two things nobody had joined before him: the falling apple and the Moon turn out to be ONE story. A satellite is not something that escaped the pull; it is something that keeps falling and keeps missing. At station height the throw needed is about 28 thousand km an hour, and that is the whole job of a rocket — not lifting things up, but getting them sideways fast enough."]),n("luc-hut-o-400-km",3,"te",["Trạm vũ trụ bay cách mặt đất 400 km. Bán kính Trái Đất là khoảng 6 400 km, nên tính từ tâm Trái Đất, trạm chỉ ở xa hơn mặt đất chừng một phần mười sáu.","The station orbits 400 km up. The Earth is about 6400 km in radius, so measured from the centre the station is only about one sixteenth further out than the ground is."],["Ở chỗ đó, Trái Đất kéo mạnh bằng bao nhiêu so với dưới mặt đất?","Out there, how strong is the Earth’s pull compared with down here?"],[["Gần bằng không — nên phi hành gia mới lơ lửng","Almost nothing — that is why the crew float"],["Khoảng một nửa","About half"],["Khoảng chín phần mười","About nine tenths"]],2,['Lực hút yếu đi theo khoảng cách tính từ TÂM Trái Đất, chứ không phải từ mặt đất — và đi thêm 400 km trên một quãng 6 400 km thì chẳng đổi được bao nhiêu. Ở đó trọng lực vẫn còn khoảng 90 phần trăm. Vậy nên câu trả lời quen thuộc "ngoài đó không có trọng lực" là sai gần như hoàn toàn: nếu không có trọng lực thì trạm đã bay thẳng đi mất từ lâu, chứ không quay quanh Trái Đất được. Lơ lửng là do rơi, không phải do hết bị kéo.',"The pull weakens with distance from the CENTRE of the Earth, not from the ground — and adding 400 km to 6400 changes little. Out there about 90 percent of the pull remains. So the familiar answer that there is no gravity up there is almost entirely wrong: with no gravity the station would have flown off in a straight line long ago instead of circling. The floating comes from falling, not from being released."]),n("hai-lan-trieu",3,"tp",["Mặt Trăng kéo nước biển của Trái Đất, và biển dâng lên hạ xuống theo. Một ngày Trái Đất quay đúng một vòng dưới Mặt Trăng.","The Moon pulls on the ocean and the sea rises and falls in step. In one day the Earth turns once beneath the Moon."],["Một ngày ở một bờ biển có mấy lần nước lên?","How many high tides does one coast get in a day?"],[["Một lần, đúng lúc Mặt Trăng ở trên đầu","One, when the Moon is overhead"],["Hai lần","Two"],["Bốn lần, mỗi lần Mặt Trăng đi qua một phần tư vòng","Four, one for each quarter turn"]],1,["Mặt Trăng kéo phía biển GẦN nó mạnh hơn kéo cả khối Trái Đất, nên nước phía ấy phình ra về phía Mặt Trăng. Nhưng nó cũng kéo cả khối Trái Đất mạnh hơn kéo phía biển XA, nên Trái Đất bị lôi đi, tụt ra khỏi khối nước phía xa — và nước phía xa phình ra theo hướng ngược lại. Hai chỗ phình nằm hai đầu đối nhau, Trái Đất quay một vòng thì một bờ biển đi qua cả hai. Cái sinh ra thuỷ triều không phải là lực kéo, mà là sự CHÊNH LỆCH giữa hai chỗ trong cùng một lực kéo.","The Moon pulls the NEAR ocean harder than it pulls the bulk of the Earth, so that water bulges towards the Moon. But it also pulls the bulk of the Earth harder than it pulls the FAR ocean, so the Earth is drawn out from under that far water — and the far water bulges the other way. The two bulges sit on opposite sides, and one turn of the Earth carries a coast through both. What makes tides is not the pull itself but the DIFFERENCE in the pull between one place and another."])])],p=[t("noi-va-chim",["Nổi & Chìm","Float & Sink"],["Nổi không phải chuyện nhẹ hay nặng, mà chuyện chiếm bao nhiêu chỗ","Floating is not about heavy or light, but about how much room you take up"],[n("tau-sat-noi",1,"tp",["Thả một cục sắt bằng nắm tay xuống nước, nó chìm ngay. Nhưng một con tàu chở hàng làm bằng đúng thứ sắt ấy, nặng mấy vạn tấn, thì nổi.","Drop a fist-sized lump of iron in water and it sinks at once. A cargo ship built of that same iron, weighing tens of thousands of tonnes, floats."],["Vì sao con tàu nổi được?","Why does the ship float?"],[["Vì tàu quá lớn nên nước đỡ được nhiều hơn","Because it is so large that the water can hold more of it"],["Vì tàu rỗng, nên chỗ nước nó chiếm còn nặng hơn cả con tàu","Because it is hollow, so the water it shoves aside weighs more than the ship"],["Vì máy tàu đẩy nước xuống liên tục","Because the engines keep pushing water down"]],1,["Nước đẩy lên đúng bằng cân nặng của khối nước bị vật chiếm chỗ — không hơn, không kém. Cục sắt đặc chiếm chỗ đúng bằng thể tích của nó, mà thể tích ấy đầy nước cũng chỉ nặng bằng một phần tám cục sắt, nên nó chìm. Con tàu cũng chừng ấy sắt nhưng dàn mỏng ra bao lấy một bụng đầy không khí, nên nó gạt được một khối nước khổng lồ. Bơm nước vào bụng tàu là tàu chìm ngay — và đó chính là cách tàu ngầm lặn xuống.","Water pushes up with exactly the weight of the water shoved aside — no more, no less. The solid lump displaces only its own small volume, and that much water weighs about an eighth of the iron, so down it goes. The ship is the same iron spread thin around a belly of air, so it shoves aside an enormous mass of water. Flood that belly and the ship sinks at once — which is exactly how a submarine dives."]),n("nuoc-bien-de-noi",1,"tp",["Cùng một người, cùng cách nằm ngửa. Ở hồ nước ngọt thì phải khua tay mới nổi được, ra biển thì nằm im cũng nổi, và ở Biển Chết thì nổi hẳn lên như tấm ván.","The same person floating on their back. In a freshwater lake it takes some paddling; in the sea they float without moving; in the Dead Sea they ride high like a plank."],["Vì sao?","Why?"],[["Vì nước mặn nặng hơn nước ngọt","Because salt water is heavier than fresh water"],["Vì muối bám vào người làm người nhẹ đi","Because the salt sticking to them makes them lighter"],["Vì biển sâu hơn hồ nên đẩy lên mạnh hơn","Because the sea is deeper and so pushes up harder"]],0,["Nước biển có muối hoà tan, nên mỗi lít nước biển nặng hơn mỗi lít nước ngọt khoảng ba phần trăm; Biển Chết mặn tới mức nặng hơn một phần tư. Mà cái đẩy bạn lên chính là cân nặng của phần nước bạn gạt đi — nước càng nặng thì gạt ít hơn đã đủ, nên bạn chìm nông hơn. Chuyện sâu hay nông thì không dính dáng gì: một cái ao sâu nửa mét cũng đẩy bạn lên đúng như vậy, miễn là đủ nước để bạn lún vào.","Sea water carries dissolved salt, so a litre of it weighs about three percent more than a litre of fresh; the Dead Sea is salty enough to weigh a quarter more. What lifts you is the weight of the water you shove aside — the heavier the water, the less of it you need to shove, so the less of you goes under. Depth has nothing to do with it: half a metre of pond lifts you just the same, as long as there is enough to sink into."]),n("bang-tan-trong-coc",2,"tp",["Một cốc nước đầy tới miệng, có một cục đá đang nổi trong đó. Cục đá nhô lên khỏi mặt nước một phần. Cứ để yên như thế cho tới khi cục đá tan hết.","A glass filled to the brim with water, an ice cube floating in it, part of the cube standing above the surface. Leave it alone until the ice has melted completely."],["Nước có tràn ra không?","Does the water overflow?"],[["Có, vì phần đá nhô lên tan ra thành nước thêm vào cốc","Yes — the part sticking up melts and adds to the glass"],["Không, mực nước giữ nguyên y hệt","No — the level stays exactly where it was"],["Không, và mực nước còn hạ xuống","No, and the level actually drops"]],1,["Cục đá đang nổi thì nó đã gạt đi một khối nước nặng đúng bằng chính nó — đó là điều kiện để nổi. Tan ra, nó biến thành đúng ngần ấy cân nước, nên lượng nước mới vừa khít cái chỗ nó đang chiếm. Không thừa một giọt. Đây là lý do băng trôi ở Bắc Cực tan hết cũng không làm mực nước biển dâng thêm bao nhiêu — cái làm biển dâng là băng nằm TRÊN ĐẤT LIỀN ở Nam Cực và Greenland, thứ chưa hề gạt nước bao giờ.","A floating cube has already shoved aside water weighing exactly what the cube weighs — that is the condition for floating. Melting, it becomes exactly that weight of water, which fits precisely into the hole it was occupying. Not a drop spare. This is why melting sea ice at the North Pole barely raises the oceans — what raises them is ice sitting ON LAND in Antarctica and Greenland, which has never displaced any water at all."]),n("nem-da-tu-thuyen",3,"tp",["Bạn ngồi trong một chiếc thuyền nhỏ giữa một cái ao. Trong thuyền có một hòn đá to. Bạn nhấc hòn đá lên và ném xuống ao, đá chìm nằm dưới đáy.","You sit in a small boat on a pond with a big stone in the boat. You lift the stone and throw it overboard; it sinks to the bottom."],["Mực nước trong ao thay đổi thế nào?","What happens to the level of the pond?"],[["Dâng lên, vì bây giờ có thêm hòn đá nằm trong ao","It rises — there is now a stone in the pond that was not there before"],["Hạ xuống","It drops"],["Giữ nguyên, vì hòn đá vẫn ở trong ao dù ở đâu","It stays put — the stone is in the pond either way"]],1,["Lúc còn trong thuyền, hòn đá bắt cả cái thuyền lún sâu thêm để gạt một khối nước NẶNG BẰNG nó. Nằm dưới đáy, nó chỉ gạt được một khối nước BẰNG THỂ TÍCH nó. Mà đá nặng gấp gần ba lần nước cùng thể tích — nên khi ở trong thuyền nó gạt nhiều nước hơn hẳn so với lúc nằm dưới đáy. Ném xuống là mất đi phần chênh đó, và mực nước hạ. Bất cứ thứ gì CHÌM cũng cho kết quả này; ném xuống một khúc gỗ nổi thì mực nước giữ nguyên, vì nổi ở đâu cũng gạt theo cân nặng.","While it is in the boat, the stone forces the whole boat to sit deeper and shove aside water WEIGHING as much as the stone. On the bottom it only shoves aside water of its own VOLUME. Stone is nearly three times as heavy as the same volume of water — so in the boat it was displacing far more than it does on the bottom. Throwing it in loses that surplus, and the level falls. Anything that SINKS gives this answer; throw in a floating log and the level does not move, because a float always displaces by weight wherever it is."]),n("chien-ham-trong-bon-tam",3,"tp",["Tưởng tượng một cái bồn khổng lồ, tạc đúng theo hình vỏ một chiến hạm nhưng rộng hơn mỗi bề đúng một xăng-ti-mét. Đặt chiến hạm vào, rồi đổ nước lấp đầy khe hở — chỉ hết chừng vài trăm lít.","Imagine a huge tub carved to the shape of a battleship’s hull but one centimetre wider all round. Lower the ship in, then pour water into the gap — only a few hundred litres of it."],["Con tàu có nổi lên không?","Does the ship float?"],[["Không — vài trăm lít nước không thể đỡ nổi mấy vạn tấn thép","No — a few hundred litres cannot hold up tens of thousands of tonnes of steel"],["Có, nó nổi hẳn lên như ngoài biển","Yes — it lifts and floats exactly as it would at sea"],["Nó nổi lên được một chút rồi tụt xuống","It lifts a little and then settles back down"]],1,['Nước không đỡ vật bằng cân nặng của chính nó, mà bằng cách ĐÈ LÊN vỏ tàu từ mọi phía, và cái đè ấy chỉ phụ thuộc vào nước SÂU bao nhiêu chứ không phải có bao nhiêu nước. Khe hở một xăng-ti-mét vẫn cho nước sâu đúng bằng ngoài biển, nên vẫn đè đúng bấy nhiêu, nên vẫn đỡ đúng bấy nhiêu. Ai từng nghĩ "phải nhiều nước mới đỡ nổi vật nặng" đều bị hụt ở đây — cũng chính vì lẽ đó mà một con đê chắn cái ao nhỏ phải xây dày y như con đê chắn một cái hồ mênh mông, nếu hai bên sâu bằng nhau.',"Water does not hold things up with its own weight but by PRESSING on the hull from every side, and that press depends only on how DEEP the water is, never on how much of it there is. A one centimetre gap still gives the same depth as the open sea, so the same press, so the same lift. Anyone who thinks a heavy thing needs plenty of water comes unstuck here — and for the same reason a dam holding back a tiny pond must be built as thick as one holding back a vast lake, if the two are equally deep."])]),t("nuoc-de",["Nước Đè","The Weight of Water"],["Nước đè mạnh hay nhẹ chỉ tuỳ vào sâu bao nhiêu","How hard water presses depends on depth and nothing else"],[n("lan-sau-dau-tai",1,"tp",["Lặn xuống đáy bể bơi sâu ba mét, tai đau nhức. Lặn xuống đáy biển sâu ba mét, tai cũng đau đúng chừng ấy.","Dive to the bottom of a three-metre pool and your ears ache. Dive three metres down in the open sea and they ache just as much."],["Cái gì đè vào tai bạn?","What is pressing on your ears?"],[["Cột nước nằm ngay trên đầu bạn","The column of water standing directly above you"],["Toàn bộ khối nước của cái bể hay của cả biển","The entire body of water — the whole pool, the whole sea"],["Sức hút của đáy bể kéo bạn xuống","The bottom pulling you down"]],0,["Chỉ có phần nước nằm ngay phía trên là đè xuống bạn được; nước ở cách đó một trăm mét về phía chân trời thì đè xuống chỗ của nó, không đè sang chỗ bạn. Vì vậy ba mét sâu ở bể bơi và ba mét sâu ở Thái Bình Dương đè lên tai bạn như nhau, dù hai bên chênh nhau cả tỉ tấn nước. Trong nước, cứ mỗi mười mét sâu thì thêm một lần cái đè của cả bầu khí quyển.","Only the water directly overhead can press down on you; water a hundred metres away towards the horizon presses down where it is, not where you are. So three metres in a pool and three metres in the Pacific squeeze your ears alike, though a billion tonnes separate them. In water, every ten metres of depth adds one more atmosphere of press."]),n("dap-lon-dap-nho",2,"tp",["Hai con đập cùng cao 5 mét, xây cùng một kiểu. Con thứ nhất chắn một cái hồ rộng mười cây số. Con thứ hai chắn một cái ao làng rộng đúng mười mét. Cả hai hồ đều sâu 5 mét sát chân đập.","Two dams, each 5 metres tall and built alike. The first holds back a lake ten kilometres across. The second holds back a village pond ten metres across. Both are 5 metres deep at the dam."],["Nước đè lên mỗi mét vuông chân đập nào mạnh hơn?","Which dam has water pressing harder on each square metre of its base?"],[["Đập chắn hồ lớn, hiển nhiên","The lake dam, obviously"],["Bằng nhau","Exactly the same"],["Đập chắn ao, vì nước dồn vào chỗ hẹp","The pond dam — the water is crowded into a small space"]],1,["Cái đè ở một điểm chỉ tính theo chiều sâu tính từ mặt nước xuống điểm đó, không tính theo bề rộng của hồ. Nên hai con đập chịu cùng một cái đè trên mỗi mét vuông, và một con đập chắn ao vẫn phải xây dày như con đập chắn hồ. Cái khác nhau là TỔNG lực: đập hồ dài hơn nên tổng cộng lại thì lớn hơn nhiều — nhưng chính vì nó dài hơn chứ không phải vì hồ rộng hơn. Đây là điều làm mọi người ngạc nhiên nhất khi lần đầu đọc về đập nước.","The press at a point depends only on the depth from the surface down to it, never on the width of the water behind. So both dams meet the same press on every square metre, and a pond dam must be built as thick as a lake dam. What differs is the TOTAL: the lake dam is longer, so the sum over its whole face is far greater — but because it is longer, not because the lake is wider. This is the fact that surprises people most on first meeting dams."]),n("binh-thong-nhau",2,"tp",["Bốn cái ống thuỷ tinh nối chung một đáy, nhưng hình dạng khác hẳn nhau: một ống thẳng hẹp, một ống phình như quả bầu, một ống nghiêng, một ống loe như cái phễu. Đổ nước cho dâng lên cả bốn.","A set of connected vessels: four glass tubes sharing one base, but shaped quite differently — one narrow and straight, one bulging like a gourd, one leaning over, one flaring like a funnel. Pour water in until it stands in all four."],["Mực nước bốn ống ra sao?","How do the four levels compare?"],[["Ống hẹp dâng cao nhất, vì cùng lượng nước dồn vào chỗ nhỏ","The narrow one stands highest — the same water crowded into less room"],["Ống loe rộng dâng cao nhất, vì chứa được nhiều nước nhất","The wide one stands highest — it holds the most water"],["Cả bốn ống dâng lên cùng một mực","All four stand at exactly the same level"]],2,["Ở đáy chung, bốn cột nước gặp nhau. Nếu một cột cao hơn thì nó đè mạnh hơn, và nó sẽ đẩy nước sang các ống kia cho tới lúc bốn bên đè bằng nhau — nghĩa là bốn bên cao bằng nhau. Hình dáng cái ống, lượng nước trong nó, hay nó nghiêng bao nhiêu đều không đổi được điều đó. Đây là cái nguyên lý cả nghề xây dựng dùng để lấy thăng bằng: một ống nhựa mềm đổ đầy nước, hai đầu để hở, thì hai mặt nước luôn nằm đúng một mặt phẳng ngang, dù đi vòng qua bao nhiêu bức tường.","At the shared base the four columns meet. If one stood higher it would press harder and would drive water into the others until all four pressed alike — which means all four stand alike. The shape of the tube, the amount of water in it, how far it leans: none of that changes the answer. This is the principle every builder uses for levelling: a soft hose full of water, open at both ends, keeps its two surfaces on one exact horizontal plane no matter how many walls it snakes around."]),n("xo-thung-dang-roi",3,"tp",["Một cái xô đựng đầy nước, thành xô có một lỗ thủng nhỏ, nước phun ra thành tia. Bây giờ buông tay cho cả cái xô rơi tự do xuống.","A bucket of water with a small hole in its side, water jetting out. Now let go and let the whole bucket fall freely."],["Trong lúc xô đang rơi, tia nước thế nào?","While the bucket is falling, what does the jet do?"],[["Phun mạnh hơn, vì cả xô đang lao xuống","Squirts harder — the whole bucket is rushing downward"],["Ngừng phun","It stops"],["Phun y như cũ, vì lỗ thủng có đổi gì đâu","Squirts exactly as before — the hole has not changed"]],1,["Tia nước phun ra được là nhờ nước phía trên đè xuống nước phía dưới. Nhưng khi cả cái xô rơi tự do thì mọi giọt nước đều rơi hệt nhau, không giọt nào tì lên giọt nào nữa — đúng như phi hành gia lơ lửng trong trạm vũ trụ. Không còn cái đè thì không còn cái đẩy nước ra lỗ, và tia tắt ngay lập tức. Cái đè trong lòng chất lỏng không phải một tính chất của nước; nó là hệ quả của việc có thứ gì đó GIỮ nước lại. Bỏ cái giữ đi thì nó biến mất.","The jet exists because the water above presses on the water below. But in free fall every drop falls alike and no drop rests on any other — exactly as the crew float inside the space station. With no press there is nothing to drive water at the hole, and the jet dies at once. Press inside a liquid is not a property of the liquid; it is a consequence of something HOLDING the liquid up. Remove the holding and it vanishes."]),n("kich-thuy-luc",3,"tp",["Cái kích thuỷ lực trong tiệm sửa xe: hai pit-tông nối nhau bằng dầu, một cái bé bằng đồng xu, một cái to bằng cái đĩa lớn gấp trăm lần. Ấn nhẹ lên pit-tông bé thì pit-tông to nâng được cả chiếc ô tô.","The hydraulic jack in a garage: two pistons joined by oil, one the size of a coin, the other a hundred times its area. A light push on the small one lifts a whole car on the big one."],["Vậy cái kích có cho bạn nhiều sức hơn mà không mất gì không?","So does the jack give you extra strength for nothing?"],[["Có — đó chính là điều kỳ diệu của máy thuỷ lực","Yes — that is the whole magic of a hydraulic machine"],["Không — bạn phải ấn xuống một quãng dài gấp trăm lần","No — you must push down a hundred times as far"],["Không — dầu nóng lên và ăn mất phần chênh","No — the oil heats up and eats the difference"]],1,["Dầu đè đều mọi phía, nên pit-tông to gấp trăm lần diện tích thì nhận được lực gấp trăm lần. Nhưng dầu không tự sinh ra: muốn pit-tông to nhấc lên một xăng-ti-mét thì phải đẩy sang đó đúng ngần ấy dầu, mà lấy từ một cái ống bé gấp trăm thì phải ấn xuống một mét. Lực gấp trăm, quãng đường chia trăm, công thì y nguyên. Mọi cái máy đều thế và không có ngoại lệ: đòn bẩy, ròng rọc, hộp số xe đạp, tất cả chỉ ĐỔI lực lấy quãng đường chứ không bao giờ cho không cái gì.","Oil presses equally in all directions, so a piston with a hundred times the area receives a hundred times the force. But the oil is not created: to raise the big piston one centimetre you must send that much oil across, and taking it from a bore a hundred times smaller means pushing down a full metre. A hundred times the force, a hundredth of the distance, and the work unchanged. Every machine is like this without exception: levers, pulleys, bicycle gears — all of them TRADE force against distance and none of them gives anything away."])]),t("nuoc-chay",["Nước Chảy","Water on the Move"],["Chỗ nước chảy nhanh là chỗ nước đè yếu","Where water runs fastest it presses least"],[n("bop-dau-voi",1,"tp",["Cầm vòi tưới cây, nước chảy ra hiền lành chỉ tới chân mình. Lấy ngón tay bịt bớt miệng vòi, tia nước lập tức bắn vọt đi xa mấy mét.","Holding a garden hose, the water dribbles out at your feet. Squash the end with your thumb and the jet shoots several metres."],["Vì sao bịt bớt lại làm nước đi xa hơn?","Why does narrowing the opening send water further?"],[["Vì bịt lại thì áp lực trong vòi tăng lên gấp bội","Because squashing it multiplies the pressure in the hose"],["Vì cùng ngần ấy nước phải chui qua một lỗ bé hơn, nên phải đi nhanh hơn","Because the same water must get through a smaller hole, so it must go faster"],["Vì ngón tay hất nước lên cao","Because your thumb flicks the water upward"]],1,["Cái máy bơm hay cái tháp nước ở đầu kia vẫn đẩy vào ngần ấy nước mỗi giây, và ngần ấy nước bắt buộc phải ra hết bằng cái lỗ bạn để lại. Lỗ nhỏ đi mười lần thì nước phải chảy qua nhanh gấp mười. Đây là luật đơn giản nhất của mọi dòng chảy: chỗ hẹp thì chảy nhanh. Nó cũng đúng với một dòng sông — chỗ lòng sông thắt lại là chỗ nước xiết nhất, và là chỗ nguy hiểm nhất để bơi qua.","The pump or the water tower at the far end still pushes in the same amount every second, and all of it has to leave through whatever hole you leave. Make the hole ten times smaller and the water must move ten times faster. This is the simplest law of any flow: narrow means fast. It holds for rivers too — where the channel pinches is where the current runs hardest, and where crossing is most dangerous."]),n("voi-nuoc-thon-lai",2,"tp",["Mở nhẹ vòi nước trong bếp, nhìn kỹ dòng nước rơi xuống bồn: nó thon dần lại, càng xuống thấp càng mảnh, có khi mảnh tới mức đứt thành giọt.","Open a kitchen tap gently and watch the falling stream: it thins as it goes down, sometimes thinning until it breaks into drops."],["Vì sao dòng nước thon lại?","Why does the stream narrow?"],[["Vì không khí ép nó lại từ hai bên","Because the air squeezes it from the sides"],["Vì nước rơi thì mỗi lúc một nhanh, mà lượng nước qua mỗi tầng vẫn bằng nhau","Because falling water speeds up, while the same amount must pass every level"],["Vì nước bốc hơi bớt trên đường rơi","Because some of it evaporates on the way down"]],1,["Trong một giây, lượng nước đi qua chỗ sát vòi và lượng nước đi qua chỗ sát bồn phải bằng nhau — nếu không thì nước phải dồn lại hoặc mất đi ở giữa chừng. Mà càng xuống thấp nước rơi càng nhanh. Đi nhanh hơn mà vẫn chỉ chở ngần ấy nước thì bắt buộc phải mảnh hơn. Đây là câu chuyện của cái vòi bịt tay, chỉ lộn ngược lại: ở kia bạn ép cho hẹp nên nó nhanh, ở đây nó tự nhanh nên nó tự hẹp.","In one second the same amount of water must pass the top of the stream and the bottom, or water would be piling up or vanishing in between. And the lower it goes the faster it falls. Carrying the same water while moving faster forces it to be thinner. It is the hose story run backwards: there you squeezed it narrow so it ran fast, here it runs fast so it goes narrow."]),n("thoi-qua-to-giay",2,"tp",["Cầm một tờ giấy mỏng bằng hai tay, để nó rủ xuống trước mặt. Bây giờ thổi thật mạnh một luồng hơi đi ngang qua MẶT TRÊN của tờ giấy.","Hold a sheet of thin paper by one edge so it droops in front of you. Now blow hard across the TOP surface of the paper."],["Tờ giấy làm gì?","What does the paper do?"],[["Bị thổi bạt xuống thấp hơn","Gets blown further down"],["Nâng lên","Lifts up"],["Rung lên nhưng không dịch đi đâu","Flutters but goes nowhere"]],1,["Không khí đứng yên bên dưới đè lên tờ giấy như bình thường. Luồng khí chảy nhanh bên trên thì đè xuống YẾU hơn — vì phần sức của nó đã dùng vào việc chạy, không còn dồn hết vào việc ép sang hai bên. Đè dưới mạnh hơn đè trên, tờ giấy nâng lên. Đây là điều làm nên cánh máy bay: mặt trên cong hơn nên khí phải chạy nhanh hơn, đè nhẹ hơn, và cả cỗ máy trăm tấn được nhấc lên bằng đúng cái chênh lệch ấy.","The still air underneath presses up as usual. The fast stream on top presses DOWN more weakly — part of its vigour has gone into travelling and is no longer available for pushing sideways. Press from below beats press from above, and the paper rises. This is what an aircraft wing is: the upper surface is more curved so the air must run faster over it, presses more lightly, and a hundred-tonne machine is held up by exactly that difference."]),n("la-tra-tu-vao-giua",3,"tp",["Khuấy một cốc trà có cặn lá trà ở đáy. Khuấy xong thì buông thìa ra, để nước tự quay chậm dần rồi dừng. Nhìn xuống đáy cốc.","Stir a cup of tea with leaves settled at the bottom. Take the spoon out and let the swirl die down on its own. Then look at the bottom."],["Cặn lá trà nằm ở đâu?","Where do the leaves end up?"],[["Văng ra bám hết vào vành đáy cốc","Flung out into a ring around the rim of the base"],["Tụ lại thành một đống nhỏ ở đúng giữa đáy","Gathered into a neat little heap at the very centre"],["Rải đều khắp đáy như trước khi khuấy","Spread evenly, just as before stirring"]],1,["Ai cũng đoán lá trà bị văng ra vành, và ai cũng đoán sai. Nước quay thì bị đẩy ra vành thật, làm mặt nước ở vành cao lên. Nhưng ngay sát ĐÁY cốc, ma sát làm tầng nước mỏng ấy quay chậm hơn hẳn — nên nó không đủ sức bám ra vành, và bị mặt nước cao ở vành ép ngược vào tâm. Thành ra dưới đáy có một dòng chảy ngầm quét từ vành vào giữa, và nó gom lá trà lại thành đống. Chính Einstein đã viết bài giải thích chuyện này, và cùng cái dòng ngầm ấy giải thích vì sao khúc sông cong thì bờ ngoài bị khoét lở còn bờ trong bồi lên bãi cát.","Everyone predicts the leaves will be flung to the rim, and everyone is wrong. The spinning water is thrown outward, which is why the surface rides high at the rim. But right at the BOTTOM, friction drags that thin layer far slower — too slow to hold its place out at the rim, so the high water at the rim presses it back towards the middle. The result is a hidden current sweeping inward along the base, and it herds the leaves into a heap. Einstein wrote the paper explaining this, and the same hidden current explains why a river bend eats away the outer bank and builds a sandbar on the inner one."]),n("hai-thuyen-di-song-song",3,"tp",["Hai chiếc thuyền đi song song, cùng chiều, cách nhau chừng vài mét, trên một dòng nước chảy. Người lái không bẻ lái, không có gió.","Two boats running side by side in the same direction a few metres apart in moving water. Neither helmsman turns, and there is no wind."],["Chuyện gì có xu hướng xảy ra?","What tends to happen?"],[["Hai thuyền bị hút lại gần nhau, có khi va vào nhau","They are drawn together, sometimes hard enough to collide"],["Hai thuyền bị đẩy tách xa nhau ra","They are pushed apart"],["Không có gì xảy ra, nước không đẩy ngang được","Nothing — water cannot push sideways like that"]],0,["Khe nước giữa hai thuyền hẹp hơn vùng nước rộng ở hai bên ngoài, mà nước phải chảy qua chỗ hẹp thì phải chảy nhanh hơn. Chảy nhanh hơn thì đè yếu hơn. Thành ra hai bên sườn phía ngoài bị nước đè mạnh hơn hai bên sườn phía trong, và hai thuyền bị ép vào nhau. Đây là tai nạn có thật của nghề đi biển — nó đã làm chìm tàu — và cũng là lý do đứng sát mép sân ga khi tàu tốc hành lao qua là việc rất nguy hiểm: chính bạn là chiếc thuyền thứ hai.","The channel between the boats is narrower than the open water outside them, and water forced through a narrow place must run faster. Faster means pressing less. So the outer flanks are pressed harder than the inner ones, and the boats are squeezed together. This is a real hazard of seamanship — it has sunk ships — and it is why standing at the platform edge as an express passes is genuinely dangerous: you are the second boat."])]),t("nuoc-la",["Nước Lạ","Water Is Strange"],["Nước làm ngược với gần như mọi chất khác, và cả sự sống dựa vào đó","Water does the opposite of nearly everything else, and life depends on it"],[n("nuoc-dong-thi-no",1,"te",["Để quên một chai nước đầy trong ngăn đá. Sáng ra chai nứt toác. Mùa đông ở xứ lạnh, ống nước trong tường cũng vỡ đúng kiểu ấy.","A full bottle of water left in the freezer overnight comes out split open. In cold countries the pipes inside walls burst the same way each winter."],["Nước đóng băng thì thế nào?","What does water do when it freezes?"],[["Co lại, và chỗ trống làm chai nứt","It shrinks, and the gap cracks the bottle"],["Nở ra","It expands"],["Giữ nguyên thể tích, chỉ cứng lại","It keeps its volume and merely hardens"]],1,["Gần như mọi chất khi đông đặc đều co lại, vì các hạt xếp sát nhau hơn. Nước thì làm ngược: các hạt nước móc vào nhau thành một khung sáu cạnh rỗng, và cái khung ấy chiếm nhiều chỗ hơn lúc chúng còn trôi tự do — nở thêm khoảng chín phần trăm. Chín phần trăm nghe nhỏ, nhưng nước nở thì không ai cản nổi: nó tách được cả tảng đá granit, và mỗi mùa đông nó vẫn lặng lẽ bẻ vụn các sườn núi.","Almost every substance shrinks on freezing, because its particles pack closer. Water does the reverse: its particles hook into an open six-sided frame that takes up more room than they did drifting free — about nine percent more. Nine percent sounds small, but nothing stops expanding water: it splits granite, and every winter it quietly breaks mountainsides apart."]),n("bang-noi-nen-ca-song",2,"te",["Vì nước đóng băng thì nhẹ đi, băng nổi lên mặt hồ. Giả sử nước làm giống mọi chất khác — đóng băng thì nặng hơn và chìm xuống.","Because freezing makes water lighter, ice floats on a lake. Suppose water behaved like everything else — freezing heavier, and sinking."],["Mùa đông ở xứ lạnh, cái hồ sẽ ra sao?","What would happen to a lake each winter?"],[["Không khác gì mấy, chỉ là băng nằm dưới đáy","Not much difference — the ice would simply lie on the bottom"],["Hồ sẽ đóng băng dần từ đáy lên cho tới khi đặc cứng cả khối, và cá chết hết","The lake would freeze from the bottom up until it was solid through, killing everything in it"],["Hồ sẽ không bao giờ đóng băng được nữa","The lake could never freeze at all"]],1,["Băng nổi lên thì nó thành cái nắp: nó che mặt hồ, cách nhiệt cho phần nước bên dưới, và mùa đông dừng lại ở đó. Cá, ếch, cây thuỷ sinh sống qua mùa trong lớp nước lỏng phía dưới. Nếu băng chìm thì mỗi mảng băng vừa tạo ra lại tụt xuống đáy, nhường mặt hồ cho lớp nước mới đóng tiếp — và cứ thế cho tới khi cả hồ thành một khối đặc. Sự sống ở vùng ôn đới và hàn đới đứng được là nhờ đúng cái tính lạ ấy của nước.","Floating ice becomes a lid: it covers the lake, insulates the water beneath, and winter stops there. Fish, frogs and water plants live out the season in the liquid below. If ice sank, each new sheet would drop to the bottom and hand the surface to the next, and so on until the whole lake was solid. Life in the temperate and polar world stands on this one oddity."]),n("day-ho-mua-dong",3,"tp",["Giữa mùa đông, mặt một cái hồ sâu đã đóng băng, nhiệt độ mặt băng là 0 độ. Cá vẫn bơi được ở tầng dưới. Nước đặc nhất — nặng nhất — không phải lúc 0 độ mà lúc 4 độ.","Mid-winter, the surface of a deep lake has frozen and the ice sits at 0 degrees. Fish still swim below."],["Nước ở sát đáy hồ nóng lạnh thế nào?","What is the water like right at the bottom?"],[["Lạnh nhất hồ, khoảng 0 độ","The coldest water in the lake, near 0 degrees"],["Khoảng 4 độ — ấm hơn cả mặt hồ","About 4 degrees — warmer than the surface"],["Nóng dần xuống sâu, có thể tới hơn 10 độ","Warmer and warmer with depth, perhaps past 10 degrees"]],1,["Nước nặng nhất không phải ở 0 độ mà ở 4 độ — dưới mức đó nó bắt đầu nhẹ dần vì các hạt đã bắt đầu xếp thành cái khung rỗng của băng. Nên mùa đông, nước mặt hồ nguội dần và chìm xuống, tới khi cả hồ về 4 độ. Sau đó nước mặt nguội tiếp thì lại NHẸ đi, nên nó ở lại trên mặt và đóng băng tại chỗ, còn khối 4 độ nằm yên dưới đáy. Cái ngưỡng 4 độ ấy là lý do đáy hồ là chỗ ấm nhất giữa mùa đông, và là chỗ cá đi trú.","Water is heaviest not at 0 degrees but at 4 — below that it begins to lighten again as its particles start assembling the open frame of ice. So through autumn the surface cools and sinks until the whole lake sits at 4. Cool the surface further and it becomes LIGHTER, so it stays on top and freezes there, while the 4-degree body rests undisturbed below. That threshold at 4 degrees is why the bottom of a lake is the warmest place in midwinter, and where the fish go."]),n("rac-muoi-tan-bang",2,"te",["Ở xứ lạnh, xe rải muối đi khắp đường sau một trận tuyết. Một lúc sau lớp băng trên mặt đường chảy ra thành nước, dù trời vẫn dưới 0 độ.","In cold countries a truck spreads salt along the roads after snow. Soon the ice turns to water, though the air is still below freezing."],["Muối làm gì?","What does the salt do?"],[["Muối toả nhiệt ra làm băng nóng lên","The salt gives off heat and warms the ice"],["Muối kéo nhiệt độ đóng băng của nước xuống thấp hơn 0 độ","The salt drags the freezing point of water down below 0"],["Muối ăn mòn băng như ăn mòn kim loại","The salt eats away at the ice the way it eats metal"]],1,["Muối tan vào nước thì các hạt muối chen vào giữa, làm các hạt nước khó móc vào nhau thành khung băng hơn — nên phải lạnh hơn nữa mới đóng được. Nước muối đặc có thể chỉ đóng băng ở âm 20 độ. Chuyện này cũng chạy theo chiều ngược lại: muối trong nước làm nước sôi ở trên 100 độ. Và nó giải thích luôn vì sao biển thì mãi không đóng băng trong khi cái ao nước ngọt cạnh đó đã đóng từ lâu.","Dissolved salt puts its own particles in among the water ones, making it harder for them to hook into the ice frame — so a lower temperature is needed before they manage it. Strong brine may not freeze until minus 20. It runs the other way too: salt in water pushes the boiling point above 100. And it explains why the sea holds out long after the freshwater pond beside it has frozen over."]),n("nhen-nuoc-tren-mat-ho",3,"tp",["Con nhện nước chạy trên mặt ao mà không chìm, dù nó nặng hơn nước. Nhìn kỹ thấy mặt nước lõm xuống dưới chân nó như một tấm bạt bị đè. Giọt nước rơi thì tự co thành hình cầu.","A water strider runs across a pond without sinking, though it is heavier than water. Look closely and the surface dips under each foot like a stretched sheet. A falling drop pulls itself into a ball."],["Cái gì đỡ con nhện?","What holds the strider up?"],[["Sức đẩy nổi, y như đỡ một con tàu","Buoyancy, just as it holds up a ship"],["Mặt nước có một lớp màng căng, vì các hạt nước ở mặt bị kéo về phía trong","The surface behaves as a taut skin, because the particles there are pulled inward"],["Chân nhện có lông đẩy nước ra xa","The hairs on its legs push the water away"]],1,["Mỗi hạt nước bị các hạt xung quanh kéo về mọi phía, nên ở giữa lòng nước thì các phía khử nhau. Nhưng hạt nằm ngay MẶT nước thì phía trên không có gì kéo, chỉ còn bị kéo xuống và kéo ngang — nên cả lớp mặt bị co lại, căng như một tấm màng. Muốn chọc thủng màng ấy phải làm tăng diện tích mặt, mà làm thế thì tốn sức, nên màng chống lại. Cũng vì thế giọt nước co thành cầu: hình cầu là hình có mặt ngoài nhỏ nhất. Nhỏ một giọt xà phòng xuống là màng đứt và con nhện chìm ngay.","Every water particle is tugged by its neighbours in all directions, so deep inside the pulls cancel. But a particle right at the SURFACE has nothing above it, only pulls downward and sideways — so the whole surface layer draws itself tight, like a skin. Piercing that skin means making more surface, and making surface costs energy, so the skin resists. It is also why a drop becomes a ball: a sphere is the shape with the least surface. Add one drop of soap and the skin fails and the strider goes under."])]),t("khong-khi",["Không Khí","Air"],["Không khí cũng là một thứ chất lỏng, chỉ là nhẹ và nhìn không thấy","Air is a fluid too — only light, and invisible"],[n("khong-khi-co-nang-khong",1,"te",["Không khí thì nhìn không thấy, cầm không được, và ta đi qua nó cả ngày mà không thấy vướng gì.","Air cannot be seen or held, and we walk through it all day without noticing."],["Không khí có nặng không?","Does air weigh anything?"],[["Không, nếu nặng thì đã rơi xuống đất hết rồi","No — if it weighed anything it would have fallen to the ground"],["Có, và cột không khí trên đầu bạn đè xuống rất mạnh","Yes, and the column of it above your head presses down hard"],["Chỉ nặng khi có gió","Only when it is moving as wind"]],1,["Một mét vuông mặt đất đang chịu khoảng mười tấn không khí đè xuống — cả cột khí cao hàng chục cây số phía trên. Ta không thấy nặng vì cái đè ấy đến từ mọi phía và bên trong người ta cũng đè ra đúng bấy nhiêu. Muốn thấy nó thì phải bỏ nó đi: hút hết khí ra khỏi một thùng thiếc kín, thùng bị bóp bẹp ngay tức khắc, và cái bóp ấy chính là không khí mà bạn vừa nói là không nặng.","Every square metre of ground carries about ten tonnes of air — the whole column tens of kilometres high above it. We do not feel it because it presses from every side and we press back from inside just as hard. To notice it you must take it away: pump the air out of a sealed tin and it crumples instantly, and the thing that crumpled it is the air you called weightless."]),n("hut-bang-ong-hut",2,"tp",["Cắm ống hút vào cốc nước rồi hút. Nước đi ngược lên trong ống, chống lại cả trọng lực, và vào miệng bạn.","Put a straw in a glass and suck. Water climbs the straw against gravity and reaches your mouth."],["Cái gì đẩy nước lên trong ống hút?","What drives the water up the straw?"],[["Miệng bạn hút, tức là kéo nước lên","Your mouth sucks — that is, it pulls the water up"],["Không khí bên ngoài đè xuống mặt nước trong cốc và ép nước lên ống","The outside air presses on the water in the glass and squeezes it up the straw"],["Ống hút có sức mao dẫn kéo nước lên","The straw draws water up by capillary action"]],1,["Không có cái gọi là lực hút ở đây. Việc duy nhất miệng bạn làm được là lấy bớt không khí trong ống ra, nghĩa là làm cái đè bên trong ống YẾU đi. Lúc đó cái đè của không khí bên ngoài lên mặt nước trong cốc thắng thế, và nó ép nước chui lên ống. Cái đè bên ngoài chỉ có chừng ấy, nên có hút giỏi tới đâu cũng chỉ nâng được cột nước cao khoảng 10 mét — đó là giới hạn cứng, và đó là lý do không có cái bơm hút nào lấy được nước từ giếng sâu hơn 10 mét lên, phải thả bơm xuống dưới mà đẩy lên.","There is no such thing as a pull here. The only thing your mouth can do is remove some air from the straw, which WEAKENS the press inside it. The outside air pressing on the surface in the glass then wins, and squeezes water up the tube. That outside press is finite, so no amount of sucking raises a column of water beyond about 10 metres — a hard ceiling, and the reason no suction pump can draw water from a well deeper than that; the pump has to go down and push."]),n("bong-bay-len-troi",2,"te",["Quả bóng bay bơm khí heli thì tuột tay là bay thẳng lên trời. Quả bóng bay thổi bằng miệng thì rơi xuống đất.","A balloon filled with helium shoots upward the moment you let go. A balloon you blew up yourself drops to the floor."],["Vì sao quả bóng heli bay lên?","Why does the helium one rise?"],[["Vì heli nhẹ hơn không khí mà nó chiếm chỗ, nên nó nổi trong không khí","Because helium is lighter than the air it displaces, so it floats in air"],["Vì heli không có trọng lượng","Because helium has no weight at all"],["Vì heli bị mặt trời hút lên","Because the Sun draws helium upward"]],0,["Đây đúng là chuyện con tàu nổi trên biển, chỉ đổi biển thành bầu khí quyển. Quả bóng gạt đi một khối không khí, và khối không khí ấy nặng hơn cả quả bóng lẫn thứ khí bên trong — nên phần chênh đẩy nó lên. Heli nặng bằng một phần bảy không khí; hơi bạn thổi ra thì nặng ngang không khí, cộng thêm vỏ cao su, nên quả bóng thổi miệng chìm trong khí quyển y như hòn đá chìm trong ao. Bay lên tới một độ cao nào đó thì không khí loãng đi và nhẹ bằng cả quả bóng, và nó dừng lại ở đó.","This is the floating ship again with the sea swapped for the atmosphere. The balloon shoves aside a volume of air, and that air weighs more than the balloon and its contents together — so the surplus lifts it. Helium weighs a seventh of air; your breath weighs about the same as air, and then there is the rubber, so a blown balloon sinks through the atmosphere like a stone through a pond. Climb far enough and the thinning air matches the balloon, and there it stops."]),n("bong-heli-trong-xe",3,"tp",["Trong một chiếc ô tô đóng kín cửa, buộc một quả bóng heli vào sàn bằng sợi dây ngắn nên nó lơ lửng giữa xe. Xe đang đứng yên thì dây thẳng đứng. Bây giờ xe rồ ga phóng tới trước.","Inside a car with the windows shut, a helium balloon is tethered by a short string to the floor and hangs in mid-air. Standing still, the string is vertical. Now the car accelerates forward."],["Quả bóng nghiêng về phía nào?","Which way does the balloon lean?"],[["Về phía sau, như người ngồi trong xe bị ép vào lưng ghế","Backwards, the way the passengers are pressed into their seats"],["Về phía trước","Forwards"],["Không nghiêng, vì nó không chạm vào gì cả","It does not lean — it is touching nothing"]],1,["Trong xe có không khí, và không khí thì NẶNG hơn quả bóng. Xe vọt tới thì khối không khí bị bỏ lại phía sau, dồn về đuôi xe — y hệt người ngồi bị ép vào ghế. Không khí dồn về sau thì phía sau đè mạnh hơn phía trước, và cái chênh đó đẩy vật NHẸ nhất trong xe ra phía trước. Quả bóng nghiêng về trước. Cũng vì lẽ đó, khi xe vào cua, quả bóng nghiêng vào PHÍA TRONG khúc cua, ngược hẳn với mọi người trong xe. Đây là một câu đố mà rất ít người lớn trả lời đúng ngay lần đầu.","The car is full of air, and air is HEAVIER than the balloon. As the car surges forward the body of air lags behind and piles up at the rear — exactly as the passengers are left against their seats. Piled at the rear, the air presses harder from behind than from in front, and that difference drives the LIGHTEST thing in the car forwards. The balloon leans forward. For the same reason it leans INTO a bend while everyone else leans out. Very few adults get this one right first time."]),n("bong-bay-len-cao-thi-sao",3,"te",["Thả một quả bóng thời tiết chỉ bơm căng vừa phải rồi để nó bay lên. Nó lên tới hơn ba mươi cây số, cao gấp ba lần máy bay hành khách, rồi kết thúc chuyến bay.","A weather balloon is filled only part way and released. It climbs past thirty kilometres, three times the height of an airliner, and then its flight ends."],["Trên đường lên cao, quả bóng thế nào?","On the way up, what happens to the balloon?"],[["Xẹp dần lại, vì trên cao lạnh","It shrinks, because it is cold up there"],["Phồng to dần ra, tới lúc vỏ chịu không nổi và nổ","It swells and swells until the skin gives way and it bursts"],["Giữ nguyên kích thước cho tới khi hết lực nâng","It keeps its size until the lift runs out"]],1,["Cái giữ cho quả bóng không phồng ra là không khí bên ngoài đè vào. Càng lên cao thì phía trên càng còn ít không khí, nên cái đè ấy càng yếu — ở 30 km chỉ còn khoảng một phần trăm so với mặt đất. Khí bên trong lập tức nở ra chiếm chỗ, và quả bóng lúc phóng chỉ to bằng cái ô tô có thể phồng lên to bằng cả căn nhà trước khi vỡ. Vì thế người ta bơm nó rất non lúc thả: chừa sẵn chỗ cho nó lớn. Cùng cái lý ấy làm tai bạn ù khi máy bay hạ cánh, và làm gói bim bim mua ở đồng bằng phồng căng lên khi mang lên núi.","What keeps the balloon from swelling is the outside air pressing in. The higher it climbs the less air remains above it, so the weaker that press — at 30 km only about one percent of what it is at the ground. The gas inside expands to fill the room, and a balloon the size of a car at launch can reach the size of a house before it splits. That is why it is filled so slackly: room is left for it to grow. The same fact pops your ears on landing, and puffs up a bag of crisps carried from the lowlands into the mountains."])])],b=[t("nong-len",["Nóng Lên","Getting Hot"],["Nóng không phải một chất — nó là các hạt bên trong chạy nhanh","Heat is not a substance — it is the particles inside moving fast"],[n("nong-la-gi",1,"te",["Đặt tay lên nắp nồi vừa đun. Nó nóng. Đặt tay lên viên gạch ngoài sân đêm. Nó lạnh. Cả hai đều làm bằng vật chất bình thường, không có gì bên trong chảy ra chảy vào.","Put a hand on a pan lid just off the stove: hot. Put it on a paving stone at night: cold. Both are ordinary matter, with nothing flowing in or out."],["Một vật nóng thì bên trong nó khác vật lạnh ở chỗ nào?","What is different inside a hot thing compared with a cold one?"],[["Trong vật nóng có chứa nhiều chất nhiệt hơn","The hot thing holds more of a substance called heat"],["Các hạt bé xíu tạo nên nó đang rung và chạy nhanh hơn","The tiny particles it is built from are jiggling and moving faster"],["Vật nóng nhẹ hơn vì nhiệt đẩy nó nở ra","The hot thing is lighter, because heat has puffed it up"]],1,['Mọi thứ đều làm từ những hạt rất bé không bao giờ đứng yên. Nóng chỉ có nghĩa là chúng rung mạnh hơn, chạy nhanh hơn — không có thêm chất gì cả. Nên "làm nóng" thực ra là truyền chuyển động: cọ xát, đập, nén, hay để cạnh một vật đã rung mạnh sẵn. Và vì thế "lạnh" cũng không phải một thứ có thể chảy vào đâu được — lạnh chỉ là ít rung. Bạn không bao giờ bơm được cái lạnh vào cốc nước; bạn chỉ lấy cái nóng ra khỏi nó.',"Everything is built from tiny particles that never hold still. Hot simply means they jiggle harder and travel faster — no extra substance is involved. So heating something is passing on motion: rubbing, hammering, squeezing, or standing it next to something already jiggling hard. And so cold is not a thing that can flow anywhere either — cold is just less jiggling. You never put cold into a glass of water; you only take heat out of it."]),n("van-lua-to-hon",2,"tp",["Nồi nước trên bếp đã sôi sùng sục. Bạn vặn lửa to gấp đôi. Nước vẫn sôi, chỉ dữ dội hơn.","A pan of water on the stove is boiling steadily. You turn the flame up to double. It still boils, just more violently."],["Nước bây giờ có nóng hơn không?","Is the water any hotter now?"],[["Có, nên luộc mì sẽ nhanh chín hơn","Yes — so the pasta will cook faster"],["Không, vẫn đúng 100 độ, chỉ cạn nhanh hơn","No — still exactly 100 degrees, just boiling away faster"],["Có, nhưng chỉ nóng hơn ở chỗ sát đáy nồi","Yes, but only right at the bottom of the pan"]],1,["Khi nước đã sôi thì mọi nhiệt đổ thêm vào không làm nó nóng lên nữa, mà đi hết vào việc bứt các hạt nước ra thành hơi. Nước sôi ở áp suất bình thường luôn là 100 độ, dù bếp gas nhỏ hay lò công nghiệp. Vặn to chỉ được đúng một thứ: nước bốc hơi nhanh hơn, tức là nồi cạn sớm hơn và bếp tốn gas hơn. Mì thì chín đúng như cũ. Đây là mẹo nấu ăn có thật: sôi rồi thì hạ lửa xuống mức vừa đủ giữ sôi.","Once water boils, extra heat no longer raises its temperature — it all goes into tearing particles loose as steam. Boiling water at ordinary pressure is 100 degrees whether the flame is a camping stove or a foundry. Turning it up buys exactly one thing: faster evaporation, which means an emptier pan and a bigger gas bill. The pasta cooks at the same rate. This is a real kitchen trick: once it boils, drop the flame to the least that keeps it boiling."]),n("dun-nuoc-va-dau",2,"tp",["Hai cái nồi giống hệt nhau trên hai bếp giống hệt nhau. Nồi thứ nhất đựng một lít nước, nồi thứ hai đựng một lít dầu ăn. Cả hai bắt đầu từ nhiệt độ phòng.","Two identical pans on two identical burners. One holds a litre of water, the other a litre of cooking oil. Both start at room temperature."],["Cái nào nóng lên nhanh hơn?","Which warms up faster?"],[["Nồi dầu","The oil"],["Nồi nước","The water"],["Nhanh như nhau, vì cùng một cái bếp","The same — one burner is like another"]],0,["Mỗi chất cần một lượng nhiệt khác nhau để nhích lên được một độ, và nước là một trong những chất khó nung nhất mà ta gặp hằng ngày: nó cần gấp đôi dầu ăn, gấp chín lần sắt, cho cùng một độ. Vì thế nồi dầu nóng vọt lên trong khi nồi nước còn ấm ấm. Cái tính lì lợm ấy của nước là lý do biển giữ cho khí hậu ven bờ dịu đi, là lý do người ta dùng nước để làm mát động cơ, và cũng là lý do cơ thể bạn — phần lớn là nước — không bị luộc chín mỗi lần trời nắng.","Every substance needs a different amount of heat to climb one degree, and water is among the most stubborn we meet daily: twice what oil needs, nine times what iron needs, for the same one degree. So the oil races up while the water is still merely warm. That stubbornness is why the sea softens the climate of a coast, why engines are cooled with water, and why your body — mostly water — is not cooked by an afternoon of sun."]),n("khuay-nuoc-thi-nong",2,"tp",["Một cái thùng nước cách nhiệt thật kỹ, bên trong có cánh khuấy nối với một quả tạ treo. Quả tạ tụt xuống, cánh khuấy quay, khuấy nước suốt mấy tiếng. Không có lửa, không có điện, không có gì nóng chạm vào.","A well-insulated tub of water with a paddle inside, driven by a falling weight. The weight sinks, the paddle turns, and the water is churned for hours. No flame, no electricity, nothing hot touching it."],["Nhiệt độ nước ra sao?","What happens to the temperature?"],[["Không đổi — khuấy thì làm sao mà nóng lên được","Unchanged — stirring cannot make anything hot"],["Nóng lên, đúng theo mức công mà quả tạ đã bỏ ra","It rises, by exactly as much work as the falling weight did"],["Lạnh đi, vì nước phải bỏ sức ra để quay cánh khuấy","It falls, because the water spends effort turning the paddle"]],1,["Đây là thí nghiệm mà James Joule làm giữa thế kỷ 19, và nó dứt điểm một cuộc tranh cãi kéo dài cả trăm năm. Trước đó người ta tin nhiệt là một chất lỏng vô hình chảy từ vật này sang vật kia — nếu thế thì cái thùng kín này không thể nào nóng lên được, vì có ai đổ chất ấy vào đâu. Nhưng nó nóng lên thật, và nóng lên đúng bằng công mà quả tạ bỏ ra. Nhiệt không phải một chất; nó là chuyển động. Đó cũng là lý do xoa hai bàn tay thì tay ấm lên, và lý do cái phanh xe đạp bốc mùi khét sau một con dốc dài.","This is the experiment James Joule ran in the middle of the nineteenth century, and it settled an argument a century old. People had believed heat was an invisible fluid poured from one body into another — in which case this sealed tub could never warm, since nobody poured anything in. But warm it does, by precisely the work the weight performed. Heat is not a substance; it is motion. It is also why rubbing your hands warms them, and why a bicycle brake smells scorched after a long descent."]),n("mo-cua-tu-lanh",3,"tp",["Một căn phòng đóng kín, không cửa sổ. Trời nóng. Bạn mở toang cửa tủ lạnh ra và để nguyên như thế cả buổi chiều, tủ vẫn cắm điện và chạy.","A sealed room with no windows on a hot day. You leave the refrigerator door wide open all afternoon, still plugged in and running."],["Cuối buổi chiều, phòng thế nào?","By the end of the afternoon, what has the room done?"],[["Mát hơn, dù không mát bằng để tủ đóng và ngồi cạnh","Cooler — not as cool as sitting by a closed fridge, but cooler"],["Nóng hơn lúc đầu","Hotter than when you started"],["Không đổi, vì tủ vừa lấy nhiệt vừa trả lại đúng bấy nhiêu","Unchanged — the fridge takes as much heat as it gives back"]],1,["Cái tủ lạnh không tiêu diệt nhiệt; nó chỉ BƠM nhiệt từ trong khoang ra bộ dàn nóng sau lưng nó. Mở cửa ra thì nó hút nhiệt ở phía trước rồi nhả đúng ngần ấy ra phía sau — hoà cả. Nhưng cái máy nén chạy bằng điện, và toàn bộ điện ấy cuối cùng cũng thành nhiệt trong phòng. Nên phòng nóng lên đúng bằng số điện cái tủ ăn. Đây là lý do một cái điều hoà bắt buộc phải có cục nóng đặt NGOÀI nhà: nếu để cả hai đầu trong một phòng thì nó là cái lò sưởi tốn tiền.","A refrigerator does not destroy heat; it PUMPS heat out of its box into the coils on its back. Open the door and it draws heat in at the front and dumps exactly that much out at the back — a wash. But the compressor runs on electricity, and every watt of it ends up as heat in that room. So the room warms by exactly what the fridge consumes. This is why an air conditioner must have its hot half OUTSIDE the house: with both ends in one room it is an expensive heater."])]),t("nguoi-di",["Nguội Đi","Cooling Down"],["Càng nóng hơn xung quanh thì càng mất nhiệt nhanh","The hotter you are than your surroundings, the faster you lose heat"],[n("thoi-vao-bat-chao",1,"tp",["Bát cháo nóng quá không ăn được. Bạn ghé miệng thổi lên mặt bát, một lúc là ăn được. Hơi bạn thổi ra thực ra ấm chừng 34 độ, tức là vẫn ấm hơn nhiệt độ phòng.","The porridge is too hot to eat. You blow across the bowl and soon it is fine. Your breath is actually about 34 degrees — warmer than the room."],["Vì sao thổi bằng hơi ấm lại làm bát cháo nguội nhanh hơn?","Why does blowing warm breath cool it faster?"],[["Vì hơi thổi ra thực ra lạnh khi ra khỏi miệng","Because the breath is actually cold by the time it leaves your lips"],["Vì nó thổi bay lớp hơi nóng ẩm đọng ngay trên mặt cháo đi","Because it sweeps away the layer of hot damp air sitting on the surface"],["Vì gió luôn làm mọi vật lạnh đi, dù gió nóng hay nguội","Because moving air cools anything, hot or cold"]],1,["Ngay trên mặt bát cháo có một lớp không khí mỏng đã bị hâm nóng và đã ngậm đầy hơi nước. Lớp ấy chắn đường: cháo không truyền nhiệt ra được nữa, và cũng không bốc hơi thêm được nữa. Thổi một cái là lớp ấy bay đi, nhường chỗ cho không khí phòng khô và mát. Mà bay hơi mới là cách bát cháo mất nhiệt nhiều nhất — mỗi giọt nước bay đi mang theo rất nhiều nhiệt. Đây cũng đúng là cách gió làm bạn rét run dù nhiệt độ không hề tụt.","Just above the porridge sits a thin film of air already warmed and already loaded with water vapour. That film blocks the way: no more heat can leave, and no more can evaporate. One breath clears it and lets in dry room air. And evaporation is how the bowl sheds most of its heat — every departing drop carries a great deal away. It is also exactly how wind chills you to shivering when the thermometer has not moved."]),n("sat-lanh-hon-go",2,"tp",["Trong cùng một căn phòng, để qua đêm một thanh sắt và một khúc gỗ. Sáng ra sờ vào: thanh sắt lạnh buốt, khúc gỗ thì âm ấm dễ chịu.","A bar of iron and a block of wood left overnight in one room. In the morning the iron feels icy and the wood feels comfortably warm."],["Nhiệt độ hai thứ đó thế nào?","What are their temperatures?"],[["Thanh sắt lạnh hơn thật, vì kim loại hút lạnh","The iron really is colder — metal attracts cold"],["Bằng nhau — cả hai đều bằng nhiệt độ phòng","Identical — both are at room temperature"],["Khúc gỗ ấm hơn thật, vì gỗ từng là cây sống","The wood really is warmer — it was once a living tree"]],1,['Để chung một phòng đủ lâu thì mọi thứ đều về đúng một nhiệt độ; cái nhiệt kế sẽ nói y hệt cho cả hai. Cái khác là tốc độ chúng RÚT nhiệt từ tay bạn. Sắt dẫn nhiệt rất nhanh nên nó kéo nhiệt khỏi ngón tay ào ào, và dây thần kinh của bạn báo về là "lạnh" — thứ nó đo được thực ra là tốc độ mất nhiệt, không phải nhiệt độ. Gỗ dẫn kém nên chỉ lấy đi chút ít, và cảm giác là ấm. Đây là lý do cùng 5 độ nhưng chạm vào tay vịn kim loại thì buốt hơn hẳn chạm vào tay vịn gỗ, và là lý do người ta lát sàn gỗ trong phòng ngủ.',"Left together long enough everything reaches one temperature; a thermometer says the same for both. What differs is how fast each DRAWS heat out of you. Iron conducts superbly and pulls warmth from a fingertip in a rush, and your nerves report cold — what they measure is the rate of loss, never the temperature. Wood conducts poorly and takes only a trickle, and reads as warm. It is why a metal handrail at 5 degrees bites and a wooden one at 5 degrees does not, and why bedrooms get wooden floors."]),n("chan-bong-co-lam-am-khong",2,"tp",["Đắp chăn bông thì ấm. Bây giờ lấy một cục nước đá, bọc thật kỹ trong chính cái chăn bông ấy, để trong phòng cả buổi.","A quilt keeps you warm. Now wrap a block of ice in that same quilt and leave it in the room for the afternoon."],["Cục nước đá thế nào?","What becomes of the ice?"],[["Tan nhanh hơn, vì chăn làm ấm nó","It melts faster — the quilt warms it"],["Tan chậm hơn hẳn so với để trần","It melts noticeably slower than it would bare"],["Tan đúng như để trần, chăn chỉ ấm với người sống","It melts at the same rate — quilts only warm living things"]],1,["Cái chăn không hề sinh ra nhiệt. Việc duy nhất nó làm là làm CHẬM đường đi của nhiệt — và nhiệt thì đi cả hai chiều. Với bạn, chăn giữ cái nóng bạn tự sinh ra khỏi thoát đi. Với cục đá, chăn giữ cái nóng của phòng khỏi tràn vào. Cùng một cái chăn, cùng một việc, hai kết quả trái ngược. Người bán kem dùng đúng nguyên lý ấy khi ủ thùng kem bằng chăn giữa trưa hè, và ai chưa nghĩ kỹ thì tưởng họ làm ngược.","A quilt makes no heat. The only thing it does is SLOW the passage of heat — and heat travels both ways. For you, it holds in the warmth you generate. For the ice, it holds out the warmth of the room. One quilt, one job, two opposite outcomes. Ice-cream sellers use exactly this when they wrap a tub in a blanket at noon, and anyone who has not thought it through assumes they have it backwards."]),n("do-sua-vao-ca-phe",3,"tp",["Một cốc cà phê vừa rót, rất nóng. Bạn phải đi ra ngoài mười phút rồi mới quay lại uống. Bạn có sẵn một hộp sữa lạnh để trong tủ mát, và bạn sẽ pha một lượng sữa như nhau dù pha lúc nào.","A cup of coffee just poured, very hot. You must step out for ten minutes before drinking it. You have cold milk from the fridge, and you will add the same amount whenever you add it."],["Muốn lúc quay lại cà phê còn nóng nhất, nên đổ sữa lúc nào?","To find it hottest when you return, when should the milk go in?"],[["Đổ ngay bây giờ, trước khi đi","Right now, before you leave"],["Đợi mười phút, lúc quay về mới đổ","After ten minutes, when you get back"],["Lúc nào cũng thế, vì tổng lượng sữa như nhau","It makes no difference — the same milk goes in either way"]],0,["Một vật mất nhiệt nhanh hay chậm là tuỳ nó nóng hơn xung quanh bao nhiêu: chênh càng lớn thì mất càng nhanh. Đổ sữa ngay là hạ cốc cà phê xuống thấp ngay từ đầu, nên suốt cả mười phút sau nó chỉ chênh ít với phòng và chỉ rỉ nhiệt ra chậm. Để nguyên cà phê nóng rẫy thì mười phút ấy nó xả nhiệt ra rất phí, rồi mới bị sữa hạ xuống thêm lần nữa. Muốn cà phê nóng thì làm nguội nó trước — nghe ngược đời, nhưng đó là điều đúng, và cũng là lý do vặn lò sưởi nhỏ suốt ngày tốn hơn là tắt hẳn rồi bật lại.","How fast a thing sheds heat depends on how far above its surroundings it sits: the bigger the gap, the faster the loss. Adding milk now drops the cup low straight away, so for the whole ten minutes it sits close to the room and leaks slowly. Left scalding, it squanders heat for ten minutes and only then gets cooled by the milk anyway. To keep coffee hot, cool it first — it sounds backwards, and it is right, and it is the same reason leaving a heater on low all day costs more than switching it off and back on."]),n("tat-lo-suoi-hay-khong",3,"tp",["Mùa đông xứ lạnh. Bạn ra khỏi nhà bốn tiếng. Về nhà bạn muốn phòng ấm 20 độ, ngoài trời 0 độ. Hai cách: để lò sưởi chạy giữ 20 độ suốt bốn tiếng, hoặc tắt hẳn rồi bật lại mạnh trước khi về.","Winter in a cold country. You are out for four hours and want the room at 20 degrees on return; outside is 0. Either leave the heater holding 20 the whole time, or switch it off and blast it back up before you return."],["Cách nào tốn ít năng lượng hơn?","Which uses less energy overall?"],[["Giữ ấm suốt, vì hâm lại từ đầu tốn hơn nhiều","Holding it warm — reheating from scratch costs far more"],["Tắt hẳn rồi bật lại","Switching it off and reheating"],["Bằng nhau, vì cuối cùng vẫn phải đưa phòng về 20 độ","The same — either way the room ends at 20"]],1,["Nhiệt thoát khỏi căn nhà theo mức chênh giữa trong và ngoài. Giữ 20 độ suốt là giữ mức chênh 20 độ suốt bốn tiếng, và trả tiền cho từng phút rò rỉ ấy. Tắt đi thì phòng nguội dần, mức chênh nhỏ dần, nên nó rò rỉ mỗi lúc một ít — tổng lượng thất thoát nhỏ hơn hẳn. Đúng là lúc bật lại bạn phải hâm nóng cả căn phòng và đồ đạc, nhưng phần đó nhỏ hơn phần bạn vừa tiết kiệm được. Cùng một lý ấy đúng cho tủ lạnh, cho bình nước nóng, và cho cốc cà phê ở câu trước — chỉ là lộn ngược chiều nóng lạnh.","Heat leaves a house in proportion to the gap between inside and out. Holding 20 keeps that gap at 20 for four solid hours and pays for every minute of leakage. Switching off lets the room cool, the gap shrink, and the leak slow with it — a far smaller total loss. Yes, reheating must warm the room and its furniture again, but that costs less than what you saved. The same reasoning covers refrigerators, hot water tanks, and the coffee in the previous question, only with hot and cold swapped."])]),t("soi-va-hoi",["Sôi & Hơi","Boiling & Steam"],["Đổi từ nước sang hơi tốn nhiều nhiệt hơn cả việc đun nó lên","Turning water into steam costs more heat than all the heating did"],[n("soi-tren-nui-cao",1,"tp",["Trên đỉnh một ngọn núi cao 4000 mét, bạn đun nước pha mì. Nước sôi sùng sục hẳn hoi, nhưng gói mì mãi không chín, phải chờ lâu gấp mấy lần ở nhà.","On a mountain 4000 metres up you boil water for noodles. It boils vigorously, yet the noodles take several times as long as at home."],["Vì sao?","Why?"],[["Vì trên cao lạnh nên bếp yếu đi","Because the cold thin air weakens the stove"],["Vì trên cao nước sôi ở nhiệt độ thấp hơn 100 độ","Because up there water boils below 100 degrees"],["Vì gói mì trên núi bị khô hơn","Because the noodles themselves have dried out"]],1,["Nước sôi khi các hạt của nó đủ mạnh để đẩy bật không khí phía trên ra mà thoát đi. Trên cao, cột không khí phía trên mỏng đi nên đè xuống nhẹ hơn — nước không cần nóng bằng vẫn thoát được. Ở 4000 mét, nước sôi khoảng 86 độ. Sôi không có nghĩa là nóng đủ: cái nấu chín món ăn là NHIỆT ĐỘ chứ không phải mấy cái bọt. Đây là lý do sách nấu ăn ở vùng cao ghi thời gian riêng, và là lý do người leo núi mang theo nồi áp suất.","Water boils when its particles can shove the air above aside and escape. Higher up, the column of air is thinner and presses more lightly — so less heat is needed for the escape. At 4000 metres water boils at about 86 degrees. Boiling does not mean hot enough: what cooks food is TEMPERATURE, not bubbles. It is why high-altitude cookbooks print their own times, and why mountaineers carry a pressure cooker."]),n("noi-ap-suat",2,"te",["Nồi áp suất là cái nồi có nắp vặn kín, chỉ chừa một cái van nhỏ. Ninh một nồi xương bằng nồi thường mất bốn tiếng; bằng nồi áp suất mất bốn mươi phút.","A pressure cooker is a pan with a lid that screws down tight, leaving only a small valve. A pot of bones takes four hours in an ordinary pan and forty minutes in this one."],["Vì sao nó nấu nhanh hơn nhiều đến thế?","Why is it so much faster?"],[["Vì nắp kín giữ nhiệt lại không cho thoát ra","Because the tight lid stops heat escaping"],["Vì hơi bị nhốt lại đè xuống mặt nước, nên nước sôi ở khoảng 120 độ chứ không phải 100","Because the trapped steam presses on the water, so it boils at about 120 degrees rather than 100"],["Vì áp suất cao ép thức ăn cho mềm ra","Because the pressure squeezes the food soft"]],1,["Đây là câu núi cao lộn ngược lại. Hơi nước thoát ra bị nhốt trong nồi, dồn lại, đè xuống mặt nước mỗi lúc một mạnh — mà đè càng mạnh thì nước càng phải nóng hơn mới sôi được. Ở gấp đôi áp suất thường, nước sôi ở khoảng 120 độ. Thêm 20 độ nghe ít, nhưng tốc độ nấu chín tăng rất nhanh theo nhiệt độ: cứ mỗi 10 độ thì nhanh lên khoảng gấp đôi. Cái van xì xì trên nắp không phải để thoát nhiệt — nó là cái chốt an toàn giữ cho áp suất không vượt quá mức nồi chịu được.","This is the mountain in reverse. The escaping steam is trapped, builds up, and presses ever harder on the surface — and the harder the press, the hotter water must be before it can boil. At twice ordinary pressure it boils at about 120 degrees. Twenty degrees sounds slight, but cooking speeds up steeply with temperature: roughly double for every ten. The hissing valve on top is not there to let heat out — it is the safety catch that stops the pressure passing what the pan can hold."]),n("mo-hoi-lam-mat",2,"te",["Chạy bộ giữa trưa, người đầm đìa mồ hôi. Ngồi trước quạt thì mát hẳn. Nhưng nếu trời vừa nóng vừa ẩm sau cơn mưa thì mồ hôi chảy ròng mà vẫn không thấy mát chút nào.","Running at noon leaves you drenched in sweat. Sit in front of a fan and you cool right down. But on a hot muggy day after rain the sweat pours and you feel no cooler at all."],["Mồ hôi làm mát cơ thể bằng cách nào?","How does sweat cool a body?"],[["Bằng chính cái ướt lạnh của nó trên da","By the cold wetness of it lying on the skin"],["Bằng cách bay hơi — mỗi giọt bay đi mang theo rất nhiều nhiệt","By evaporating — every drop that leaves carries off a great deal of heat"],["Bằng cách mở lỗ chân lông cho nhiệt thoát ra","By opening the pores so heat can get out"]],1,["Muốn bứt một hạt nước ra khỏi mặt da và biến nó thành hơi thì phải tốn rất nhiều nhiệt — nhiều hơn cả việc đun chính giọt nước ấy từ lạnh lên tới sôi. Nhiệt ấy lấy ngay từ da bạn, nên da nguội đi. Mồ hôi CHẢY thì không làm mát gì cả, mồ hôi BAY HƠI mới làm mát. Ngày ẩm thì không khí đã ngậm gần đủ nước rồi nên mồ hôi không bay đi được, và cơ chế làm mát của cơ thể đứng hình — đó chính là lý do trời nồm oi bức nguy hiểm hơn trời nắng khô cùng nhiệt độ.","Tearing a water particle off your skin and turning it into vapour costs a great deal of heat — more than heating that same drop from cold all the way to boiling. That heat is taken straight out of your skin, and your skin cools. Sweat that RUNS cools nothing; sweat that EVAPORATES cools everything. On a muggy day the air is already nearly full of water, the sweat cannot leave, and the whole cooling system stalls — which is why humid heat is more dangerous than dry heat at the same reading."]),n("hoi-nuoc-bong-nang-hon",3,"tp",["Nước sôi và hơi nước bốc lên từ nồi đều ở 100 độ. Nhưng ai từng bị hơi nồi phụt vào tay đều biết vết bỏng ấy nặng hơn hẳn so với nhúng tay vào nước sôi cùng một khoảnh khắc.","Boiling water and the steam above it are both at 100 degrees. Yet anyone scalded by a jet of steam knows it burns far worse than a moment in boiling water."],["Vì sao hơi nước cùng nhiệt độ lại bỏng nặng hơn nhiều?","Why does steam at the same temperature burn so much worse?"],[["Vì hơi phụt ra nhanh nên bắn sâu vào da","Because the jet is fast and drives into the skin"],["Vì khi hơi chạm da lạnh nó ngưng lại thành nước, và nhả ra toàn bộ số nhiệt đã tốn để biến nước thành hơi","Because on cool skin the steam condenses back to water and releases all the heat that turning it into steam had cost"],["Vì hơi nước thực ra nóng hơn 100 độ","Because steam is actually hotter than 100 degrees"]],1,["Biến một kilogam nước ở 100 độ thành hơi ở 100 độ tốn thêm một lượng nhiệt khổng lồ — bằng cỡ nhiệt để đun cũng chừng ấy nước từ 20 độ lên tới 100 tới hơn năm lần. Nhiệt ấy không làm nóng thêm chút nào, nó chỉ nằm im trong hơi. Đến khi hơi chạm vào da và ngưng lại, toàn bộ số nhiệt ấy đổ ra một lúc, ngay tại chỗ. Cũng chính vì lượng nhiệt giấu ấy mà hơi nước được dùng để chạy tuốc-bin trong mọi nhà máy điện, và để sưởi cả một thành phố qua đường ống.","Turning a kilogram of water at 100 into steam at 100 costs an enormous extra amount of heat — more than five times what it took to warm that water from 20 up to 100 in the first place. That heat raises the temperature not at all; it just sits inside the steam. When the steam meets skin and condenses, all of it comes out at once, right there. It is that hidden store which drives the turbines of every power station and heats whole cities through pipes."]),n("giot-nuoc-nhay-tren-chao",3,"tp",["Rắc vài giọt nước lên một cái chảo hơi nóng: chúng xèo lên rồi biến mất trong một, hai giây. Bây giờ nung chảo lên thật nóng, đỏ già, rồi rắc đúng ngần ấy nước.","Flick a few drops onto a moderately hot pan: they hiss and vanish in a second or two. Now heat the pan until it is glowing hot and flick on the same drops."],["Chuyện gì xảy ra với giọt nước trên cái chảo nóng hơn nhiều đó?","What do the drops do on the much hotter pan?"],[["Biến mất tức khắc, nhanh hơn hẳn lần trước","Vanish instantly, far faster than before"],["Co thành hòn bi tròn, trượt nhảy lung tung trên mặt chảo cả phút mới hết","Draw into little beads that skate about the pan for a full minute before going"],["Bắn tung toé ra khỏi chảo ngay","Spit straight off the pan"]],1,["Chảo quá nóng thì mặt dưới giọt nước hoá hơi ngay tức khắc, và lớp hơi ấy nâng cả giọt nước lên khỏi mặt chảo. Mà hơi thì dẫn nhiệt rất kém — nên từ giây đó trở đi giọt nước nằm trên cái đệm hơi của chính nó, gần như cách nhiệt hoàn toàn với cái chảo, và nó sống thọ hơn hẳn so với lúc chảo mát hơn. Nóng hơn lại làm chậm đi: đây là một trong ít chỗ mà tăng một thứ lên lại cho kết quả ngược. Người thợ rèn dùng đúng hiện tượng này để ướm tay ướt lên sắt nung mà không bỏng, và nó cũng là lý do đầu bếp hay vẩy nước lên chảo để đo xem chảo đã đủ nóng chưa.","On a very hot pan the underside of the drop flashes to vapour at once, and that vapour lifts the whole drop clear of the metal. Vapour conducts heat poorly — so from that moment the drop rides on a cushion of its own making, all but insulated from the pan, and outlives what it managed on the cooler one. Hotter makes it slower: one of the few places where turning something up reverses the result. Smiths use it to touch wet fingers to glowing iron unburnt, and cooks use it to test when a pan is ready."])]),t("no-ra",["Nở Ra","Expanding"],["Nóng lên thì gần như mọi thứ đều to ra — và không gì cản nổi","Warm nearly anything and it grows — and nothing stops it"],[n("khe-ho-duong-ray",1,"te",["Đường ray xe lửa kiểu cũ không phải một thanh liền: cứ vài chục mét lại có một khe hở nhỏ giữa hai thanh, và đó là cái làm nên tiếng lịch kịch đều đều khi ngồi trên tàu.","Old railway track is not one long bar: every few dozen metres there is a small gap between rails, and that gap is what makes the steady clack you hear on board."],["Cái khe ấy để làm gì?","What is the gap for?"],[["Để thợ dễ tháo ra thay từng thanh","So that workers can lift out one rail at a time"],["Để chừa chỗ cho thanh ray dài ra khi trời nóng","To leave room for the rail to grow longer in hot weather"],["Để nước mưa thoát xuống dưới","To let rainwater drain away"]],1,["Sắt nóng lên thì dài ra. Một thanh ray 25 mét, giữa mùa đông và trưa hè có thể chênh nhau hơn một xăng-ti-mét. Nghe thì nhỏ, nhưng nếu không chừa chỗ thì các thanh chống nhau và cả tuyến đường bị đẩy cong vặn lên khỏi nền — chuyện ấy đã xảy ra và gây lật tàu. Cầu thép cũng có khe co giãn ở hai đầu, ống dẫn dầu chạy hình chữ chi chứ không chạy thẳng, và mọi con đường bê tông đều có mạch cắt ngang đều đặn: tất cả cùng một lý do.","Iron grows when it warms. A 25-metre rail can differ by more than a centimetre between a winter night and a summer noon. It sounds slight, but with no room to grow the rails jam against each other and the whole line buckles up off its bed — this has happened and has derailed trains. Steel bridges get expansion joints at their ends, oil pipelines run in zigzags rather than straight, and every concrete road is cut across at regular intervals: all the same reason."]),n("nap-lo-chat-qua",2,"te",["Cái lọ thuỷ tinh có nắp kim loại vặn chặt quá, không ai mở nổi. Mẹo cũ: dốc ngược cái nắp vào dòng nước nóng chừng nửa phút, rồi vặn — nắp bung ra dễ dàng.","A glass jar with a metal lid screwed on too tight for anyone. The old trick: hold the lid under hot running water for half a minute and then twist — it comes away easily."],["Vì sao mẹo ấy có tác dụng?","Why does the trick work?"],[["Vì nước nóng làm trơn ren nắp","Because the hot water lubricates the thread"],["Vì kim loại nở ra nhiều hơn thuỷ tinh, nên cái nắp rộng ra khỏi cổ lọ","Because metal grows more than glass, so the lid widens off the neck"],["Vì hơi nóng làm mềm cái nắp","Because the heat softens the lid"]],1,["Cả nắp lẫn cổ lọ đều nở ra khi nóng, nhưng không nở bằng nhau: kim loại nở gấp mấy lần thuỷ tinh cho cùng một độ. Nên chỉ cần dội nóng ĐÚNG cái nắp là nó lớn ra nhanh hơn cái cổ lọ bên dưới, và mối siết lỏng đi. Chính vì thế phải dội vào nắp chứ đừng nhúng cả cái lọ vào nước nóng — nhúng cả lọ thì hai bên cùng nóng lên và bạn được lợi ít hơn nhiều. Cái tính nở khác nhau của hai kim loại còn được dùng làm cái ngắt điện tự động trong bàn là và ấm siêu tốc: hai lá kim loại dán vào nhau, nóng lên thì cong đi và ngắt mạch.","Both lid and neck grow with heat, but not equally: metal grows several times as much as glass for the same rise. So warming JUST the lid makes it outgrow the neck beneath and the grip loosens. That is why you warm the lid rather than dunk the whole jar — dunk it and both warm together and you gain far less. The same difference between two metals makes the automatic cut-out in an iron or a kettle: two strips bonded together bend as they warm and break the circuit."]),n("binh-xang-tran-ra",2,"te",["Đổ xăng đầy ắp tới miệng bình vào buổi sáng sớm mát trời, rồi đỗ xe ngoài nắng cả buổi trưa. Về tới nơi thì thấy xăng đã rỉ ra loang dưới gầm xe.","Fill the tank right to the brim on a cool morning, then leave the car in the midday sun. You come back to fuel weeping out under the car."],["Vì sao?","Why?"],[["Vì nắng làm xăng bốc hơi rồi đẩy phần lỏng ra ngoài","Because the sun boils some fuel to vapour and it pushes the rest out"],["Vì xăng nở ra khi nóng, nhiều hơn hẳn cái bình thép chứa nó","Because the fuel grows when warm, far more than the steel tank does"],["Vì bình thép co lại khi nóng nên bóp xăng ra","Because the steel tank shrinks in the heat and squeezes the fuel out"]],1,["Chất lỏng nở nhiều hơn chất rắn rất nhiều — xăng nóng thêm 20 độ thì phình ra khoảng hai phần trăm, còn cái bình thép thì gần như không nhúc nhích. Đổ đầy tới miệng là không chừa chỗ cho phần phình ấy, nên nó phải trào ra. Đây là lý do cây xăng luôn ngắt vòi khi bình gần đầy chứ không cố nhét thêm, và là lý do mọi bình chứa chất lỏng — từ chai nước ngọt tới bồn dầu — đều chừa một khoảng trống trên đỉnh. Chính cái tính nở nhiều của chất lỏng làm nên cái nhiệt kế: một cột chất lỏng trong ống thuỷ tinh hẹp, nở ra một tí là dâng lên trông thấy.","Liquids grow far more than solids — warm petrol by 20 degrees and it swells about two percent, while the steel tank barely stirs. Filled to the brim there is nowhere for that swelling to go, so out it comes. It is why a fuel pump cuts off near full rather than forcing in more, and why every liquid container from a soft drink bottle to an oil tank keeps an empty space at the top. That same generous swelling is what makes a thermometer work: a thread of liquid in a narrow glass tube climbs visibly on the smallest change."]),n("lo-tren-tam-kim-loai",3,"tp",["Một tấm thép có khoan một cái lỗ tròn ở giữa. Đem cả tấm thép nung nóng lên thật đều.","A steel plate with a round hole drilled through the middle. The whole plate is heated evenly."],["Cái lỗ ra sao?","What happens to the hole?"],[["Nhỏ lại, vì thép quanh nó nở vào lấp bớt","It shrinks — the steel around it grows inward"],["To ra","It grows"],["Không đổi, vì lỗ là chỗ trống, chỗ trống thì không nở","It stays the same — a hole is nothing, and nothing does not expand"]],1,["Cách chắc nhất để thấy: lấy bút vẽ một vòng tròn lên tấm thép LIỀN, không khoan gì cả, rồi nung nóng. Cái vòng tròn vẽ ấy to ra, vì mọi khoảng cách trên tấm thép đều to ra theo. Bây giờ khoan bỏ đúng phần bên trong vòng vẽ đi — phần thép còn lại có biết là bên trong nó đã bị lấy đi hay chưa đâu, nên nó vẫn giãn y như thế. Cái lỗ to ra đúng theo tỉ lệ ấy. Nói cách khác, nung nóng một vật thì nó phóng to lên như một tấm ảnh được phóng, mọi kích thước cùng nhân lên một con số — kể cả các chỗ trống. Thợ máy dùng đúng chuyện này để lắp vòng bi: nung nóng cái vòng cho lỗ rộng ra, tròng vào trục, rồi để nguội siết chặt lại.","The surest way to see it: draw a circle in ink on a SOLID plate, drill nothing, and heat it. The drawn circle grows, because every distance on the plate grows. Now drill out exactly what was inside that circle — the remaining steel has no way of knowing the middle has gone, so it stretches just as before. The hole grows in the same proportion. Put another way, heating a thing enlarges it like a photograph, every dimension multiplied by one number, empty spaces included. Machinists use precisely this to fit bearings: heat the ring so the bore opens, slide it on, let it cool and grip."]),n("chan-hai-dau-khong-cho-no",3,"tp",["Một dầm cầu bê tông dài 30 mét. Giữa hè nó dài thêm chừng một xăng-ti-mét so với giữa đông, nên người ta chừa khe co giãn hai đầu. Giả sử người thiết kế quên, xây bịt cứng cả hai đầu vào mố cầu.","A 30-metre concrete beam on a bridge. In midsummer it is about a centimetre longer than in midwinter, and expansion joints are left at each end for it. Now suppose the designer forgot, and cast both ends solidly into the abutments."],["Trưa hè, chuyện gì xảy ra?","What happens on a summer afternoon?"],[["Không sao cả, một xăng-ti-mét thì bê tông chịu được","Nothing much — concrete can absorb a centimetre"],["Dầm tự bẻ gãy hoặc đẩy vỡ mố cầu, vì lực nở của vật rắn cực lớn","The beam breaks itself or bursts the abutment — the force of expansion is enormous"],["Dầm cong võng xuống nhưng vẫn nguyên vẹn","The beam sags but survives intact"]],1,["Chặn không cho một vật rắn nở ra chính là ép nó lại đúng bằng ngần ấy — và bê tông thì cực kỳ khó ép. Muốn ép một dầm 30 mét ngắn lại một xăng-ti-mét phải dùng một lực cỡ hàng nghìn tấn, lớn hơn nhiều lần cái trọng lượng mà cây cầu được thiết kế để đỡ. Nên hoặc dầm nứt, hoặc mố vỡ, hoặc cả tấm bị đẩy trồi lên. Đây là lý do khe co giãn không phải chi tiết làm cho đẹp mà là bộ phận chịu lực: nó không đỡ gì cả, nó chỉ NHƯỜNG CHỖ — và nhường chỗ đúng lúc là một việc kỹ thuật nghiêm túc.","Stopping a solid from expanding is the same as squeezing it by that much — and concrete is desperately hard to squeeze. Compressing a 30-metre beam by a centimetre calls for a force of thousands of tonnes, many times what the bridge was ever built to carry. So either the beam cracks, or the abutment bursts, or the deck is shoved upward. This is why an expansion joint is not decoration but a structural part: it holds nothing up, it only GETS OUT OF THE WAY — and getting out of the way at the right moment is serious engineering."])]),t("giu-nhiet",["Giữ Nhiệt","Holding Heat In"],["Nhiệt đi được ba đường, và bịt cả ba mới gọi là giữ","Heat travels by three roads, and holding it means blocking all three"],[n("phich-nuoc-giu-nong",1,"te",["Cái phích nước nóng: một bình thuỷ tinh hai lớp, giữa hai lớp đã hút hết không khí ra, và mặt trong tráng một lớp bạc bóng như gương.","A vacuum flask: a glass vessel with two walls, the space between them pumped empty of air, and the facing surfaces silvered like a mirror."],["Ba chi tiết ấy cùng làm một việc gì?","What single job are those three details doing?"],[["Chặn cả ba đường mà nhiệt có thể đi ra","Blocking all three roads by which heat could get out"],["Giữ cho nước không sánh ra ngoài","Keeping the water from slopping about"],["Làm cho nước tự sinh thêm nhiệt","Making the water generate more heat of its own"]],0,["Nhiệt chỉ có ba đường ra. Nó có thể truyền dọc theo vật rắn — nên thành phích làm bằng thuỷ tinh, thứ dẫn nhiệt rất kém, và hai lớp chỉ dính nhau ở một chỗ nhỏ trên cổ. Nó có thể theo dòng không khí bò đi — nên người ta hút sạch không khí giữa hai lớp, không còn gì để mà bò. Và nó có thể tự bức xạ ra thành ánh sáng vô hình — nên hai mặt được tráng bạc để hắt bức xạ ấy quay ngược trở lại. Bịt đủ cả ba thì nước còn nóng cả ngày. Bịt hai bỏ một thì nguội trong một tiếng.","Heat has only three roads out. It can travel along solid material — so the walls are glass, a poor conductor, and the two of them touch only at a small ring at the neck. It can ride along moving air — so the air between the walls is pumped away, leaving nothing to ride on. And it can radiate as invisible light — so both faces are silvered to throw that radiation back. Block all three and the water stays hot all day. Block two and it is cold within the hour."]),n("ao-len-giu-am-bang-gi",2,"te",["Áo len, chăn bông, lông chim, xốp, tường hai lớp: những thứ giữ ấm tốt nhất đều xốp và đầy lỗ nhỏ li ti bên trong.","Wool, quilts, feathers, foam, cavity walls: the best warm things are all fluffy and riddled with tiny pockets."],["Cái gì thật sự giữ ấm trong những thứ đó?","What is actually doing the insulating?"],[["Chính sợi len và sợi bông, vì chúng ấm sẵn","The wool and cotton fibres themselves, being warm by nature"],["Lớp không khí bị nhốt lại và giữ cho đứng yên trong các lỗ nhỏ","The air trapped in the pockets and kept from moving"],["Lớp mỡ tự nhiên còn sót trong sợi lông","The natural grease left in the fibres"]],1,["Không khí đứng yên là một trong những thứ cách nhiệt tốt nhất mà thiên nhiên có. Vấn đề là không khí không chịu đứng yên: hễ một chỗ ấm lên là nó bò đi và mang nhiệt theo. Nên mọi vật liệu giữ ấm thực chất chỉ làm một việc — chia không khí ra thành hàng triệu ngăn bé xíu để nó không bò đi đâu được. Cái áo len không ấm, chỗ trống trong cái áo len mới ấm. Vì thế áo len bị ướt thì mất tác dụng ngay (nước chiếm chỗ không khí và dẫn nhiệt gấp hai mươi lần), và vì thế mặc ba áo mỏng ấm hơn một áo dày cùng cân nặng: ba áo thì có thêm hai lớp khí kẹp giữa.","Still air is among the finest insulators there is. The trouble is that air refuses to stay still: warm one patch and it crawls away carrying the heat. So every warm material really does one job — dividing air into millions of pockets too small to crawl in. The jumper is not warm; the gaps in the jumper are warm. Which is why a soaked jumper is useless at once (water takes the place of the air and conducts twenty times better), and why three thin layers beat one thick one of the same weight: three layers add two more films of trapped air."]),n("dem-quang-may-lanh-hon",2,"te",["Hai đêm mùa đông liền nhau, gió như nhau. Đêm thứ nhất trời đầy mây thấp. Đêm thứ hai trời quang, sao đầy trời. Sáng ra đêm thứ hai lạnh hơn hẳn, có khi có sương muối.","Two winter nights in a row, the same wind. The first is thick with low cloud, the second is clear and full of stars. The clear morning is markedly colder, sometimes with frost."],["Vì sao đêm quang mây lại lạnh hơn?","Why is the clear night colder?"],[["Vì không có mây thì ánh sao chiếu xuống làm lạnh mặt đất","Because with no cloud the starlight chills the ground"],["Vì mây chặn nhiệt mà mặt đất bức xạ ngược lên, hắt nó trở xuống","Because cloud blocks the heat the ground radiates upward and throws it back down"],["Vì đêm quang thì gió trên cao mạnh hơn","Because the wind aloft is stronger on a clear night"]],1,["Suốt đêm, mặt đất bức xạ nhiệt lên trời dưới dạng ánh sáng hồng ngoại, thứ mắt không thấy. Trời quang thì bức xạ ấy đi thẳng ra ngoài không gian và mất hẳn — mặt đất coi như đang phơi mình trước cái lạnh của vũ trụ. Có mây thì hơi nước trong mây hấp thụ bức xạ ấy rồi phát ngược trở xuống, nên một phần lớn quay lại. Mây là cái chăn của Trái Đất, đúng nghĩa đen. Đây là cùng một cơ chế mà các khí nhà kính đang làm ở quy mô cả hành tinh, và cũng là lý do người trồng rau hay phủ nilon cho luống rau trong những đêm quang trời nhất.","All night the ground radiates heat skyward as infrared light, invisible to us. On a clear night that radiation goes straight out to space and is gone — the ground is bare to the cold of the universe. With cloud, the water vapour in it absorbs the radiation and re-emits it downward, and much of it comes back. Cloud is the blanket of the Earth, quite literally. It is the same mechanism the greenhouse gases run at planetary scale, and the reason growers throw sheeting over their beds on precisely the clearest nights."]),n("guong-lom-chieu-vao-cuc-da",3,"tp",["Một cái gương lõm lớn, ở tiêu điểm đặt một nhiệt kế rất nhạy. Chĩa gương vào đống lửa thì nhiệt kế vọt lên — chuyện đó ai cũng đoán được. Bây giờ chĩa cái gương ấy vào một tảng nước đá lớn.","A big concave mirror with a sensitive thermometer at its focus. Aim it at a fire and the reading leaps — no surprise. Now aim the same mirror at a large block of ice."],["Nhiệt kế làm gì?","What does the thermometer do?"],[["Đứng yên, vì cục đá đâu có phát ra gì","Holds still — ice gives out nothing"],["Tụt xuống thấy rõ","Falls, noticeably"],["Nhích lên một chút, vì cục đá vẫn ấm hơn không độ tuyệt đối","Rises a little — the ice is still above absolute zero"]],1,['Nhiệt kế tụt thật, và câu trả lời KHÔNG phải là "cái gương gom cái lạnh lại". Không có cái gì gọi là tia lạnh. Chuyện là: mọi vật đều bức xạ nhiệt ra xung quanh, và vật càng nóng thì bức xạ càng mạnh. Cái nhiệt kế bức xạ về phía cục đá, cục đá cũng bức xạ về phía nhiệt kế — nhưng cục đá lạnh hơn nên gửi lại ít hơn. Cái gương chỉ làm một việc là nối hai bên lại cho chặt. Kết quả là nhiệt kế cho đi nhiều hơn nhận về, nên nó nguội. "Lạnh" ở đây, đúng như mọi chỗ khác, chỉ là một cách nói về việc mất nhiệt nhanh hơn nhận nhiệt.',"The reading really does fall, and the answer is NOT that the mirror gathers cold. There is no such thing as a ray of cold. What happens is this: everything radiates heat to its surroundings, and the hotter it is the more it sends. The thermometer radiates towards the ice; the ice radiates back — but being colder it returns less. All the mirror does is couple the two firmly together. The thermometer therefore gives out more than it takes in, and it cools. Cold here, as everywhere, is only a way of saying that losses outrun gains."]),n("nha-mai-ton-va-mai-ngoi",3,"te",["Hai căn nhà cạnh nhau giữa trưa nắng. Một nhà lợp tôn kim loại mỏng, một nhà lợp ngói đất nung dày. Bên trong nhà mái tôn nóng như lò, nhà mái ngói dễ chịu hơn nhiều.","Two houses side by side at noon. One is roofed with thin metal sheet, the other with thick fired clay tiles. Inside, the metal-roofed house is an oven and the tiled one is far more bearable."],["Đâu là lý do chính?","What is the main reason?"],[["Tôn màu sáng nên hút nắng nhiều hơn ngói màu đỏ","The pale metal absorbs more sun than the red tile does"],["Tôn mỏng và dẫn nhiệt cực nhanh nên nhiệt xuyên qua tức thời; ngói dày và dẫn kém nên nhiệt bò qua mất hàng giờ","Thin metal conducts superbly and heat crosses at once; thick tile conducts poorly and heat takes hours to creep through"],["Ngói có lỗ nhỏ cho nhiệt thoát ngược ra ngoài","Tiles have pores that let heat escape back out"]],1,["Kim loại dẫn nhiệt nhanh gấp hàng trăm lần đất nung, mà tấm tôn lại chỉ dày chưa tới một ly. Nên nắng đổ lên tôn thì mặt dưới nóng gần như cùng lúc với mặt trên, và nó bức xạ thẳng xuống đầu người ở dưới. Viên ngói dày mấy phân, dẫn kém, lại còn rỗng ở giữa — nhiệt phải bò qua mất mấy tiếng, và khi nó bò tới nơi thì mặt trời đã lặn và mái đã bắt đầu nguội. Đây gọi là độ trễ nhiệt, và nó là lý do các ngôi nhà cổ ở xứ nóng đều xây tường rất dày: không phải để chặn nhiệt hẳn, mà để làm nhiệt tới TRỄ, tới lúc trời đã mát.","Metal conducts hundreds of times better than fired clay, and the sheet is under a millimetre thick. So sun on the metal warms its underside almost as soon as its top, and it radiates straight down onto the people below. A tile is centimetres thick, conducts poorly, and is often hollow inside — the heat takes hours to creep across, and by the time it arrives the sun has set and the roof has begun to cool. This is thermal lag, and it is why old houses in hot countries have very thick walls: not to stop the heat but to make it arrive LATE, when the evening has come."])])],v=[t("tieng-di",["Tiếng Đi","How Sound Travels"],["Tiếng dong không bay đi — cái rung mới truyền đi","Sound does not fly — the shaking is what travels"],[n("tren-mat-trang-khong-nghe",1,"te",["Trong phim, phi thuyền nổ tung ngoài vũ trụ nghe ầm một tiếng long trời. Ngoài vũ trụ và trên Mặt Trăng thì không có không khí.","In films, a ship explodes in space with a mighty roar. In space and on the Moon there is no air."],["Đứng trên Mặt Trăng, ngay cạnh một vụ nổ, bạn nghe thấy gì?","Standing on the Moon right beside an explosion, what would you hear?"],[["Vẫn nghe được, chỉ nhỏ hơn vì loãng","You would still hear it, only fainter"],["Không nghe gì cả","Nothing at all"],["Nghe rất to, vì không có gì cản đường","Very loud indeed — nothing in the way to muffle it"]],1,["Tiếng động là cái rung được chuyền tay từ hạt này sang hạt bên cạnh. Không có hạt nào để chuyền thì không có gì tới tai bạn — im lặng tuyệt đối, dù vụ nổ có dữ dội tới đâu. Chuyện này đã được chứng minh từ thế kỷ 17: đặt một cái chuông reo trong bình thuỷ tinh rồi hút hết không khí ra, chuông vẫn thấy rung mà không nghe gì nữa. Ánh sáng thì đi qua chỗ trống được, vì nó không cần ai chuyền hộ. Đó là khác biệt lớn nhất giữa hai thứ.","Sound is a shake passed from one particle to the next. With no particles to pass it, nothing reaches you — perfect silence, however violent the blast. This was settled in the seventeenth century: ring a bell inside a glass jar and pump the air out, and the bell is seen to shake and heard no more. Light crosses emptiness quite happily, because it needs nobody to pass it on. That is the deepest difference between the two."]),n("dem-giay-giua-chop-va-sam",1,"tp",["Đêm giông, bạn thấy tia chớp loé lên, rồi đếm thầm: một, hai, ba — và tiếng sấm nổ tới. Ánh sáng tới gần như tức thì; tiếng thì đi được chừng 340 mét mỗi giây.","In a storm you see the flash, count under your breath — one, two, three — and then the thunder arrives. Light gets to you almost instantly; sound covers about 340 metres a second."],["Tia sét ấy cách bạn khoảng bao xa?","About how far away was the strike?"],[["Khoảng 1 cây số","About 1 kilometre"],["Khoảng 3 cây số","About 3 kilometres"],["Khoảng 100 mét","About 100 metres"]],0,["Ánh sáng đi nhanh tới mức chuyến đi vài cây số của nó gần như không tốn thời gian — bạn thấy tia chớp gần như đúng lúc nó xảy ra. Tiếng thì bò chậm hơn rất nhiều, khoảng 340 mét mỗi giây. Nên mỗi giây bạn đếm được là thêm chừng một phần ba cây số. Ba giây là khoảng một cây. Đây là cái đồng hồ đo khoảng cách mà ai cũng mang sẵn trong người, và nó còn nói cho bạn biết cơn giông đang tới gần hay đi xa: khoảng đếm ngắn dần là nó đang tới.","Light travels so fast that a few kilometres cost it no noticeable time — you see the flash essentially as it happens. Sound crawls along at about 340 metres a second. So every second you count is about a third of a kilometre. Three seconds is roughly one. It is a rangefinder everybody carries, and it also tells you whether the storm is closing: a shrinking count means it is coming your way."]),n("ap-tai-xuong-duong-ray",2,"tp",["Trong phim cũ, người ta áp tai xuống đường ray để biết tàu sắp tới. Và nó có tác dụng thật: nghe qua thanh ray thì biết sớm hơn nghe qua không khí.","In old films people press an ear to the rail to tell if a train is coming. And it works: the rail brings the news before the air does."],["Vì sao tiếng đi trong thanh thép lại nhanh hơn trong không khí?","Why does sound travel faster through steel than through air?"],[["Vì thép cứng và các hạt trong nó nằm sát nhau, chuyền cái rung đi rất nhanh","Because steel is stiff and its particles sit close, passing the shake on very fast"],["Vì thanh ray thẳng nên tiếng không phải đi vòng","Because the rail is straight and the sound need not go round anything"],["Vì thép nặng hơn nên đẩy tiếng đi mạnh hơn","Because steel is heavier and shoves the sound along harder"]],0,["Cái rung được chuyền tay giữa các hạt, nên chuyền nhanh hay chậm là tuỳ chúng nằm sát nhau tới đâu và níu nhau chặt tới đâu. Trong không khí các hạt ở rất xa nhau và gần như không níu gì — 340 mét một giây. Trong nước sát hơn nhiều — khoảng 1500. Trong thép thì các hạt móc chặt vào nhau — khoảng 5000, nhanh gấp mười lăm lần không khí. Đây cũng là lý do cá voi gọi nhau được qua hàng trăm cây số biển, và lý do đặt tai xuống đất là mẹo săn bắt cổ xưa nhất của loài người.","The shake is handed between particles, so how fast it goes depends on how close they sit and how firmly they hold each other. In air they are far apart and barely linked — 340 metres a second. In water, much closer — around 1500. In steel, locked together — around 5000, fifteen times air. It is also why whales call to each other across hundreds of kilometres of sea, and why an ear to the ground is among the oldest hunting tricks there is."]),n("dem-nghe-xa-hon",3,"tp",["Cùng một tiếng chuông nhà thờ, cùng một khoảng cách. Ban trưa nắng thì nghe mờ mờ, có khi không nghe thấy. Ban đêm lặng gió thì nghe rõ mồn một.","The same church bell at the same distance. At noon it is faint or lost altogether; on a still night it comes through clearly."],["Vì sao ban đêm nghe xa hơn?","Why does night carry sound further?"],[["Vì ban đêm yên tĩnh nên tai nghe rõ hơn","Because the night is quiet, so ears hear better"],["Vì ban đêm lớp khí sát mặt đất lạnh hơn lớp trên cao, nên sóng âm bị bẻ cong quặt trở xuống đất","Because at night the air near the ground is colder than the air above, so sound waves are bent back down towards the ground"],["Vì ban đêm không khí đặc hơn nên dẫn âm tốt hơn","Because night air is denser and carries sound better"]],1,["Yên tĩnh có giúp thật, nhưng cái chính là chuyện khác. Tiếng đi trong khí ấm nhanh hơn trong khí lạnh. Ban trưa mặt đất bị nung nóng nên lớp khí sát đất ấm nhất, phần sóng đi thấp chạy nhanh hơn phần đi cao, và cả mặt sóng bị bẻ VỒNG LÊN, rời khỏi mặt đất — tiếng bay lên trời mất. Ban đêm mặt đất nguội nhanh nên lớp sát đất lạnh nhất, mọi chuyện lộn ngược, sóng bị bẻ QUẶT XUỐNG và bám theo mặt đất đi rất xa. Cũng chính hiện tượng bẻ cong ấy tạo ra ảo ảnh vũng nước trên mặt đường nhựa giữa trưa — chỉ là với ánh sáng thay vì tiếng động.","The quiet helps, but the main story is elsewhere. Sound goes faster through warm air than cold. At noon the ground is baked and the lowest air is warmest, so the low part of the wave outruns the high part and the whole front is bent UPWARD, away from the ground — the sound climbs into the sky and is lost. At night the ground cools quickly, the lowest air is coldest, everything reverses, and the wave is bent DOWNWARD to hug the ground for kilometres. The same bending makes the shimmering puddle on a hot road at noon — only with light instead of sound."]),n("tieng-no-sieu-thanh",3,"tp",["Một máy bay bay nhanh hơn tốc độ âm thanh. Người dưới đất nghe một tiếng nổ rất lớn, gọi là tiếng nổ siêu thanh.","An aircraft flies faster than sound. People on the ground hear one very loud crack, the sonic boom."],["Tiếng nổ ấy xảy ra khi nào?","When does that boom happen?"],[["Đúng một lần, vào khoảnh khắc máy bay vượt qua tốc độ âm thanh","Once only, at the instant the aircraft passes through the speed of sound"],["Liên tục suốt chuyến bay — ai đứng dưới đường bay cũng nghe một tiếng khi cái nón sóng quét qua mình","Continuously for the whole flight — everyone under the path hears a crack as the cone of sound sweeps over them"],["Vào lúc máy bay giảm tốc xuống dưới tốc độ âm thanh","At the moment the aircraft drops back below the speed of sound"]],1,["Máy bay nào bay cũng ép không khí trước mũi thành sóng. Bay chậm hơn tiếng thì sóng chạy tới trước và tản ra. Bay nhanh hơn tiếng thì máy bay đuổi kịp chính sóng của mình, và mọi sóng dồn lại thành một mặt nón kéo lê phía sau nó — kéo dài SUỐT chuyến bay chứ không phải một lần. Bạn nghe thấy nổ vào đúng lúc cái nón ấy quét qua chỗ bạn đứng. Y hệt vệt sóng hình chữ V mà con thuyền kéo lê sau đuôi: nó luôn ở đó, và bờ nào cũng sẽ bị nó vỗ vào, mỗi bờ một lúc khác nhau. Vì thế mà máy bay siêu thanh bị cấm bay qua đất liền.","Every aircraft squeezes the air ahead of it into waves. Slower than sound, those waves run ahead and spread. Faster than sound, the aircraft catches its own waves and they pile into a cone dragged along behind — dragged for the WHOLE flight, not once. You hear the crack at the moment that cone sweeps across you. It is the V-shaped wake a boat drags behind it: always there, and every bank gets slapped by it, each at its own moment. This is why supersonic flight over land is banned."])]),t("cao-va-tram",["Cao & Trầm","High & Low"],["Rung nhanh thì nghe cao, rung chậm thì nghe trầm","Shake fast and it sounds high; shake slowly and it sounds low"],[n("day-dan-ngan-thi-cao",1,"tp",["Cây đàn ghi-ta: bấm ngón tay lên phím càng gần thân đàn thì đoạn dây rung càng ngắn, và tiếng càng cao. Dây to nhất cho tiếng trầm nhất; vặn khoá cho dây căng hơn thì tiếng cao lên.","A guitar: press a fret nearer the body and the vibrating length shortens and the note rises. The thickest string gives the lowest note; tighten a string and its note rises."],["Ba cách ấy cùng làm một việc gì?","What single thing are those three doing?"],[["Cùng làm dây rung nhanh hơn hoặc chậm hơn","All changing how fast the string vibrates"],["Cùng làm dây kêu to hơn hoặc nhỏ hơn","All changing how loud the string is"],["Cùng làm dây rung lâu hơn hoặc mau tắt hơn","All changing how long the string keeps ringing"]],0,["Cao hay trầm chỉ là chuyện dây rung bao nhiêu lần trong một giây. Dây ngắn thì rung qua rung lại mau hơn. Dây căng thì bật về nhanh hơn. Dây mảnh thì nhẹ nên cũng bật nhanh hơn. Ba cái nút ấy là toàn bộ những gì người ta chỉnh trên mọi nhạc cụ dây trên thế giới. To hay nhỏ thì là chuyện khác hẳn — đó là dây rung RỘNG bao nhiêu, và nó không dính gì tới cao thấp: gảy mạnh thì to hơn chứ không cao hơn.","High and low is only how many times a second the string swings. Short means it swings back sooner. Tight means it snaps back faster. Thin means it is light and snaps back faster too. Those three knobs are all anyone adjusts on any stringed instrument anywhere. Loudness is a separate matter — that is how FAR the string swings, and it has nothing to do with pitch: pluck harder and it is louder, not higher."]),n("rot-nuoc-vao-chai",1,"tp",["Rót nước từ vòi vào một cái chai thuỷ tinh. Tiếng ọc ọc trong chai cứ cao dần lên đều đặn, và đến lúc gần đầy thì nghe rất cao — nghe tiếng thôi cũng biết sắp phải khoá vòi.","Filling a glass bottle from a tap. The gurgling note climbs steadily, and near the top it is high — you can tell by ear alone when to shut off the water."],["Vì sao tiếng cao dần lên?","Why does the note climb?"],[["Vì nước chảy vào mỗi lúc một mạnh","Because the water runs in faster and faster"],["Vì cột không khí còn lại trong chai ngắn dần, mà cột khí ngắn thì rung nhanh hơn","Because the column of air left in the bottle keeps shortening, and a short column shakes faster"],["Vì thuỷ tinh nóng lên nên căng ra","Because the glass warms and tightens"]],1,["Cái phát ra tiếng ở đây không phải nước mà là cột KHÔNG KHÍ phía trên nước. Nó rung y như một cây sáo, và cây sáo càng ngắn thì tiếng càng cao — đó là lý do ống sáo dài cho nốt trầm, ống ngắn cho nốt bổng. Nước dâng lên là cây sáo ngắn dần lại, nên tiếng cao dần. Người khiếm thị rót nước bằng đúng cái tai này. Chú ý là nếu bạn GÕ vào thành chai thay vì thổi thì mọi chuyện lộn ngược lại — xem câu cuối của bộ này.","What is sounding here is not the water but the column of AIR above it. It rings like a flute, and a shorter flute gives a higher note — which is why long pipes give bass and short pipes give treble. Rising water is a shortening flute, so the note climbs. Blind people pour by exactly this ear. Note that if you TAP the bottle instead of blowing across it, everything reverses — see the last question in this set."]),n("coi-xe-cuu-thuong",2,"tp",["Xe cứu thương hú còi lao tới rồi vụt qua mặt bạn. Lúc nó tới gần, tiếng còi nghe cao; đúng lúc nó lướt qua, tiếng tụt xuống trầm hẳn và giữ trầm cho tới khi đi khuất.","An ambulance races towards you and past. Coming on, the siren sounds high; the instant it passes, the note drops and stays low as it recedes."],["Vì sao?","Why?"],[["Vì tài xế bấm đổi còi khi đi qua","Because the driver switches the siren over as they pass"],["Vì xe chạy tới thì dồn các đợt sóng lại gần nhau, chạy đi thì kéo chúng ra xa nhau","Because approaching, the car crowds the wave crests together; receding, it stretches them apart"],["Vì tiếng phải đi ngược gió khi xe đã đi qua","Because after it passes the sound has to fight the airflow"]],1,["Cái còi vẫn phát đúng một nốt suốt từ đầu tới cuối. Cái đổi là khoảng cách giữa các đợt sóng khi chúng tới tai bạn. Xe chạy tới thì mỗi đợt sóng mới được phát ra từ một chỗ gần hơn đợt trước, nên các đợt bị dồn lại — tới tai bạn dày hơn, nghe cao hơn. Xe chạy xa thì mỗi đợt phát từ chỗ xa hơn, các đợt bị kéo giãn — nghe trầm hơn. Chính hiệu ứng này, làm với ánh sáng thay vì tiếng động, là cách các nhà thiên văn biết được các thiên hà đang chạy xa khỏi chúng ta, và từ đó biết được vũ trụ đang giãn nở.","The siren holds one note throughout. What changes is the spacing of the waves as they reach you. Coming on, each new wave leaves from a point closer than the last, so they crowd together — they arrive more often and sound higher. Going away, each leaves from further off and they stretch out — lower. This same effect, run on light instead of sound, is how astronomers found that the galaxies are receding from us, and from there that the universe is expanding."]),n("hit-khi-heli",3,"tp",["Hít một hơi khí heli từ quả bóng bay rồi nói, giọng bỗng the thé như trong phim hoạt hình. Tiếng đi trong heli nhanh gần gấp ba trong không khí.","Breathe in helium from a balloon and speak: the voice comes out squeaky, like a cartoon. Sound travels in helium nearly three times as fast as in air."],["Lúc đó dây thanh quản của bạn rung thế nào?","What are your vocal cords doing at that moment?"],[["Rung nhanh gấp ba, vì heli nhẹ nên dây dễ rung hơn","Vibrating three times as fast — the light gas lets them move more freely"],["Rung y hệt như bình thường, không nhanh hơn chút nào","Vibrating exactly as usual, no faster at all"],["Rung chậm lại, và cái the thé đến từ chỗ khác","Vibrating more slowly, and the squeak comes from elsewhere"]],1,["Dây thanh vẫn rung đúng số lần một giây như mọi khi — nốt gốc của giọng bạn không đổi. Cái đổi là khoang miệng và cổ họng phía trên nó. Khoang ấy hoạt động như một cây sáo, chọn khuếch đại vài dải tần nhất định và chính chúng làm nên cái ÂM SẮC nhận ra được của một giọng người. Mà dải nào được khuếch đại thì tuỳ tốc độ âm trong khí trong khoang. Heli làm tiếng đi nhanh gấp gần ba, nên các dải ấy nhảy vọt lên cao, và giọng nghe thành như thế. Nói cách khác: cao độ giữ nguyên, chỉ có bộ lọc bị xê dịch. Hít khí nặng hơn không khí thì giọng trầm xuống đúng theo cách ngược lại.","The cords vibrate at exactly their usual rate — the underlying note of your voice does not change. What changes is the mouth and throat above them. That cavity works as a flute, picking out certain bands to amplify, and those bands are what give a human voice its recognisable COLOUR. Which bands get picked depends on how fast sound travels in the gas filling the cavity. Helium nearly trebles that speed, so the bands leap upward and the voice arrives sounding like that. Put another way: the pitch is untouched, only the filter has moved. Breathe a gas heavier than air and the voice drops in exactly the mirror way."]),n("go-chai-va-thoi-chai",3,"tp",["Xếp một hàng chai giống hệt nhau, đổ nước vào mỗi chai một mực khác nhau. Lần lượt THỔI ngang qua miệng từng chai, rồi lần lượt lấy thìa GÕ vào thành từng chai.","A row of identical bottles filled to different levels. First BLOW across the mouth of each in turn, then TAP the side of each with a spoon."],["So sánh hai lần, chai nhiều nước nhất cho tiếng thế nào?","Comparing the two, what does the fullest bottle do?"],[["Cả hai lần đều cho tiếng cao nhất","Gives the highest note both times"],["Cả hai lần đều cho tiếng trầm nhất","Gives the lowest note both times"],["Thổi thì cho tiếng cao nhất, gõ thì cho tiếng trầm nhất","Blowing gives the highest note; tapping gives the lowest"]],2,["Hai lần ấy làm rung hai thứ khác hẳn nhau. THỔI thì rung cột không khí phía trên mặt nước: chai nhiều nước có cột khí ngắn nhất, rung nhanh nhất, tiếng cao nhất. GÕ thì rung chính cái chai cùng khối nước trong nó: chai nhiều nước là vật nặng nhất, mà vật càng nặng thì càng lì, rung chậm nhất, tiếng trầm nhất. Cùng một hàng chai, hai cách chạm vào, hai thang âm chạy ngược chiều nhau. Bài học không nằm ở cái chai mà ở câu hỏi: muốn biết tiếng cao hay trầm thì trước hết phải hỏi CÁI GÌ đang rung. Bỏ qua câu ấy thì đoán kiểu gì cũng có một nửa số lần sai.","The two actions shake two quite different things. BLOWING shakes the air column above the water: the fullest bottle has the shortest column, shakes fastest, sounds highest. TAPPING shakes the bottle together with the water in it: the fullest bottle is the heaviest object, and heavy means sluggish, so it shakes slowest and sounds lowest. One row of bottles, two ways of touching it, two scales running opposite ways. The lesson is not about bottles but about the question to ask first: WHAT is vibrating. Skip that question and half your predictions will be wrong."])]),t("song-gap-song",["Sóng Gặp Sóng","When Waves Meet"],["Hai sóng gặp nhau thì cộng lại, rồi đi tiếp như chưa hề gặp","Two waves add where they meet, then travel on as if nothing had happened"],[n("tieng-vong-trong-hang",1,"tp",["Hét lên trong một cái hang lớn hay giữa hai vách núi thì nghe tiếng vọng lại. Hét trong phòng khách nhà mình thì không, dù tường phòng cũng dội tiếng lại.","Shout in a large cave or between two cliffs and an echo comes back. Shout in your living room and none does, though the walls reflect sound just as well."],["Vì sao trong phòng nhỏ lại không nghe thấy tiếng vọng?","Why is there no echo in a small room?"],[["Vì tường nhà hút hết tiếng chứ không dội lại","Because house walls soak sound up instead of reflecting it"],["Vì tiếng dội về quá sớm, tai không tách được nó khỏi tiếng gốc","Because the reflection returns too soon for the ear to separate it from the original"],["Vì phòng nhỏ nên tiếng yếu đi trước khi kịp dội","Because the room is small and the sound dies before it can bounce"]],1,["Tiếng vẫn dội lại đầy đủ trong phòng khách — chỉ là nó về quá nhanh. Tai người cần chừng một phần mười giây để nghe ra hai tiếng riêng biệt; ngắn hơn thì hai cái nhập làm một. Trong một phần mười giây, tiếng đi được chừng 34 mét, tức là bức tường phải cách bạn hơn 17 mét thì tiếng đi và về mới đủ chậm. Phòng khách chỉ vài mét nên tiếng dội chồng ngay lên tiếng gốc — bạn không nghe ra tiếng vọng, nhưng bạn nghe ra cái phòng: chính mấy cái dội sớm ấy làm nên cảm giác một căn phòng trống khác hẳn một căn phòng đầy đồ.","The living room reflects sound perfectly well — the reflection just returns too soon. The ear needs about a tenth of a second to hear two sounds as two; closer than that and they fuse. In a tenth of a second sound covers about 34 metres, so the wall must be more than 17 metres away before the round trip is slow enough. A living room is a few metres, so the reflection lands on top of the original — you do not hear an echo, but you do hear the room: those early reflections are exactly what makes an empty room sound different from a furnished one."]),n("hai-song-gap-nhau",2,"tp",["Hai người cầm hai đầu một sợi dây thừng dài, mỗi người giật một cái tạo ra một gợn sóng chạy về phía người kia. Hai gợn gặp nhau ở giữa dây.","Two people hold the ends of a long rope and each flicks a pulse towards the other. The two pulses meet in the middle."],["Sau khi gặp nhau, hai gợn sóng thế nào?","After they meet, what do the pulses do?"],[["Va vào nhau rồi bật ngược trở lại","They collide and bounce back the way they came"],["Chồng lên nhau ở chỗ gặp, rồi mỗi cái đi tiếp nguyên vẹn như chưa hề gặp","They overlap where they meet, then each carries on unchanged as if nothing had happened"],["Triệt tiêu nhau và cả hai biến mất","They wipe each other out and both vanish"]],1,["Sóng không phải vật, nên chúng không va chạm. Ở đúng chỗ gặp, sợi dây chỉ làm một việc rất đơn giản: nhấc lên bằng tổng của cả hai. Nếu hai gợn cùng hướng lên thì chỗ ấy vọt lên gấp đôi; nếu một lên một xuống thì chỗ ấy phẳng lì trong một khoảnh khắc — trông như cả hai đã biến mất, dù không hề. Xong việc, mỗi gợn đi tiếp đúng hướng cũ, đúng hình cũ. Đây là lý do trong một phòng đông người bạn vẫn nghe được riêng giọng của bạn mình: hàng trăm cái tiếng đang đi xuyên qua nhau mà không cái nào làm hỏng cái nào.","Waves are not objects, so they do not collide. At the meeting point the rope does something very simple: it lifts by the sum of the two. If both pulses point up, that spot leaps to double height; if one points up and one down, that spot goes momentarily flat — looking for all the world as if both had vanished, though neither has. Then each pulse carries on with its old direction and its old shape. This is why in a crowded room you can still pick out one friend: hundreds of sounds are passing through one another and none of them spoils another."]),n("tai-nghe-chong-on",2,"te",["Cái tai nghe chống ồn: bật lên là tiếng ù ù của động cơ máy bay biến mất gần hết, dù nó không hề bịt kín tai hơn lúc tắt.","Noise-cancelling headphones: switch them on and the drone of an aircraft engine largely disappears, though they seal your ears no more tightly than before."],["Nó làm gì?","What are they doing?"],[["Nó dùng một cái mi-crô nghe tiếng ồn, rồi phát ra một sóng ngược hẳn để cộng lại thành phẳng","Listening with a microphone and playing back an opposite wave, so the two add to nothing"],["Nó phát ra một tiếng nhạc to hơn để át tiếng ồn đi","Playing something louder to drown the noise out"],["Nó làm cứng màng loa lại để chặn tiếng ồn không lọt qua","Stiffening the drivers to block the noise mechanically"]],0,["Đây chính là chuyện hai gợn sóng ngược chiều gặp nhau, làm một cách cố ý. Cái mi-crô nhỏ ở mặt ngoài nghe tiếng ồn đang tới, con chip tính ra ngay một sóng lộn ngược y hệt, và loa phát nó ra vào đúng khoảnh khắc tiếng ồn tới tai. Hai cái cộng lại thành gần bằng không, và bạn nghe thấy im lặng. Nó làm tốt với tiếng đều đều và trầm — tiếng động cơ, tiếng điều hoà — vì loại tiếng đó đoán trước được. Nó làm kém với tiếng nói và tiếng vỡ đột ngột, vì tới lúc tính xong thì tiếng đã lọt qua rồi.","This is the two opposite pulses meeting, done on purpose. A small microphone on the outside hears the incoming noise, a chip works out the exact mirror image, and the driver plays it at the instant the noise reaches your ear. The two add to nearly nothing and you hear quiet. It works well on steady low sounds — engines, air conditioning — because those can be predicted. It works poorly on speech and sudden bangs, because by the time the sum is worked out the sound has already gone by."]),n("hai-cai-loa-cung-mot-not",3,"tp",["Hai cái loa cách nhau vài mét, cùng phát đúng một nốt đơn, đều đặn, không đổi. Bạn đi bộ chậm rãi theo một đường thẳng ngang qua trước mặt hai loa.","Two speakers a few metres apart play one steady, unchanging note. You walk slowly along a straight line in front of them."],["Bạn nghe thấy gì trên đường đi?","What do you hear as you walk?"],[["To đều suốt, chỉ to nhất ở đúng chính giữa","One steady loudness, at its greatest right in the middle"],["To dần khi tới gần loa và nhỏ dần khi ra xa","Louder near each speaker and quieter between them"],["To nhỏ xen kẽ nhau đều đặn, có những chỗ gần như im hẳn","Regularly alternating loud and quiet patches, some of them almost silent"]],2,["Từ mỗi chỗ bạn đứng, hai loa cách bạn hai khoảng khác nhau, nên hai sóng tới tai bạn lệch nhau một chút. Ở những chỗ mà chênh lệch đúng bằng một số nguyên lần bước sóng thì hai đỉnh sóng chồng lên nhau và tiếng to gấp đôi. Ở những chỗ mà chênh lệch đúng bằng một nửa bước sóng thì đỉnh của cái này rơi đúng vào đáy của cái kia, và chúng khử nhau gần hết — im lặng do CỘNG hai tiếng động vào nhau. Đi ngang qua là đi qua một cái lưới to nhỏ xen kẽ đứng yên trong không khí. Đây là bằng chứng đơn giản nhất cho thấy tiếng động là sóng, và cùng thí nghiệm ấy làm với ánh sáng chính là thứ đã chứng minh ánh sáng cũng là sóng.","From wherever you stand the two speakers are at two different distances, so their waves arrive slightly out of step. Where the difference is a whole number of wavelengths, crest lands on crest and the sound doubles. Where it is half a wavelength, crest lands on trough and they very nearly cancel — silence produced by ADDING two sounds together. Walking across is walking through a standing lattice of loud and quiet fixed in the air. It is the simplest proof that sound is a wave, and the same experiment run with light is what proved light is one too."]),n("hai-day-dan-lech-nhau",3,"tp",["Người lên dây gảy cùng lúc hai dây đáng lẽ cùng một nốt, nhưng một dây hơi chùng. Thay vì nghe hai nốt lệch nhau, họ nghe một nốt cứ to lên rồi nhỏ đi, đều đặn như thở.","Tuning, you sound two strings that should give one note, but one is slightly slack. Instead of two notes you hear a single note that swells and fades, swells and fades, as regularly as breathing."],["Cái nhịp phập phồng ấy nói lên điều gì?","What does that throbbing tell the tuner?"],[["Nó đếm đúng độ lệch giữa hai dây: mỗi giây phập phồng bao nhiêu lần thì hai dây lệch nhau bấy nhiêu","It counts the mismatch exactly: throbs per second equals the difference between the two strings"],["Nó cho biết một dây sắp đứt","It warns that one string is about to break"],["Nó chỉ là do tay gảy không đều","It is only an uneven pluck"]],0,["Hai sóng gần bằng nhau thì lúc đầu chúng cùng nhịp và cộng lại thành to. Nhưng cái nhanh hơn cứ nhích dần lên trước, tới lúc nó đi ngược hẳn với cái kia và hai bên khử nhau — tiếng lịm đi. Rồi nó nhích tiếp cho tới khi bắt kịp một vòng và lại cùng nhịp — tiếng to trở lại. Số lần phập phồng trong một giây bằng đúng hiệu số giữa hai tần số. Nên người lên dây không cần nghe được cao độ tuyệt đối, họ chỉ cần vặn cho tới khi hết phập phồng — và lúc đó hai dây bằng nhau chính xác tới từng phần rất nhỏ. Một cái tai bình thường, dùng đúng cách, đo chính xác hơn nhiều so với nó tự thấy.","Two nearly equal waves start in step and add to something loud. But the faster one creeps ahead until it is exactly opposed to the other and they cancel — the sound dies away. It creeps on until it has gained a whole cycle and they are in step again — loud once more. The throbs per second equal the difference between the two frequencies exactly. So a tuner needs no absolute sense of pitch at all; they simply turn the peg until the throbbing stops, and at that instant the two are matched to a tiny fraction. An ordinary ear, used properly, measures far more finely than it feels able to."])]),t("lac-va-rung",["Lắc & Rung","Swinging & Shaking"],["Mọi vật đều có một nhịp riêng, và đẩy đúng nhịp thì rất ít sức cũng thành rất nhiều","Everything has its own rhythm, and pushing on that rhythm turns a little into a lot"],[n("day-xich-du-dung-nhip",1,"tp",["Đẩy em bé trên xích đu. Bạn đẩy rất nhẹ, nhưng đẩy đúng vào lúc xích đu vừa lùi hết về phía bạn và bắt đầu đi tới. Sau mươi lần, xích đu bay rất cao.","Pushing a child on a swing. Each push is gentle, but timed for the moment the swing has come all the way back and is starting forward. After a dozen pushes it is flying high."],["Nếu bạn đẩy mạnh hơn nhiều nhưng vào những lúc bất kỳ thì sao?","What if you push much harder but at random moments?"],[["Xích đu còn bay cao hơn, vì bạn đẩy mạnh hơn","It goes even higher — you are pushing harder"],["Xích đu chỉ giật cục và không lên cao được bao nhiêu","It jerks about and never gets far up"],["Kết quả như nhau, vì tổng sức bỏ ra mới quan trọng","The same result — only the total effort counts"]],1,['Xích đu có một nhịp riêng của nó, và bạn không đổi được cái nhịp ấy. Đẩy đúng nhịp thì mỗi cú đẩy nhỏ được cộng thêm vào cái đã có, và chúng dồn lại thành rất lớn. Đẩy sai nhịp thì có lúc bạn cộng vào, có lúc bạn đẩy ngược lại chính cái đà vừa gây dựng — và phần lớn công sức bị chính bạn tiêu huỷ. Cái nguyên tắc "ít mà đúng lúc hơn nhiều mà bừa" này gọi là cộng hưởng, và nó là thứ làm nên cả cái đài phát thanh, cái lò vi sóng, lẫn việc một ca sĩ làm vỡ được cái ly.',"The swing has a rhythm of its own, and you cannot change it. Push on that rhythm and each small push adds to what is already there, and they pile up into something large. Push off it and sometimes you add, sometimes you fight the very momentum you built — and most of your effort is destroyed by you. This principle of a little at the right time beating a lot at any time is called resonance, and it is behind the radio, the microwave oven, and a singer breaking a glass."]),n("con-lac-dai-hay-ngan",2,"tp",["Hai con lắc treo cạnh nhau, thả cùng lúc. Con thứ nhất dây dài một mét, con thứ hai dây dài hai mươi lăm xăng-ti-mét. Quả nặng ở đầu hai dây bằng nhau.","Two pendulums released together. The first hangs on a metre of string, the second on twenty-five centimetres. The bobs are identical."],["Con nào lắc qua lắc lại nhanh hơn?","Which swings back and forth faster?"],[["Con dây dài","The long one"],["Con dây ngắn","The short one"],["Bằng nhau, vì cùng quả nặng","Neither — the bobs are the same"]],1,["Con lắc ngắn lắc nhanh hơn, và độ dài là thứ DUY NHẤT quyết định — cân nặng của quả nặng không ảnh hưởng gì cả, biên độ lắc rộng hay hẹp cũng gần như không. Dây ngắn đi bốn lần thì lắc nhanh lên đúng hai lần. Chính vì cái nhịp ấy ổn định tới mức đó mà suốt ba trăm năm, mọi cái đồng hồ chính xác trên thế giới đều là một con lắc: người ta chỉnh giờ bằng cách vặn quả nặng lên xuống một chút trên thanh treo, tức là đổi độ dài. Galileo phát hiện ra tính ổn định này khi ngồi trong nhà thờ nhìn cái đèn treo đung đưa, và ông đo nhịp của nó bằng mạch đập của chính mình.","The short one swings faster, and length is the ONLY thing that decides it — the weight of the bob makes no difference at all, and the width of the swing almost none. Quarter the length and it swings exactly twice as fast. It was because that rhythm is so dependable that for three centuries every accurate clock in the world was a pendulum: they were set by sliding the bob a little up or down its rod, which is to say by changing the length. Galileo noticed the steadiness watching a lamp sway in a cathedral, and timed it against his own pulse."]),n("be-nang-be-nhe-cung-xich-du",3,"tp",["Hai đứa trẻ chơi trên hai cái xích đu giống hệt nhau, cùng chiều dài dây, treo cạnh nhau. Một đứa nặng gấp đôi đứa kia. Cả hai cùng được đẩy cho lắc.","Two children on two identical swings of the same length, side by side. One weighs twice the other. Both are set swinging."],["Đứa nào lắc qua lắc lại nhanh hơn?","Which one swings back and forth faster?"],[["Đứa nhẹ, vì nhẹ thì dễ đưa qua đưa lại hơn","The lighter one — less to move about"],["Đứa nặng, vì nặng thì bị kéo xuống mạnh hơn","The heavier one — gravity pulls harder on it"],["Hai đứa lắc đúng cùng một nhịp","They swing at exactly the same rate"]],2,["Đây lại đúng là câu voi và lông chim, mặc một bộ quần áo khác. Trái Đất kéo đứa nặng mạnh gấp đôi thật — nhưng đứa nặng cũng ì gấp đôi. Hai cái đó khử nhau sạch sẽ, và cái nhịp còn lại chỉ phụ thuộc vào chiều dài sợi dây. Đây là chỗ mà rất nhiều người lớn đoán sai, vì trực giác nói rằng nặng thì phải khác. Ai đã đoán đúng câu ống hút chân không ở bộ đầu tiên thì đã có sẵn câu trả lời cho câu này — mà thường thì họ vẫn đoán sai, vì một cái xích đu trông không giống một cú rơi. Nhận ra hai bài toán khác vỏ mà cùng ruột là một trong những việc khó nhất của cả môn học.","This is the elephant and the feather again in different clothes. The Earth does pull twice as hard on the heavier child — and the heavier child is twice as sluggish. Those cancel exactly, and the rhythm that remains depends only on the length of the rope. A great many adults get this wrong, because intuition insists that weight must matter. Anyone who answered the vacuum tube correctly in the first set already holds the answer to this one — and usually still gets it wrong, because a swing does not look like a fall. Recognising two problems as one beneath different skins is among the hardest work in the whole subject."]),n("linh-qua-cau-treo",2,"tp",["Quân đội có một điều lệnh lạ: khi một đoàn lính đi qua cầu treo, họ phải BỎ nhịp bước đều và đi tự do, mỗi người một nhịp.","Armies keep an odd standing order: crossing a suspension bridge, troops must BREAK step and walk out of time with each other."],["Vì sao?","Why?"],[["Vì đi đều thì cả đoàn dồn trọng lượng vào một chỗ cùng lúc","Because marching in step puts all their weight on one spot at once"],["Vì nhịp bước đều có thể trùng với nhịp riêng của cây cầu và làm cầu rung mỗi lúc một mạnh","Because a steady step can match the bridge’s own rhythm and drive it into ever larger swings"],["Vì tiếng bước chân đều làm hỏng dây cáp","Because the regular sound damages the cables"]],1,["Cây cầu cũng là một con lắc, chỉ là rất lớn và rất cứng, và nó cũng có nhịp riêng. Một đoàn lính đi đều là hàng trăm cú đẩy nhỏ đến đúng một nhịp — chính là đẩy xích đu đúng lúc, ở quy mô mấy trăm tấn. Nếu nhịp bước trùng nhịp cầu thì các cú đẩy dồn lại và cầu lắc ngày một mạnh. Chuyện này đã xảy ra thật: một cây cầu ở Anh sập năm 1831 dưới chân một đoàn lính. Đi lộn xộn thì các cú đẩy đến ngẫu nhiên, cái này triệt cái kia, và cây cầu không nhận được gì. Năm 2000 cầu đi bộ Thiên Niên Kỷ ở London phải đóng cửa vì đúng chuyện này, chỉ khác là chính đám đông tự động bước vào nhịp mà không ai ra lệnh.","A bridge is a pendulum too, only vast and stiff, and it has a rhythm of its own. Troops in step are hundreds of small pushes arriving on one beat — the swing again, at a scale of hundreds of tonnes. If the step matches the bridge, the pushes accumulate and the swings grow. It has really happened: a bridge in England collapsed under marching soldiers in 1831. Out of step, the pushes arrive at random, cancel one another, and the bridge receives nothing. In 2000 the Millennium footbridge in London had to close for exactly this, except that the crowd fell into step by itself with nobody ordering it."]),n("ly-ruou-vo-vi-tieng-hat",3,"tp",["Một ca sĩ hát đúng một nốt kéo dài trước cái ly rượu pha lê, và cái ly vỡ tan. Chuyện này có thật, không phải chỉ trong phim.","A singer holds one sustained note in front of a crystal glass and the glass shatters. This really happens; it is not only a film trick."],["Điều gì bắt buộc phải đúng thì mới làm được?","What must be true for it to work?"],[["Nốt hát phải thật cao, càng cao càng dễ vỡ","The note must be very high — the higher the better"],["Nốt hát phải trúng đúng cái nhịp rung riêng của chính cái ly đó","The note must land exactly on that particular glass’s own natural rhythm"],["Ca sĩ phải hát thật to, cao thấp thế nào cũng được","The singer need only be loud enough; the pitch does not matter"]],1,["Gõ nhẹ vào miệng cái ly là nghe được nhịp riêng của nó — mỗi cái ly một nốt. Hát trúng đúng nốt ấy thì mỗi đợt sóng âm tới đúng lúc thành ly đang đi ra, và nó đẩy thêm một chút. Hàng nghìn cú đẩy nhỏ đúng nhịp dồn lại làm thành ly rung mỗi lúc một rộng, cho tới lúc pha lê không co giãn thêm được nữa và nứt. Hát to mà sai nốt thì chỉ ồn, ly không hề gì. Đây vẫn là em bé trên xích đu: cái quyết định không phải sức mạnh, mà là trúng nhịp. Ly pha lê dễ vỡ hơn ly thường vì nó rung lâu và ít hao — nghĩa là nó giữ lại được nhiều hơn từ mỗi cú đẩy.","Tap the rim and you hear the glass’s own note — every glass has its own. Sing exactly that note and each wave arrives just as the wall is moving outward, and gives it a nudge. Thousands of well-timed nudges build the vibration wider and wider until the crystal can stretch no further and cracks. Sing loudly off the note and it is merely noise; the glass is untouched. This is still the child on the swing: what decides it is not strength but timing. Crystal breaks more readily than ordinary glass because it rings long and loses little — meaning it keeps more of each push."])]),t("dat-rung",["Đất Rung","When the Ground Shakes"],["Động đất và sóng thần đều là sóng, và sóng thì có luật của sóng","Earthquakes and tsunamis are waves, and waves keep to the rules of waves"],[n("dong-dat-la-gi",1,"te",["Vỏ Trái Đất không liền một khối mà vỡ thành mấy chục mảng lớn, và các mảng ấy trôi rất chậm, chừng vài xăng-ti-mét một năm — bằng tốc độ móng tay bạn mọc dài ra.","The crust of the Earth is not one piece but a few dozen great plates, drifting a few centimetres a year — about the speed your fingernails grow."],["Động đất xảy ra thế nào?","How does an earthquake happen?"],[["Đất bên dưới nổ tung ra vì sức nóng","The ground below explodes from the heat"],["Hai mảng bị kẹt vào nhau, ứ lại hàng chục năm, rồi bật trượt một cái","Two plates are locked together, strain builds for decades, and then they slip all at once"],["Cả mảng đột nhiên trôi nhanh hơn hẳn bình thường","A plate suddenly begins drifting much faster than usual"]],1,["Nếu hai mảng trôi trượt êm ả thì đã chẳng có động đất nào. Vấn đề là chúng dính vào nhau ở chỗ tiếp giáp: bên dưới vẫn bị đẩy đều đều, nhưng mặt tiếp xúc thì kẹt cứng, nên đá hai bên bị vặn xoắn và tích năng lượng lại hệt như một cái lò xo bị nén. Ứ tới lúc chịu không nổi thì nó trượt phựt một cái — có khi vài mét trong vài giây — và toàn bộ số năng lượng tích cả mấy chục năm bung ra thành sóng chạy khắp mặt đất. Đó cũng là lý do người ta biết chỗ nào sắp có động đất mà không biết bao giờ: biết cái lò xo đang bị nén, nhưng không biết nó đứt vào ngày nào.","If the plates slid smoothly past each other there would be no earthquakes at all. The trouble is that they stick where they meet: the deep drive continues, but the contact is locked, so the rock on either side is twisted and stores energy like a compressed spring. When it can hold no longer it slips at once — sometimes metres in seconds — and decades of stored energy leave as waves running through the ground. It is also why we know where earthquakes will come and not when: we can see the spring being wound, not the day it lets go."]),n("hai-loai-song-dong-dat",2,"te",["Máy đo động đất ghi được hai loại sóng đến vào hai lúc khác nhau từ cùng một trận: một loại đến trước, chạy nhanh, rung dọc theo hướng đi; một loại đến sau, chậm hơn, lắc ngang và phá nhà cửa dữ hơn nhiều.","A seismograph records two kinds of wave arriving at different times from one quake: a fast one first, shaking along its direction of travel, and a slower one after, rocking sideways and doing far more damage."],["Cái chênh lệch thời gian giữa hai loại sóng ấy dùng để làm gì?","What is the gap between the two arrivals good for?"],[["Để tính xem trạm đo cách tâm chấn bao xa","Working out how far the station is from the epicentre"],["Để biết trận động đất mạnh bao nhiêu","Working out how strong the quake was"],["Để biết trận động đất kéo dài bao lâu","Working out how long the quake lasted"]],0,["Hai loại sóng cùng xuất phát một lúc từ một chỗ, nhưng đi với hai tốc độ khác nhau — nên càng đi xa thì chúng càng tách nhau ra, y như hai người chạy bộ nhanh chậm khác nhau. Đo cái khoảng cách giữa hai lần đến là biết chúng đã chạy bao xa. Nhưng một trạm chỉ nói được KHOẢNG CÁCH chứ không nói được HƯỚNG — nó chỉ vẽ ra một vòng tròn quanh mình. Phải có ba trạm ở ba nơi khác nhau, ba vòng tròn cắt nhau tại đúng một điểm, thì mới ra được tâm chấn. Đây cũng đúng là cách máy định vị trong điện thoại bạn xác định chỗ bạn đứng, chỉ khác là nó dùng vệ tinh thay cho trạm đo.","Both waves leave one place at one instant but travel at different speeds — so the further they go the further apart they arrive, like two runners of unequal pace. Measure the gap between the arrivals and you know how far they have run. But one station gives only a DISTANCE, never a direction — it draws a circle round itself. Three stations in three places give three circles crossing at one point, and that is the epicentre. It is exactly how the satellite navigation in your phone finds you, with satellites in place of seismographs."]),n("nen-dat-mem-hu-hai-nang",3,"te",["Sau một trận động đất, hai khu phố cách tâm chấn đúng bằng nhau nhưng thiệt hại khác hẳn: khu xây trên nền đá gốc gần như nguyên vẹn, khu xây trên nền đất bồi mềm thì sập nhiều.","After a quake, two districts equally far from the epicentre fare very differently: the one on bedrock is largely intact, the one on soft filled ground is badly wrecked."],["Vì sao nền đất mềm lại nguy hiểm hơn?","Why is the soft ground more dangerous?"],[["Vì đất mềm không đỡ nổi móng nhà","Because soft ground cannot carry the foundations"],["Vì đất mềm làm sóng chậm lại nên rung phình to ra, mà nhịp của đất mềm lại hay trùng nhịp riêng của nhà cao tầng","Because waves slow in soft ground so their swing grows, and the rhythm of soft ground often matches the buildings’ own"],["Vì đất mềm giữ nước nên bị trơn","Because soft ground holds water and becomes slippery"]],1,["Sóng vào đất mềm thì chạy chậm hẳn lại, mà năng lượng thì vẫn ngần ấy — nên nó phải đền bù bằng cách rung rộng ra, có khi rộng gấp mấy lần so với trên đá. Tệ hơn nữa, đất mềm rung theo một nhịp chậm, và nhịp chậm ấy thường trùng đúng với nhịp riêng của những toà nhà cao vài chục tầng. Lúc đó lại đúng là em bé trên xích đu, chỉ khác là cái được đẩy là cả toà nhà. Thành phố Mexico năm 1985 là ví dụ tàn khốc nhất: tâm chấn cách hơn 350 km, nhưng khu trung tâm nằm trên nền một cái hồ cạn cũ, và những toà nhà cao đúng tầm cộng hưởng đã sập trong khi nhà thấp bên cạnh đứng nguyên.","Waves entering soft ground slow right down while carrying the same energy — so they compensate by swinging wider, sometimes several times wider than on rock. Worse, soft ground rocks at a slow rhythm, and that rhythm often matches the natural rhythm of buildings of a few dozen storeys. Then it is the child on the swing again, with a tower block for a child. Mexico City in 1985 is the cruellest example: the epicentre was over 350 km away, but the centre sits on an old dry lakebed, and buildings of exactly the resonant height came down while shorter neighbours stood."]),n("nuoc-rut-xa-bat-thuong",1,"te",["Đang đứng trên bãi biển, bỗng nước rút ra xa bất thường, để lộ cả một dải đáy biển chưa ai từng thấy, cá nằm giãy trên cát. Nhiều người thấy lạ nên đi ra xem.","On a beach the sea suddenly draws far out, laying bare a stretch of seabed nobody has seen, fish flapping on the sand. Many people walk out to look."],["Phải làm gì?","What should you do?"],[["Chạy ngay lên chỗ cao nhất có thể, càng xa bờ càng tốt","Run for the highest ground you can reach, immediately"],["Đứng yên xem, vì nước rút thì không có gì nguy hiểm","Stay and watch — a retreating sea is nothing to fear"],["Đi ra nhặt cá, vì lát nữa nước sẽ về như cũ","Go and gather the fish before the water returns"]],0,["Nước rút xa bất thường là một trong những dấu hiệu rõ nhất của sóng thần đang tới, và nó thường chỉ báo trước vài phút tới vài chục phút. Sóng thần là một con sóng rất DÀI: nếu bờ của bạn đón phải cái đáy sóng trước thì biển bị hút ra xa, rồi đỉnh sóng ập vào ngay sau đó. Năm 2004 ở Ấn Độ Dương, rất nhiều người chết vì đã đi ra bãi cát vừa lộ ra để xem. Có một đứa trẻ mười tuổi người Anh vừa học đúng chuyện này ở trường, nhận ra dấu hiệu, và kịp báo cho cả bãi biển ở Thái Lan chạy lên cao. Đây là loại kiến thức mà học một lần dùng cả đời, và có khi chỉ dùng đúng một lần.","A sea drawing unusually far out is among the clearest warnings of an approaching tsunami, and it usually gives only minutes. A tsunami is a very LONG wave: if your shore meets the trough first, the sea is sucked away and the crest follows straight behind. In the Indian Ocean in 2004 many people died having walked out onto the newly bared sand to look. A ten-year-old British girl who had just learned this at school recognised it and got a whole beach in Thailand up to high ground in time. It is the kind of knowledge learned once and carried for life, and perhaps used exactly once."]),n("song-than-ngoai-khoi",3,"te",["Một con tàu giữa đại dương đi ngay trên một con sóng thần mà thuỷ thủ không hay biết: ngoài khơi nó chỉ cao nửa mét và dài hàng trăm cây số. Vào tới bờ thì cao mấy chục mét.","A ship in mid-ocean rides straight over a travelling tsunami without the crew noticing: out there it stands only half a metre high and runs hundreds of kilometres from crest to crest. Yet at the shore it rears tens of metres."],["Vì sao vào bờ nó lại cao lên khủng khiếp như thế?","Why does it rear up so terribly at the coast?"],[["Vì nó gom thêm nước dọc đường đi","Because it picks up more water along the way"],["Vì nước nông làm sóng chạy chậm lại, phần đuôi dồn lên phần đầu, và năng lượng dồn vào chiều cao","Because shallow water slows it, the back piles into the front, and the energy is forced into height"],["Vì đáy biển gần bờ dốc nên hất sóng lên","Because the seabed slopes up near the shore and throws the wave upward"]],1,["Sóng chạy trong nước sâu thì rất nhanh — sóng thần ngoài khơi đi khoảng 800 km một giờ, bằng máy bay phản lực — nhưng năng lượng của nó trải mỏng ra trên một chiều dài mấy trăm cây số và suốt cả chiều sâu của biển, nên bề mặt chỉ nhô lên vài chục xăng-ti-mét. Vào tới chỗ nông, phần đầu sóng chạm đáy và chậm hẳn lại trong khi phần đuôi còn ở nước sâu vẫn lao tới — cả con sóng bị dồn ngắn lại. Ngần ấy năng lượng ép vào một khoảng ngắn hơn và một cột nước nông hơn thì chỉ còn một chỗ để đi: lên cao. Đây cũng là lý do sóng thần không giống sóng vỗ bờ bình thường — nó không đổ ập rồi rút, nó là mực nước biển dâng lên và cứ dâng, đi sâu vào đất liền hàng cây số.","Waves in deep water are fast — a tsunami crosses the ocean at about 800 km an hour, the speed of a jet — but its energy is spread over hundreds of kilometres of length and the whole depth of the sea, so the surface rises only tens of centimetres. In the shallows the front touches bottom and slows while the back, still in deep water, keeps coming — and the whole wave is compressed. The same energy squeezed into a shorter length and a shallower column of water has one place left to go: upward. It is also why a tsunami is nothing like an ordinary breaker — it does not crash and withdraw, it is the sea level rising and continuing to rise, kilometres inland."])])],k=[t("bong-do",["Bóng Đổ","Shadows"],["Bóng là chỗ ánh sáng bị chặn — nên bóng kể lại hình của nguồn sáng","A shadow is where light was blocked — so shadows tell you the shape of the source"],[n("mat-nhin-thay-bang-cach-nao",1,"te",["Trong một căn phòng tối hoàn toàn, không một khe sáng nào, bạn không nhìn thấy gì cả — kể cả bàn tay đưa sát mặt. Bật đèn lên là thấy ngay.","In a room with no light at all you see nothing — not even your own hand held to your face. Switch on a lamp and there it is."],["Bạn nhìn thấy bàn tay bằng cách nào?","How do you see the hand?"],[["Mắt phát ra một thứ gì đó chiếu tới bàn tay rồi nhận lại","The eye sends something out to the hand and gets it back"],["Ánh sáng từ đèn dội khỏi bàn tay rồi đi vào mắt bạn","Light from the lamp bounces off the hand and enters your eye"],["Bàn tay tự phát ra ánh sáng yếu mà chỉ thấy được khi phòng sáng","The hand gives off a faint light that only shows when the room is lit"]],1,["Mắt không phát ra gì hết — nó chỉ là cái hứng. Mọi thứ bạn nhìn thấy trong đời đều là ánh sáng do một nguồn nào đó phát ra, dội qua vài lần, rồi rơi vào mắt bạn. Người Hy Lạp cổ từng tin ngược lại, rằng mắt bắn ra những tia đi dò tìm, và cái ý ấy nghe rất hợp lý cho tới khi có người hỏi: vậy sao trong bóng tối các tia đó không dò được gì? Cả chương này về sau chỉ là một câu hỏi lặp đi lặp lại: từ nguồn sáng tới mắt bạn, ánh sáng đã đi qua những đâu và bị bẻ ở chỗ nào.","The eye emits nothing — it only catches. Everything you have ever seen is light from some source, bounced a few times, landing in your eye. The ancient Greeks believed the reverse, that eyes shoot out feeling rays, and it sounds entirely reasonable until somebody asks why those rays find nothing in the dark. Everything that follows in this set is one question asked again and again: between the source and your eye, where did the light go and where was it bent."]),n("mep-bong-sac-hay-nhoe",2,"tp",["Giơ bàn tay lên trước một bức tường. Dưới nắng mặt trời giữa trưa, mép bóng bàn tay sắc nét. Dưới một cái đèn tuýp dài trên trần, mép bóng nhoè ra, và càng đưa tay xa tường thì càng nhoè.","Hold a hand up to a wall. In noon sunlight the shadow has a crisp edge. Under a long fluorescent tube it blurs, and the further the hand from the wall the blurrier it gets."],["Cái gì quyết định mép bóng sắc hay nhoè?","What decides whether a shadow edge is sharp or soft?"],[["Nguồn sáng mạnh hay yếu","How bright the source is"],["Nguồn sáng lớn hay nhỏ khi nhìn từ chỗ bức tường","How large the source looks from where the wall is"],["Ánh sáng nóng hay lạnh","Whether the light is warm or cool in colour"]],1,["Bóng nhoè là chỗ chỉ chặn được MỘT PHẦN nguồn sáng. Nếu nguồn là một điểm thì mỗi chỗ trên tường hoặc thấy được cả nguồn hoặc không thấy gì — mép sắc như dao cắt. Nếu nguồn là một cái đèn dài thì có cả một dải trên tường ở đó bạn thấy được nửa cái đèn, và dải ấy tối lờ mờ chứ không tối hẳn. Mặt Trời tuy khổng lồ nhưng ở rất xa nên nhìn từ Trái Đất nó chỉ bằng nửa độ — gần như một điểm, nên bóng nắng sắc. Đây là điều mà thợ chụp ảnh dùng hằng ngày: muốn ánh sáng dịu thì làm cho nguồn sáng TO ra, bằng cách căng một tấm vải trắng trước đèn.","A soft edge is where only PART of the source is blocked. If the source were a point, every spot on the wall either sees it or does not — an edge like a knife cut. With a long tube there is a whole band on the wall from which you can see half the tube, and that band is dimmed rather than dark. The Sun is enormous but so far away that from here it spans half a degree — near enough a point, so sunlight gives crisp shadows. Photographers use this daily: to soften light, make the source BIGGER by stretching white cloth in front of it."]),n("dom-nang-duoi-tan-cay",3,"tp",["Đứng dưới tán cây rậm giữa trưa nắng, nhìn xuống mặt sân: nắng lọt qua kẽ lá thành vô số đốm sáng, và các đốm ấy đều tròn, dù không kẽ lá nào có hình tròn cả.","Under a leafy tree at noon, look at the ground: sunlight through the gaps makes countless bright patches, and they are all round — though not one gap in the leaves is round."],["Vì sao các đốm nắng đều tròn?","Why are the patches round?"],[["Vì ánh sáng tự nhiên có xu hướng toả tròn ra","Because light naturally spreads into a circle"],["Vì mỗi kẽ lá là một cái lỗ kim, và mỗi đốm sáng chính là một cái ảnh của Mặt Trời","Because each gap is a pinhole, and each patch is an image of the Sun"],["Vì gió làm lá rung nên các đốm bị nhoè thành tròn","Because the leaves stir in the wind and blur the patches round"]],1,["Một cái lỗ nhỏ chiếu lên mặt phẳng phía sau một cái ảnh của thứ ở phía trước nó — đó là cái máy ảnh lỗ kim, thứ máy ảnh đầu tiên loài người làm ra. Kẽ lá đóng đúng vai cái lỗ ấy, và cái ở phía trước là Mặt Trời, vốn tròn. Nên mỗi đốm sáng là một tấm ảnh nhỏ của Mặt Trời, chứ không phải cái bóng của kẽ lá. Cách kiểm chứng thì tuyệt đẹp: vào ngày có nhật thực một phần, ra đứng dưới gốc cây và nhìn xuống — mọi đốm nắng đều biến thành hình lưỡi liềm, quay cùng một chiều. Cả tán cây trở thành hàng nghìn cái máy ảnh cùng chụp một tấm.","A small hole casts on the surface behind it an image of whatever is in front — that is the pinhole camera, the first camera people made. A gap in the leaves plays the hole, and what is in front is the Sun, which is round. So each patch is a small photograph of the Sun rather than a shadow of the gap. The check is beautiful: on the day of a partial eclipse, stand under a tree and look down — every patch has become a crescent, all facing the same way. The whole canopy turns into thousands of cameras taking one picture."]),n("bong-tren-tuyet-mau-gi",3,"tp",["Một ngày nắng đẹp, trời trong xanh, trên một cánh đồng tuyết trắng. Bạn đứng đó và nhìn cái bóng của chính mình đổ trên tuyết.","A bright day with a clear blue sky, on a field of white snow. You look at your own shadow lying on the snow."],["Cái bóng ấy màu gì?","What colour is that shadow?"],[["Xám, vì bóng là chỗ ít sáng hơn","Grey — a shadow is simply a darker place"],["Xanh lam thấy rõ","Distinctly blue"],["Đen, vì hoàn toàn không có ánh sáng nào tới đó","Black — no light reaches it at all"]],1,["Chỗ có bóng không hề tối om: nó chỉ bị che mất Mặt Trời, còn cả bầu trời thì vẫn chiếu xuống nó. Mà bầu trời thì màu xanh lam. Nên vùng bóng chỉ được chiếu sáng bằng ánh sáng xanh của bầu trời, còn vùng ngoài bóng thì nhận cả ánh nắng vàng trực tiếp lẫn ánh trời. Đặt hai vùng cạnh nhau thì mắt thấy rõ cái chênh lệch màu ấy. Các hoạ sĩ Ấn tượng đã vẽ bóng màu xanh lam và bị chê là bịa đặt, cho tới khi người ta chịu ra ngoài nhìn kỹ. Bài học chung: muốn biết một chỗ có màu gì thì đừng hỏi nó tối hay sáng, hãy hỏi ánh sáng nào đang tới được chỗ đó.","A shadow is not darkness: it is merely a place with the Sun hidden, while the whole sky still shines on it. And the sky is blue. So the shadowed patch is lit by blue skylight alone, while the sunlit patch receives direct yellow sunlight as well. Set side by side, the eye reads the difference plainly. The Impressionists painted blue shadows and were accused of inventing them, until people agreed to go outside and look. The general lesson: to ask what colour a place is, do not ask whether it is dark, ask what light is reaching it."]),n("nhat-thuc-hay-nguyet-thuc",2,"te",["Nhật thực là Mặt Trăng che khuất Mặt Trời. Nguyệt thực là Trái Đất đổ bóng lên Mặt Trăng. Cả hai đều hiếm gặp gần như nhau.","A solar eclipse is the Moon covering the Sun. A lunar eclipse is the Earth casting its shadow on the Moon. Both happen about as often as each other."],["Loại nào có nhiều người trên Trái Đất xem được hơn hẳn?","Which of the two is seen by far more people?"],[["Nhật thực","The solar eclipse"],["Nguyệt thực","The lunar eclipse"],["Hai loại như nhau","About the same for both"]],1,['Nguyệt thực xảy ra Ở TRÊN Mặt Trăng, nên bất cứ ai đang nhìn thấy Mặt Trăng lúc đó đều xem được — tức là cả nửa Trái Đất đang là ban đêm, hàng tỉ người, và xem hàng tiếng đồng hồ. Nhật thực toàn phần thì ngược hẳn: cái bóng Mặt Trăng đổ xuống Trái Đất chỉ là một vệt rộng chừng trăm cây số quét ngang địa cầu, và đứng đúng trong vệt đó mới thấy toàn phần, mỗi lần chỉ vài phút. Đây là chỗ mà chữ "hiếm" đánh lừa: hai hiện tượng xảy ra gần bằng nhau, nhưng cơ hội một người cụ thể được nhìn thấy thì chênh nhau hàng trăm lần — vì cái khác nhau nằm ở chỗ CÁI BÓNG ĐỔ LÊN ĐÂU.',"A lunar eclipse happens AT the Moon, so anybody who can see the Moon can watch it — half the Earth, in its night, billions of people, for hours at a time. A total solar eclipse is the opposite: the shadow of the Moon lands on the Earth as a track about a hundred kilometres wide sweeping across the globe, and only those standing in it see totality, for a few minutes. This is where the word rare misleads: the two events occur about equally often, yet the chance of any given person seeing one differs by hundreds of times — because what differs is WHERE THE SHADOW FALLS."])]),t("guong-soi",["Gương Soi","Mirrors"],["Gương không lật trái phải — nó lật trước sau","A mirror does not swap left and right — it swaps front and back"],[n("anh-trong-guong-o-dau",1,"tp",["Đứng cách một tấm gương phẳng treo trên tường đúng một mét, nhìn ảnh của mình. Bây giờ lùi lại thêm một mét nữa.","Stand exactly one metre from a flat mirror on a wall and look at your reflection. Now step back another metre."],["Ảnh của bạn bây giờ cách bạn bao xa?","How far is your reflection from you now?"],[["Hai mét, vì bạn lùi thêm một mét","Two metres — you moved back one"],["Bốn mét","Four metres"],["Vẫn hai mét như lúc đầu","Still two metres, as before"]],1,["Ảnh trong gương phẳng luôn nằm phía sau gương, cách gương đúng bằng khoảng cách từ bạn tới gương. Đứng cách một mét thì ảnh ở sau gương một mét, tổng cộng hai mét. Lùi ra hai mét thì ảnh cũng lùi vào hai mét, tổng cộng bốn — nghĩa là bạn lùi một bước thì khoảng cách giữa bạn và ảnh tăng hai bước. Đây là lý do khi bạn đi tới gần gương thì ảnh của bạn tiến tới nhanh gấp đôi so với cảm giác, và là lý do một tiệm nhỏ treo gương ở cuối phòng thì trông sâu gấp đôi.","The image in a flat mirror always lies behind the glass, as far behind as you stand in front. At one metre, the image is one metre behind and two metres from you. At two metres it is two behind and four away — so one step back opens the gap by two. This is why walking towards a mirror makes your reflection approach twice as fast as feels right, and why a small shop with a mirror at the back looks twice as deep."]),n("chu-nguoc-tren-xe-cuu-thuong",2,"te",["Trên nắp ca-pô xe cứu thương, chữ CỨU THƯƠNG được sơn lộn ngược từ phải sang trái, nhìn từ ngoài thấy rất khó đọc.","Across the bonnet of an ambulance the word AMBULANCE is painted reversed left to right, hard to read from outside."],["Vì sao người ta sơn như thế?","Why is it painted that way?"],[["Để cho khác các xe khác, dễ nhận ra từ xa","To look unlike other vehicles and stand out at a distance"],["Để tài xế xe phía trước đọc được nó qua gương chiếu hậu","So the driver ahead can read it in the rear-view mirror"],["Để dễ đọc khi trời tối và đèn pha chiếu vào","So that it reads better in headlights at night"]],1,["Người cần đọc dòng chữ ấy nhất là người đang lái xe phía trước và phải nhường đường ngay. Người đó không quay đầu lại nhìn được, họ nhìn qua gương chiếu hậu — mà gương thì đảo hình lại. Nên viết ngược sẵn thì trong gương nó thành xuôi. Đây là một ví dụ đẹp của việc thiết kế cho ĐÚNG người đọc trong ĐÚNG hoàn cảnh, chứ không thiết kế cho người đứng ngoài nhìn vào.","The person who most needs to read it is driving ahead and must give way at once. They cannot turn round; they look in the mirror — and a mirror reverses. Write it reversed and the mirror makes it right. It is a fine example of designing for the ACTUAL reader in the ACTUAL situation rather than for a bystander looking on."]),n("guong-loi-o-goc-cua",2,"te",["Ở góc cua khuất trong ngõ hẹp, người ta treo một cái gương LỒI, mặt phình ra ngoài. Nhìn vào đó thấy cả một khúc đường rất rộng, nhưng mọi thứ trông nhỏ đi và xa hơn thật.","At a blind corner in a narrow lane hangs a CONVEX mirror, bulging outward. It shows a wide stretch of road, but everything looks smaller and further away than it is."],["Vì sao dùng gương lồi mà không dùng gương phẳng?","Why a convex mirror rather than a flat one?"],[["Vì gương lồi gom được ánh sáng từ một góc rộng hơn nhiều vào cùng một tấm gương nhỏ","Because a convex mirror gathers light from a far wider angle into the same small piece of glass"],["Vì gương lồi làm hình sáng hơn","Because a convex mirror makes a brighter image"],["Vì gương lồi khó vỡ hơn","Because a convex mirror is harder to break"]],0,["Mặt gương cong ra ngoài thì mỗi mảnh nhỏ của nó quay về một hướng hơi khác nhau, nên cả tấm gương hứng được cảnh vật từ một góc rất rộng. Cái giá phải trả là toàn bộ khúc đường rộng ấy bị nhét vào một tấm gương nhỏ, nên mọi thứ co lại và trông xa hơn thật. Đó chính là lý do gương chiếu hậu bên phải của ô tô luôn có dòng chữ cảnh báo rằng vật thật ra gần hơn vẻ ngoài — người ta cố tình đánh đổi độ chính xác của khoảng cách để lấy tầm nhìn rộng, và bắt buộc phải nói cho tài xế biết mình vừa đánh đổi cái gì.","A surface curving outward points each little piece of itself a slightly different way, so one sheet of glass collects the scene from a very wide angle. The price is that the whole wide scene is packed into a small mirror, so everything shrinks and reads as further off. That is exactly why the passenger-side mirror on a car carries a warning that objects are closer than they appear — the width was bought deliberately at the cost of distance, and the driver has to be told what was traded."]),n("guong-cao-bao-nhieu-la-du",3,"tp",["Bạn muốn treo một tấm gương phẳng trên tường sao cho nhìn thấy được toàn thân mình, từ đỉnh đầu tới gót chân. Bạn cao 160 xăng-ti-mét. Tia sáng đập vào gương nảy ra đúng bằng cái góc nó đập vào.","You want a flat mirror on the wall in which you can see yourself from the top of your head to your heels. You are 160 centimetres tall."],["Tấm gương phải cao ít nhất bao nhiêu?","How tall must the mirror be, at the least?"],[["160 xăng-ti-mét — phải cao bằng người mới thấy hết người","A full 160 — it must be as tall as you"],["80 xăng-ti-mét","80 centimetres"],["Tuỳ đứng gần hay xa: đứng càng xa thì gương càng cần nhỏ","It depends on distance — stand further back and a smaller mirror will do"]],1,["Chỉ cần một nửa chiều cao, và câu trả lời KHÔNG đổi dù bạn đứng gần hay xa. Lý do: tia sáng từ đỉnh đầu bạn muốn vào mắt bạn thì phải chạm gương ở đúng điểm giữa đỉnh đầu và mắt — cao hơn chỗ đó thì gương thừa. Tia từ gót chân phải chạm gương ở đúng điểm giữa gót và mắt. Khoảng cách giữa hai điểm chạm ấy luôn đúng bằng một nửa chiều cao của bạn. Lùi ra xa thì ảnh nhỏ đi thật, nhưng hai điểm chạm cũng không xê dịch, nên gương không cần nhỏ đi. Đây là câu mà hầu như ai cũng đoán sai lần đầu, và cũng là câu tiết kiệm được tiền thật khi đi mua gương.","Half your height is enough, and the answer does NOT change with distance. The reason: a ray from the top of your head reaching your eye must strike the glass exactly halfway between your crown and your eye — glass above that is wasted. A ray from your heels must strike halfway between heel and eye. The gap between those two points is always half your height. Step back and the image does shrink, but the two strike points do not move, so no smaller mirror will do. Nearly everybody gets this wrong at first, and getting it right saves real money at the shop."]),n("guong-lat-cai-gi",3,"tp",["Đứng trước gương giơ tay PHẢI lên, ảnh trong gương giơ tay trái. Nhưng nếu bạn nhảy lên thì ảnh cũng nhảy lên chứ không chúi đầu xuống.","Raise your RIGHT hand at a mirror and the reflection raises its left. Yet jump up and the reflection jumps up too — it does not go head down."],["Vậy rốt cuộc gương lật cái gì?","So what does a mirror actually reverse?"],[["Lật trái với phải, đúng như ta vẫn nói","Left and right, exactly as everyone says"],["Lật trước với sau — tức là chiều đâm vào gương","Front and back — the direction pointing into the glass"],["Không lật gì cả, chỉ là ta quen nhìn nhầm","Nothing at all — we simply misread it"]],1,['Gương không hề biết đâu là trái đâu là phải của bạn. Nó chỉ làm đúng một việc, và làm với mọi điểm như nhau: cái gì ở cách gương 30 phân về phía trước thì ảnh nằm 30 phân về phía sau. Trên dưới giữ nguyên, trái phải giữ nguyên, chỉ có chiều TRƯỚC-SAU bị đảo. Cái làm ta tưởng nó lật trái phải là do chính ta: để so mình với cái ảnh, ta tưởng tượng mình quay nửa vòng quanh trục đứng để đứng vào chỗ cái ảnh — và chính cú quay tưởng tượng đó mới đổi trái thành phải. Bằng chứng: nằm nghiêng người ra soi thì lập tức thấy gương "lật trên dưới", vì lúc đó ta tưởng tượng quay quanh một trục khác. Muốn kiểm tra thật gọn: viết chữ lên một tờ giấy trong, giơ lên soi — chữ trong gương xuôi hay ngược tuỳ bạn lật tờ giấy quanh trục nào.',"A mirror has no idea which side of you is left. It does one thing and does it to every point alike: whatever stands 30 centimetres in front lands 30 centimetres behind. Up stays up, left stays left, and only the FRONT-BACK direction is turned around. What makes us think otherwise is us: to compare ourselves with the image we imagine turning halfway round on the spot to stand where it stands — and that imagined turn is what swaps left for right. The proof: lie on your side and the mirror instantly seems to swap up and down, because now we imagine turning about a different axis. The neat test: write on a translucent sheet and hold it up — whether the writing reads correctly depends on which way you flipped the paper."])]),t("be-gay",["Bẻ Gãy","Bending Light"],["Ánh sáng đổi hướng khi đổi môi trường, và nó chọn đường nhanh nhất","Light turns when it changes medium, and it takes the quickest way"],[n("cai-thia-trong-coc-nuoc",1,"tp",["Cắm một cái thìa thẳng vào cốc nước, nhìn nghiêng từ bên cạnh: cái thìa trông như bị gãy khúc ngay tại mặt nước, phần dưới lệch hẳn đi.","Stand a straight spoon in a glass of water and look from the side: it appears broken at the surface, the lower half offset."],["Vì sao?","Why?"],[["Vì nước phóng to phần thìa nằm dưới","Because the water magnifies the lower part"],["Vì ánh sáng đi từ nước ra không khí thì đổi hướng ở mặt phân cách","Because light leaving the water for the air changes direction at the boundary"],["Vì mắt ta không quen nhìn xuyên qua nước","Because eyes are not used to looking through water"]],1,["Ánh sáng đi trong nước chậm hơn trong không khí, và ở đúng mặt phân cách giữa hai bên nó đổi hướng đột ngột. Mắt bạn thì không biết chuyện ấy — nó luôn giả định ánh sáng đi thẳng, nên nó truy ngược tia sáng theo đường thẳng và đặt phần thìa dưới nước vào một chỗ không đúng chỗ thật. Cái thìa vẫn thẳng nguyên; cái bị bẻ là ĐƯỜNG ĐI của ánh sáng, và cái đoán sai là bộ não. Mọi ảo ảnh trong bộ này đều thuộc đúng một kiểu như vậy.","Light moves more slowly in water than in air, and at the boundary between them it turns abruptly. Your eye knows nothing of this — it always assumes light came in a straight line, so it traces the ray straight back and puts the submerged part of the spoon somewhere it is not. The spoon is perfectly straight; what was bent is the PATH of the light, and what guessed wrong is the brain. Every illusion in this set is of exactly this kind."]),n("dam-ca-duoi-nuoc",3,"tp",["Đứng trên bờ, nhìn xuống nước thấy một con cá, và bạn phóng lao xuống. Nếu bạn nhắm thẳng vào chỗ nhìn thấy con cá thì lao sẽ trượt qua phía trên lưng nó.","Standing on the bank you see a fish below and throw a spear. Aim straight at where you see it and the spear passes over its back."],["Phải nhắm vào đâu?","Where should you aim?"],[["Thấp hơn chỗ nhìn thấy — con cá thật ra sâu hơn vẻ ngoài","Lower than it appears — the fish is deeper than it looks"],["Cao hơn chỗ nhìn thấy","Higher than it appears"],["Đúng chỗ nhìn thấy, chỉ cần phóng nhanh hơn","Straight at it, only faster"]],0,["Ánh sáng từ con cá đi lên, tới mặt nước thì bị bẻ quặt ra xa phương thẳng đứng trước khi tới mắt bạn. Mắt truy ngược theo đường thẳng nên đặt con cá CAO hơn và gần mặt nước hơn chỗ nó thật sự nằm. Nên phải nhắm thấp xuống. Người đi săn cá bằng lao ở khắp thế giới đều biết chuyện này bằng kinh nghiệm, từ rất lâu trước khi có ai viết ra định luật khúc xạ. Cùng cái bẻ ấy làm cho cái bể bơi luôn trông nông hơn thật — và đó là một trong những lý do người ta chết đuối ở chỗ tưởng là chỗ cạn.","Light from the fish rises to the surface and is bent away from the vertical before it reaches you. Your eye traces it straight back and places the fish HIGHER and nearer the surface than it truly is. So aim low. Spear fishers everywhere learned this by hand long before anyone wrote down a law of refraction. The same bending makes every swimming pool look shallower than it is — one of the reasons people drown in what they took for the shallow end."]),n("cau-vong-o-phia-nao",2,"tp",["Cầu vồng chỉ hiện ra khi vừa có mưa vừa có nắng. Bạn ra sân, thấy cầu vồng.","A rainbow appears only when rain and sunshine happen together. You step outside and there it is."],["Cầu vồng nằm ở phía nào so với Mặt Trời?","Where is the rainbow in relation to the Sun?"],[["Cùng phía với Mặt Trời","On the same side as the Sun"],["Ở phía đối diện hẳn với Mặt Trời — Mặt Trời luôn sau lưng người xem","On the exactly opposite side — the Sun is always behind the viewer"],["Ở ngay trên đỉnh đầu, không liên quan tới Mặt Trời","Straight overhead, unrelated to the Sun"]],1,["Mỗi giọt mưa làm hai việc: bẻ ánh nắng khi đi vào, dội một lần ở mặt sau giọt, rồi bẻ lần nữa khi đi ra. Cái dội ở mặt sau là chỗ quan trọng — nó hắt ánh sáng QUAY LẠI phía Mặt Trời tới, tức là về phía bạn nếu Mặt Trời ở sau lưng bạn. Vì thế cầu vồng bao giờ cũng nằm đối diện Mặt Trời, và tâm của vòng cung ấy nằm đúng ở cái bóng của chính đầu bạn. Cũng vì thế Mặt Trời càng lên cao thì cầu vồng càng thấp xuống, và quá trưa nắng gắt thì không thấy cầu vồng nữa — vòng cung đã tụt xuống dưới chân trời. Từ máy bay thì thấy được cả một vòng tròn kín.","Each raindrop does two things: it bends the sunlight going in, bounces it once off the back of the drop, and bends it again coming out. The bounce is the crucial part — it sends the light BACK towards the Sun, which is towards you if the Sun is behind you. So a rainbow always sits opposite the Sun, and the centre of the arc is exactly the shadow of your own head. It is also why a higher Sun means a lower rainbow, and why none appears in the middle of a bright day — the arc has sunk below the horizon. From an aircraft you can see the full circle."]),n("kinh-lup-lam-gi",2,"te",["Cái kính lúp là một miếng thuỷ tinh dày ở giữa, mỏng dần ra rìa. Đưa nó lại gần một dòng chữ nhỏ thì chữ to ra; đưa nó hứng nắng thì gom nắng lại thành một chấm sáng chói đốt cháy được giấy.","A magnifying glass is a disc of glass thick in the middle and thin at the rim. Held over small print it enlarges the letters; held in sunlight it draws the light to a burning point."],["Hai chuyện đó có chung một nguyên nhân gì?","What single cause is behind both?"],[["Thuỷ tinh bẻ mọi tia sáng đi qua nó chụm về một chỗ","The glass bends every ray passing through it towards one place"],["Thuỷ tinh phóng đại mọi thứ vì nó trong suốt","Glass enlarges things because it is transparent"],["Thuỷ tinh giữ ánh sáng lại rồi phát ra mạnh hơn","Glass stores light and gives it out more strongly"]],0,["Mỗi tia sáng đi vào miếng thuỷ tinh đều bị bẻ, và vì hai mặt của nó cong nên mọi tia đều bị bẻ chụm về một điểm. Hứng nắng thì cả một vòng tròn nắng bị dồn vào một chấm — chấm ấy nhận ngần ấy năng lượng trên một diện tích bé xíu, nên nóng tới mức cháy. Đưa lại gần chữ thì các tia từ chữ bị bẻ ra thành một chùm loe hơn, mắt truy ngược lại và thấy một cái chữ lớn hơn ở xa hơn. Cùng một miếng thuỷ tinh, cùng một việc bẻ tia. Và đó cũng là toàn bộ việc mà thuỷ tinh thể trong mắt bạn đang làm suốt ngày — kính cận, kính viễn chỉ là bù thêm phần bẻ còn thiếu hoặc bớt đi phần bẻ thừa.","Every ray entering the glass is bent, and because both faces are curved they are all bent towards one place. In sunlight a whole disc of light is gathered into a point, and that point receives all that energy on a tiny area, so it scorches. Over print, rays from the letters are bent into a wider cone, the eye traces them back, and sees a bigger letter further away. One piece of glass, one act of bending. It is also the whole job of the lens inside your eye — spectacles only add the bending it lacks or take away the bending it has too much of."]),n("vi-sao-anh-sang-be-cong",3,"tp",["Người cứu hộ trên cát thấy người đuối nước chếch sang bên. Chạy trên cát nhanh hơn bơi rất nhiều. Người giỏi không lao thẳng xuống, mà chạy chếch thêm một đoạn trên cát rồi mới xuống nước.","A lifeguard on sand sees a swimmer in trouble off to one side. Running on sand is far faster than swimming. A good lifeguard does not run straight at the swimmer but runs further along the sand first and enters the water nearer them."],["Ánh sáng đi từ không khí vào nước cũng bẻ đúng kiểu ấy. Vì sao?","Light entering water from air bends in exactly the same way. Why?"],[["Vì nước hút ánh sáng về phía nó","Because water attracts light towards itself"],["Vì ánh sáng đi theo đường tốn ÍT THỜI GIAN nhất, chứ không phải đường ngắn nhất","Because light takes the path of LEAST TIME, not the shortest path"],["Vì các hạt nước va vào tia sáng và hất nó lệch đi","Because water particles knock the ray sideways"]],1,["Đường thẳng là đường NGẮN nhất, nhưng nếu một đoạn của nó phải đi qua vùng chậm thì nó không phải đường NHANH nhất. Người cứu hộ chấp nhận chạy dài hơn trên cát để rút ngắn đoạn phải bơi, và tổng thời gian nhỏ đi. Ánh sáng làm y hệt: nó đi trong nước chậm hơn, nên đường nó thật sự đi là đường kéo dài phần trong không khí và rút ngắn phần trong nước — và cái đường ấy trông đúng như bị bẻ gãy tại mặt nước. Đây là nguyên lý Fermat, và nó đẹp ở chỗ nó giải thích được cả gương, cả thấu kính, cả cầu vồng bằng đúng một câu: trong mọi đường có thể đi, ánh sáng đi đường mất ít thời gian nhất.","A straight line is the SHORTEST path, but if part of it lies in slow country it is not the QUICKEST. The lifeguard accepts more running to buy less swimming, and the total time falls. Light does the same: it moves more slowly in water, so the path it actually takes lengthens the air leg and shortens the water leg — and that path looks exactly like a break at the surface. This is Fermat’s principle, and its beauty is that mirrors, lenses and rainbows all follow from one sentence: of all the paths available, light takes the one that costs the least time."])]),t("mau-sac",["Màu Sắc","Colour"],["Màu của một vật là màu nó KHÔNG giữ lại","The colour of a thing is the colour it did not keep"],[n("vi-sao-cai-ao-mau-do",1,"te",["Ánh nắng trắng thật ra là mọi màu trộn lại — cho nó qua một lăng kính là thấy đủ cả dải. Bây giờ chiếu ánh nắng ấy vào một cái áo màu đỏ.","White sunlight is really every colour mixed — send it through a prism and the whole band appears. Now shine that sunlight on a red shirt."],["Vì sao cái áo trông màu đỏ?","Why does the shirt look red?"],[["Vì nó tự sinh ra ánh sáng đỏ","Because it makes red light of its own"],["Vì nó nuốt gần hết các màu khác và hắt màu đỏ trở lại mắt bạn","Because it swallows nearly every other colour and throws red back at you"],["Vì thuốc nhuộm đỏ làm ánh sáng trắng đổi thành đỏ","Because the red dye turns white light into red light"]],1,["Cái áo không thêm gì vào ánh sáng cả — nó chỉ LẤY BỚT. Thuốc nhuộm hấp thụ phần lam, phần lục, phần vàng, giữ chúng lại thành nhiệt, và trả lại phần đỏ. Nên cái mà bạn gọi là màu của cái áo chính là phần ánh sáng mà cái áo KHÔNG dùng. Ngẫm ra thì hơi lạ: ta gọi tên đồ vật theo đúng cái phần chúng vứt đi. Đây cũng là lý do áo đen nóng hơn áo trắng dưới nắng — đen nghĩa là giữ lại gần hết, và giữ lại thì thành nhiệt.","The shirt adds nothing to the light — it TAKES AWAY. The dye absorbs the blue, the green and the yellow, keeps them as heat, and returns the red. So what you call the colour of the shirt is precisely the light the shirt had no use for. Put that way it is a little strange: we name things after what they threw out. It is also why a black shirt is hotter than a white one in the sun — black means keeping nearly all of it, and keeping it means heat."]),n("ao-xanh-duoi-den-do",2,"tp",["Một căn phòng tối chỉ có duy nhất một cái đèn đỏ, không có tí ánh sáng nào khác. Bạn mang vào đó một cái áo màu xanh lam tươi.","A dark room lit only by a single red lamp, with no other light of any kind. You carry in a bright blue shirt."],["Cái áo trông màu gì?","What colour does the shirt look?"],[["Vẫn xanh lam, chỉ tối hơn","Still blue, only darker"],["Gần như đen","Nearly black"],["Màu tím, vì đỏ trộn với xanh","Purple — red mixed with blue"]],1,["Cái áo xanh chỉ hắt lại được ánh xanh, mà trong phòng ấy không hề có ánh xanh nào để hắt. Ánh đỏ chiếu vào thì bị cái áo nuốt gần hết, nên gần như không có gì quay lại mắt bạn — và không có gì quay lại thì đó chính là màu đen. Muốn thấy một màu thì phải có sẵn màu đó trong ánh sáng chiếu vào; vật thể không sáng tạo ra màu, nó chỉ chọn lọc. Đây là lý do đứng dưới đèn đường màu cam thì không phân biệt nổi cái áo đỏ với cái áo nâu, và là lý do các cửa hàng quần áo rất kỹ tính về loại đèn họ lắp.","A blue shirt can only return blue, and in that room there is no blue to return. The red falling on it is nearly all swallowed, so almost nothing comes back to your eye — and nothing coming back is what black means. To see a colour it must be present in the light arriving; objects do not create colour, they only select. It is why under orange street lamps a red coat and a brown one are indistinguishable, and why clothes shops are so particular about the lamps they fit."]),n("tron-mau-anh-sang-va-son",3,"tp",["Chiếu chồng lên nhau một chùm sáng ĐỎ và một chùm sáng LỤC lên bức tường trắng, chỗ chồng nhau hiện ra màu vàng tươi. Nhưng lấy sơn đỏ trộn với sơn lục thì ra một màu nâu xỉn.","Shine a RED beam and a GREEN beam onto a white wall so they overlap, and the overlap is bright yellow. Yet mix red paint with green paint and you get a dull brown."],["Vì sao hai cách trộn lại cho hai kết quả khác hẳn nhau?","Why do the two kinds of mixing give such different results?"],[["Vì sơn có tạp chất còn ánh sáng thì tinh khiết","Because paint has impurities and light is pure"],["Vì trộn ánh sáng là CỘNG thêm màu vào, còn trộn sơn là mỗi loại lại NUỐT thêm màu đi","Because mixing light ADDS colours together, while mixing paint means each one SUBTRACTS more"],["Vì mắt người nhìn sơn khác nhìn ánh sáng","Because the eye reads paint differently from light"]],1,["Hai chùm sáng chồng lên nhau thì mắt bạn nhận được cả đỏ lẫn lục cùng lúc, và bộ não gọi cái tổ hợp ấy là vàng — đó là cách màn hình điện thoại tạo ra mọi màu từ đúng ba chấm đỏ, lục, lam. Còn sơn thì làm việc bằng cách nuốt bớt: sơn đỏ nuốt lục và lam, sơn lục nuốt đỏ và lam. Trộn hai thứ ấy thì cả hai cùng nuốt, gần như chẳng còn màu nào sống sót, và cái còn lại là một màu tối đục. Cộng vào thì càng trộn càng sáng, tới cùng là trắng; nuốt đi thì càng trộn càng tối, tới cùng là đen. Đây là chỗ mà hai thế giới màu — màn hình và giấy in — không bao giờ khớp nhau hoàn toàn được, và thợ in phải sống chung với chuyện đó.","Two beams overlapping deliver both red and green to your eye at once, and the brain calls that combination yellow — this is how a phone screen makes every colour from just three dots of red, green and blue. Paint works by removal: red paint eats green and blue, green paint eats red and blue. Mix them and both do their eating, almost nothing survives, and what remains is a muddy dark. Adding gets brighter the more you mix, ending in white; subtracting gets darker, ending in black. This is exactly where the two worlds of colour — screens and printed paper — can never quite be made to agree, and printers live with it."]),n("cau-vong-may-mau",2,"tp",["Ai cũng học rằng cầu vồng có bảy màu: đỏ, cam, vàng, lục, lam, chàm, tím. Nhìn kỹ một cái cầu vồng thật thì không thấy có vạch ngăn nào giữa các màu.","Everyone is taught that a rainbow has seven colours. Look closely at a real one and there are no dividing lines anywhere."],["Thật ra cầu vồng có bao nhiêu màu?","How many colours does a rainbow really have?"],[["Đúng bảy — đó là con số của tự nhiên","Exactly seven — that is nature’s number"],["Một dải liền không có ranh giới; chia thành bảy là chuyện con người tự đặt ra","One unbroken band with no boundaries; the seven are a human invention"],["Ba, vì mắt người chỉ có ba loại tế bào màu","Three, because the eye has only three kinds of colour cell"]],1,["Ánh sáng đi ra khỏi giọt mưa theo một dải liên tục, đổi dần dần chứ không nhảy bậc — giữa vàng và lục có vô số sắc trung gian, không có chỗ nào để kẻ một vạch. Newton là người chọn con số bảy, và ông chọn nó một phần vì muốn cho hợp với bảy nốt nhạc, chứ không phải vì đo được bảy. Nhiều nền văn hoá đếm khác hẳn: có nơi chỉ gọi tên bốn màu trong cầu vồng, có nơi sáu. Bài học ở đây không phải về cầu vồng mà về mọi cái bảng phân loại: cái ranh giới thường là do người vẽ ra để dễ nói chuyện, còn thứ ngoài kia thì cứ liền một dải.","Light leaves a raindrop as an unbroken band, shading continuously rather than stepping — between yellow and green lie countless intermediate shades with nowhere to draw a line. Newton chose seven, and chose it partly to match the seven notes of a musical scale rather than because he measured seven. Other cultures count quite differently: some name four colours in a rainbow, some six. The lesson is not about rainbows but about every scheme of categories: the boundaries are usually drawn by people so they can talk, while the thing out there runs on unbroken."]),n("vi-sao-la-cay-mau-luc",3,"te",["Cây sống bằng cách bắt ánh nắng và biến nó thành thức ăn. Ánh nắng thì đủ mọi màu. Lá cây thì màu lục.","Plants live by catching sunlight and turning it into food. Sunlight comes in every colour. Leaves are green."],["Màu lục của lá nói lên điều gì về cách cây dùng ánh sáng?","What does that green tell you about how a plant uses light?"],[["Lá dùng ánh lục là chính, vì thế nó mới có màu lục","Green is the colour it mainly uses, which is why it looks green"],["Lá dùng ánh đỏ và ánh lam, còn ánh lục thì hắt trả lại — nghĩa là lục là màu cây KHÔNG dùng","It uses red and blue and throws the green back — meaning green is the colour it does NOT use"],["Màu lá không liên quan gì tới ánh sáng, nó là màu của nhựa cây","Leaf colour has nothing to do with light; it is the colour of the sap"]],1,["Chất diệp lục hấp thụ mạnh nhất ở vùng đỏ và vùng lam, và hắt trả vùng lục — nên cây xanh là dấu hiệu của một phần ánh sáng bị BỎ QUA. Điều này làm nhiều người ngạc nhiên, vì ánh lục lại chính là vùng mạnh nhất trong ánh nắng. Vì sao cây lại bỏ qua đúng phần dồi dào nhất thì cho tới nay vẫn còn tranh luận; một cách giải thích là những sinh vật quang hợp đầu tiên đã chiếm mất vùng lục từ trước, nên lớp sau phải sống bằng phần thừa. Dù lý do là gì, cái quy tắc ở câu đầu bộ này vẫn đứng vững cho cả một khu rừng: màu bạn nhìn thấy là phần bị vứt đi.","Chlorophyll absorbs most strongly in the red and the blue and returns the green — so a green world is the sign of a slice of sunlight being PASSED OVER. This surprises people, because green is the strongest part of sunlight. Why plants should skip the most plentiful part is still argued about; one account is that earlier photosynthesising life had already claimed the green, leaving later arrivals the leftovers. Whatever the reason, the rule from the first question of this set holds for an entire forest: the colour you see is the part that was discarded."])]),t("troi-xanh",["Trời Xanh","The Blue Sky"],["Bầu trời có màu vì không khí tán ánh sáng ra, và nó kén màu","The sky has colour because air scatters light — and it is fussy about which"],[n("vi-sao-troi-xanh",1,"te",["Không khí thì trong suốt: nhìn ngang qua một căn phòng không thấy nó có màu gì. Vậy mà nhìn lên bầu trời giữa ban ngày thì thấy một màu xanh lam đậm.","Air is transparent: look across a room and it has no colour at all. Yet look up at midday and the sky is deep blue."],["Màu xanh ấy từ đâu ra?","Where does that blue come from?"],[["Từ nước biển hắt lên trời","Reflected up from the sea"],["Các hạt khí hất ánh lam đi tứ tung mạnh hơn hẳn ánh đỏ, nên nhìn hướng nào cũng có ánh lam rơi vào mắt","Air particles fling blue light about far more than red, so from every direction blue arrives at your eye"],["Từ lớp ozon màu xanh trên cao","From a blue layer of ozone high up"]],1,["Các hạt khí rất nhỏ so với bước sóng ánh sáng, và những hạt như thế hất ánh sáng bước sóng NGẮN mạnh hơn hẳn bước sóng dài — ánh lam bị hất mạnh hơn ánh đỏ cả chục lần. Nên ánh nắng đi xuyên qua khí quyển bị bóc dần phần lam ra và rải khắp bầu trời. Bạn ngước nhìn bất cứ hướng nào cũng có ánh lam từ hướng đó rơi vào mắt, và bạn gọi đó là màu của bầu trời. Trong một căn phòng thì lớp không khí quá mỏng nên chẳng hất được bao nhiêu, và nó vẫn trong suốt. Bầu trời xanh không phải một vật màu xanh — nó là ánh nắng bị tán ra, nhìn từ bên cạnh.","Air particles are very small compared with the wavelength of light, and such particles fling SHORT wavelengths about far more than long ones — blue is scattered some ten times as strongly as red. So sunlight crossing the atmosphere is stripped of blue, which is spread across the whole sky. Look in any direction and blue from that direction lands in your eye, and you call it the colour of the sky. Across a room the layer of air is too thin to scatter noticeably and it stays clear. A blue sky is not a blue object — it is sunlight scattered, seen from the side."]),n("hoang-hon-mau-do",2,"te",["Cũng bầu trời ấy, cũng không khí ấy. Nhưng lúc mặt trời sắp lặn thì nó chuyển sang cam rồi đỏ rực.","The same sky and the same air. But as the Sun goes down it turns orange and then a burning red."],["Vì sao?","Why?"],[["Vì mặt trời lúc lặn thật sự nóng hơn nên đỏ hơn","Because the setting Sun is genuinely hotter and so redder"],["Vì ánh nắng phải xuyên một quãng khí quyển dài hơn nhiều, ánh lam bị hất đi hết dọc đường, chỉ còn đỏ tới nơi","Because the light must cross far more atmosphere, the blue is scattered away along the road, and only red survives the journey"],["Vì bụi buổi chiều nhiều hơn buổi sáng","Because there is more dust in the evening than in the morning"]],1,["Giữa trưa, ánh nắng chỉ xuyên thẳng qua chừng vài chục cây số khí quyển. Lúc sắp lặn, nó đi xiên gần như song song mặt đất và phải xuyên qua một quãng khí dài gấp mấy chục lần. Trên quãng đường dài ấy, ánh lam bị hất đi gần hết — hất đi đâu đó, không tới được mắt bạn — nên cái còn sót lại tới nơi là phần đỏ và cam. Vẫn đúng một cơ chế của câu trước, chỉ khác là lần này bạn nhìn THẲNG vào chùm nắng đã bị bóc mất phần lam, thay vì nhìn ngang vào phần lam bị bóc ra. Đây cũng là lý do Mặt Trăng khi nguyệt thực toàn phần lại đỏ như đồng: ánh sáng duy nhất tới được nó là ánh nắng đã lách qua rìa khí quyển Trái Đất, tức là toàn bộ các buổi hoàng hôn trên hành tinh này cộng lại.","At noon sunlight crosses only a few dozen kilometres of atmosphere. Near sunset it comes in almost level with the ground and must cross tens of times as much. Over that long road nearly all the blue is scattered away — away somewhere else, not into your eye — so what survives the trip is the red and the orange. It is the same mechanism as the previous question, except that now you are looking STRAIGHT INTO the beam that has been stripped, instead of sideways at the strippings. It is also why the Moon glows copper in a total eclipse: the only light reaching it has grazed the rim of the Earth, which is to say every sunset on the planet at once."]),n("vi-sao-may-mau-trang",2,"te",["Mây làm bằng vô số giọt nước và tinh thể băng rất nhỏ lơ lửng. Bầu trời quanh nó thì xanh, còn mây thì trắng, và mây dày thì xám.","Cloud is countless tiny water droplets and ice crystals afloat. The sky around it is blue; the cloud is white, and a thick one is grey."],["Vì sao mây trắng chứ không xanh như bầu trời?","Why is cloud white rather than blue like the sky?"],[["Vì giọt nước trong mây lớn hơn hạt khí rất nhiều, nên nó hất mọi màu đi mạnh như nhau","Because cloud droplets are far bigger than air particles, so they scatter every colour equally"],["Vì nước vốn màu trắng","Because water is white"],["Vì mây ở cao hơn nên gần Mặt Trời hơn","Because cloud is higher up and nearer the Sun"]],0,["Cái quyết định là kích thước. Hạt khí bé hơn bước sóng ánh sáng rất nhiều nên nó kén màu, và nó chọn ánh lam. Giọt nước trong mây thì to hơn bước sóng, và những vật to như thế hất mọi màu đi như nhau — hất đủ cả thì cộng lại vẫn là trắng. Còn mây giông màu xám hay đen thì không phải vì nó đổi màu, mà vì nó dày tới mức ánh sáng bị hất qua hất lại quá nhiều lần và không mấy tia xuống được tới đáy đám mây, chỗ mà bạn đang nhìn. Cùng một đám mây ấy, nhìn từ máy bay ở phía trên thì vẫn trắng chói.","Size decides it. Air particles are far smaller than a wavelength, so they are fussy and pick blue. Cloud droplets are larger than a wavelength, and things that size scatter every colour alike — and all the colours together is white again. A storm cloud looks grey or black not because its colour changed but because it is so thick that light is bounced about too many times and little of it reaches the underside, which is the part you are looking at. Seen from an aircraft above, that same cloud is dazzling white."]),n("bau-troi-tren-mat-trang",2,"te",["Trên Mặt Trăng không có khí quyển. Phi hành gia đứng dưới ánh nắng chói chang, mặt đất trắng loá, bóng đổ sắc như dao.","The Moon has no atmosphere. An astronaut stands in blazing sunlight, the ground glaring, shadows knife-sharp."],["Ngước lên, họ thấy bầu trời màu gì?","Looking up, what colour is the sky?"],[["Xanh lam nhạt hơn ở Trái Đất","A paler blue than on Earth"],["Đen, và các ngôi sao vẫn ở đó giữa ban ngày","Black, with the stars still there in broad daylight"],["Trắng chói vì nắng quá mạnh","Blazing white from the strength of the sunlight"]],1,["Bầu trời xanh của Trái Đất là ánh nắng bị các hạt khí hất tứ tung. Không có khí thì không có gì để hất, nên nhìn lên là nhìn thẳng vào khoảng không — đen tuyền. Nắng vẫn chói chang, mặt đất vẫn loá, nhưng ngay bên cạnh Mặt Trời là màn đêm. Và vì không có ánh trời tán ra, các ngôi sao vẫn hiện ra ngay giữa ban ngày — chỉ có điều mắt vừa nhìn mặt đất chói thì phải mất một lúc mới quen tối để thấy chúng, và đó là lý do các bức ảnh chụp trên Mặt Trăng không có ngôi sao nào. Cũng vì không có khí quyển nên trên đó không có hoàng hôn, không có mây, không có tiếng động, và bóng đổ tối đen chứ không xanh như trên tuyết.","The blue of Earth is sunlight flung about by air particles. With no air there is nothing to fling it, so looking up means looking straight into space — pure black. The Sun still blazes and the ground still glares, but right beside the Sun is night. And with no scattered skylight the stars are there in daylight — though eyes adjusted to the glaring ground need time to find them, which is why the photographs taken there show none. For the same lack of air there are no sunsets, no clouds, no sound, and shadows that are utterly black rather than blue as on snow."]),n("sao-nhap-nhay-hanh-tinh-thi-khong",3,"tp",["Nhìn lên trời đêm quang: các ngôi sao lấp lánh, nhấp nháy, đổi cả màu một chút. Nhưng sao Kim và sao Mộc thì sáng đều đặn, không nhấp nháy. Đây là mẹo cũ để phân biệt hành tinh với ngôi sao bằng mắt thường.","On a clear night the stars twinkle, flicker and even shift colour slightly. Venus and Jupiter shine steadily and do not. This is the old naked-eye trick for telling a planet from a star."],["Vì sao?","Why?"],[["Vì hành tinh ở gần hơn nên sáng hơn và ổn định hơn","Because planets are nearer, so brighter and steadier"],["Sao xa tới mức là một ĐIỂM; hành tinh là một cái đĩa nhỏ, tức nhiều điểm lệch nhịp bù trừ nhau","Because a star is a POINT while a planet is a small disc — many points flickering out of step average to steady"],["Vì hành tinh không tự phát sáng nên ánh sáng của nó dịu hơn","Because planets shine by reflection and their light is gentler"]],1,["Khí quyển Trái Đất luôn cuộn xoáy, chỗ ấm chỗ lạnh xen nhau, mà nóng lạnh khác nhau thì bẻ ánh sáng khác nhau — nên tia sáng đi tới mắt bạn bị lắc liên tục. Ngôi sao ở xa hàng nghìn tỉ cây số nên dù nó to hơn Mặt Trời, nó vẫn tới mắt bạn như một điểm duy nhất, và điểm ấy bị lắc thì bạn thấy nhấp nháy. Hành tinh gần hơn rất nhiều nên nó là một cái đĩa nhỏ — vẫn quá nhỏ để mắt thường thấy ra hình đĩa, nhưng đủ để tính là cả một đám điểm sáng cạnh nhau. Mỗi điểm nhấp nháy theo kiểu riêng, lệch nhau, và cộng lại thì các dao động bù trừ nhau thành ra sáng đều. Đây chính là lý do người ta phải đưa kính thiên văn lên quỹ đạo: không phải để lên gần hơn, mà để thoát khỏi cái lớp khí đang lắc.","The atmosphere is forever churning, warm patches beside cool ones, and different temperatures bend light differently — so the ray reaching you is constantly jiggled. A star is so far away that although it may dwarf the Sun it still arrives as a single point, and a jiggled point reads as a twinkle. A planet is enormously nearer and is a small disc — still far too small for the naked eye to resolve, but enough to count as a crowd of points side by side. Each point flickers in its own way, out of step with its neighbours, and the sum averages out to a steady glow. This is precisely why telescopes are put into orbit: not to get closer, but to get out from under the churning air."])])],w=[t("bep-song",["Bếp Sóng","The Food-Heating Radio Box"],["Cái lò vi sóng không nấu bằng lửa — nó lắc các hạt nước","A microwave does not cook with fire — it shakes the water"],[n("lo-vi-song-lam-nong-the-nao",1,"te",["Cho một bát cơm nguội vào lò vi sóng, bấm hai phút, cơm nóng. Trong lò không có lửa, không có dây nung đỏ, thành lò vẫn nguội.","Put cold rice in a microwave, press two minutes, and it comes out hot. There is no flame inside, no glowing element, and the walls stay cool."],["Cái lò làm gì với bát cơm?","What is the box doing to the rice?"],[["Nó bắn một loại sóng làm các hạt nước trong cơm lắc nhanh lên, mà lắc nhanh chính là nóng","It fires a kind of wave that makes the water particles in the rice shake faster, and faster shaking is heat"],["Nó hút hết không khí lạnh ra khỏi bát cơm","It draws the cold air out of the rice"],["Nó bắn ra một chùm nhiệt vô hình rọi thẳng vào cơm","It fires an invisible beam of heat straight at the rice"]],0,["Lò phát ra sóng vô tuyến có kích cỡ chừng bằng bàn tay. Hạt nước có một đầu hơi dương và một đầu hơi âm, nên khi sóng chạy qua thì nó bị xoay tới xoay lui theo, hàng tỉ lần một giây. Xoay tới xoay lui chính là chuyển động, và chuyển động của các hạt bên trong đúng là cái ta gọi là nóng. Đó là lý do lò vi sóng làm nóng rất giỏi những thứ có nước — cơm, canh, thịt — và gần như không đụng tới cái đĩa sứ hay cái cốc thuỷ tinh khô. Nếu cái đĩa nóng lên thì nó nóng vì thức ăn truyền sang, chứ không phải vì cái lò.","The box emits radio waves about the size of a hand. A water particle has a slightly positive end and a slightly negative one, so a passing wave twists it back and forth billions of times a second. Back and forth is motion, and motion of the particles inside is precisely what heat is. That is why a microwave is so good at anything holding water — rice, soup, meat — and barely touches a dry china plate or a glass. If the plate does get hot, it got that from the food, not from the box."]),n("lo-vi-song-va-wifi",2,"te",["Lò vi sóng và bộ phát wifi trong nhà dùng sóng cùng một cỡ. Nếu lò bị hở thì lúc bạn hâm đồ ăn, phim đang xem trên máy tính có thể bị khựng lại.","A microwave oven and the wifi box in your house use waves of the same size. If the oven leaks, heating your lunch can stall the film on your laptop."],["Vì sao hai thứ chẳng liên quan gì lại dùng chung một cỡ sóng?","Why do two such unrelated things share one wave size?"],[["Vì cỡ sóng ấy là cỡ duy nhất xuyên qua tường được","Because that size is the only one that goes through walls"],["Vì lò dùng trước, nên các nước để dải đó tự do cho ai cũng dùng, và wifi lấy đúng chỗ trống ấy","Because ovens used it first, so countries left that band free for anyone, and wifi later had to take one of the few free bands"],["Vì nước hấp thụ đúng cỡ sóng ấy mạnh nhất","Because water absorbs that size most strongly of all"]],1,["Bầu trời sóng vô tuyến bị chia nhỏ và cấp phát rất chặt: dải này cho đài phát thanh, dải kia cho quân đội, dải nọ cho hàng không. Hồi lò vi sóng bắt đầu phổ biến, các nước quyết định để dải nó đang dùng thành dải TỰ DO, vì đằng nào cũng đã có hàng triệu cái lò rú lên trong đó rồi, chẳng ai dùng để liên lạc cho nổi. Mấy chục năm sau, người làm wifi cần một dải mà không phải đi xin phép ai, và đây là một trong số rất ít dải như thế. Nói cách khác, cả thế giới đang gửi tin nhắn qua cái dải sóng của bếp — không phải vì nó tốt nhất, mà vì nó là chỗ trống.","The radio sky is carved up and handed out very strictly: this band for broadcasting, that one for the military, another for aviation. When microwave ovens became common, countries agreed to leave the band they were using FREE for anyone, since millions of ovens were already howling in it and nobody could communicate there anyway. Decades later, wifi needed a band it could use without asking permission, and this was one of the very few. So the whole world sends its messages through the kitchen band — not because it is best, but because it was vacant."]),n("kim-loai-trong-lo-vi-song",2,"te",["Sách hướng dẫn nào cũng ghi: không cho đồ kim loại vào lò vi sóng. Cho cái nĩa vào là thấy tia lửa xanh nhảy tanh tách ở đầu răng nĩa.","Every manual says the same: no metal in the microwave. Put a fork in and blue sparks crackle at the tips of the tines."],["Vì sao?","Why?"],[["Vì kim loại hút hết sóng làm hỏng cái lò","Because metal absorbs all the waves and ruins the oven"],["Vì sóng làm các hạt điện chạy dồn trên mặt kim loại, và ở mép nhọn chúng dồn tới mức phóng qua không khí","Because the waves drive charge along the metal surface, and at a sharp edge it crowds until it jumps through the air"],["Vì kim loại nóng chảy ở nhiệt độ thấp","Because metal melts at a low temperature"]],1,["Kim loại cho các hạt điện chạy tự do, nên sóng tới là đẩy chúng chạy dồn qua dồn lại trên bề mặt. Ở chỗ phẳng thì chúng trải ra, không sao. Ở mép nhọn hay đầu răng nĩa thì không còn chỗ trải, chúng dồn lại rất dày, và tới lúc đủ dày thì chúng phóng thẳng qua không khí thành tia lửa. Chính vì kim loại hắt sóng lại như thế nên thành lò và cái lưới trên cửa lò đều làm bằng kim loại — chúng nhốt sóng ở trong. Lỗ trên lưới bé hơn cỡ sóng rất nhiều nên sóng không lọt ra, còn ánh sáng thì bước sóng bé xíu nên lọt qua thoải mái, và bạn nhìn vào trong được.","Metal lets charge move freely, so an arriving wave drives it sloshing back and forth across the surface. On a flat sheet it spreads out harmlessly. At a sharp edge or a fork tine there is nowhere to spread, it crowds thickly, and past a certain crowding it jumps straight through the air as a spark. It is exactly because metal throws the waves back that the walls and the mesh in the door are metal — they keep the waves inside. The holes in the mesh are far smaller than the wave, so the wave cannot get out, while light has a tiny wavelength and passes easily, which is how you can watch."]),n("cho-nong-cho-lanh-trong-lo",3,"te",["Hâm một đĩa thức ăn, có chỗ bỏng rẫy có chỗ còn lạnh ngắt. Vì thế lò nào cũng có đĩa xoay dưới đáy, và sách hướng dẫn bảo hâm xong hãy đảo đều rồi để yên một lát.","Reheat a plate and some spots scald while others stay cold. Which is why every oven has a turntable, and every manual says to stir and let it stand afterwards."],["Vì sao lại có chỗ nóng chỗ lạnh?","Why the hot and cold patches?"],[["Vì sóng phát ra không đều, lúc mạnh lúc yếu","Because the emitter is uneven, sometimes strong and sometimes weak"],["Vì sóng dội trong hộp kim loại rồi chồng lên nhau, thành những chỗ rất mạnh và chỗ gần như không có, đứng yên tại chỗ","Because the waves bounce about the metal box and overlap, making fixed places where they add strongly and fixed places where they nearly cancel"],["Vì thức ăn ở gần cửa lò thì lạnh hơn","Because food nearer the door stays cooler"]],1,["Đây chính là câu hai cái loa cùng phát một nốt, nhốt trong một cái hộp kim loại. Sóng dội khỏi thành lò rồi chồng lên chính nó; có những chỗ đỉnh gặp đỉnh nên rất mạnh, có những chỗ đỉnh gặp đáy nên gần như bằng không, và cái lưới nóng lạnh ấy ĐỨNG YÊN chứ không chạy. Cái đĩa xoay không làm cho sóng đều hơn — nó chỉ kéo thức ăn đi qua đủ mọi chỗ trong cái lưới ấy. Và vì thế lời khuyên để yên một lát sau khi hâm không phải chuyện vặt: trong lúc đứng yên, nhiệt tự bò từ chỗ nóng sang chỗ lạnh và cả đĩa mới thật sự đều. Có thể tự đo được cỡ sóng của lò bằng cách bỏ đĩa xoay ra, cho một khay sô-cô-la vào, và đo khoảng cách giữa các chỗ chảy.","This is the two speakers playing one note, shut in a metal box. The waves bounce off the walls and lie across themselves; in some places crest meets crest and it is fierce, in others crest meets trough and it is nearly nothing, and that lattice of hot and cold STANDS STILL rather than moving. The turntable does not even the waves out — it merely drags the food through every part of the lattice. And the advice to let it stand is not a nicety: while it stands, heat creeps from the hot places into the cold and the plate finally becomes even. You can measure the wave size yourself by removing the turntable, melting a tray of chocolate, and measuring between the molten patches."]),n("da-lanh-trong-lo-vi-song",3,"te",["Bỏ vào lò vi sóng một cốc nước lạnh và một cốc nước đá cùng khối lượng, bật cùng thời gian. Cốc nước lỏng nóng lên rõ rệt; cục đá thì hầu như vẫn còn nguyên, chỉ ướt ở mặt ngoài.","Microwave a cup of cold water and an equal mass of ice for the same time. The liquid warms markedly; the ice is largely intact, merely wet on the outside."],["Vì sao lò vi sóng làm nóng nước đá kém hẳn?","Why is a microwave so poor at heating ice?"],[["Vì nước đá lạnh quá nên cần nhiều năng lượng hơn","Because ice is so cold that it needs more energy"],["Vì trong nước đá, các hạt nước bị khoá cứng vào khung tinh thể nên không xoay theo sóng được","Because in ice the water particles are locked into a rigid frame and cannot twist along with the wave"],["Vì sóng không xuyên qua được nước đá","Because the waves cannot get through ice"]],1,["Cả cơ chế của cái lò dựa vào việc hạt nước XOAY tới xoay lui theo sóng. Trong nước lỏng, các hạt trôi tự do nên xoay thoải mái. Trong nước đá, chúng đã móc vào nhau thành cái khung sáu cạnh cứng ngắc, và một hạt bị khoá thì không xoay được — sóng chạy qua mà gần như không truyền được gì cho nó. Đây là lý do lò vi sóng có nút rã đông riêng, và nút ấy không phải là hâm ở mức nhỏ hơn theo nghĩa thông thường: nó bật tắt liên tục, để những giây tắt cho phần nước đã tan (thứ hấp thụ rất giỏi) kịp truyền nhiệt vào phần còn đông. Không có mấy giây nghỉ ấy thì mép ngoài chín trong khi lõi vẫn là một cục băng.","The whole mechanism rests on water particles TWISTING back and forth with the wave. In liquid they drift freely and twist happily. In ice they are hooked into a rigid six-sided frame, and a locked particle cannot twist — the wave passes and hands over almost nothing. This is why a microwave has a separate defrost setting, and that setting is not simply a lower power in the ordinary sense: it switches on and off, and the off seconds let the already-melted water, which absorbs superbly, pass its heat inward to what is still frozen. Without those pauses the outside cooks while the middle is still a block of ice."])]),t("tau-troi",["Tàu Trời","Sky Boats"],["Lên tới quỹ đạo không phải chuyện lên CAO, mà là chuyện đi NGANG cho đủ nhanh","Reaching orbit is not about going UP but about going SIDEWAYS fast enough"],[n("ten-lua-day-vao-cai-gi",1,"te",["Một quả tên lửa đang bay giữa vũ trụ, xung quanh không có không khí, không có gì để tì vào. Nó đốt nhiên liệu, phụt một luồng khí về phía sau, và nó tăng tốc.","A rocket coasts in space with no air around it and nothing to push against. It burns fuel, blasts gas out behind it, and speeds up."],["Nó đẩy vào cái gì để đi tới?","What is it pushing against?"],[["Đẩy vào không khí phía sau","Against the air behind it"],["Không đẩy vào gì cả — nó ném khí về phía sau, và chính cái ném ấy đẩy nó tới trước","Against nothing — it throws gas backwards, and the throwing pushes it forwards"],["Đẩy vào lực hút của các ngôi sao","Against the pull of the stars"]],1,["Đẩy một cái gì đó ra xa thì bao giờ cũng bị đẩy lại đúng bấy nhiêu — đúng câu con ngựa kéo xe, chỉ đổi bối cảnh. Quả tên lửa ném về sau vài tấn khí với tốc độ mấy nghìn mét một giây, và cái ném ấy hất chính nó về phía trước. Nó không cần cái gì bên ngoài để tì vào; nó tì vào chính khối khí nó vừa vứt đi. Vì thế tên lửa chạy trong vũ trụ tốt hơn trong khí quyển, chứ không phải kém hơn. Đứng trên ván trượt mà ném liên tiếp mấy quả bóng nặng về sau thì bạn cũng trượt tới trước, và đó là một quả tên lửa đầy đủ ý nghĩa.","Push anything away and you are pushed back exactly as hard — the horse and cart again, in a new setting. The rocket throws several tonnes of gas backwards at thousands of metres a second, and that throwing flings it forwards. It needs nothing outside to lean on; it leans on the gas it has just discarded. Which is why rockets work better in space than in the atmosphere, not worse. Stand on a skateboard and hurl heavy balls behind you and you will roll forwards, and that is a rocket in every sense that matters."]),n("vi-sao-ten-lua-nhieu-tang",2,"te",["Tên lửa đưa hàng lên quỹ đạo gồm mấy tầng chồng lên nhau. Cháy hết tầng dưới thì nó cắt bỏ cả cái vỏ tầng ấy, để rơi xuống biển, rồi tầng trên mới đốt.","An orbital rocket is built in stages. When the bottom stage burns out, the whole empty shell is cut loose and dropped into the sea before the next one lights."],["Vì sao phải vứt bỏ như thế thay vì mang theo?","Why throw it away rather than carry it?"],[["Vì cái vỏ rỗng đã hết dùng nhưng vẫn nặng, và mang theo thì phải tốn nhiên liệu để gia tốc cho cả nó","Because the empty shell is useless but still heavy, and carrying it means spending fuel to accelerate it too"],["Vì cái vỏ rỗng sẽ nổ nếu mang theo","Because an empty shell would explode if kept"],["Vì luật hàng không bắt phải bỏ lại","Because aviation rules require it"]],0,["Sau khi cháy hết, cái thùng nhiên liệu tầng một chỉ còn là một cái vỏ rỗng nặng mấy chục tấn. Mang nó theo thì mọi giây gia tốc còn lại đều phải gia tốc cả nó, và nhiên liệu để làm việc đó lại cần thêm nhiên liệu để mang chính nó lên — vòng luẩn quẩn ấy tăng rất nhanh, nên vài tấn thừa ở dưới đáy có thể ăn mất cả tấn hàng ở trên đỉnh. Vứt đi là cách duy nhất từng làm được cho tới gần đây. Bây giờ người ta cho tầng một hạ cánh lại và dùng lại, nhưng chú ý là họ vẫn VỨT nó khỏi phần còn lại đúng như cũ — cái đổi là thay vì rơi xuống biển thì nó tự bay về, và đó là một bài toán khác hẳn.","Once burnt out, the first-stage tank is an empty shell weighing tens of tonnes. Carry it and every remaining second of acceleration must accelerate it too, and the fuel for that needs more fuel to lift it in turn — a spiral that grows fast, so a few spare tonnes at the bottom can eat a whole tonne of cargo at the top. Dropping it was the only workable answer until recently. Today the first stage is landed and flown again, but note that it is still CUT LOOSE from the rest exactly as before — what changed is that instead of falling in the sea it flies itself home, which is a quite separate problem."]),n("nhien-lieu-dung-de-len-cao-hay-di-ngang",2,"te",["Trạm vũ trụ bay cách mặt đất 400 km và chạy quanh Trái Đất với tốc độ khoảng 28 nghìn km một giờ. Một quả tên lửa phải đưa hàng lên tới đó.","The space station orbits 400 km up, circling the Earth at about 28 thousand km an hour. A rocket has to deliver cargo there."],["Phần lớn nhiên liệu dùng vào việc gì?","What is most of the fuel spent on?"],[["Nâng hàng lên cao 400 km","Lifting the cargo 400 km up"],["Đẩy hàng đi NGANG cho đạt tốc độ quỹ đạo","Driving the cargo SIDEWAYS to orbital speed"],["Chống lại sức cản của không khí","Fighting the resistance of the air"]],1,["Nâng một vật lên 400 km tốn ít hơn nhiều so với người ta tưởng — một quả tên lửa nhỏ cũng làm được, và các tên lửa thăm dò vẫn lên tới độ cao ấy rồi rơi thẳng xuống. Cái đắt là tốc độ đi ngang: muốn ở lại trên đó chứ không rơi xuống thì phải đi ngang gần 8 km mỗi GIÂY. Đó là lý do tên lửa vừa rời bệ phóng là bắt đầu nghiêng dần, và đến cuối hành trình thì gần như bay song song mặt đất. Nói cho gọn: quỹ đạo không phải một cái độ cao, nó là một cái tốc độ. Đây cũng chính là hình vẽ khẩu đại bác của Newton, làm thật.","Lifting something 400 km costs far less than people expect — a modest rocket manages it, and sounding rockets reach that height and fall straight back. What is expensive is the sideways speed: to stay up rather than come down you need nearly 8 km per SECOND across. That is why a rocket begins tilting almost as soon as it clears the pad and finishes its climb flying nearly parallel to the ground. Put briefly: an orbit is not a height, it is a speed. It is the drawing of Newton’s cannon, actually built."]),n("tau-nong-do-luc-quay-ve",3,"te",["Tàu vũ trụ quay về Trái Đất lao vào khí quyển với tốc độ hàng chục nghìn km một giờ. Bụng tàu nóng lên tới hơn 1500 độ, phải bọc một lớp gạch chịu nhiệt đặc biệt.","A returning spacecraft enters the atmosphere at tens of thousands of km an hour. Its underside reaches over 1500 degrees and needs a special heat shield."],["Cái gì làm nó nóng lên tới mức ấy?","What makes it that hot?"],[["Ma sát giữa vỏ tàu và không khí, như xoa hai bàn tay","Friction between the hull and the air, like rubbing your hands"],["Chủ yếu là do tàu NÉN không khí trước mũi lại đột ngột, mà nén khí thì khí nóng lên dữ dội","Mostly because the craft SQUEEZES the air ahead of it violently, and squeezed gas gets very hot"],["Do ánh nắng mặt trời không còn bị khí quyển che chắn","Because sunlight is no longer filtered by the atmosphere"]],1,["Ma sát có góp phần, nhưng phần lớn cái nóng đến từ chỗ khác: con tàu lao nhanh hơn tốc độ âm thanh mấy chục lần, nên không khí trước mũi nó không kịp tránh ra — nó bị dồn ép lại thành một lớp mỏng cực đặc, và nén khí lại thì khí nóng lên, y như cái bơm xe đạp nóng ở đầu vòi khi bơm mạnh. Cái nóng ấy nằm trong lớp KHÍ chứ không phải trên bề mặt tàu, và đó là lý do người ta cố tình làm bụng tàu TÙ chứ không nhọn: mũi tù đẩy lớp khí nóng ra xa thân tàu, còn mũi nhọn thì kéo nó áp sát vào. Một trong những phát hiện phản trực giác nhất của cả ngành hàng không vũ trụ — muốn xuyên qua khí quyển an toàn thì đừng làm cho nhọn.","Friction plays a part, but most of the heat comes from elsewhere: the craft is travelling dozens of times the speed of sound, so the air ahead cannot get out of the way — it is crushed into a thin, extremely dense layer, and squeezed gas gets hot, just as a bicycle pump warms at the nozzle. That heat lives in the AIR rather than on the skin, which is why the underside is deliberately made BLUNT rather than pointed: a blunt nose holds the hot layer away from the hull, while a sharp one draws it in tight. One of the most counter-intuitive findings in the whole field — to cross an atmosphere safely, do not make it sharp."]),n("can-nguoi-tren-tram-vu-tru",3,"te",["Trên trạm vũ trụ mọi thứ lơ lửng, nên cái cân thường vô dụng: đứng lên nó thì nó chỉ số không. Nhưng phi hành gia vẫn phải theo dõi cân nặng của mình hằng tuần vì lý do sức khoẻ.","Everything floats on the station, so an ordinary scale is useless: stand on it and it reads zero. Yet the crew must track their mass every week for medical reasons."],["Làm cách nào đo được?","How is it done?"],[["Buộc người vào một cái ghế gắn lò xo, đẩy cho rung, rồi đếm nhịp rung — người càng nặng thì rung càng chậm","Strap them into a sprung seat, set it oscillating, and count the rhythm — the more mass, the slower the swing"],["Đo thể tích cơ thể rồi tính ra cân nặng","Measure the volume of the body and calculate from that"],["Không đo được, phải chờ về Trái Đất mới cân","It cannot be done; they must wait until they land"]],0,["Cái cân ở nhà không đo khối lượng — nó đo cái ĐÈ của bạn lên mặt cân, và trên trạm thì cái đè ấy bằng không. Nhưng khối lượng còn lộ ra theo một đường khác hẳn: nó là mức độ Ì. Vật càng nhiều khối lượng thì càng khó bắt đổi chuyển động, nên gắn nó vào một cái lò xo rồi cho rung thì nó rung chậm hơn. Đếm số nhịp rung trong một phút là ra khối lượng, và cách này chạy tốt như nhau ở đâu cũng được — trên Trái Đất, trên Mặt Trăng, hay giữa vũ trụ. Đây là một ví dụ đẹp của việc gặp ngõ cụt thì phải quay lại hỏi: đại lượng mình cần thật ra CÒN LỘ RA Ở CHỖ NÀO NỮA.","A bathroom scale does not measure mass — it measures your PRESS on its top, and up there that press is zero. But mass shows itself another way entirely: as sluggishness. The more mass, the harder it is to change a motion, so fix it to a spring and set it swinging and it swings more slowly. Count the swings in a minute and you have the mass, and the method works identically anywhere — on Earth, on the Moon, or in deep space. It is a fine example of what to do at a dead end: go back and ask WHERE ELSE the quantity you want reveals itself."])]),t("nha-dien",["Nhà Điện","Power Buildings"],["Gần như mọi nhà máy điện chỉ làm một việc: đun nước để quay một cái bánh xe","Almost every power station does one thing: boil water to turn a wheel"],[n("diem-chung-cua-nha-may-dien",1,"te",["Nhà máy nhiệt điện than, nhà máy điện hạt nhân, nhà máy điện địa nhiệt, và cả nhà máy điện mặt trời loại dùng gương hội tụ — bốn thứ nghe rất khác nhau.","A coal station, a nuclear station, a geothermal station, and the kind of solar station that uses mirrors — four very different-sounding things."],["Bốn loại ấy giống nhau ở chỗ nào?","What do all four have in common?"],[["Cả bốn đều chỉ dùng nguồn của mình để đun nước thành hơi, rồi cho hơi thổi quay một cái bánh xe nối với máy phát","All four use their source only to boil water into steam, and let the steam spin a wheel joined to a generator"],["Cả bốn đều biến nhiệt thẳng thành điện, không có bộ phận chuyển động nào","All four turn heat straight into electricity with no moving parts"],["Cả bốn đều đốt một thứ nhiên liệu nào đó","All four burn some kind of fuel"]],0,["Cái ruột của gần như mọi nhà máy điện trên thế giới là một cái ấm nước rất lớn và một cái chong chóng rất lớn. Than, urani, hơi nóng dưới lòng đất, hay ánh nắng gom bằng gương: bốn cách hoàn toàn khác nhau để đun sôi cùng một thứ nước. Xong rồi thì phần còn lại giống hệt nhau — hơi phụt qua tua-bin, tua-bin quay, nam châm quay theo trong cuộn dây, và điện chạy ra đường dây. Nhìn ra được cái ruột chung ấy thì cả một ngành công nghiệp gọn lại thành một hình vẽ. Chỉ có ba loại đứng ngoài: thuỷ điện và điện gió thì quay bánh xe thẳng mà không cần đun gì, còn pin mặt trời thì không có bánh xe nào cả.","The core of nearly every power station in the world is a very large kettle and a very large windmill. Coal, uranium, heat from underground, sunlight gathered by mirrors: four entirely different ways of boiling the same water. After that they are identical — steam through a turbine, the turbine spins, magnets turn inside coils, and current goes down the line. See that shared core and a whole industry collapses into one diagram. Only three stand outside it: hydro and wind turn the wheel directly with nothing boiled, and solar panels have no wheel at all."]),n("lo-hat-nhan-lam-gi",2,"te",["Trong lò phản ứng hạt nhân, các hạt nhân urani bị bắn vỡ ra và toả ra một lượng năng lượng khổng lồ. Người ta thả vào lò những thanh điều khiển để nuốt bớt hạt, giữ cho phản ứng không chạy loạn.","In a nuclear reactor, uranium nuclei are split and release an enormous amount of energy. Control rods are lowered in to swallow particles and keep the reaction from running away."],["Năng lượng ấy được dùng làm gì ngay sau đó?","What is that energy used for immediately afterwards?"],[["Biến thẳng thành điện nhờ một thiết bị đặc biệt","Turned straight into electricity by a special device"],["Đun nước thành hơi để quay tua-bin, y hệt nhà máy than","Boiling water into steam to spin a turbine, exactly as in a coal station"],["Nạp thẳng vào ắc quy khổng lồ","Charged straight into enormous batteries"]],1,["Toàn bộ cái lò hạt nhân — thứ công nghệ phức tạp và đắt đỏ bậc nhất mà loài người xây được — cuối cùng chỉ đóng vai cái BẾP. Nó làm nóng, nước sôi, hơi quay tua-bin, hết. Phần từ tua-bin trở đi thì y hệt một nhà máy đốt than xây từ thế kỷ trước. Nhận ra chuyện này là một cú ngã ngửa nho nhỏ, và nó rất hữu ích: nó cho biết một nhà máy điện hạt nhân bị hạn chế bởi đúng những định luật nhiệt như mọi cái ấm nước khác, kể cả cái luật buộc nó phải vứt đi hơn một nửa số nhiệt sinh ra. Đó là lý do nhà máy nào cũng phải xây cạnh một con sông hay bờ biển, và phải có mấy cái tháp giải nhiệt khổng lồ.","The entire reactor — among the most complex and expensive things people have ever built — ends up playing the part of the STOVE. It gets hot, water boils, steam spins a turbine, and that is all. From the turbine onward it is indistinguishable from a coal station built a century ago. Noticing this is a small jolt, and a useful one: it says a nuclear station is bound by exactly the same laws of heat as any other kettle, including the one forcing it to throw away more than half the heat it makes. Which is why every such station sits beside a river or the sea, with enormous cooling towers."]),n("vi-sao-day-tai-dien-the-cao",2,"te",["Điện trong nhà bạn ở mức 220 vôn. Nhưng đường dây tải điện đi xa hàng trăm cây số thì chạy ở hàng trăm nghìn vôn, và phải có trạm biến áp hạ xuống dần trước khi vào khu dân cư.","The electricity in your house is at 220 volts. But the lines that carry it hundreds of kilometres run at hundreds of thousands of volts, stepped down at substations before reaching homes."],["Vì sao truyền đi xa lại phải dùng điện thế rất cao?","Why must long-distance transmission use such high voltage?"],[["Vì điện thế cao thì điện đi nhanh hơn","Because high voltage makes the electricity travel faster"],["Vì cùng một lượng công suất, thế càng cao thì dòng càng nhỏ, mà hao phí trên dây tăng theo bình phương dòng","Because for the same power, higher voltage means smaller current, and the loss in the wire grows as the square of the current"],["Vì dây dài thì điện bị mất dần nên phải bơm vào nhiều hơn","Because a long wire loses charge and more must be pushed in"]],1,["Công suất là thế nhân với dòng, nên muốn chuyển đi ngần ấy công suất thì có thể chọn thế thấp dòng lớn, hoặc thế cao dòng nhỏ. Mà phần hao phí biến thành nhiệt trên dây thì tính theo dòng NHÂN VỚI CHÍNH NÓ: giảm dòng đi mười lần thì hao phí giảm một trăm lần. Vì thế người ta đẩy thế lên thật cao để dòng xuống thật thấp, rồi tới nơi mới hạ xuống. Đây cũng chính là cuộc tranh cãi lớn giữa Edison và Tesla hồi cuối thế kỷ 19: điện một chiều hồi ấy không hạ thế xuống dễ dàng được, nên nó thua — không phải vì nó tệ hơn, mà vì nó không đổi thế được bằng một cái biến áp đơn giản.","Power is voltage multiplied by current, so to move a given power you may choose low voltage with large current or high voltage with small. But the loss turning into heat in the wire goes as the current MULTIPLIED BY ITSELF: cut the current by ten and the loss falls by a hundred. So the voltage is pushed high to keep the current low, and dropped again on arrival. This was the substance of the great argument between Edison and Tesla at the end of the nineteenth century: the direct current of the day could not easily be stepped down, and so it lost — not for being worse, but for not being convertible with a simple transformer."]),n("thap-giai-nhiet-phun-gi",3,"te",["Cạnh nhà máy điện có mấy cái tháp khổng lồ hình eo thắt, suốt ngày phun lên trời một cột trắng đục cuồn cuộn. Nhiều người nhìn ảnh và tưởng đó là khói ô nhiễm.","Beside a power station stand vast waisted towers, endlessly billowing a thick white column into the sky. Many people see the picture and take it for pollution."],["Cột trắng ấy là gì, và vì sao bắt buộc phải có nó?","What is that white column, and why must it be there?"],[["Là khói của lò đốt, và phải xả ra vì không lọc hết được","Furnace smoke, released because it cannot all be filtered"],["Là hơi nước đã ngưng thành sương, và nó phải có vì máy chạy bằng nhiệt nào cũng buộc phải vứt đi phần lớn nhiệt","Condensed water vapour, and it must be there because every heat engine is obliged to throw away most of the heat it takes in"],["Là hơi hoá chất làm nguội, có hại nếu hít phải","Coolant chemicals, harmful to breathe"]],1,["Cột trắng ấy là mây, đúng nghĩa: hơi nước bốc lên gặp không khí lạnh rồi ngưng lại thành giọt nhỏ. Nhưng câu hỏi hay hơn là vì sao bắt buộc phải có nó. Một cái máy chạy bằng nhiệt chỉ lấy ra được công khi nhiệt CHẢY từ chỗ nóng sang chỗ lạnh, và phần nhiệt lấy được nhiều hay ít tuỳ vào chênh lệch giữa hai đầu ấy. Với hơi nước ở nhiệt độ mà thép chịu nổi, phần lấy được cùng lắm chừng bốn mươi phần trăm — sáu mươi phần trăm còn lại BẮT BUỘC phải đổ đi ở đầu lạnh, nếu không thì dòng nhiệt dừng và máy đứng. Cái tháp ấy chính là đầu lạnh. Nó không phải chỗ lãng phí do làm ẩu; nó là cái giá mà mọi cỗ máy nhiệt trong vũ trụ đều phải trả.","That column is cloud in the plain sense: water vapour rising into cooler air and condensing into droplets. But the better question is why it has to be there. A heat engine can extract work only while heat FLOWS from somewhere hot to somewhere cold, and how much it extracts depends on the gap between the two. With steam at temperatures steel can bear, the best available is around forty percent — the other sixty percent MUST be dumped at the cold end, or the flow stops and the engine stands still. That tower is the cold end. It is not waste from carelessness; it is the price every heat engine in the universe pays."]),n("pin-mat-troi-khac-cho-nao",2,"te",["Tấm pin mặt trời trên mái nhà không có bộ phận nào chuyển động, không ồn, không cần nước, không có ống khói. Nó đứng ngoài cái sơ đồ ấm nước và bánh xe của mọi nhà máy điện khác.","A solar panel on a roof has no moving parts, makes no noise, needs no water and has no chimney. It sits outside the kettle-and-wheel diagram of every other power station."],["Nó làm gì?","What does it do?"],[["Nó dùng nắng để đun một chất lỏng bên trong tấm","It uses sunlight to boil a liquid inside the panel"],["Ánh sáng đập vào một lớp vật liệu, hất thẳng các hạt điện thành dòng — không qua nhiệt, không qua chuyển động","Light strikes a special material and knocks charge straight out of place, making a current — with no heat step and no motion"],["Nó tích ánh sáng lại rồi ban đêm nhả ra thành điện","It stores light by day and releases it as electricity at night"]],1,["Đây là một trong số rất ít cách biến năng lượng thành điện mà bỏ qua hẳn khâu nhiệt. Một hạt ánh sáng đập vào lớp vật liệu, hất một hạt điện bật ra khỏi chỗ của nó, và cấu tạo của tấm pin bắt hạt điện ấy chỉ đi được về một phía — thế là có dòng. Vì không phải là máy nhiệt nên nó không bị buộc phải vứt đi sáu mươi phần trăm như cái tháp giải nhiệt ở câu trước; nó có giới hạn riêng nhưng là giới hạn khác. Cái giá phải trả nằm ở chỗ khác: nắng thì không phải lúc nào cũng có, và đó là lý do cả ngành này bây giờ xoay quanh chuyện tích trữ chứ không còn xoay quanh chuyện tấm pin nữa. Chính hiện tượng ánh sáng hất hạt điện ra ngoài là thứ Einstein giải thích năm 1905, và ông được giải Nobel cho bài đó chứ không phải cho thuyết tương đối.","This is one of very few ways of making electricity that skips the heat step entirely. A particle of light strikes the material, knocks a charge out of place, and the construction of the cell allows that charge to travel only one way — and there is your current. Not being a heat engine, it is not obliged to dump sixty percent like the cooling tower in the previous question; it has its own ceiling, but a different one. The price sits elsewhere: the sun is not always there, which is why the whole industry now turns on storage rather than on panels. The very effect of light knocking charge loose is what Einstein explained in 1905, and it is what he was given the Nobel Prize for, not relativity."])]),t("trong-nguoi",["Trong Người","Inside a Person"],["Cơ thể là một cỗ máy, và mọi bộ phận của nó đều có một việc giải thích được","A body is a machine, and every part of it has a job that can be explained"],[n("moi-te-bao-co-ban-chi-dan-gi",1,"te",["Cơ thể người có khoảng ba mươi nghìn tỉ tế bào, đủ mọi loại: tế bào da, tế bào gan, tế bào thần kinh, tế bào cơ. Chúng khác nhau xa về hình dáng và công việc.","A human body holds some thirty trillion cells of every kind: skin, liver, nerve, muscle. They differ enormously in shape and in job."],["Bản chỉ dẫn bên trong mỗi loại tế bào ấy thế nào?","What is the instruction book inside each kind like?"],[["Mỗi loại có bản chỉ dẫn riêng, viết cho đúng việc của nó","Each kind carries its own book, written for its own job"],["Mọi tế bào đều mang đúng một bản chỉ dẫn giống hệt nhau, chỉ khác ở chỗ chúng đọc phần nào","Every cell carries one and the same book, and they differ only in which parts they read"],["Chỉ tế bào não giữ bản chỉ dẫn, các tế bào khác nhận lệnh từ đó","Only brain cells hold the book; the rest take orders from them"]],1,['Mỗi tế bào trong người bạn đều giữ trọn vẹn một bản chỉ dẫn giống hệt nhau, đủ để dựng lại cả cơ thể. Cái quyết định một tế bào thành tế bào gan hay tế bào da là nó MỞ những trang nào và ĐÓNG những trang nào. Chính vì bản chỉ dẫn nào cũng đầy đủ mà người ta nhân bản được con cừu Dolly từ một tế bào tuyến vú, và cũng vì thế mà một mẩu da rơi lại hiện trường đủ để nói ra mọi thứ về chủ nhân của nó. Cái ý "cùng một bản, khác cách đọc" còn giải thích luôn vì sao con sâu và con bướm là một con: cùng một bản chỉ dẫn, hai lần đọc khác nhau.',"Every cell in you keeps one complete and identical book, enough to build the whole body again. What makes a cell a liver cell rather than a skin cell is which pages it OPENS and which it keeps SHUT. It is because every copy is complete that Dolly the sheep could be cloned from a single udder cell, and why a flake of skin left at a scene tells everything about who shed it. The idea of one book read differently also settles why a caterpillar and a butterfly are one animal: one book, two readings."]),n("mau-do-vi-sao",2,"te",["Máu người màu đỏ. Nhìn qua da thì mấy cái mạch ở cổ tay lại trông xanh lam, nên nhiều người tin rằng máu trong tĩnh mạch màu xanh, ra tới không khí mới đỏ lên.","Human blood is red. Through the skin the vessels at your wrist look blue, so many people believe venous blood is blue and only reddens on meeting the air."],["Sự thật là gì?","What is actually true?"],[["Máu trong tĩnh mạch màu xanh thật, oxy làm nó đỏ lên","Venous blood really is blue and oxygen reddens it"],["Máu lúc nào cũng đỏ; mạch trông xanh là do cách ánh sáng đi qua lớp da rồi quay ra","Blood is always red; the vessels look blue because of how light passes through skin and comes back"],["Máu không có màu, màu đỏ là của thành mạch","Blood has no colour of its own; the red is the vessel wall"]],1,["Máu đỏ vì trong hồng cầu có một phân tử mang một nguyên tử sắt để chở oxy, và cái phức hợp ấy hắt lại ánh đỏ. Máu vừa nhả oxy ở tay chân về thì đỏ sẫm hơn — sẫm chứ không xanh; lấy máu tĩnh mạch ra ống nghiệm là thấy ngay. Cái vẻ xanh ở cổ tay là chuyện của ánh sáng, không phải của máu: ánh đỏ xuyên sâu vào mô rồi bị hấp thụ gần hết, còn ánh lam bị hắt trở ra ngay ở lớp nông — nên phần quay lại mắt bạn nghiêng về phía lam. Cùng lý do ấy làm mấy cái vết bầm chuyển màu, và đây lại đúng là bài học của bộ Màu Sắc: muốn biết một chỗ có màu gì thì hỏi xem ánh sáng nào đã đi tới đó và quay ra được.","Blood is red because red cells carry a molecule holding an iron atom to ferry oxygen, and that complex reflects red. Blood that has just given up its oxygen in the limbs is a darker red — darker, not blue; draw some into a tube and see. The blue look at the wrist belongs to the light rather than the blood: red penetrates deep into tissue and is largely absorbed, while blue is thrown back from the shallow layers — so what returns to your eye leans blue. The same reasoning colours a bruise as it fades, and it is exactly the lesson of the Colour set: to ask what colour a place is, ask what light got there and got back out."]),n("cai-gi-thuc-ta-tho",3,"te",["Nín thở thì một lúc là thấy tức ngực không chịu nổi và phải thở. Nhưng lúc ấy trong máu vẫn còn khá nhiều oxy — người ta đã đo được.","Hold your breath and before long the urge is unbearable. Yet at that moment there is still plenty of oxygen in the blood; this has been measured."],["Cái gì thúc bạn phải thở?","What is driving you to breathe?"],[["Lượng oxy trong máu tụt xuống","The falling oxygen in your blood"],["Lượng khí thải cacbonic trong máu dâng lên","The rising carbon dioxide in your blood"],["Phổi bị xẹp lại nên đau","The lungs collapsing and hurting"]],1,["Cơ thể theo dõi cái đi RA chứ không theo dõi cái đi VÀO — nó đo mức khí thải chứ không đo mức oxy. Cách ấy hợp lý vì trong đời sống bình thường hai thứ luôn đi kèm nhau, và khí thải thì đo dễ hơn nhiều. Nhưng nó tạo ra một lỗ hổng chết người: ở đâu mà hai thứ tách rời nhau thì cơ thể không hề báo động. Thở gấp thật sâu mấy chục lần rồi lặn xuống thì bạn đã xả bớt khí thải đi, cơn thèm thở đến muộn hẳn — và người ta ngất dưới nước vì hết oxy mà không hề thấy khó chịu trước đó. Đây cũng là lý do các khí trơ như nitơ giết người rất êm: nạn nhân không thấy ngạt gì cả. Bài học: một cái cảm biến đo GIÁN TIẾP thì chỉ đáng tin trong đúng hoàn cảnh mà nó được sinh ra để đo.","The body watches what goes OUT rather than what comes IN — it measures waste gas, not oxygen. That is sensible, since in ordinary life the two move together and the waste gas is far easier to sense. But it leaves a deadly hole: wherever the two come apart, the body raises no alarm. Breathe hard and deep a few dozen times and then dive, and you have flushed out waste gas, the urge arrives far later — and people black out underwater from lack of oxygen having felt no discomfort at all. It is also why inert gases such as nitrogen kill so gently: the victim feels no suffocation. The lesson: a sensor that measures INDIRECTLY can be trusted only in the circumstances it evolved for."]),n("xuong-co-song-khong",2,"te",["Bộ xương trong tủ phòng thí nghiệm khô, cứng, trắng, không khác gì một cái giá đỡ bằng đá. Xương trong người bạn thì khác hẳn.","The skeleton in a laboratory cupboard is dry, hard and white — no different from a stone frame. The bone inside you is another matter."],["Xương trong cơ thể sống có sống không?","Is bone in a living body alive?"],[["Không, nó chỉ là cái khung đá vôi cứng do cơ thể đắp ra một lần rồi thôi","No — it is a lime frame laid down once and left"],["Có, và nó liên tục bị dỡ ra xây lại, dày lên ở chỗ chịu lực nhiều","Yes, and it is constantly torn down and rebuilt, thickening where it is worked hardest"],["Chỉ có tuỷ bên trong là sống, phần cứng thì không","Only the marrow inside is alive; the hard part is not"]],1,["Xương là mô sống, có mạch máu, có thần kinh, và có hai đội thợ làm việc suốt đời: một đội gặm xương cũ đi, một đội đắp xương mới vào. Chỗ nào thường xuyên chịu lực thì đội đắp thắng thế và xương dày lên; chỗ nào không dùng tới thì đội gặm thắng và xương mỏng đi. Đó là lý do tay thuận của vận động viên quần vợt có xương dày hơn tay kia thấy rõ, và cũng là lý do phi hành gia trên trạm vũ trụ mất xương nhanh tới mức đáng sợ — không có trọng lực đè xuống thì cơ thể kết luận rằng bộ khung này không cần chắc tới thế, và bắt đầu tháo bớt. Xương không phải cái giá đỡ đúc sẵn; nó là một bản ghi chép sống về việc bạn đã dùng cơ thể mình vào việc gì.","Bone is living tissue with blood vessels and nerves and two crews at work for life: one gnawing old bone away, one laying new bone down. Where load is regular the builders win and the bone thickens; where it is unused the gnawers win and it thins. That is why a tennis player’s racket arm is visibly denser than the other, and why astronauts lose bone alarmingly fast — with no weight bearing down, the body concludes this frame need not be so strong and begins dismantling it. Bone is not a cast frame; it is a living record of what you have used your body for."]),n("vi-sao-vet-thuong-sung-nong",2,"te",["Bị đứt tay hay bong gân thì chỗ ấy sưng lên, nóng, đỏ và đau. Bốn dấu hiệu này đi cùng nhau tới mức thầy thuốc La Mã đã ghi lại đủ cả bốn từ hai nghìn năm trước.","Cut a finger or twist an ankle and the place swells, reddens, warms and hurts. The four signs travel together so reliably that Roman physicians listed all four two thousand years ago."],["Bốn dấu hiệu ấy là gì?","What are those four signs?"],[["Là dấu hiệu vết thương đang nhiễm trùng và trở nặng","Signs that the wound is infected and getting worse"],["Là chính phản ứng sửa chữa của cơ thể: mạch máu quanh đó mở rộng ra để đưa quân cứu viện tới","The repair response itself: the vessels around the spot open wide to bring the rescue crew in"],["Là do cơ thể mất máu nên dồn máu về chỗ đó","A response to blood loss, pooling blood at the site"]],1,["Ngay khi mô bị hỏng, các tế bào ở đó phát ra tín hiệu hoá học làm mạch máu quanh vùng nở rộng và thành mạch trở nên dễ lọt hơn. Máu dồn tới nhiều nên chỗ ấy ĐỎ và NÓNG; dịch và các tế bào bảo vệ tràn ra khỏi mạch nên nó SƯNG; và chính cái sưng cộng với các chất báo hiệu ép vào dây thần kinh làm nó ĐAU. Cả bốn là một gói, và cả bốn đều có ích: đau là để bạn thôi dùng tới chỗ ấy trong lúc nó đang được vá. Vì thế uống thuốc giảm sưng giảm đau là một sự đánh đổi thật sự chứ không phải chuyện hiển nhiên nên làm — bạn thấy dễ chịu hơn, và bạn cũng vừa bảo đội sửa chữa làm chậm lại một chút.","The moment tissue is damaged, the cells there release chemical signals that widen nearby vessels and make their walls easier to cross. More blood arrives, so the place is RED and WARM; fluid and defending cells leak out of the vessels, so it SWELLS; and the swelling together with the signalling chemicals presses on nerves, so it HURTS. All four come as one package, and all four are useful: the pain is there to stop you using the part while it is being mended. Which makes taking something for the swelling and the pain a genuine trade rather than an obvious good — you feel better, and you have also told the repair crew to slow down a little."])]),t("may-trong-nha",["Máy Trong Nhà","Machines at Home"],["Mấy cái máy quen nhất trong nhà đều đang làm những việc đã học ở các bộ trước","The most familiar machines at home are all doing things from the earlier sets"],[n("tu-lanh-lam-lanh-the-nao",1,"te",["Cái tủ lạnh không hề tạo ra cái lạnh — không có thứ gì gọi là cái lạnh để mà tạo ra. Nó chỉ có một cái máy nén, một mớ ống, và một chất lỏng chạy vòng quanh trong ống.","A refrigerator does not make cold — there is no such thing as cold to make. It has a compressor, a loop of pipes, and a liquid running round inside them."],["Nó lấy nhiệt ra khỏi khoang lạnh bằng cách nào?","How does it get heat out of the cold box?"],[["Chất lỏng bay hơi trong khoang lạnh và lấy nhiệt đi; ra ngoài bị nén cho ngưng lại, nhả nhiệt ra sau lưng tủ","A liquid boils inside and carries heat away; outside it is squeezed back to liquid and lets that heat go at the back"],["Máy nén thổi khí lạnh vào trong khoang","The compressor blows cold air into the box"],["Chất lỏng trong ống vốn rất lạnh và làm nguội mọi thứ nó chạy qua","The liquid in the pipes is very cold and chills whatever it passes"]],0,["Cả cái tủ lạnh chỉ là câu mồ hôi làm mát cơ thể, chạy thành một vòng khép kín. Bay hơi thì lấy đi rất nhiều nhiệt, ngưng tụ thì nhả ra đúng ngần ấy — nên nếu bạn bắt một chất bay hơi ở CHỖ NÀY và ngưng tụ ở CHỖ KIA thì bạn đã chở nhiệt từ chỗ này sang chỗ kia. Cái máy nén là thứ ép chất ấy phải ngưng tụ ở bên ngoài dù bên ngoài đang ấm hơn, và điện bạn trả là trả cho việc ép ấy. Sờ vào dàn ống đen sau lưng tủ thì thấy nó ấm — đó chính là nhiệt vừa được chở ra khỏi hộp sữa của bạn. Cái điều hoà là đúng cỗ máy đó với cái hộp lớn bằng cả căn phòng, và cái máy bơm nhiệt sưởi ấm mùa đông là đúng cỗ máy đó lắp ngược đầu lại.","The whole refrigerator is the sweat-cooling question run as a closed loop. Evaporating takes a great deal of heat away and condensing gives exactly that much back — so if you make a substance evaporate HERE and condense THERE, you have carried heat from here to there. The compressor is what forces it to condense outside although outside is warmer, and the electricity you pay for is paying for that forcing. Touch the black coils at the back and they are warm — that is the heat just carried out of your milk. An air conditioner is the same machine with a room for its box, and a heat pump warming a house in winter is the same machine turned around."]),n("dong-co-xang-lam-gi",2,"te",["Trong xi-lanh động cơ, một chút xăng trộn với không khí rồi bị đánh lửa. Tiếng nổ ấy lặp lại hàng nghìn lần mỗi phút, và chiếc xe chạy.","In a cylinder, a little petrol mixed with air is set alight. That small bang repeats thousands of times a minute, and the car goes."],["Cái nổ ấy đẩy xe đi bằng cách nào?","How does the bang move the car?"],[["Sức nổ đập thẳng vào bánh xe","The blast strikes the wheels directly"],["Cháy làm khí nóng vọt lên, khí nóng thì nở ra rất mạnh, và nó đẩy một cái pit-tông trượt xuống","Burning makes the gas very hot, hot gas expands hard, and it drives a piston down the cylinder"],["Xăng cháy tạo ra điện chạy vào động cơ điện","The petrol makes electricity which runs a motor"]],1,["Cái nổ không đẩy gì trực tiếp cả. Việc duy nhất nó làm là làm cho khí trong xi-lanh NÓNG lên đột ngột, và khí nóng thì đè ra mọi phía mạnh hơn hẳn khí nguội. Trong cái xi-lanh ấy có đúng một bức tường chịu nhúc nhích, là cái pit-tông — nên toàn bộ cái đè ấy dồn vào việc đẩy pit-tông trượt xuống. Trục khuỷu biến cú trượt thẳng ấy thành cú quay, và bánh xe quay. Nói cách khác, động cơ ô tô là một cái máy NHIỆT y hệt nhà máy điện ở bộ trước, chỉ khác là nó dùng chính khí cháy thay cho hơi nước, và nó cũng bị đúng cái luật kia trói: phần lớn nhiệt bắt buộc phải vứt đi.","The bang pushes nothing directly. Its only job is to make the gas in the cylinder suddenly HOT, and hot gas presses outward far harder than cool gas. That cylinder has exactly one wall free to move, the piston — so all that pressing goes into driving the piston down. The crankshaft turns that straight shove into a rotation, and the wheels turn. Put another way, a car engine is a HEAT engine just like the power station in the last set, using burnt gas instead of steam, and it is bound by the same law: most of the heat must be thrown away."]),n("dong-co-hieu-suat-bao-nhieu",2,"te",["Đổ vào bình một trăm nghìn đồng tiền xăng. Chỉ một phần trong số đó thật sự biến thành chuyển động của chiếc xe; phần còn lại đi ra ngoài dưới dạng nhiệt qua ống xả và qua két nước.","Put a hundred thousand dong of petrol in the tank. Only part of it truly becomes motion; the rest leaves as heat through the exhaust and the radiator."],["Phần biến thành chuyển động là khoảng bao nhiêu?","About how much becomes motion?"],[["Khoảng ba phần tư","About three quarters"],["Khoảng một phần tư","About a quarter"],["Gần như toàn bộ, chỉ hao vài phần trăm","Nearly all of it, with a few percent lost"]],1,["Một động cơ xăng thông thường chỉ đưa được chừng hai mươi tới ba mươi phần trăm năng lượng của nhiên liệu xuống tới bánh xe. Nghe thì như một cỗ máy làm ẩu, nhưng không phải: đây chính là cái trần mà tháp giải nhiệt ở bộ trước đã nói tới. Máy nhiệt chỉ rút được công khi nhiệt chảy từ nóng sang lạnh, và phần rút được bị chặn bởi chênh lệch nhiệt độ giữa hai đầu. Muốn khá hơn thì phải cho cháy nóng hơn nữa, mà nóng hơn nữa thì kim loại chảy. Cái ống xả nóng rẫy và cái két nước sôi sùng sục không phải là chỗ hỏng của xe — chúng chính là cái đầu lạnh bắt buộc phải có. Đây cũng là lý do xe điện tiết kiệm hơn hẳn: động cơ điện không phải máy nhiệt nên nó không bị cái trần ấy trói.","An ordinary petrol engine delivers only about twenty to thirty percent of the fuel’s energy to the wheels. That sounds like a slovenly machine, and it is not: this is the very ceiling the cooling tower described in the last set. A heat engine extracts work only while heat flows from hot to cold, and what it can extract is capped by the gap between the two ends. To do better you must burn hotter, and hotter melts metal. The scorching exhaust and the boiling radiator are not faults in the car — they are the obligatory cold end. It is also why an electric car does so much better: an electric motor is not a heat engine and is not bound by that ceiling."]),n("den-led-tiet-kiem-hon-vi-sao",2,"te",["Bóng dây tóc kiểu cũ và bóng LED cho ra chừng ấy ánh sáng, nhưng bóng cũ ăn 60 oát còn LED chỉ 7 oát. Sờ vào bóng cũ đang sáng thì bỏng tay; sờ LED chỉ hơi ấm.","An old filament bulb and an LED give about the same light, but the old one draws 60 watts and the LED draws 7. Touch the old one while lit and it burns you; the LED is merely warm."],["Cái bóng dây tóc đã tiêu 53 oát kia vào việc gì?","What did the filament bulb spend those other 53 watts on?"],[["Vào việc nung dây tóc lên hơn 2500 độ, mà phần lớn số đó ra ngoài thành nhiệt chứ không thành ánh sáng nhìn được","On heating the filament past 2500 degrees, and most of that leaves as heat rather than as visible light"],["Vào việc thắp sáng phần đui đèn và dây điện","On lighting the fitting and the wiring"],["Vào việc giữ cho bóng đèn không nổ","On keeping the bulb from bursting"]],0,["Bóng dây tóc làm ra ánh sáng bằng cách duy nhất mà con người biết suốt hàng nghìn năm: nung một thứ lên thật nóng cho tới khi nó phát sáng. Nhưng một vật nóng thì phát ra cả một dải rộng, mà mắt người chỉ nhìn thấy được một khúc rất hẹp trong dải ấy — phần còn lại toả ra thành nhiệt vô hình. Ở nhiệt độ mà sợi vonfram chịu được, phần rơi đúng vào khúc nhìn thấy chỉ chừng năm phần trăm. Đèn LED thì không đi qua khâu nung nóng: điện đẩy các hạt điện qua một lớp vật liệu và mỗi lần chúng tụt xuống một bậc thì nhả ra một hạt ánh sáng, và người ta chọn vật liệu sao cho hạt ánh sáng ấy rơi đúng vào khúc mắt nhìn được. Bỏ được một khâu trung gian bắt buộc phải phí, đó là chỗ mà tất cả số điện kia được cứu về.","A filament bulb makes light the only way people knew for thousands of years: heat something until it glows. But a hot object radiates across a broad band, and the eye sees only a narrow slice of it — the rest leaves as invisible heat. At the temperature tungsten can survive, the share landing in the visible slice is around five percent. An LED skips the heating step: current drives charges through a layered material and each time one drops a step it releases a particle of light, and the material is chosen so that particle falls in the visible slice. Removing an intermediate step that had to be wasteful is where all that electricity was saved."]),n("dien-thoai-biet-minh-o-dau",3,"te",["Mở bản đồ trên điện thoại, một chấm xanh hiện ra đúng chỗ bạn đang đứng, sai số vài mét. Điện thoại không hề gửi gì lên vệ tinh — nó chỉ NGHE.","Open a map on a phone and a blue dot appears where you stand, accurate to a few metres. The phone sends nothing to the satellites — it only LISTENS."],["Nó xác định vị trí bằng cách nào?","How does it work out where it is?"],[["Vệ tinh chụp ảnh và nhận ra cái điện thoại","A satellite photographs it and recognises the phone"],["Mỗi vệ tinh phát đi giờ của mình; điện thoại so giờ nhận được, ra khoảng cách tới từng cái, rồi tìm điểm khớp","Each satellite broadcasts its own time; the phone compares what arrives, works out its distance to each, and finds the point that fits all"],["Vệ tinh gửi một tia dò xuống rồi đo tia phản hồi","The satellite sends down a probing beam and measures what comes back"]],1,['Mỗi vệ tinh mang một cái đồng hồ cực chính xác và phát đi không ngừng câu "bây giờ là mấy giờ, và tôi đang ở đây". Tín hiệu ấy đi với tốc độ ánh sáng, nên khi tới điện thoại thì nó đã cũ đi một chút — đo cái cũ ấy là biết khoảng cách. Một vệ tinh cho một mặt cầu quanh nó; ba vệ tinh cho ba mặt cầu cắt nhau; bốn cái thì đủ để tính luôn cả sai lệch đồng hồ trong điện thoại. Đây đúng là cách tìm tâm chấn động đất ở bộ trước, chỉ đổi trạm đo thành vệ tinh. Một điều đáng nói: các đồng hồ trên vệ tinh chạy lệch so với dưới đất do hiệu ứng tương đối, và nếu không hiệu chỉnh thì chấm xanh của bạn sẽ trôi đi hơn mười cây số mỗi ngày. Thuyết tương đối không phải chuyện xa vời — nó nằm trong túi bạn.',"Each satellite carries an extremely accurate clock and broadcasts without pause the message that it is now this time and I am here. The signal travels at the speed of light, so by the time it arrives it is slightly stale — measure the staleness and you have the distance. One satellite gives a sphere around it; three give three spheres crossing; four are enough to solve for the phone’s own clock error as well. This is precisely the way an epicentre is found in the previous set, with satellites for seismographs. Worth noting: the clocks up there run at a different rate from ours because of relativity, and left uncorrected your blue dot would drift more than ten kilometres a day. Relativity is not remote — it is in your pocket."])])],f=[t("ma-sat",["Ma Sát","Grip"],["Ma sát không phải kẻ thù — không có nó thì không ai bước đi được","Friction is not the enemy — without it nobody could take a step"],[n("day-hop-chua-di",1,"tp",["Một cái hòm gỗ nặng đứng yên trên nền nhà. Bạn đẩy nhẹ vào nó bằng một lực đúng 5 kilôgam lực. Cái hòm không nhúc nhích một li nào.","A heavy wooden crate sits still on the floor. You push it with a force of exactly 5 kilograms weight. The crate does not budge at all."],["Lúc ấy ma sát đang giữ cái hòm bằng lực bao nhiêu?","How hard is friction holding the crate at that moment?"],[["Đúng 5 — bằng hệt lực bạn đang đẩy","Exactly 5 — the same as the push"],["Nhiều hơn 5, vì nếu bằng thì hòm phải đi rồi","More than 5, since if it were equal the crate would move"],["Bằng sức nặng của cái hòm, không liên quan tới tay bạn","Equal to the weight of the crate, nothing to do with your hands"]],0,["Cái hòm đứng yên, nghĩa là tổng mọi lực đặt lên nó bằng không. Bạn đẩy 5, vậy ma sát phải kéo lại đúng 5 — không hơn một chút nào, vì nếu ma sát lớn hơn thì cái hòm đã phải chạy ngược về phía bạn. Ma sát nghỉ không phải một con số cố định; nó là một lực biết tự chỉnh, luôn bằng đúng cái đang đẩy nó, cho tới một mức trần. Đẩy 8 thì nó giữ 8. Đẩy quá trần thì nó buông, và đó chính là cái giật mình lúc cái hòm bất chợt trôi đi.","The crate is still, which means every force on it sums to zero. You push 5, so friction pulls back exactly 5 — not a fraction more, because if friction were larger the crate would have slid towards you. Static friction is not a fixed number; it is a self-adjusting force, always matching whatever pushes it, up to a ceiling. Push 8 and it holds 8. Push past the ceiling and it lets go — which is the lurch you feel when the crate suddenly slides."]),n("vien-gach-nam-hay-dung",2,"tp",["Một viên gạch kéo lê trên sàn bằng dây. Lần đầu kéo lúc gạch nằm bẹt, mặt rộng áp xuống. Lần sau dựng nghiêng lên, chỉ còn mặt hẹp chạm sàn. Cùng viên gạch, cùng cái sàn.","A brick is dragged across a floor by a string. First lying flat on its widest face, then tipped onto its narrow edge. Same brick, same floor."],["Lần nào kéo nặng tay hơn?","Which drag takes more force?"],[["Lúc nằm bẹt, vì chạm sàn nhiều hơn","Lying flat, because more of it touches the floor"],["Hai lần nặng như nhau","Both take the same force"],["Lúc dựng nghiêng, vì dồn hết sức nặng vào một vệt hẹp","On its edge, because all the weight is squeezed into a narrow strip"]],1,["Kết quả này làm hầu hết mọi người khó chịu, và nó đúng: kéo hai lần nặng như nhau. Chỗ tiếp xúc rộng gấp ba thì mỗi điểm chịu áp lực chỉ bằng một phần ba, hai cái nhân với nhau ra đúng một số cũ. Ma sát tính theo sức nặng đè xuống, không theo bề rộng chỗ chạm. Muốn kéo nhẹ đi thì chỉ có hai đường: làm viên gạch nhẹ đi, hoặc đổi cái sàn — lật qua lật lại viên gạch thì vô ích.","This result annoys nearly everybody, and it holds: both drags take the same force. Three times the contact area means each point carries a third of the pressure, and the two changes cancel exactly. Friction depends on the weight pressing down, not on the width of the contact. To drag more easily there are only two roads: make the brick lighter, or change the floor — turning the brick over achieves nothing."]),n("lop-xe-dua-tron-lu",2,"te",["Lốp xe máy đi đường thường có rãnh sâu khắp mặt. Lốp xe đua trên đường khô thì nhẵn lì, không một cái rãnh nào.","An everyday motorbike tyre is cut with deep grooves all over. A racing tyre for a dry track is completely smooth, without a single groove."],["Rãnh trên lốp thường để làm gì?","What are the grooves on the ordinary tyre for?"],[["Để bám đường tốt hơn khi đường khô","To grip better on dry roads"],["Để có chỗ cho nước thoát ra khi đường ướt","To give water somewhere to escape on a wet road"],["Để lốp bớt nóng lúc chạy nhanh","To keep the tyre cooler at speed"]],1,["Trên đường khô, lốp nhẵn bám tốt hơn lốp có rãnh, vì cao su chạm mặt đường được nhiều hơn — nên xe đua dùng lốp lì. Rãnh sinh ra cho một tình huống khác hẳn: khi có một màng nước, bánh xe có thể trượt lên trên màng ấy và mất hẳn tiếp xúc. Rãnh là đường thoát để nước kịp chạy ra hai bên. Vậy nên lốp mòn hết rãnh không phải chuyện thẩm mỹ: nó vẫn bám tốt cho tới đúng cơn mưa đầu tiên.","On dry tarmac a smooth tyre grips better than a grooved one, because more rubber meets the road — which is why racing tyres are slick. The grooves exist for a different situation: with a film of water the wheel can ride up on it and lose contact altogether. The grooves are escape channels so the water can get out sideways. So a tyre worn smooth is not a cosmetic matter: it grips beautifully until the first rain."]),n("phanh-cung-khoa-banh",3,"tp",["Hai xe đạp giống nhau lao xuống dốc cùng tốc độ. Người thứ nhất bóp phanh thật mạnh, bánh khoá cứng lại và trượt lê trên đường. Người thứ hai bóp vừa đủ để bánh còn lăn, chỉ lăn chậm dần.","Two identical bicycles run down a slope at the same speed. The first rider clamps the brake hard, locking the wheel so it skids. The second brakes just short of locking, so the wheel still rolls."],["Xe nào dừng trong quãng ngắn hơn?","Which stops in the shorter distance?"],[["Xe khoá cứng bánh, vì phanh mạnh nhất","The skidding one — it braked hardest"],["Xe còn lăn bánh","The one still rolling"],["Hai xe dừng ở cùng một chỗ","Both stop at the same place"]],1,["Đây là chỗ bẻ luật của cả bộ. Ma sát nghỉ — giữa hai mặt chưa trượt lên nhau — bao giờ cũng mạnh hơn ma sát trượt. Bánh còn lăn thì điểm chạm đất đứng yên so với mặt đường ngay khoảnh khắc ấy, nên nó dùng ma sát nghỉ. Bánh khoá cứng thì cao su đang lết, và lết là ma sát trượt: yếu hơn, lại nóng lên làm cao su chảy thành một lớp trơn. Chưa kể bánh trượt thì không lái được nữa. Toàn bộ hệ thống phanh ABS trên ô tô sinh ra chỉ để làm một việc: nhả phanh ra vài chục lần mỗi giây cho bánh đừng bao giờ khoá.","Here is where the rule bends. Static friction — between surfaces not yet sliding — is always stronger than sliding friction. A rolling wheel has its contact point momentarily still relative to the road, so it uses static friction. A locked wheel is dragging, and dragging is sliding friction: weaker, and hot enough to melt a slippery film of rubber. A skidding wheel also steers nowhere. The whole ABS system on a car exists to do one thing: release the brake dozens of times a second so the wheel never locks."]),n("di-tren-bang-vi-sao-kho",2,"tp",["Trên mặt băng, người ta không đứng vững, không bước được, và ngã thì rất khó đứng dậy. Nhưng băng vẫn là một mặt phẳng cứng, chẳng khác gì mặt sân xi măng.","On ice a person cannot stand steadily, cannot walk, and once down finds it hard to get up. Yet ice is still a hard flat surface, no different in that respect from a concrete yard."],["Bước đi cần cái gì mà mặt băng không cho?","What does walking need that ice will not give?"],[["Một mặt đủ nhám để chân đẩy ngược ra sau","A surface rough enough for the foot to push backwards against"],["Một mặt đủ cứng để đỡ được sức nặng","A surface hard enough to carry the weight"],["Một mặt đủ ấm để chân không tê đi","A surface warm enough that the foot does not go numb"]],0,["Bước đi không phải là nhấc chân lên đặt về phía trước. Nó là đẩy mặt đất về phía sau, và mặt đất đẩy mình về phía trước đúng bằng chừng ấy. Cái đẩy ngược ấy hoàn toàn là ma sát. Mặt băng gần như không có ma sát, nên chân đẩy ra sau thì chân trôi ra sau, còn người thì đứng nguyên tại chỗ. Đó cũng là lý do trên sàn trơn người ta bước ngắn và đặt bàn chân thẳng đứng xuống: bước dài đòi lực đẩy ngang lớn hơn, mà lực ngang lớn thì mặt băng không cấp nổi.","Walking is not lifting a foot and placing it ahead. It is shoving the ground backwards, and the ground shoving you forwards by exactly as much. That shove is entirely friction. Ice supplies almost none, so a foot pushed back simply travels back while the person stays put. It is also why on a slippery floor people take short steps and set the sole down vertically: a long stride needs a larger sideways push, and ice cannot supply one."])]),t("quan-tinh",["Quán Tính","What Keeps Going"],["Vật đang đứng thì muốn đứng, đang đi thì muốn đi — đổi ý là phải có lực","What is still stays still and what moves keeps moving, unless something forces a change"],[n("giat-khan-trai-ban",1,"tp",["Trên khăn trải bàn có một chồng bát đĩa. Kéo tấm khăn ra thật chậm thì bát đĩa đi theo và đổ. Giật thật nhanh thì khăn ra mà bát đĩa còn nguyên tại chỗ.","A stack of crockery stands on a tablecloth. Pull the cloth slowly and the crockery travels with it and falls. Whip it out fast and the cloth leaves while the crockery stays."],["Vì sao giật nhanh lại được?","Why does the fast pull work?"],[["Vì kéo nhanh thì ma sát biến mất hoàn toàn","Because a fast pull removes friction entirely"],["Vì ma sát chỉ kịp tác dụng trong một khoảnh khắc quá ngắn để đẩy bát đi","Because friction only gets a moment too short to shift the crockery"],["Vì bát đĩa nặng nên nó tự bám vào mặt bàn","Because heavy crockery clings to the table by itself"]],1,["Ma sát vẫn còn, và nó vẫn đẩy chồng bát đi theo tấm khăn. Cái khác là thời gian. Muốn một vật nặng đạt được vận tốc đáng kể thì lực phải tác dụng trong một quãng thời gian đủ dài. Giật nhanh nghĩa là lực ấy chỉ có vài phần trăm giây, đủ để chồng bát nhích vài milimét rồi thôi — nhìn ra thì như nó không hề động. Kéo chậm thì lực nhỏ hơn nhưng kéo dài, và tổng lại thừa sức lôi cả chồng bát xuống đất.","Friction is still there, and it does drag the crockery along with the cloth. What differs is time. To give a heavy object any real speed, a force must act for long enough. A fast whip gives that force a few hundredths of a second — enough to shift the stack a millimetre or two and no further, which looks like not moving at all. A slow pull applies a smaller force for far longer, and the total is more than enough to bring everything down."]),n("xe-buyt-phanh-gap",1,"tp",["Bạn đứng trên xe buýt đang chạy, không bám vào đâu cả. Xe phanh gấp.","You are standing on a moving bus, holding on to nothing. The driver brakes hard."],["Người bạn đổ về phía nào, và vì sao?","Which way do you fall, and why?"],[["Về phía trước, vì có một lực ném mình tới trước","Forwards, because a force throws me forwards"],["Về phía trước, vì xe chậm lại còn mình thì chưa","Forwards, because the bus slowed and I have not"],["Về phía sau, vì xe kéo mình lại","Backwards, because the bus drags me back"]],1,['Không có lực nào ném mình về phía trước cả — đó chính là điểm hay. Trước khi phanh, cả xe lẫn mình cùng chạy 30 cây số một giờ. Cái phanh tác dụng lên xe, không tác dụng lên mình; sàn xe chỉ đủ ma sát để kéo bàn chân lại. Thân trên vẫn giữ nguyên 30 cây số một giờ như cũ, nên nó vượt lên trước bàn chân, và mình đổ nhào. Cảm giác "bị ném tới trước" là thật, nhưng nguyên nhân không phải một cái đẩy — nó là chuyện phần còn lại của thế giới vừa chậm lại mà mình thì chưa.',"No force throws you forwards — that is the whole point. Before braking, the bus and you were both doing thirty kilometres an hour. The brake acts on the bus, not on you; the floor only has enough friction to slow your feet. Your upper body is still doing thirty, so it overtakes your feet and you topple. The feeling of being thrown forwards is real, but its cause is not a shove — it is that the rest of the world just slowed and you did not."]),n("bong-bay-trong-xe-kin",3,"tp",["Trong một chiếc ô tô đóng kín cửa, có một quả bóng bay bơm khí heli buộc dây vào sàn, đang lơ lửng thẳng đứng. Xe đột ngột tăng tốc lao về phía trước.","Inside a sealed car floats a helium balloon on a string tied to the floor, hanging straight up. The car suddenly accelerates forwards."],["Quả bóng nghiêng về phía nào?","Which way does the balloon lean?"],[["Ngả về phía sau, giống mọi hành khách","Backwards, like every passenger"],["Ngả về phía trước","Forwards"],["Vẫn đứng thẳng, vì heli quá nhẹ","Straight up still — helium is too light to care"]],1,["Đây là chỗ bẻ luật. Mọi thứ có khối lượng trong xe đều bị trễ lại phía sau, kể cả không khí — nên không khí dồn về đuôi xe, và phía đuôi trở nên đặc hơn, áp suất cao hơn. Quả bóng heli nhẹ hơn không khí quanh nó, nên nó luôn bị đẩy về phía áp suất thấp, tức là về phía trước. Đúng cái lý do làm nó bay lên chứ không rơi xuống: nó không đi theo trọng lực, nó đi ngược lại chỗ không khí bị dồn. Ai từng thấy bong bóng trong xe con nghiêng tới trước lúc đề ga thì đã nhìn thấy điều này rồi.","Here the rule bends. Everything with mass in the car lags backwards, the air included — so the air piles up at the rear, making it denser and its pressure higher. The helium balloon is lighter than the air around it, so it is always pushed towards the lower pressure, which is forwards. It is exactly the reason it rises rather than falls: it does not follow gravity, it goes opposite to wherever the air is being crowded. Anyone who has watched a balloon tilt forwards as a car pulls away has already seen this."]),n("go-can-bua-xuong-dat",2,"tp",["Đầu búa bị lỏng khỏi cán. Người thợ không đóng đinh vào đâu cả — anh ta cầm ngược búa lên, nện đuôi cán xuống nền cứng vài cái. Đầu búa siết chặt lại vào cán.","A hammer head has worked loose on its handle. The carpenter drives no nail — he turns the hammer over and knocks the butt of the handle down on a hard floor a few times. The head tightens back on."],["Cái gì đã siết đầu búa vào?","What tightened the head?"],[["Cú nện làm cán nở ra vì nóng","The knocks warmed the handle so it swelled"],["Cán dừng lại khi chạm đất, còn đầu búa vẫn đang đi xuống","The handle stopped at the floor while the head kept travelling down"],["Rung động làm gỗ và sắt dính vào nhau","The vibration made wood and iron stick together"]],1,["Cán búa chạm đất thì dừng phắt. Đầu búa không chạm gì cả, nên nó giữ nguyên chuyển động đi xuống của mình và trượt thêm một đoạn trên cán — tức là ăn sâu vào. Lặp vài cái là chặt. Đây đúng là mẹo mà thợ mộc nào cũng biết, và nó chỉ hoạt động vì quán tính: không có một lực nào đóng đầu búa vào cả, chỉ có việc cán bị chặn lại còn đầu búa thì không ai chặn. Cũng vì thế mà nện đầu búa xuống đất lại làm nó lỏng thêm.","The handle hits the floor and stops dead. The head touches nothing, so it keeps its downward motion and slides a little further onto the handle — which is to say, seats itself deeper. A few knocks and it is tight. This is a trick every carpenter knows, and it works purely by inertia: no force drives the head on, it is simply that the handle was stopped and the head was not. It is also why knocking the head down on the floor loosens it instead."]),n("rut-to-giay-duoi-dong-xu",2,"tp",["Một đồng xu đặt trên tờ giấy nhỏ, tờ giấy đặt trên mép bàn. Rút tờ giấy ra thật nhanh theo phương ngang thì đồng xu rơi thẳng xuống chỗ cũ.","A coin sits on a small piece of paper at the edge of a table. Whip the paper out sideways and the coin drops straight down where it was."],["Đồng xu rơi thẳng xuống nghĩa là gì?","What does its dropping straight down tell you?"],[["Nó đã không nhận được lực ngang đáng kể nào","It received no sideways force worth speaking of"],["Trọng lực lúc ấy mạnh hơn bình thường","Gravity was briefly stronger than usual"],["Tờ giấy đã đẩy nó ngược lại một cái","The paper gave it a push the other way"]],0,["Đồng xu rơi thẳng xuống, nghĩa là theo phương ngang nó vẫn đứng yên như cũ. Ma sát giữa giấy và xu có tồn tại và có đẩy, nhưng chỉ trong khoảnh khắc tờ giấy còn nằm dưới nó — quá ngắn để cấp cho đồng xu một vận tốc ngang nhìn thấy được. Đây là cùng một hiện tượng với tấm khăn trải bàn, thu nhỏ lại tới mức làm được trên một góc bàn học. Rút chậm thì đồng xu đi theo và văng ra xa, và đó là cách kiểm tra rằng lời giải này đúng.","The coin falls straight down, which means sideways it never moved. Friction between paper and coin does exist and does push, but only for the instant the paper is still underneath — too short to give the coin any visible sideways speed. This is the tablecloth again, shrunk to the corner of a desk. Pull slowly and the coin travels with the paper and flies off, which is how you check the explanation is right."])]),t("suc-can",["Sức Cản","Pushing Through Air"],["Không khí là một chất, và đi nhanh trong một chất thì phải trả giá","Air is a substance, and moving fast through any substance has a price"],[n("to-giay-phang-va-vo-tron",1,"tp",["Hai tờ giấy giống hệt nhau, cùng cân nặng. Một tờ để phẳng, một tờ vò tròn thành viên. Thả cùng lúc từ cùng độ cao.","Two identical sheets of paper, the same weight. One left flat, one crushed into a ball. Both dropped at the same moment from the same height."],["Vì sao viên giấy vò chạm đất trước?","Why does the crumpled one land first?"],[["Vì vò lại thì nó nặng hơn","Because crumpling made it heavier"],["Vì nó phải rẽ qua ít không khí hơn","Because it has less air to shoulder aside"],["Vì tờ phẳng bị gió trong phòng thổi lên","Because a draught in the room lifts the flat sheet"]],1,['Hai tờ giấy nặng đúng bằng nhau, nên trọng lực kéo chúng như nhau. Cái khác duy nhất là mặt cản: tờ phẳng phải đẩy một khối không khí rộng bằng cả tờ giấy sang hai bên, còn viên vò thì chỉ rẽ một lỗ bé. Trong chân không, hai tờ rơi hệt nhau và chạm đất cùng lúc — thí nghiệm ấy đã được làm trên Mặt Trăng với một cái búa và một cái lông chim. Nên câu "vật nặng rơi nhanh hơn" thật ra chưa bao giờ nói về sức nặng; nó nói về không khí.',"The two sheets weigh the same, so gravity pulls them equally. The only difference is frontage: the flat sheet must shove aside a slab of air as wide as itself, while the ball bores a small hole. In a vacuum the two fall identically and land together — an experiment actually performed on the Moon with a hammer and a feather. So the saying that heavy things fall faster was never about weight at all; it was about air."]),n("nhay-du-roi-mai-co-nhanh-mai",2,"tp",["Một người nhảy khỏi máy bay và rơi tự do, chưa mở dù. Trọng lực kéo suốt, không lúc nào ngừng.","A skydiver leaves the aircraft in free fall, parachute still closed. Gravity pulls the whole way and never lets up."],["Người ấy có rơi mỗi lúc một nhanh mãi không?","Does the fall keep getting faster and faster without limit?"],[["Có, cho tới lúc chạm đất","Yes, right up to the ground"],["Không, tới một tốc độ nào đó thì dừng lại ở đấy","No — it levels off at some speed and stays there"],["Không, tới một lúc thì bắt đầu chậm dần lại","No — after a while it starts slowing down again"]],1,["Càng rơi nhanh thì không khí cản càng mạnh. Tới một tốc độ nào đó, sức cản lớn đúng bằng sức nặng, tổng lực thành không, và từ đó người ấy rơi đều — không nhanh thêm nữa. Với một người nằm dang tay, tốc độ ấy khoảng 200 cây số một giờ; chụm người lại thì lên tới hơn 300, vì mặt cản nhỏ đi. Mở dù là làm mặt cản to vọt lên, nên tốc độ ổn định mới tụt xuống còn khoảng 20 cây số một giờ. Cái dù không phanh ai cả — nó chỉ đổi cái mức mà sức cản cân được sức nặng.","The faster the fall, the harder the air pushes back. At some speed that push equals the weight exactly, the total force becomes zero, and from then on the fall is steady — no faster. For a spread-eagled body that is around 200 kilometres an hour; tucked into a dive it passes 300, because the frontage shrinks. Opening a parachute makes the frontage enormous, so the new steady speed is about 20. The canopy brakes nobody — it merely changes the speed at which drag balances weight."]),n("dap-xe-gap-doi-toc-do",2,"te",["Đạp xe trong trời lặng gió. Bạn tăng tốc từ 10 lên 20 cây số một giờ, tức là gấp đôi.","Cycling on a still day, you go from 10 kilometres an hour to 20 — exactly double."],["Sức cản của không khí tăng lên bao nhiêu lần?","How much does the air resistance grow?"],[["Gấp đôi","It doubles"],["Gấp bốn","It quadruples"],["Không đổi, vì trời lặng gió","It stays the same — the air is still"]],1,["Đi nhanh gấp đôi thì mỗi giây phải rẽ gấp đôi lượng không khí, và mỗi khối không khí ấy lại bị hất đi với tốc độ gấp đôi. Hai cái nhân với nhau thành gấp bốn. Đó là lý do đạp xe 15 cây số một giờ thì nhẹ nhàng mà 35 thì gần như không giữ nổi, dù chỉ hơn nhau hơn gấp đôi. Cũng chính vì thế mà lái xe 100 tốn xăng hơn hẳn lái 70 — phần lớn xăng ở tốc độ cao không dùng để đi, nó dùng để đẩy không khí ra khỏi đường.","Twice the speed means shoving twice as much air aside each second, and hurling each parcel of it away twice as fast. Multiply the two and you get four. That is why 15 kilometres an hour on a bicycle is a pleasant amble and 35 is barely sustainable, though it is only just over double. It is the same reason a car at 100 drinks far more than at 70 — most of the fuel at speed is not spent travelling, it is spent moving air out of the road."]),n("nap-sau-xe-tai",3,"tp",["Đoàn đua xe đạp bám sát nhau thành hàng dài. Người đi đầu mệt hơn hẳn, và cứ vài phút họ lại đổi người dẫn.","A bunch of racing cyclists rides in a tight line. The rider in front tires far faster, and every few minutes they swap the lead."],["Người phía sau được lợi cái gì?","What do the riders behind gain?"],[["Được người trước kéo theo bằng luồng gió xoáy","They are towed along in the swirl behind the leader"],["Đi trong vùng không khí đã bị người trước rẽ ra sẵn","They ride in air the leader has already pushed aside"],["Đỡ phải nhìn đường nên đạp đều hơn","They need not watch the road so they pedal more evenly"]],1,["Người dẫn đầu phải rẽ một khối không khí đứng yên, và tốn khoảng một phần ba sức chỉ cho việc ấy. Ngay sau lưng anh ta là một vùng không khí đã bị kéo đi theo, gần như đứng yên so với đoàn xe — nên người bám sau chỉ phải đẩy rất ít. Tiết kiệm được tới ba mươi phần trăm sức, đủ để cả đoàn đi nhanh hơn bất kỳ ai đi một mình. Cùng một hiện tượng làm đàn ngỗng bay hình chữ V, và làm hai xe tải chạy sát nhau tốn ít dầu hơn hai xe chạy rời.","The leader shoulders aside a wall of still air, and spends about a third of all effort on that alone. Directly behind is a pocket of air already dragged along, nearly still relative to the bunch — so the follower has very little to push. The saving reaches thirty per cent, enough that the group outruns any solo rider. The same effect puts geese in a V, and makes two lorries running close burn less diesel than two running apart."]),n("giot-mua-roi-tu-hai-cay-so",3,"tp",["Đám mây mưa thường ở độ cao khoảng hai cây số. Một hòn đá thả rơi từ độ cao ấy sẽ chạm đất với tốc độ chết người.","Rain clouds commonly sit about two kilometres up. A stone dropped from there would hit the ground at a lethal speed."],["Vì sao đứng dưới mưa lại không sao?","Why is standing in rain harmless?"],[["Vì giọt mưa quá nhẹ nên trọng lực gần như không kéo nó","Because a raindrop is so light that gravity barely pulls it"],["Vì giọt mưa đạt tốc độ đều rất sớm và giữ nguyên tốc độ ấy","Because a drop reaches a steady speed very early and holds it"],["Vì mưa rơi chậm dần khi xuống gần mặt đất","Because rain slows down as it nears the ground"]],1,["Trọng lực kéo giọt mưa đúng như kéo hòn đá, nhưng giọt mưa bé nên tỉ lệ giữa mặt cản và khối lượng của nó lớn hơn hòn đá rất nhiều. Chỉ sau vài chục mét, sức cản đã bằng sức nặng và giọt mưa đi đều ở khoảng 25 cây số một giờ — rồi giữ đúng tốc độ ấy suốt hai cây số còn lại. Bốn mét đầu hay hai nghìn mét cũng không khác nhau chút nào. Cũng vì thế mà một con kiến rơi từ nóc nhà xuống thì bò đi bình thường, còn một con ngựa thì không.","Gravity pulls the drop exactly as it pulls the stone, but the drop is small, so its frontage is enormous compared with its mass. Within a few tens of metres the drag already equals the weight and the drop settles at about 25 kilometres an hour — then holds that speed for the remaining two kilometres. Falling four metres and falling two thousand come out the same. It is also why an ant dropped from a roof walks away and a horse does not."])])],T=[t("trong-tam",["Trọng Tâm","Where the Weight Sits"],["Mỗi vật có một điểm mà cả sức nặng của nó coi như dồn vào đấy","Every object has one point where all its weight may as well be"],[n("dung-sat-tuong-cui-nhat",1,"tp",["Đứng thẳng, gót chân và lưng áp sát vào tường, không được nhấc gót lên. Trước mũi chân có một đồng xu. Cúi xuống nhặt.","Stand with heels and back flat against a wall, heels not allowed to lift. A coin lies just in front of your toes. Bend and pick it up."],["Chuyện gì xảy ra?","What happens?"],[["Nhặt được bình thường, chỉ hơi khó chịu","You pick it up, just a little awkwardly"],["Không cúi được xa, hoặc cúi thì đổ về phía trước","You cannot reach far, or you topple forwards"],["Lưng bị tường đẩy nên nhặt còn dễ hơn","The wall pushes your back, making it easier"]],1,["Bình thường lúc cúi xuống, mông người ta tự động đưa ra sau — không ai dạy, cơ thể tự làm — để trọng tâm luôn nằm trên khoảng giữa hai bàn chân. Bức tường chặn đúng cái động tác ấy. Không đưa mông ra sau được thì cúi tới đâu trọng tâm chạy ra khỏi bàn chân tới đấy, và một vật có trọng tâm rơi ra ngoài chân đế thì đổ. Đây là thí nghiệm làm được ngay tại lớp, và nó cho thấy giữ thăng bằng không phải chuyện cơ bắp mà là chuyện hình học.","Normally when you bend, your backside swings out behind — nobody teaches this, the body just does it — so the centre of weight stays over the space between your feet. The wall blocks exactly that motion. With no room to counterweight behind, every centimetre forward carries the centre out past your toes, and anything whose weight-point leaves its base falls. This is a classroom experiment, and it shows balance is not a matter of muscle but of geometry."]),n("xe-cho-cao-de-lat",2,"te",["Hai xe tải giống hệt nhau, cùng chở đúng một tấn. Xe thứ nhất chất hàng thấp sát sàn thùng. Xe thứ hai chất hàng chồng lên cao. Cả hai vào cùng một khúc cua.","Two identical lorries each carry exactly one tonne. One is loaded low against the bed, the other stacked high. Both take the same bend."],["Xe nào dễ lật hơn?","Which is likelier to roll?"],[["Xe chất cao","The high-loaded one"],["Hai xe như nhau, vì cùng một tấn","Both the same — the same tonne"],["Xe chất thấp, vì hàng dồn vào một chỗ","The low-loaded one, since the load is concentrated"]],0,["Cùng một tấn, nhưng trọng tâm ở hai độ cao khác nhau. Vào cua, xe bị hất ra ngoài, và cái quyết định lật hay không là đường thẳng đứng qua trọng tâm còn nằm trong khoảng hai bánh bên ngoài hay đã trượt ra khỏi đó. Trọng tâm càng cao thì chỉ cần nghiêng một góc nhỏ là nó đã ra ngoài. Vì thế xe buýt hai tầng có tầng dưới nặng cố ý, xe đua thì bẹp sát đất, và người chở đồ cồng kềnh nên xếp thứ nặng xuống dưới cùng chứ không phải xếp cho gọn mắt.","The same tonne, but the weight-point sits at two different heights. On a bend the load is thrown outwards, and what decides a roll is whether the vertical line through that point still falls between the outer wheels or has slipped past them. The higher the point, the smaller the tilt needed to push it out. Which is why double-deckers are deliberately heavy downstairs, racing cars are flattened to the road, and anyone loading a cart should put the heaviest thing at the bottom rather than wherever it looks tidiest."]),n("thap-nghieng-den-dau-thi-do",2,"tp",["Tháp nghiêng Pisa đã nghiêng gần bốn độ suốt mấy trăm năm mà không đổ. Người ta vẫn lo, và vẫn gia cố.","The tower at Pisa has leaned nearly four degrees for centuries without falling. People still worry about it, and still shore it up."],["Cái gì quyết định lúc nào nó đổ?","What decides when it goes over?"],[["Khi nó nghiêng quá bốn mươi lăm độ","When the lean passes forty-five degrees"],["Khi đường thẳng đứng qua trọng tâm rơi ra ngoài chân móng","When the vertical through its weight-point falls outside the base"],["Khi sức nặng phần trên vượt sức nặng phần dưới","When the top half outweighs the bottom half"]],1,["Không có một góc thần thánh nào cả. Một vật đứng được chừng nào đường thẳng đứng thả từ trọng tâm của nó còn rơi vào bên trong chân đế. Cái tháp Pisa nghiêng bốn độ mà vẫn đứng vì chân móng nó rộng và trọng tâm nó thấp; một cây bút chì dựng đứng thì chỉ nghiêng một độ đã đổ, vì chân đế của nó bằng đầu ngón tay. Cũng chính vì thế mà một người say đứng dạng chân ra, và một cái thang càng mở rộng chân càng chắc.","There is no magic angle. A thing stands as long as a plumb line dropped from its weight-point still lands inside its base. Pisa leans four degrees and stands because its footing is broad and its weight sits low; a pencil balanced on end topples at one degree, because its base is the width of a fingertip. It is also why a drunk stands with feet apart, and why a stepladder is steadier the wider its legs are opened."]),n("ghe-nga-hai-chan-sau",3,"tp",["Ngồi ghế gỗ bốn chân, ngả người ra sau cho ghế chỉ còn tì trên hai chân sau. Ngả từ từ. Có một góc mà quá nó là ngã.","Sitting on a four-legged wooden chair, you tip back until only the two rear legs touch. Lean slowly. There is an angle past which you go over."],["Ngay trước lúc ngã, cái gì đang xảy ra?","Just before the fall, what is happening?"],[["Trọng tâm đang đứng đúng trên đường nối hai chân sau","The weight-point stands exactly over the line joining the rear legs"],["Hai chân sau đang chịu gấp đôi sức nặng bình thường","The rear legs are carrying twice the usual weight"],["Ghế đang bắt đầu bị đẩy ngược về phía trước","The chair is starting to be pushed back forwards"]],0,["Chỗ bẻ luật nằm ở đây: điểm ngã không phải điểm nặng nhất, nó là điểm cân bằng. Ngay trước khi ngã, trọng tâm của cả người lẫn ghế đứng đúng trên đường nối hai chân sau — lúc ấy hệ thống hoàn toàn cân bằng và về lý thuyết có thể đứng yên mãi mãi. Nhưng đó là cân bằng không bền: nhích ra sau một li thì trọng lực xoay tiếp về sau, nhích tới một li thì nó xoay về trước. Ngồi ngả ghế mà thấy phải liên tục vẫy tay, chính là vì mình đang đứng ngay trên đỉnh ấy.","Here is where the rule bends: the tipping point is not the heaviest point, it is the balance point. Just before the fall, the combined weight-point of chair and sitter stands exactly over the line between the rear legs — at which instant the system is perfectly balanced and could in theory stay there forever. But it is unstable balance: a millimetre back and gravity turns it further back, a millimetre forward and it swings home. The constant small arm-waving of anyone tipping a chair is the feel of sitting on that summit."]),n("ganh-nuoc-hai-dau",2,"tp",["Một cái đòn gánh, hai đầu treo hai thùng nước không bằng nhau: một thùng đầy, một thùng vơi. Người gánh vẫn đi được êm, không thấy nặng lệch bên nào.","A carrying pole with two unequal buckets: one full, one half full. The carrier still walks smoothly, feeling no pull to either side."],["Người ấy đã làm gì?","What has the carrier done?"],[["Đặt vai lệch về phía thùng nặng","Moved the shoulder towards the heavier bucket"],["Đặt vai lệch về phía thùng nhẹ","Moved the shoulder towards the lighter bucket"],["Nâng thùng nặng lên cao hơn thùng nhẹ","Hung the heavier bucket higher than the lighter one"]],0,["Cái cân bằng ở đây không phải cân bằng sức nặng mà cân bằng tích của sức nặng với khoảng cách tới vai. Thùng nặng gấp đôi thì phải treo gần vai bằng một nửa. Người gánh nước không tính toán gì cả, họ dịch vai cho tới lúc thấy êm — nhưng cái êm ấy chính là lúc hai tích bằng nhau. Đây cũng là toàn bộ nguyên lý của cái cân đòn ngoài chợ: một quả cân nhỏ trượt ra xa cân được một con lợn, chỉ cần cánh tay đòn đủ dài.","The balance here is not of weights but of weight multiplied by distance from the shoulder. A bucket twice as heavy must hang half as far out. The carrier calculates nothing, simply sliding the shoulder until it feels level — but that feeling of level is the moment the two products match. It is also the entire principle of the market steelyard: a small sliding weight can balance a pig, provided its arm is long enough."])]),t("don-va-canh-tay",["Đòn & Cánh Tay","Levers and Arms"],["Lực nhân với khoảng cách mới là thứ quyết định, không phải lực","It is force times distance that counts, not force alone"],[n("day-cua-gan-ban-le",1,"tp",["Một cánh cửa nặng. Lần thứ nhất bạn đẩy ở mép ngoài, xa bản lề nhất. Lần thứ hai đẩy ở chỗ chỉ cách bản lề một gang tay.","A heavy door. First you push at the outer edge, farthest from the hinge. Then you push a hand’s width from the hinge."],["Lần nào phải đẩy mạnh hơn?","Which push has to be harder?"],[["Lần đẩy sát bản lề","The one near the hinge"],["Lần đẩy ở mép ngoài","The one at the outer edge"],["Hai lần như nhau, vì cùng một cánh cửa","The same both times — it is one door"]],0,["Cái làm cánh cửa quay không phải lực mà là lực nhân với khoảng cách tới bản lề. Đẩy xa gấp mười thì chỉ cần một phần mười lực. Đó là lý do tay nắm cửa bao giờ cũng gắn ở mép xa nhất chứ không phải giữa cánh — và cũng là lý do một đứa trẻ đẩy được cánh cổng sắt mà người lớn đẩy sát bản lề thì không nhúc nhích. Không có thêm sức nào sinh ra cả; chỉ là cùng một sức đặt ở chỗ có lợi hơn.","What turns a door is not force but force multiplied by distance from the hinge. Push ten times further out and a tenth of the force does the job. It is why handles are fitted at the far edge and never in the middle — and why a child can swing an iron gate that an adult pushing near the hinge cannot shift. No extra strength appears; the same strength is simply placed where it counts for more."]),n("keo-cat-ton-can-dai",2,"te",["Cái kéo cắt giấy có lưỡi dài, cán ngắn. Cái kéo cắt tôn thì ngược hẳn: lưỡi ngắn cũn, cán dài ngoẵng.","Paper scissors have long blades and short handles. Tin snips are the reverse: stubby blades and very long handles."],["Vì sao kéo cắt tôn làm ngược lại?","Why are tin snips built the other way round?"],[["Để lưỡi ngắn thì cứng hơn, không bị cong","So the short blade is stiffer and will not bend"],["Để đổi quãng đường tay đi lấy lực ở lưỡi","To trade the distance the hand travels for force at the blade"],["Để cắt được đường dài hơn trong một nhát","So one cut can run further along the sheet"]],1,["Kéo là hai cái đòn bẩy chung một trục. Cán dài gấp năm lưỡi thì lực ở lưỡi lớn gấp năm lực tay bóp — cái giá phải trả là lưỡi chỉ ngậm được một đoạn rất ngắn mỗi nhát, nên cắt tôn phải nhấm từng tí một. Kéo cắt giấy đổi ngược: giấy mềm nên không cần lực, cái cần là cắt được một đường dài trong một nhát. Không cái nào tốt hơn cái nào — chúng đổi lực lấy quãng đường theo hai hướng ngược nhau, và tổng thì không ai được thêm gì.","A pair of scissors is two levers on one pivot. Handles five times the blade give five times the hand’s force at the cutting edge — paid for by biting only a short length each stroke, which is why cutting sheet metal goes nibble by nibble. Paper scissors trade the other way: paper needs no force, it needs a long cut in one closing. Neither design is better — they swap force for distance in opposite directions, and nobody gains overall."]),n("xe-cut-kit-xep-hang-o-dau",2,"tp",["Một xe cút kít, bánh ở đằng trước, hai tay cầm ở đằng sau. Cùng một bao xi măng, có thể đặt sát bánh xe hoặc đặt lùi về gần tay cầm.","A wheelbarrow: wheel at the front, handles at the back. The same bag of cement can sit right over the wheel or back near the handles."],["Đặt ở đâu thì nhấc nhẹ tay hơn?","Which position is lighter to lift?"],[["Sát bánh xe","Right over the wheel"],["Gần tay cầm","Near the handles"],["Ở đúng giữa hai đầu","Exactly halfway between"]],0,["Cái bánh xe là điểm tựa. Sức nặng đặt càng gần điểm tựa thì cánh tay đòn của nó càng ngắn, nên phần mà hai bàn tay phải gánh càng nhỏ. Đặt bao xi măng ngay trên trục bánh thì gần như toàn bộ sức nặng đi thẳng xuống bánh xe, tay chỉ còn giữ thăng bằng. Đây là mẹo mà thợ nào cũng làm theo bản năng, và nó cũng giải thích vì sao bê một thùng nước sát người thì nhẹ hơn hẳn bê xa người, dù thùng nước không nhẹ đi chút nào.","The wheel is the pivot. The nearer the load sits to the pivot, the shorter its arm, and the smaller the share the hands must carry. Placed directly over the axle, almost the entire weight goes down through the wheel and the hands are left merely steering. Every labourer does this by instinct, and it also explains why a bucket of water held close to the body is far lighter than the same bucket held out at arm’s length, though nothing about the water has changed."]),n("can-doi-tren-mat-trang",3,"tp",["Mang lên Mặt Trăng hai thứ: một cái cân đòn hai đĩa với bộ quả cân, và một cái cân lò xo. Cân cùng một túi gạo một cân.","Two instruments are carried to the Moon: a two-pan balance with its set of weights, and a spring scale. Both weigh the same one-kilo bag of rice."],["Cái nào vẫn đọc đúng một cân?","Which still reads one kilo?"],[["Cả hai đều đúng","Both of them"],["Chỉ cân đòn hai đĩa","Only the two-pan balance"],["Chỉ cân lò xo","Only the spring scale"]],1,["Chỗ bẻ luật: hai cái cân không đo cùng một thứ. Cân lò xo đo lực kéo xuống, mà trên Mặt Trăng lực ấy chỉ còn một phần sáu — nên nó đọc ra 0,17 cân. Cân đòn thì so túi gạo với quả cân, và cả hai bên cùng nhẹ đi một phần sáu, nên đòn vẫn thăng bằng ở đúng vạch một cân. Cân đòn đo khối lượng, cân lò xo đo trọng lượng, và ở Trái Đất hai con số ấy trùng nhau nên gần như không ai để ý — cho tới lúc đem cái cân đi chỗ khác.","Here the rule bends: the two instruments do not measure the same quantity. The spring scale measures downward pull, and on the Moon that pull is a sixth — so it reads 0.17. The balance compares the rice against brass weights, and both sides lighten by the same sixth, so the beam still levels at one kilo. A balance measures mass, a spring scale measures weight, and on Earth the two numbers coincide so closely that almost nobody notices — until the instrument is taken somewhere else."]),n("co-le-can-dai-mo-oc",2,"te",["Một con ốc siết chặt không mở nổi bằng cờ lê ngắn. Người thợ lồng một đoạn ống sắt vào cán cờ lê cho nó dài gấp ba, rồi mở ra dễ dàng.","A seized nut will not shift with a short spanner. The mechanic slips a length of pipe over the handle to treble its length, and it comes loose easily."],["Vì sao đoạn ống ấy có tác dụng?","Why does the pipe work?"],[["Vì ống sắt cứng hơn cán cờ lê","Because the pipe is stiffer than the spanner"],["Vì cánh tay đòn dài gấp ba thì lực xoắn lớn gấp ba","Because three times the arm gives three times the twist"],["Vì tay cầm xa thì bóp được chặt hơn","Because a distant grip can be squeezed harder"]],1,["Cái làm con ốc quay là lực nhân với khoảng cách tới tâm ốc. Nối dài cán gấp ba thì cùng một sức tay sinh ra lực xoắn gấp ba. Không có gì thần kỳ, và cũng không miễn phí: tay phải đi một quãng dài gấp ba để con ốc quay được từng ấy. Đây cũng là chỗ nguy hiểm quen thuộc trong xưởng — lực xoắn tăng gấp ba thì con ốc có thể đứt trước khi nó chịu quay, và lúc ấy cả người lẫn ống sắt cùng ngã.","What turns a nut is force multiplied by distance from its centre. Treble the handle and the same arm produces three times the twist. Nothing miraculous, and nothing free: the hand must now travel three times as far for the same turn of the nut. It is also a familiar workshop hazard — treble the twist and the bolt may shear before it yields, at which point the mechanic and the pipe go over together."])]),t("quay-va-giu",["Quay & Giữ","Spin and Steadiness"],["Một vật đang quay chống lại mọi cố gắng làm đổi trục quay của nó","A spinning thing resists every attempt to tilt the axis it spins about"],[n("banh-da-coi-xay",1,"te",["Cái cối xay tay có một bánh đá rất nặng. Quay khởi động thì ì ạch, nhưng khi đã quay đều thì nó tự chạy tiếp một lúc lâu dù buông tay.","A hand mill has a very heavy stone wheel. Starting it is a struggle, but once it turns steadily it keeps going a good while after the hand lets go."],["Bánh đá nặng để làm gì?","What is the heavy stone for?"],[["Để nghiền được hạt cứng hơn nhờ sức nặng","To crush harder grain by sheer weight"],["Để giữ cho vòng quay đều, không giật cục theo tay người","To hold the turning steady instead of jerking with the hand"],["Để cối không bị trượt trên bàn","To stop the mill sliding on the table"]],1,["Bánh nặng khó làm quay và cũng khó làm dừng — cả hai mặt của cùng một tính chất. Tay người kéo từng nhịp mạnh yếu không đều, nhưng bánh đá nuốt hết chỗ chênh ấy và trả ra một vòng quay đều. Mọi cỗ máy có nhịp giật đều lắp một bánh như thế: đầu máy hơi nước, động cơ nổ, bàn xoay gốm. Nó không sinh thêm năng lượng nào — nó chỉ giữ năng lượng lại trong lúc dư và nhả ra trong lúc thiếu.","A heavy wheel is hard to start and equally hard to stop — two faces of one property. A human arm pulls in uneven surges, but the stone swallows the unevenness and gives back a smooth rotation. Every machine with a lumpy rhythm carries one: the steam engine, the petrol engine, the potter’s wheel. It creates no energy — it stores what arrives in surplus and returns it during the lean part of the cycle."]),n("xe-dap-dang-chay-khong-do",2,"tp",["Xe đạp dựng đứng một chỗ thì đổ ngay. Cũng chiếc xe ấy đang chạy thì đứng vững, thậm chí buông tay lái vẫn đi thẳng được một quãng.","A bicycle stood still falls over at once. The same bicycle rolling stays upright, and will run straight for a while even with no hands on the bars."],["Cái gì giữ nó đứng?","What holds it up?"],[["Chỉ nhờ hai bánh quay nên có tính giữ trục","Only the spinning wheels holding their axis"],["Chủ yếu nhờ bánh trước tự lái vào phía xe đang nghiêng","Mostly the front wheel steering itself into the lean"],["Nhờ gió thổi từ phía trước đỡ lấy xe","The oncoming wind propping the bicycle up"]],1,["Cái quay của hai bánh có góp phần, nhưng ít hơn người ta tưởng nhiều: người ta đã làm hẳn một chiếc xe có bánh quay ngược để triệt tiêu hiệu ứng ấy, và nó vẫn đứng được. Cái chính là hình học của bánh lái: xe nghiêng sang trái thì bánh trước tự quay sang trái, đưa điểm tựa chạy vào dưới trọng tâm — đúng như bưng một cây gậy dựng đứng trên lòng bàn tay, mình đưa tay chạy theo chứ không giữ cứng. Xe đạp là một vật luôn sắp đổ và luôn tự cứu mình.","The spin of the wheels contributes, but far less than people assume: a bicycle has been built with counter-rotating wheels to cancel that effect, and it still balances. The main thing is the steering geometry: lean left and the front wheel turns left on its own, running the support point back under the weight — exactly as when balancing a stick on your palm, where you move the hand rather than hold it rigid. A bicycle is a thing perpetually falling and perpetually catching itself."]),n("con-quay-khong-do",2,"tp",["Con quay gỗ đứng yên thì đổ ngay lập tức. Vẫn con quay ấy, quay tít thì đứng trên một mũi nhọn hàng phút, thậm chí đứng nghiêng mà không đổ.","A wooden top will not stand still for an instant. Spinning fast, the same top stands on its point for minutes, and stays up even when tilted."],["Quay nhanh cho nó thêm cái gì?","What does spinning give it?"],[["Thêm sức nâng đẩy nó lên khỏi mặt đất","A lift that pushes it up off the ground"],["Sức chống lại mọi thay đổi hướng của trục quay","Resistance to any change in the direction of its axis"],["Bớt trọng lượng nhờ chuyển động","Less weight, thanks to the motion"]],1,["Trọng lực vẫn kéo con quay đúng như cũ, và trục nó vẫn nghiêng. Cái khác là một vật đang quay không chịu đổi hướng trục ngay: đẩy nó ngã sang một bên thì nó không ngã bên ấy mà xoay chậm sang một bên khác — cái vòng lượn chậm ta thấy ở chóp con quay. Nhờ vậy nó cứ vòng vòng mãi thay vì đổ. Đây cũng là thứ giữ hướng cho một quả bóng bầu dục xoáy, cho một viên đạn có rãnh nòng, và cho la bàn con quay trên tàu biển.","Gravity pulls the top exactly as before, and its axis is genuinely tilted. The difference is that a spinning body will not change the direction of its axis promptly: push it to fall one way and instead of falling it swings slowly to another — the lazy circling you see at the tip. So it circles on instead of toppling. The same property keeps a spiralling rugby ball pointed, steadies a rifled bullet, and holds a ship’s gyrocompass on course."]),n("nguoi-truot-bang-co-tay",3,"tp",["Vận động viên trượt băng đang xoay tại chỗ với hai tay dang rộng. Cô ấy thu hai tay ép sát vào người. Không ai đẩy thêm, mặt băng gần như không có ma sát.","A skater is spinning on the spot with both arms outstretched. She pulls her arms tight against her body. Nobody pushes, and the ice is nearly frictionless."],["Chuyện gì xảy ra với tốc độ xoay?","What happens to the spin?"],[["Chậm lại, vì thu tay là mất đà","It slows, because pulling in loses momentum"],["Nhanh vọt lên","It speeds up sharply"],["Không đổi, vì không ai đẩy thêm","It stays the same, since nobody pushed"]],1,["Đây là chỗ bẻ luật, và nó làm ai cũng ngờ ngợ vì trông như có gì đó tự sinh ra. Thứ được bảo toàn khi không ai đẩy không phải tốc độ xoay mà là tích của tốc độ ấy với mức khối lượng nằm xa trục. Thu tay vào là kéo khối lượng lại gần trục, nên để tích ấy không đổi thì tốc độ phải tăng lên. Sức để làm chuyện đó đến từ chính cơ tay kéo vào — cô ấy phải kéo ngược lại một lực rất mạnh, và đúng phần công ấy biến thành vòng xoay nhanh hơn.","This is where the rule bends, and it looks suspiciously like something appearing from nothing. What is conserved when nobody pushes is not the rate of spin but that rate multiplied by how far the mass sits from the axis. Pulling the arms in brings mass close to the axis, so to keep the product fixed the rate must rise. The energy comes from her own arms — she has to haul inwards against a real force, and precisely that work becomes the faster spin."]),n("nghieng-banh-xe-dang-quay",3,"tp",["Ngồi trên ghế xoay, hai tay cầm trục một bánh xe đạp đang quay tít, trục nằm ngang. Bạn nghiêng trục bánh xe cho nó dựng đứng lên.","Sitting on a swivel chair, you hold the axle of a fast-spinning bicycle wheel horizontally in both hands. You tilt that axle up to vertical."],["Chuyện gì xảy ra với chiếc ghế?","What happens to the chair?"],[["Không có gì, bánh xe không chạm vào ghế","Nothing — the wheel never touches the chair"],["Ghế bắt đầu tự xoay theo chiều ngược lại","The chair begins to turn, the opposite way"],["Ghế bị đẩy lùi ra sau một đoạn","The chair is shoved backwards"]],1,["Chiếc ghế tự xoay, và nó xoay ngay lúc tay mình nghiêng bánh xe chứ không sớm hơn. Cái quay của một hệ kín thì không tự mất đi cũng không tự sinh ra: bánh xe vừa đổi hướng quay của nó, nên phần còn lại của hệ — người và ghế — phải quay ngược lại đúng chừng ấy để tổng giữ nguyên. Đây là thí nghiệm lớp học nổi tiếng nhất về chuyện ấy, và cũng chính là cách một con mèo rơi ngửa tự lật lại được giữa không trung mà không cần bám vào cái gì.","The chair turns, and it turns at the moment your hands tilt the wheel, not before. The spin of a closed system neither vanishes nor appears: the wheel has changed the direction of its own turning, so the rest of the system — you and the chair — must turn oppositely by just as much to keep the total unchanged. It is the most famous classroom demonstration of the point, and it is also how a cat dropped upside down rights itself in mid-air with nothing to push against."])])],x=[t("ap-suat-khi",["Áp Suất Khí","The Weight of Air"],["Không khí không phải chỗ trống — nó là một chất nặng đè lên mọi thứ","Air is not emptiness — it is a heavy substance pressing on everything"],[n("to-giay-che-coc-nuoc",1,"tp",["Đổ đầy nước vào một cái cốc, đậy miệng cốc bằng một tờ giấy phẳng, giữ tờ giấy rồi lật úp cốc xuống. Buông tay ra: nước không đổ, tờ giấy vẫn dính ở miệng cốc.","Fill a glass to the brim, lay a flat card over the mouth, hold it and turn the glass upside down. Let go: the water stays and the card stays with it."],["Cái gì đang đỡ cột nước ấy?","What is holding that column of water up?"],[["Tờ giấy dính vào miệng cốc nhờ nước","The card sticking to the rim because it is wet"],["Không khí bên dưới đẩy tờ giấy lên","The air underneath pushing the card up"],["Nước nhẹ đi khi cốc bị lật ngược","The water weighing less once the glass is inverted"]],1,["Không khí đẩy lên tờ giấy với một lực rất lớn: khoảng một kilôgam trên mỗi centimét vuông. Một cái cốc miệng rộng chừng năm centimét thì lực đẩy lên ấy đủ đỡ tới hơn mười kilôgam nước, trong khi cốc nước chỉ nặng vài trăm gam. Nên chuyện lạ không phải là nước không đổ; chuyện lạ là bình thường ta không hề thấy cái lực khổng lồ ấy, vì nó đẩy đều từ mọi phía nên triệt tiêu nhau.","Air pushes up on the card hard: about a kilogram on every square centimetre. A glass five centimetres across is therefore held by enough force to support more than ten kilograms of water, while the glassful weighs a few hundred grams. So the surprise is not that the water stays; the surprise is that we never notice this enormous force, because it presses equally from every side and cancels itself out."]),n("hut-bang-ong-mut",2,"tp",["Cắm ống hút vào cốc nước rồi hút. Nước đi lên miệng mình.","Put a straw in a glass of water and suck. The water comes up to your mouth."],["Cái gì thực sự đưa nước lên?","What actually lifts the water?"],[["Miệng mình kéo nước lên bằng lực hút","My mouth pulls the water up with suction"],["Không khí bên ngoài đè xuống mặt nước và đẩy nó vào ống","The outside air presses on the surface and shoves it into the straw"],["Nước tự dâng lên vì trong ống trống rỗng","The water rises by itself because the straw is empty"]],1,["Không có cái gọi là lực hút cả. Hút chỉ là lấy bớt không khí trong ống ra, làm áp suất trong ống thấp đi. Lúc ấy không khí bên ngoài — vẫn đè lên mặt nước trong cốc như nó vẫn đè — đẩy nước vào chỗ áp suất thấp hơn, tức là lên trong ống. Nếu đem cả cốc lẫn ống vào một cái chuông đã rút hết khí thì hút cách gì nước cũng không lên, và đó là cách kiểm tra rằng lời giải này đúng.","There is no such thing as suck. Sucking merely removes some air from the straw, lowering the pressure inside it. The outside air — still pressing on the surface of the drink exactly as before — then shoves water towards the lower pressure, which is up the straw. Put glass and straw inside a jar with the air pumped out and no amount of sucking will raise a drop, which is how you check the explanation."]),n("goi-bim-bim-len-nui",2,"te",["Một gói bim bim mua dưới đồng bằng, mang lên đèo cao hai nghìn mét. Gói phồng căng lên như sắp nổ, dù không ai bơm thêm gì vào.","A sealed bag of crisps bought in the lowlands is carried to a two-thousand-metre pass. The bag swells tight as a drum, though nobody added anything."],["Vì sao nó phồng?","Why does it swell?"],[["Vì trên cao lạnh hơn nên khí trong gói nở ra","Because the cold up there expands the gas inside"],["Vì không khí bên ngoài loãng đi, đè vào gói nhẹ hơn","Because the thinner outside air presses on the bag less"],["Vì gói bị xóc trên đường nên khí bên trong giãn","Because the bumpy road stretched the packet"]],1,["Cái gói vốn đứng yên vì hai áp suất cân nhau: khí bên trong đẩy ra, khí quyển bên ngoài đè vào. Lên cao thì phía trên đầu còn ít không khí hơn, nên áp suất ngoài giảm — mà khí bên trong thì không đổi, vẫn đẩy ra như cũ. Cân bằng vỡ, và gói phồng cho tới khi màng gói căng ra đủ để bù phần chênh. Cũng chính vì thế mà tai ù lúc lên đèo, và cũng vì thế mà máy bay phải nén khí vào khoang chứ không bay với khí trời bên ngoài.","The bag was flat because two pressures balanced: gas inside pushing out, atmosphere outside pushing in. Higher up there is less air overhead, so the outside pressure drops — while the gas inside is unchanged and pushes just as hard. The balance breaks, and the bag expands until the stretched film makes up the difference. It is also why ears pop on a mountain road, and why aircraft pump their cabins full rather than flying with the air outside."]),n("bom-hut-khong-qua-muoi-met",3,"tp",["Một cái bơm hút đặt trên miệng giếng, hút nước lên bằng ống. Giếng sâu 8 mét thì bơm chạy tốt. Giếng sâu 12 mét thì dù bơm khoẻ đến đâu, nước cũng không lên nổi.","A suction pump at the top of a well draws water up a pipe. From eight metres it works well. From twelve metres no pump, however powerful, brings water up at all."],["Vì sao có một mức trần như thế?","Why is there a ceiling like that?"],[["Vì ống quá dài thì ma sát trong ống thắng hết","Because friction in a long pipe overwhelms everything"],["Vì khí quyển chỉ đẩy nổi một cột nước cao chừng 10 mét","Because the atmosphere can only hold up about ten metres of water"],["Vì nước dưới sâu nặng hơn nước ở gần mặt","Because deep water is heavier than water near the surface"]],1,["Chỗ bẻ luật nằm ở đây: cái bơm không kéo nước, nó chỉ lấy khí ra khỏi ống. Việc đẩy nước lên là của khí quyển, và khí quyển thì chỉ đè được với một áp suất nhất định — vừa đúng bằng sức nặng của một cột nước cao khoảng mười mét. Bơm khoẻ hơn không giúp gì, vì trần ấy không phải trần của cái bơm mà là trần của bầu trời. Muốn lấy nước sâu hơn thì phải thả bơm xuống dưới mà ĐẨY nước lên, chứ đứng trên hút thì không bao giờ được — và mọi máy bơm giếng sâu đều làm đúng thế.","Here the rule bends: the pump does not lift water, it only removes air from the pipe. The lifting is done by the atmosphere, and the atmosphere presses with a fixed pressure — worth about ten metres of water and no more. A stronger pump changes nothing, because the ceiling belongs not to the pump but to the sky. To draw from deeper you must lower the pump and push the water up, never stand on top and pull — which is precisely what every deep-well pump does."]),n("hai-nua-qua-cau-hut-nhau",2,"tp",["Hai nửa vỏ cầu bằng đồng úp khít vào nhau, không keo, không chốt. Người ta rút hết không khí bên trong ra. Sau đó buộc mỗi bên vào một đàn ngựa kéo ngược nhau mà không tách nổi.","Two copper hemispheres are pressed together with no glue and no catch. The air inside is pumped out. Teams of horses harnessed to each side then pull in opposite directions and cannot part them."],["Cái gì giữ hai nửa lại với nhau?","What holds the halves together?"],[["Chỗ trống bên trong hút hai nửa vào nhau","The emptiness inside sucking the halves together"],["Không khí bên ngoài ép vào từ mọi phía","The outside air squeezing in from every direction"],["Đồng nhẵn quá nên hai mặt dính chặt","Copper so smooth that the two faces stick"]],1,["Bên trong không có gì để hút cả — chỗ trống không kéo được ai. Toàn bộ lực là của không khí bên ngoài: bình thường nó ép vào từ ngoài và khí bên trong đẩy ra cân lại, nên quả cầu rời ra dễ dàng. Rút khí bên trong đi thì mất hẳn phần đẩy ra, còn phần ép vào vẫn nguyên. Với quả cầu đường kính nửa mét thì phần chênh ấy lên tới gần hai tấn. Đây là thí nghiệm Magdeburg năm 1654, và nó được làm ra chính để cho người ta thấy không khí nặng.","There is nothing inside to suck — emptiness pulls on nobody. The entire force belongs to the outside air: ordinarily it squeezes inwards while the air within pushes out and cancels it, so the sphere falls apart easily. Pump the inside out and the outward push is gone while the inward squeeze remains. On a sphere half a metre across the difference approaches two tonnes. This is the Magdeburg experiment of 1654, staged for exactly this purpose: to make people see that air is heavy."])]),t("noi-trong-khong-khi",["Nổi Trong Không Khí","Floating in Air"],["Không khí đẩy nổi mọi thứ, y như nước — chỉ là đẩy nhẹ hơn nhiều","Air buoys everything up just as water does, only far more gently"],[n("bong-heli-bay-len",1,"tp",["Quả bóng bay bơm heli thả tay ra thì bay lên. Quả bóng bơm bằng hơi thổi ra từ miệng thì rơi xuống. Vỏ bóng giống hệt nhau.","A balloon filled with helium rises when released. The same balloon filled by mouth falls. The rubber is identical."],["Vì sao quả heli bay lên?","Why does the helium one rise?"],[["Vì heli không có trọng lượng","Because helium has no weight"],["Vì cả quả bóng nhẹ hơn khối không khí mà nó chiếm chỗ","Because the whole balloon weighs less than the air it displaces"],["Vì heli nóng hơn không khí trong phòng","Because helium is hotter than the room"]],1,["Heli có trọng lượng, chỉ là ít. Quy tắc y hệt như một khúc gỗ trong nước: vật nào nhẹ hơn phần chất lỏng hay chất khí mà nó chiếm chỗ thì nổi lên. Quả bóng heli chiếm chỗ chừng ấy không khí, mà cả quả — vỏ cộng khí bên trong — lại nhẹ hơn khối không khí ấy, nên phần chênh đẩy nó lên. Thổi bằng miệng thì khí bên trong nặng hơn không khí ngoài một chút, cộng với vỏ cao su nữa, thành ra nặng hơn — và nó rơi.","Helium weighs something, just very little. The rule is the same as a log in water: whatever weighs less than the fluid it displaces goes up. The helium balloon displaces a balloon-sized parcel of air, and the whole thing — skin plus contents — weighs less than that parcel, so the difference lifts it. Blown by mouth, the gas inside is slightly heavier than outside air, and with the rubber added the total is heavier still — so it falls."]),n("khinh-khi-cau-dot-lua",2,"te",["Khinh khí cầu không bơm heli. Nó chỉ có một cái đầu đốt hâm nóng chính không khí bên trong quả cầu, và thế là bay lên.","A hot-air balloon holds no helium. It simply has a burner heating ordinary air inside the envelope, and up it goes."],["Đốt lửa làm gì cho quả cầu?","What does the burner accomplish?"],[["Đẩy thêm không khí vào trong cho quả cầu căng","Forces extra air in so the envelope stiffens"],["Làm khí trong quả cầu loãng ra, nên cả quả nhẹ hơn","Thins the air inside, so the whole thing weighs less"],["Tạo luồng khói bốc lên kéo quả cầu theo","Makes a rising smoke column that drags the balloon up"]],1,["Nung nóng thì không khí nở ra, và vì quả cầu hở đáy nên phần nở ra thoát bớt ra ngoài. Cùng một thể tích ấy giờ chứa ít khí hơn, nên nhẹ hơn khối không khí lạnh mà nó chiếm chỗ — thế là nổi lên, đúng một luật với quả bóng heli. Nên toàn bộ việc lái một khinh khí cầu chỉ là đốt thêm để lên và để nguội để xuống. Cũng chính cái luật ấy làm khói bếp bay lên và làm gió biển thổi vào bờ lúc trưa nắng.","Heating makes air expand, and because the envelope is open at the bottom the surplus escapes. The same volume now holds less gas and so weighs less than the cool parcel of air it displaces — and up it goes, by the same law as the helium balloon. Flying one is therefore nothing but burning to rise and cooling to descend. The same law lifts kitchen smoke and pulls the sea breeze ashore on a hot afternoon."]),n("can-qua-bong-bom-cang",3,"tp",["Đặt một quả bóng đá xẹp lên cân, ghi số. Bơm thật căng rồi cân lại. Cân thường trong phòng, không khí bình thường.","Weigh a deflated football on a scale and note the reading. Pump it hard and weigh it again. An ordinary scale, in ordinary room air."],["Số trên cân thay đổi thế nào?","How does the reading change?"],[["Nặng lên, vì khí nén vào có khối lượng","Heavier, because the compressed air has mass"],["Không đổi, vì không khí thì không nặng","Unchanged, since air weighs nothing"],["Nhẹ đi, vì quả bóng căng thì nổi hơn","Lighter, because an inflated ball is more buoyant"]],0,["Quả bóng nặng lên thật, dù chỉ vài gam — đủ để một cái cân nhà bếp tốt đọc ra. Chỗ bẻ luật là ở quả bóng bay: quả bóng bay bơm hơi thường thì gần như không đổi cân nặng, vì vỏ nó nở ra nên khí bên trong không bị nén, và phần khí thêm vào gần như bằng đúng phần không khí bị nó đẩy ra chỗ khác. Quả bóng đá thì vỏ cứng, thể tích không đổi mà khí bên trong bị nhồi gấp mấy lần — nên phần khí thừa ấy hiện lên cân. Nén khí là chuyện cân đo được.","The ball does get heavier, by a few grams — enough for a good kitchen scale. Where the rule bends is the party balloon: inflating one barely changes its weight, because the skin stretches so the air inside is not compressed, and the added gas is almost exactly balanced by the air it shoves out of the way. A football has a rigid shell, so its volume is fixed while several times as much air is crammed in — and that surplus shows on the scale. Compressed air is a weighable thing."]),n("khoi-bay-len-roi-di-ngang",2,"te",["Khói từ một điếu thuốc hay một nén hương bay thẳng lên một đoạn, rồi tới một độ cao nào đó thì tản ra và đi ngang.","Smoke from a cigarette or an incense stick rises straight for a stretch, then at some height spreads out and drifts sideways."],["Vì sao nó không bay lên mãi?","Why does it not keep rising?"],[["Vì khói nguội đi cho tới lúc nặng bằng không khí quanh nó","Because it cools until it weighs the same as the air around it"],["Vì trần nhà chặn nó lại","Because the ceiling stops it"],["Vì khói hết đà sau khi bay được một đoạn","Because the smoke runs out of momentum"]],0,["Khói bay lên vì nó nóng, tức là loãng hơn không khí quanh nó. Càng lên nó càng trộn với khí lạnh và nguội đi, tới lúc mật độ hai bên bằng nhau thì không còn gì đẩy nó lên nữa và nó nằm lại đúng ở đó. Cũng chính vì thế mà mây có đáy phẳng như bị cắt, và khói nhà máy trong ngày lặng gió lại trải thành một tấm thảm ngang lơ lửng thay vì tan lên trời.","Smoke rises because it is hot, which is to say thinner than the air around it. As it climbs it mixes with cooler air and cools, and once the two densities match there is nothing left to lift it and it settles at that level. It is also why clouds have flat bottoms as though sliced, and why factory smoke on a still day spreads into a horizontal sheet instead of dispersing upwards."]),n("bong-len-cao-thi-sao",2,"tp",["Thả một quả bóng heli ngoài trời. Nó bay lên mãi. Nhiều người tưởng nó bay ra ngoài vũ trụ.","A helium balloon is let go outdoors and climbs and climbs. Many people imagine it leaves for space."],["Chuyện gì thực sự xảy ra với nó?","What really becomes of it?"],[["Nó bay ra khỏi khí quyển rồi trôi trong vũ trụ","It leaves the atmosphere and drifts off into space"],["Nó nở ra vì khí quyển loãng dần, tới một độ cao thì nổ","It swells as the air thins, and at some height it bursts"],["Nó dừng lại ở một độ cao rồi lơ lửng ở đó mãi","It halts at one height and hovers there forever"]],1,["Càng lên cao khí quyển càng loãng, tức là ép vào quả bóng càng ít, nên vỏ cao su cứ nở dần ra. Tới quãng ba mươi cây số thì nó đã to gấp nhiều lần lúc thả và cao su không chịu nổi nữa, thế là nổ, rồi mảnh vụn rơi xuống. Bóng thời tiết chính là loại bóng làm ra để đi hết hành trình ấy: người ta bơm non lúc thả để chừa chỗ cho nó nở, và biết trước nó sẽ vỡ ở đâu.","The higher it goes the thinner the atmosphere, so the less it squeezes the balloon, and the rubber steadily expands. By around thirty kilometres it is many times its launch size and the skin gives way; it bursts and the shreds fall back. Weather balloons are made for exactly that journey: they are launched deliberately slack to leave room for the swelling, and the burst height is known in advance."])]),t("gio-va-canh",["Gió & Cánh","Wind and Wings"],["Chỗ nào khí chạy nhanh thì chỗ ấy ép ra hai bên yếu đi","Where air runs fast, its sideways push grows weaker"],[n("thoi-tren-to-giay",1,"tp",["Cầm mép một tờ giấy mỏng cho nó rủ xuống. Thổi mạnh dọc theo MẶT TRÊN của tờ giấy.","Hold one edge of a thin sheet of paper so it droops. Blow hard along the TOP surface of it."],["Tờ giấy làm gì?","What does the paper do?"],[["Bị thổi rạp xuống thấp hơn","Is blown further down"],["Nâng lên phía luồng khí đang thổi","Lifts up towards the moving air"],["Không nhúc nhích, vì thổi bên trên thì không chạm vào nó","Does nothing — the blowing never touches it"]],1,["Tờ giấy nâng lên, và điều đó làm ai lần đầu cũng ngạc nhiên. Luồng khí chạy nhanh ở mặt trên ép xuống yếu hơn khối khí đứng yên ở mặt dưới, nên phần chênh đẩy tờ giấy lên. Đây là mẹo đơn giản nhất cho thấy một điều rất lớn: áp suất của một chất khí không phải một con số cố định, nó phụ thuộc vào chất khí ấy đang chạy nhanh hay đứng yên.","The paper lifts, which surprises everybody the first time. The fast stream over the top presses down less firmly than the still air below, so the difference pushes the sheet up. It is the simplest demonstration of a very large idea: the pressure of a gas is not a fixed number, it depends on whether that gas is racing or standing still."]),n("mai-ton-bay-trong-bao",2,"te",["Bão thổi qua một ngôi nhà mái tôn. Mái bị bốc lên và văng đi. Nhiều người nghĩ gió đã đập vào mái và hất nó lên.","A storm passes over a house with a sheet-metal roof. The roof is lifted off and flung away. Most people picture the wind striking the roof and knocking it up."],["Cái gì thực sự bốc mái lên?","What really lifts the roof?"],[["Gió luồn xuống dưới mái rồi nâng lên","Wind getting under the roof and lifting"],["Khí chạy nhanh trên mái làm áp suất phía trên tụt xuống","Fast air over the roof dropping the pressure above it"],["Mưa làm mái nặng lên rồi bật ra khỏi đinh","Rain weighing the roof down until the nails give"]],1,["Gió phải vượt qua mái nên nó chạy nhanh nhất ngay trên mặt mái, và chỗ khí chạy nhanh thì ép xuống yếu đi. Trong khi đó không khí trong nhà vẫn đứng yên và vẫn ép lên như cũ. Phần chênh ấy trải trên cả trăm mét vuông mái thì thành nhiều tấn, đủ để bốc cả mái. Chính vì thế người ta khuyên mở hé cửa phía khuất gió cho áp suất trong nhà giảm theo, và cũng chính vì thế mà mái bay lên chứ không bị đè bẹp xuống.","The wind must climb over the roof, so it runs fastest right at the surface, and fast-moving air presses down less. Meanwhile the air inside the house is still and presses up exactly as before. Spread over a hundred square metres that difference amounts to tonnes, enough to lift the whole roof. It is why people are told to crack a window on the sheltered side to let the inside pressure fall too, and why roofs are lifted off rather than crushed in."]),n("canh-may-bay-hinh-cong",2,"te",["Cánh máy bay có mặt trên cong hơn mặt dưới, và khi bay thì nó hơi ngóc lên so với luồng gió tới.","An aircraft wing is more curved on top than beneath, and in flight it is tilted slightly nose-up into the oncoming air."],["Cánh nâng máy bay lên bằng cách nào?","How does the wing hold the aircraft up?"],[["Cánh hất luồng khí xuống dưới, và khí đẩy cánh lên lại","It throws the airflow downwards, and the air pushes the wing up"],["Cánh nhẹ hơn không khí nên nó tự nổi","The wing is lighter than air and floats"],["Động cơ thổi khí thẳng xuống dưới cánh","The engines blow air straight down under the wing"]],0,["Cách nói gọn nhất và không sai: cánh lái cả một dòng khí lớn chếch xuống dưới, và theo đúng luật cứ đẩy ai thì bị đẩy lại, dòng khí ấy đẩy cánh lên. Chuyện mặt trên cong làm khí chạy nhanh hơn và áp suất giảm cũng đúng, và hai cách kể ấy là hai mặt của cùng một việc chứ không phải hai nguyên nhân khác nhau. Một chiếc Boeing hất xuống chừng vài tấn không khí mỗi giây, và đúng chừng ấy là thứ giữ nó trên trời.","The shortest true account: the wing steers a great river of air downwards, and by the law that every push is answered, that air pushes the wing up. It is equally true that the curved upper surface speeds the flow and lowers the pressure there, and the two accounts are two faces of one event rather than two separate causes. A large airliner throws several tonnes of air downwards every second, and that is exactly what keeps it up."]),n("thoi-vao-giua-hai-to-giay",3,"tp",["Treo hai tờ giấy mỏng song song, cách nhau chừng ba centimét. Thổi thật mạnh vào đúng khe hở giữa hai tờ.","Hang two thin sheets of paper parallel, about three centimetres apart. Blow hard straight into the gap between them."],["Hai tờ giấy làm gì?","What do the sheets do?"],[["Bị thổi bạt ra xa nhau","They are blown apart"],["Bị hút lại sát vào nhau","They are drawn together"],["Đứng yên, vì luồng khí đi thẳng qua khe","They stay put, since the stream goes straight through"]],1,["Ai cũng đoán chúng bạt ra, và chúng lại dính vào nhau. Luồng khí chạy nhanh trong khe ép ra hai bên yếu hơn khối khí đứng yên ở mặt ngoài, nên phần chênh ép hai tờ giấy lại. Chỗ bẻ luật nằm đúng ở đây: cái thổi vào không phải một cái đẩy ra, vì thứ quyết định là khí chạy nhanh hay đứng yên chứ không phải nó đang đi về phía nào. Cùng hiện tượng ấy làm hai con thuyền chạy song song bị hút vào nhau, và làm cánh cửa sập lại khi mở cửa sổ đối diện.","Everybody expects them to be blown apart, and they close instead. The fast stream in the gap presses outwards less firmly than the still air on the outside faces, and the difference squeezes the sheets together. Here the rule bends: blowing into a gap is not the same as pushing it open, because what counts is whether air is moving fast or standing still, not which way it happens to be heading. The same effect draws two boats running side by side together, and slams a door when the opposite window opens."]),n("qua-bong-xoay-di-cong",3,"tp",["Cầu thủ sút quả bóng có xoáy mạnh. Quả bóng bay theo một đường cong hẳn sang một bên, dù không có gió.","A footballer strikes a ball with heavy spin. The ball curves markedly to one side, on a windless day."],["Cái gì bẻ cong đường bay?","What bends the flight?"],[["Vì quả bóng xoáy nên nó nhẹ hơn ở một bên","Spinning makes the ball lighter on one side"],["Vỏ bóng kéo không khí quay theo, làm một bên khí chạy nhanh hơn bên kia","The skin drags air round with it, so one side flows faster than the other"],["Đường khâu trên quả bóng lái nó như bánh lái","The stitching steers it like a rudder"]],1,["Mặt quả bóng nhám, nên lúc xoáy nó lôi một lớp không khí quay theo. Ở một bên, lớp khí bị lôi đi cùng chiều với luồng gió tới nên tổng lại chạy nhanh hơn; bên kia thì ngược chiều nên chậm lại. Bên chạy nhanh ép yếu hơn, bên chạy chậm ép mạnh hơn, và phần chênh đẩy quả bóng cong sang một phía suốt đường bay. Chỗ bẻ luật là ở đây: nếu quả bóng thật sự nhẵn tuyệt đối thì nó không lôi được lớp khí nào, và cú sút xoáy sẽ không cong chút nào.","The surface is slightly rough, so as it spins it drags a layer of air round with it. On one side that dragged layer runs with the oncoming stream and the total is faster; on the other it runs against it and slows. The fast side presses less, the slow side more, and the difference pushes the ball sideways all the way to goal. Here the rule bends: a perfectly smooth ball would drag no layer at all, and the same spin would bend nothing."])])],q=[t("day-thi-bi-day",["Đẩy Thì Bị Đẩy","Push and Be Pushed"],["Không ai đẩy được cái gì mà không bị chính cái ấy đẩy lại","Nothing can be pushed without pushing back just as hard"],[n("nhay-tu-thuyen-len-bo",1,"tp",["Một chiếc thuyền nan nhỏ đậu sát bờ, không buộc dây. Bạn đứng ở mũi thuyền và nhảy mạnh lên bờ.","A light boat lies against the bank, untied. You stand at the bow and jump hard for the shore."],["Chuyện gì xảy ra với chiếc thuyền?","What happens to the boat?"],[["Nó bị đẩy lùi ra xa bờ","It is shoved back away from the bank"],["Nó đứng yên vì nó nặng hơn người","It stays put, being heavier than the jumper"],["Nó bị kéo theo về phía bờ","It is dragged along towards the bank"]],0,["Muốn nhảy lên bờ thì chân phải đạp vào thuyền, và cái đạp ấy đẩy thuyền ra sau đúng bằng lực nó đẩy mình tới trước. Thuyền nhẹ nên nó lùi nhanh, và người nhảy hụt là chuyện thường gặp. Không có cách nào tránh: mọi lực đều đi thành cặp, và không ai tự đẩy mình đi được nếu không có cái gì đó để đẩy vào. Đó cũng là lý do một người đứng trên mặt băng nhẵn hoàn toàn thì không tài nào tự đi được, trừ khi ném đi một thứ gì đó.","To jump ashore your feet must shove the boat, and that shove drives the boat backwards exactly as hard as it drives you forwards. The boat is light, so it goes quickly, and falling short is a common result. There is no avoiding it: forces come in pairs, and nobody moves themselves without something to push against. It is also why a person on perfectly smooth ice cannot get anywhere at all, unless they throw something away."]),n("sung-giat-vai",2,"tp",["Một khẩu súng nặng 4 kilôgam bắn ra viên đạn nặng 10 gam. Viên đạn lao đi rất nhanh; khẩu súng giật vào vai người bắn.","A rifle weighing 4 kilograms fires a 10-gram bullet. The bullet leaves very fast; the rifle kicks back into the shoulder."],["So sánh súng và đạn thì cái gì bằng nhau?","What is equal between rifle and bullet?"],[["Tốc độ của chúng","Their speeds"],["Tích của khối lượng với tốc độ, nhưng ngược chiều","Mass times speed, in opposite directions"],["Quãng đường chúng đi được","The distances they travel"]],1,["Khí thuốc đẩy đạn về phía trước và đẩy súng về phía sau bằng đúng một lực, trong đúng một khoảng thời gian. Nên tích khối lượng nhân tốc độ của hai bên bằng nhau, chỉ ngược chiều. Súng nặng gấp bốn trăm lần viên đạn nên nó lùi chậm hơn bốn trăm lần — vẫn đủ bầm vai. Cũng chính vì thế mà súng càng nặng càng đỡ giật, và tên lửa bay được trong chân không dù chẳng có gì để tì vào.","The burning charge pushes the bullet forward and the rifle back with one and the same force, for one and the same instant. So mass multiplied by speed matches on both sides, opposite in direction. The rifle is four hundred times heavier, so it moves four hundred times slower — still enough to bruise a shoulder. It is also why a heavier gun kicks less, and why a rocket works in a vacuum with nothing to lean on."]),n("xe-tai-dam-xe-may",3,"tp",["Một xe tải đâm vào một xe máy đang đi ngược chiều. Xe máy nát, người đi xe máy nguy kịch; xe tải chỉ móp cái cản.","A lorry collides head-on with a motorbike. The bike is destroyed and its rider critically hurt; the lorry has a dented bumper."],["Trong cú va ấy, lực hai bên đặt lên nhau thế nào?","During the impact, how do the forces on each compare?"],[["Xe tải tác dụng lực lớn hơn nhiều","The lorry exerts a far bigger force"],["Hai lực bằng nhau chính xác, ngược chiều nhau","The two forces are exactly equal and opposite"],["Lực lớn hơn thuộc về xe đang đi nhanh hơn","The bigger force belongs to whichever was going faster"]],1,['Đây là chỗ bẻ luật, và nó trái với mọi trực giác: hai lực bằng nhau tuyệt đối. Cái khác nhau không phải lực mà là hậu quả, vì cùng một lực đặt lên một khối lượng nhỏ thì sinh ra gia tốc lớn hơn rất nhiều. Xe tải nặng gấp năm mươi lần nên nó bị hất đi ít, còn xe máy thì bị bẻ ngoặt trong tích tắc — và chính cái đổi vận tốc đột ngột ấy mới là thứ giết người, chứ không phải "lực của xe tải". Nói đúng chuyện này ra thì mọi thứ về mũ bảo hiểm và túi khí mới hiểu được.',"Here the rule bends, and it contradicts every instinct: the two forces are exactly equal. What differs is not the force but the consequence, because one force applied to a small mass produces far greater acceleration. The lorry is fifty times heavier, so it is barely deflected, while the bike is wrenched round in an instant — and it is that violent change of velocity that kills, not any greater force from the lorry. Getting this straight is what makes helmets and airbags comprehensible."]),n("tui-khi-o-to",2,"te",["Túi khí bung ra trong một phần trăm giây rồi xẹp dần khi người lái đập vào nó. Nó không cứng như một tấm đệm mút — nó cố ý xì hơi ra.","An airbag inflates in a hundredth of a second and then deflates as the driver strikes it. It is not firm like a foam pad — it lets gas out on purpose."],["Vì sao phải xì hơi ra?","Why is it made to deflate?"],[["Để người lái không bị nảy ngược lại","So the driver does not bounce back off it"],["Để kéo dài thời gian dừng, nên lực đặt lên người nhỏ đi","To stretch out the stopping time, so the force on the body is smaller"],["Để túi khí không chặn tầm nhìn sau tai nạn","So the bag does not block the view after the crash"]],1,["Người lái đang đi 50 cây số một giờ thì phải về 0, và cái đó thì không thương lượng được. Thứ thương lượng được là mất bao lâu. Dừng trong 5 phần nghìn giây khi đập vào vô lăng cứng thì lực rất lớn; kéo dài thành 50 phần nghìn giây nhờ cái túi xì hơi thì lực nhỏ đi mười lần. Toàn bộ ngành an toàn xe cộ chỉ làm đúng một việc ấy: kéo dài cú dừng. Mũ bảo hiểm cũng thế — lớp xốp bên trong sinh ra để bẹp đi, và một cái mũ đã bẹp một lần thì phải bỏ.","The driver at fifty kilometres an hour must reach zero, and that part is not negotiable. What is negotiable is how long it takes. Stopping in five thousandths of a second against a hard wheel means an enormous force; stretched to fifty thousandths by a deflating bag, the force is ten times smaller. The entire craft of vehicle safety does this one thing: lengthen the stop. A helmet is the same — its inner foam exists to be crushed, and a helmet once crushed must be thrown away."]),n("bat-bong-thi-lui-tay",2,"tp",["Bắt một quả bóng ném mạnh. Người quen bắt bao giờ cũng đưa tay lùi về sau theo quả bóng trong lúc bắt, chứ không giữ tay cứng đơ.","Catching a hard-thrown ball, an experienced player always draws the hands back with the ball rather than holding them rigid."],["Đưa tay lùi để làm gì?","What does drawing the hands back achieve?"],[["Để quả bóng đi chậm lại trước khi chạm tay","To slow the ball before it touches the hands"],["Để cú dừng kéo dài hơn, nên tay chịu lực nhẹ hơn","To make the stop last longer, so the hands feel less force"],["Để quả bóng đỡ nảy ra khỏi tay","To stop the ball bouncing out of the hands"]],1,["Quả bóng vẫn phải về 0, và tổng cái phải hấp thụ thì không đổi. Đưa tay lùi làm quãng thời gian dừng dài gấp mấy lần, nên lực đặt lên bàn tay nhỏ đi đúng bấy nhiêu lần. Đó là cùng một nguyên lý với túi khí, với việc gập gối lúc tiếp đất, với việc nhảy xuống cát thay vì xuống bê tông. Không ai bớt được cái phải nhận; người ta chỉ trải nó ra trên một quãng thời gian dài hơn.","The ball must still reach zero, and the total to be absorbed is fixed. Drawing the hands back makes the stop several times longer, so the force on the palms is smaller by the same factor. It is the airbag again, and the bent knees on landing, and jumping onto sand rather than concrete. Nobody reduces what must be taken; they only spread it over more time."])]),t("dan-hoi",["Nảy & Không Nảy","Bouncing and Not"],["Cùng một cú rơi, vật nảy lại đánh mạnh hơn vật nằm bẹp","From one and the same fall, a thing that bounces hits harder than one that stays put"],[n("bong-cao-su-va-cuc-dat",1,"tp",["Thả một quả bóng cao su và một cục đất sét cùng cân nặng, cùng độ cao, xuống một tấm ván mỏng đặt trên hai điểm tựa. Bóng nảy lên cao; đất sét dính bệt tại chỗ.","A rubber ball and a lump of clay of equal weight are dropped from the same height onto a thin plank on two supports. The ball bounces high; the clay stays where it lands."],["Cái nào đánh vào tấm ván mạnh hơn?","Which hits the plank harder?"],[["Cục đất sét, vì nó dồn hết vào một chỗ","The clay, because it delivers everything in one place"],["Quả bóng cao su","The rubber ball"],["Hai cái như nhau, vì cùng cân và cùng độ cao","The same — equal weights from equal heights"]],1,["Cục đất sét phải được tấm ván chặn lại từ tốc độ rơi về 0 — thế là hết. Quả bóng thì bị chặn về 0 rồi còn bị đẩy ngược lên với tốc độ gần bằng cũ, tức là tấm ván phải làm nhiều hơn gần gấp đôi. Nên nếu muốn bẻ tấm ván, hãy chọn quả bóng. Điều này trái với cảm giác thông thường rằng thứ dính bệt vào mới là thứ đánh nặng, và nó có ích thật: cái búa cao su nảy lại truyền lực mạnh hơn một cái búa chì cùng cân.","The clay only has to be brought from falling speed to nothing — and that is the end of it. The ball is brought to nothing and then driven back up at nearly its old speed, so the plank must do very nearly twice as much. If you want to break the plank, choose the ball. This runs against the feeling that whatever lands with a dead thud hits hardest, and it is genuinely useful: a bouncing rubber mallet delivers more than a lead one of equal weight."]),n("bong-nho-tren-bong-to",3,"tp",["Đặt một quả bóng bàn nằm ngay trên đỉnh một quả bóng rổ, giữ cho thẳng, rồi thả cả hai cùng lúc xuống nền cứng.","Rest a table-tennis ball on top of a basketball, hold them in line, and drop both together onto a hard floor."],["Quả bóng bàn bay lên tới đâu?","How high does the small ball go?"],[["Lên đúng độ cao lúc thả","Back to the height it was dropped from"],["Cao hơn hẳn độ cao lúc thả, có khi gấp mấy lần","Far higher than it was dropped from, sometimes several times"],["Thấp hơn, vì quả to đã hút mất phần nảy","Lower, because the big ball absorbed the bounce"]],1,["Chỗ bẻ luật: quả bóng bàn bay vọt lên có khi tới bốn lần độ cao thả, và trông như tự sinh năng lượng ra. Không phải. Quả bóng rổ nảy lên trước, rồi đâm vào quả bóng bàn đang còn rơi xuống — như một cú vụt bằng vợt. Quả bóng rổ nặng hơn rất nhiều nên nó chỉ mất một phần nhỏ tốc độ của mình, còn quả nhẹ thì nhận gần hết. Đúng cái này là cách một hòn đá bay ngang qua sao Mộc rồi vọt đi nhanh hơn, và là cách người ta phóng tàu ra rìa Hệ Mặt Trời mà không cần thêm nhiên liệu.","Here the rule bends: the little ball can leap four times the drop height, looking for all the world as though energy appeared from nowhere. It did not. The basketball rebounds first and then strikes the descending table-tennis ball, like a racket stroke. The heavy ball loses only a small share of its speed while the light one receives nearly all of it. This is exactly how a probe swinging past Jupiter leaves faster than it arrived, and how spacecraft are flung to the edge of the Solar System with no extra fuel."]),n("bua-dong-dinh-tren-de",2,"tp",["Đóng một cái đinh vào tấm gỗ mỏng đặt trên bàn thì tấm gỗ nảy lên, đinh không vào. Kê tấm gỗ lên một cái đe sắt nặng thì đinh vào ngay.","Nailing into a thin board lying on a table just makes the board jump. Set the board on a heavy iron anvil and the nail drives straight in."],["Cái đe làm gì?","What does the anvil do?"],[["Làm tấm gỗ mềm ra nên đinh xuyên dễ hơn","Softens the board so the nail passes more easily"],["Không cho tấm gỗ kịp lùi, nên toàn bộ cú búa đi vào đinh","Stops the board retreating, so the whole blow goes into the nail"],["Hút cái đinh xuống vì đe làm bằng sắt","Pulls the nail down because the anvil is iron"]],1,["Búa đánh xuống thì cả đinh lẫn tấm gỗ đều muốn lùi. Nếu tấm gỗ lùi được thì phần lớn cú đánh chỉ làm tấm gỗ chuyển động, không có mấy phần dồn vào việc đẩy đinh xuyên qua thớ. Cái đe nặng khiến tấm gỗ gần như không nhúc nhích trong khoảnh khắc ấy, nên toàn bộ cú búa phải được tiêu đi bằng cách đẩy đinh vào. Cũng chính vì thế mà thợ rèn dùng đe nặng, và cắt móng tay tì lên bàn cứng thì gọn hơn tì lên đùi.","When the hammer falls, both the nail and the board would like to move away. If the board can retreat, most of the blow merely sets the board moving and little of it goes into driving the nail through the grain. A heavy anvil keeps the board effectively motionless for that instant, so the whole blow must be spent pushing the nail in. It is why smiths use heavy anvils, and why cutting a nail against a hard table works better than against your own knee."]),n("trung-roi-xuong-co",1,"te",["Thả một quả trứng từ cùng độ cao, xuống nền gạch thì vỡ, xuống một tấm đệm dày thì không sao. Cùng quả trứng, cùng độ cao.","An egg dropped from one height smashes on a tiled floor and survives on a thick cushion. Same egg, same height."],["Tấm đệm đã đổi cái gì?","What did the cushion change?"],[["Nó làm quả trứng rơi chậm hơn","It made the egg fall more slowly"],["Nó kéo dài thời gian dừng lại","It stretched out the time of stopping"],["Nó làm quả trứng nhẹ đi lúc chạm","It made the egg lighter on landing"]],1,["Quả trứng chạm đệm với đúng tốc độ như chạm gạch — cùng độ cao thì cùng tốc độ, tấm đệm không hề làm nó rơi chậm hơn. Cái đệm chỉ làm một việc: thay vì dừng trong một phần nghìn giây, quả trứng lún vào đệm và dừng trong vài phần trăm giây. Lực đặt lên vỏ trứng nhỏ đi vài chục lần, và vỏ chịu được. Đây là cùng một câu chuyện với túi khí và với bàn tay bắt bóng, chỉ nhỏ lại vừa một quả trứng.","The egg meets the cushion at exactly the speed at which it would have met the tiles — same height, same speed; the cushion slows nothing on the way down. All the cushion does is this: instead of stopping in a thousandth of a second, the egg sinks in and stops over a few hundredths. The force on the shell drops dozens of times, and the shell holds. It is the airbag and the catching hands again, shrunk to the size of an egg."]),n("nay-mai-khong-dung",2,"tp",["Thả một quả bóng cao su tốt xuống sàn. Nó nảy lên, thấp hơn lần trước một chút, rồi lại nảy, thấp dần, cuối cùng nằm im.","A good rubber ball is dropped on a floor. It rebounds a little lower each time, and at last lies still."],["Phần độ cao mất đi sau mỗi lần nảy đã đi đâu?","Where does the lost height go?"],[["Biến mất hoàn toàn","It vanishes altogether"],["Thành nhiệt trong quả bóng và trong sàn, cùng tiếng động","Into heat in ball and floor, and into sound"],["Bị trọng lực giữ lại dưới sàn","Gravity keeps it below the floor"]],1,["Mỗi lần chạm, quả bóng bị bẹp rồi bung ra, và cao su bị bẹp thì nóng lên một chút — bơm xe đạp một hồi rồi sờ vào ống bơm cũng thấy đúng chuyện ấy. Thêm nữa mỗi cú nảy phát ra một tiếng động, mà tiếng động cũng là năng lượng đi ra ngoài. Không có gì biến mất; nó chỉ chuyển sang dạng tản ra khắp nơi và không gom lại được. Một quả bóng nảy mãi không dừng sẽ đòi cao su không nóng lên và cú nảy không phát ra tiếng nào.","At every contact the ball is squashed and springs back, and squashed rubber warms a little — the same thing you feel in a bicycle pump after a minute of work. Each bounce also makes a sound, and sound is energy leaving. Nothing has vanished; it has merely taken a form spread so thinly that it cannot be gathered back. A ball that bounced forever would require rubber that never warms and a bounce that makes no noise."])]),t("dua-va-hut",["Đưa Đi & Hút Vào","Passing It On"],["Chuyển động truyền qua nhau được, và tổng thì không đổi","Motion passes from one body to another, and the total is unchanged"],[n("buoc-tu-thuyen-len-bo",1,"tp",["Bạn đứng trên một chiếc thuyền nhỏ đang đậu sát bờ, không buộc dây. Bạn bước mạnh một bước lên bờ.","You are standing in a small boat resting against the bank, no rope tied. You take one firm step onto the bank."],["Chiếc thuyền làm gì lúc bạn bước?","What does the boat do as you step?"],[["Trôi ra xa bờ","It slides away from the bank"],["Đứng yên, vì bạn chỉ đẩy xuống chứ không đẩy ngang","It stays put — you pushed down, not sideways"],["Trôi theo bạn vào sát bờ hơn","It drifts after you, closer in"]],0,["Muốn đi tới trước thì chân bạn phải đạp về phía sau — và cái nó đạp vào là chiếc thuyền. Thuyền nhận cú đạp ấy nên trôi ngược ra. Chuyển động không tự sinh ra ở đâu cả: bạn đi tới bao nhiêu thì thuyền phải lùi lại đúng bấy nhiêu, chia theo ai nặng hơn ai. Thuyền nhẹ thì nó trôi ra rõ, thuyền nặng thì nó chỉ nhích — nhưng nó luôn nhích. Đây cũng là cách tên lửa bay trong chỗ không có gì để đạp: nó phun vật chất về phía sau, và phần còn lại đi tới trước.","To move forward your foot has to push backward — and what it pushes against is the boat. The boat takes that push and slides the other way. Motion is never made from nothing: however far you go forward, the boat must go back to match, shared out by who is heavier. A light boat slides visibly, a heavy one barely twitches — but it always twitches. This is also how a rocket moves where there is nothing to push against: it throws matter backward, and the rest goes forward."]),n("hai-vien-bi-cham-nhau",2,"tp",["Trên máng nhẵn, một viên bi lăn tới đập vào một viên bi giống hệt đang đứng yên. Sau cú chạm, viên tới dừng lại và viên đứng yên lăn đi.","On a smooth track a rolling marble strikes an identical marble at rest. After the click, the moving one stops and the still one rolls away."],["Viên thứ hai lăn đi nhanh cỡ nào?","How fast does the second marble go?"],[["Nhanh gần bằng viên thứ nhất lúc tới","Nearly as fast as the first was going"],["Nhanh gấp đôi, vì nhận thêm cú đẩy","Twice as fast, having been given a shove"],["Chậm hơn hẳn, chỉ bằng một nửa","Much slower, about half as fast"]],0,["Hai viên bi giống hệt nhau, nên cú chạm truyền gần trọn vẹn: viên tới đứng lại, viên kia đi tiếp với gần đúng tốc độ cũ. Nếu viên thứ hai đi nhanh gấp đôi thì tổng chuyển động đã tự sinh thêm ra, mà chuyện đó không xảy ra bao giờ. Cái đúng là tổng của khối lượng nhân tốc độ trước và sau cú chạm bằng nhau — và ở trường hợp hai viên bằng nhau thì cách duy nhất thoả điều ấy là đổi vai cho nhau.","The marbles are identical, so the click passes the motion on almost entire: the arriving one halts and the other leaves at very nearly the old speed. If the second went twice as fast, motion would have been created out of nothing, which never happens. What holds is that the total of mass times speed is the same before and after — and with two equal marbles the only way to satisfy that is to swap roles."]),n("hang-bi-treo-day",3,"tp",["Năm viên bi thép giống nhau treo sát nhau thành một hàng. Kéo hai viên ở đầu ra rồi thả xuống.","Five identical steel balls hang in a touching row. Two at one end are lifted and released."],["Đầu bên kia bật ra mấy viên?","How many fly out at the far end?"],[["Một viên, nhưng bay nhanh gấp đôi","One, going twice as fast"],["Đúng hai viên, bay với tốc độ cũ","Exactly two, at the original speed"],["Cả ba viên còn lại cùng bật ra","All three remaining balls swing out"]],1,["Chỗ bẻ luật: một viên bay gấp đôi tốc độ nghe rất hợp lý và vẫn giữ đúng tổng khối lượng nhân tốc độ — nhưng nó không xảy ra, vì còn một sổ sách thứ hai phải khớp. Năng lượng của chuyển động tính theo bình phương tốc độ, nên một viên đi gấp đôi mang năng lượng gấp đôi mức đáng có. Chỉ có đúng một kết cục thoả cả hai sổ sách cùng lúc: hai viên bật ra với đúng tốc độ cũ. Cái đồ chơi để bàn quen thuộc ấy thật ra là một chiếc cân kiểm tra hai định luật một lúc.","Here the rule bends: one ball at twice the speed sounds sensible and does keep the total of mass times speed correct — yet it never happens, because a second set of books must also balance. The energy of motion goes as the square of speed, so a single ball at double speed would carry twice the energy available. Exactly one outcome satisfies both ledgers at once: two balls leave at the original speed. That familiar desk toy is really a device for checking two laws simultaneously."]),n("nuoc-day-guong-quay",2,"te",["Dòng nước chảy đập vào các gầu của một guồng nước và làm nó quay. Nước đi ra khỏi guồng chậm hơn lúc đi vào.","A stream strikes the buckets of a water wheel and turns it. The water leaves the wheel more slowly than it arrived."],["Việc nước chảy chậm đi cho biết điều gì?","What does that slowing tell you?"],[["Nước bị guồng làm nóng lên nên chậm lại","The wheel warmed the water, so it slowed"],["Phần chuyển động nước mất đi chính là phần guồng nhận được","The motion the water lost is what the wheel gained"],["Nước chảy chậm vì nó đã đi được một quãng xa hơn","The water is slower simply from having travelled further"]],1,["Một cỗ máy lấy sức từ dòng chảy thì bao giờ cũng để lại phía sau một dòng chảy chậm hơn — nếu nước đi ra vẫn nhanh như cũ thì guồng đã chẳng lấy được gì. Cũng đúng như thế với cánh quạt gió: gió sau cánh chậm hơn gió trước cánh, và đó là lý do không cỗ máy gió nào lấy được hết sức của gió, vì lấy hết nghĩa là không khí đứng im ngay sau cánh và như thế thì không còn chỗ cho luồng sau đi qua.","Any machine taking power from a flow leaves a slower flow behind it — if the water left as fast as it arrived, the wheel would have taken nothing. The same is true of a wind turbine: the air behind the blades is slower than the air in front, and it is why no wind machine can take all the wind, since taking all of it would leave the air motionless right behind the blades, with nowhere for the next stream to go."]),n("dun-thuyen-bang-quat",3,"tp",["Một người ngồi trên thuyền, dựng cánh buồm lên, rồi lấy một cái quạt máy đặt trên thuyền thổi thẳng vào buồm của chính mình.","A man in a boat raises a sail, then sets up an electric fan in the boat and blows it straight into his own sail."],["Chiếc thuyền đi về đâu?","Where does the boat go?"],[["Đi tới trước, vì buồm nhận gió","Forwards — the sail catches the wind"],["Gần như đứng yên, hoặc nhích rất chậm về phía sau","Nearly nowhere, or creeps slightly backwards"],["Đi lùi mạnh về phía sau","Strongly backwards"]],1,["Cái quạt đẩy không khí về phía buồm, và chính nó bị đẩy ngược lại về phía sau đúng chừng ấy. Luồng khí ấy đập vào buồm rồi đẩy buồm tới trước — vừa đúng bằng phần quạt đã đẩy ngược. Hai cái triệt tiêu nhau, vì cả quạt lẫn buồm đều nằm trên cùng một chiếc thuyền. Thực tế thuyền còn nhích lùi một chút, vì buồm không hứng trọn được luồng khí. Chỗ bẻ luật là ở đây: bỏ cánh buồm đi thì chiếc thuyền lại chạy tới trước thật — vì lúc ấy không khí bị ném hẳn ra khỏi hệ.","The fan drives air towards the sail and is itself driven backwards by just as much. That stream hits the sail and pushes it forwards by the same amount. The two cancel, because fan and sail sit in the same boat. In practice it creeps backwards a little, since the sail cannot catch the whole stream. Here the rule bends: take the sail down and the boat really does move forwards — because now the air is thrown clear of the system altogether."]),n("nhay-len-can-thi-can-doc-gi",2,"tp",["Đứng yên trên cân sức khoẻ thì cân đọc đúng cân nặng của mình. Bây giờ ngồi xổm xuống rồi bật mạnh người lên.","Standing still on a bathroom scale, it reads your weight. Now crouch and spring upwards hard."],["Trong lúc đang bật lên, cân đọc số thế nào?","What does the scale read during the push-off?"],[["Lớn hơn cân nặng thật","More than your true weight"],["Nhỏ hơn, vì mình đang rời khỏi mặt cân","Less, because you are leaving the surface"],["Đúng bằng cân nặng thật, không đổi","Exactly your true weight, unchanged"]],0,["Muốn bật lên thì chân phải đạp xuống mặt cân mạnh hơn sức nặng của mình, và cân đọc đúng cái lực đạp ấy chứ không đọc sức nặng. Ngay sau khi rời chân khỏi cân thì số về 0, còn lúc tiếp đất thì lại vọt lên rất cao. Đó cũng là cảm giác nặng người trong thang máy đang đi lên và nhẹ hẫng lúc thang bắt đầu đi xuống: cái cân — và cái tai trong của mình — chưa bao giờ đo trọng lực, chúng đo lực mà sàn đang đẩy vào mình.","To spring up, your legs must press the scale harder than your weight, and the scale reads that press rather than the weight. The instant your feet leave, it reads zero, and on landing it spikes far higher. It is the same heaviness felt in a lift starting upwards and the lightness as it starts down: neither the scale nor your inner ear has ever measured gravity — they measure the force the floor is applying to you."])])],N=[t("dong-dien-chay",["Dòng Điện","Current"],["Điện chỉ chảy khi có một vòng kín — hở một chỗ là cả vòng đứng lại","Electricity flows only round a closed loop — one gap and the whole loop stops"],[n("mach-ho-mot-cho",1,"te",["Một cục pin, một bóng đèn nhỏ, hai đoạn dây. Nối đủ thành vòng thì đèn sáng. Cắt một đoạn dây ở phía SAU bóng đèn, tức là ở đoạn từ đèn quay về pin.","A battery, a small bulb and two wires. Joined into a loop, the bulb lights. Now cut one wire AFTER the bulb, on the stretch running back to the battery."],["Bóng đèn ra sao?","What happens to the bulb?"],[["Vẫn sáng, vì điện đã tới được đèn rồi","Still lit — the electricity already reached it"],["Tắt ngay lập tức","Goes out at once"],["Sáng yếu đi một nửa","Shines at about half brightness"]],1,["Đèn tắt ngay, và đó là điều quan trọng nhất về điện: nó không phải một thứ được rót vào bóng đèn rồi dùng hết ở đấy. Nó chảy thành một vòng kín, và cắt vòng ở đâu cũng làm cả vòng dừng lại — trước hay sau bóng đèn không khác gì nhau. Cái bị tiêu đi trong bóng đèn không phải dòng điện: lượng điện chảy vào bằng đúng lượng chảy ra. Cái bị tiêu là năng lượng, và nó ra khỏi bóng đèn dưới dạng ánh sáng và hơi nóng.","It goes out immediately, and that is the most important fact about electricity: it is not something poured into a bulb and used up there. It runs round a closed loop, and cutting the loop anywhere stops all of it — before or after the bulb makes no difference. What the bulb consumes is not current: exactly as much flows out as flows in. What it consumes is energy, and that leaves as light and warmth."]),n("hai-den-noi-tiep",2,"te",["Một chuỗi đèn nhấp nháy mắc nối tiếp: dòng điện đi qua bóng thứ nhất rồi mới sang bóng thứ hai, thứ ba, cứ thế. Một bóng cháy đứt tóc.","A string of fairy lights is wired in series: the current passes through the first bulb, then the second, then the third. One bulb burns out."],["Chuyện gì xảy ra với cả chuỗi?","What happens to the string?"],[["Chỉ bóng ấy tắt, các bóng khác vẫn sáng","Only that bulb goes dark; the rest stay lit"],["Cả chuỗi tắt hết","The entire string goes out"],["Các bóng còn lại sáng hơn hẳn lên","The remaining bulbs get noticeably brighter"]],1,["Nối tiếp nghĩa là chỉ có đúng một vòng cho dòng đi, nên đứt một chỗ là đứt cả vòng — và đó chính là nỗi bực quen thuộc của mọi chuỗi đèn Tết đời cũ. Cách chữa là mắc song song: mỗi bóng có vòng riêng của nó về nguồn, nên bóng nào hỏng thì chỉ mình nó tối. Đèn trong nhà mắc song song hết, và đó là lý do tắt đèn bếp thì đèn phòng khách không tối đi theo.","In series there is exactly one loop for the current, so one break breaks everything — the familiar misery of old Christmas lights. The cure is parallel wiring: each bulb has its own loop back to the source, so a failure darkens only itself. House lighting is all parallel, which is why switching off the kitchen does not dim the living room."]),n("day-nong-len-o-cho-nao",2,"te",["Trong cái bếp điện, dây dẫn từ ổ cắm vào thì mát, còn cái ruột đun bên trong thì đỏ rực. Cùng một dòng điện chạy qua cả hai.","In an electric ring, the lead from the socket stays cool while the element inside glows red. The same current passes through both."],["Vì sao chỉ ruột đun nóng?","Why does only the element get hot?"],[["Vì dòng điện ở đó lớn hơn","Because more current flows there"],["Vì ruột đun cản dòng nhiều hơn, nên nhả ra nhiều nhiệt hơn","Because it resists the current more, and so gives off more heat"],["Vì ruột đun nằm gần bếp nên bị bếp hun nóng","Because it sits inside the stove and is warmed by it"]],1,["Dòng điện qua hai đoạn là như nhau, đúng như nước chảy qua một đường ống thì mọi chỗ cùng lưu lượng. Cái khác là mức cản: dây đồng to thì cản rất ít, còn sợi ruột đun mảnh và làm bằng hợp kim cản nhiều. Chỗ nào cản nhiều thì năng lượng bị chuyển thành nhiệt nhiều — nên nó đỏ lên còn dây dẫn thì không. Đây cũng là lý do một sợi dây nối quá mảnh cho một cái ấm điện sẽ nóng chảy: nó vô tình trở thành cái ruột đun thứ hai.","The current is the same in both, just as the flow through a pipe is the same at every point along it. What differs is resistance: thick copper resists very little, while the thin alloy element resists a great deal. Where resistance is high, energy is turned into heat — so it glows while the lead does not. It is also why an undersized extension lead to a kettle melts: it has quietly become a second heating element."]),n("dien-chay-nhanh-the-nao",3,"tp",["Bật công tắc ở đầu này, bóng đèn ở cuối một sợi dây dài hàng chục mét sáng lên gần như ngay lập tức.","Flick a switch at one end and a bulb at the far end of a wire tens of metres long lights almost instantly."],["Các hạt mang điện trong dây chạy nhanh cỡ nào?","How fast do the charge carriers in the wire actually travel?"],[["Gần bằng tốc độ ánh sáng","Nearly the speed of light"],["Chậm hơn người đi bộ rất nhiều, cỡ vài mét một giờ","Far slower than a walking pace — a few metres an hour"],["Đúng bằng tốc độ âm thanh trong kim loại","At the speed of sound in metal"]],1,["Chỗ bẻ luật: bóng đèn sáng ngay, nhưng các hạt mang điện thì bò rất chậm — trong một sợi dây gia dụng chúng nhích chừng vài mét mỗi giờ. Cái chạy nhanh là cái ĐẨY, không phải hạt: sợi dây vốn đã đầy hạt mang điện sẵn, nên đẩy ở đầu này thì đầu kia nhúc nhích gần như tức thì, y hệt một ống nước đã đầy nước từ trước. Nước ở vòi chảy ra ngay khi mở, không phải vì nước từ bể chạy tới nhanh, mà vì trong ống đã có sẵn nước rồi.","Here the rule bends: the bulb lights at once, yet the charge carriers crawl — in household wire they advance a few metres an hour. What travels fast is the push, not the particles: the wire is already full of carriers, so a shove at one end nudges the far end almost immediately, exactly like a pipe already full of water. A tap runs the instant you open it, not because water sprints from the reservoir, but because the pipe was full already."]),n("chim-dau-tren-day-dien",2,"te",["Con chim đậu cả hai chân trên một sợi dây điện cao thế trần, không sao cả. Người trèo lên chạm vào đúng sợi ấy trong khi chân còn đứng dưới đất thì chết.","A bird perches with both feet on a bare high-voltage line and is unharmed. A person touching that same line while standing on the ground is killed."],["Vì sao con chim không sao?","Why is the bird safe?"],[["Vì lông chim cách điện","Because feathers insulate it"],["Vì hai chân nó cùng nằm trên một sợi, nên không có vòng nào để dòng đi qua nó","Because both feet are on one wire, so no loop runs through it"],["Vì chim quá nhẹ nên dòng điện bỏ qua","Because it is too light for the current to notice"]],1,["Dòng điện chỉ chảy khi có một vòng kín, và nó luôn chọn đường dễ đi. Hai chân con chim cùng nằm trên một sợi dây đồng dày, cách nhau vài centimét — chạy qua đoạn đồng ấy dễ hơn hẳn chạy qua người con chim, nên không có gì đáng kể đi qua nó. Người chạm dây mà chân chạm đất thì tự mình làm nên một vòng từ dây xuống đất, và cả cơ thể trở thành một đoạn của vòng ấy. Con chim an toàn không phải nhờ nó là chim, mà nhờ nó không nối hai chỗ khác nhau lại.","Current flows only round a closed loop, and it takes the easiest road. Both of the bird’s feet sit on one thick copper wire, centimetres apart — running through that copper is far easier than running through a bird, so nothing much does. A person touching the line while earthed makes a loop from wire to ground, and their body becomes a length of it. The bird is safe not for being a bird, but for not joining two different places together."])]),t("nam-cham",["Nam Châm","Magnets"],["Điện và từ là hai mặt của một thứ — động cái này thì cái kia hiện ra","Electricity and magnetism are two faces of one thing — move one and the other appears"],[n("cat-doi-nam-cham",1,"tp",["Một thanh nam châm có đầu bắc và đầu nam. Cưa đôi nó ra giữa thân.","A bar magnet has a north end and a south end. Saw it in half across the middle."],["Bây giờ có gì?","What do you now have?"],[["Một nửa chỉ có cực bắc, một nửa chỉ có cực nam","One piece with only a north pole and one with only a south"],["Hai thanh nam châm nhỏ, mỗi thanh lại đủ cả hai cực","Two smaller magnets, each with both poles again"],["Hai mẩu sắt thường, hết từ tính","Two ordinary bits of iron, no longer magnetic"]],1,['Cưa bao nhiêu lần cũng vậy: mỗi mẩu lại mọc đủ hai cực. Lý do là từ tính không nằm ở hai đầu thanh mà nằm trong từng vùng rất nhỏ bên trong, mỗi vùng đã tự là một nam châm tí hon xếp cùng hướng. Nên "một cực bắc rời ra" là thứ chưa ai tìm thấy bao giờ. Đây là chỗ điện và từ khác nhau rõ nhất: điện tích dương tách rời điện tích âm được, còn cực từ thì không.',"Saw it as often as you like: every fragment grows a full pair of poles. The reason is that magnetism does not live at the two ends but in countless tiny regions inside, each already a miniature magnet lined up with its neighbours. A north pole on its own has never been found by anybody. This is where electricity and magnetism differ most plainly: positive charge can be separated from negative, magnetic poles cannot."]),n("kim-la-ban-chi-dau",2,"te",["Kim la bàn tự quay về hướng bắc và đứng yên ở đó, ở bất cứ chỗ nào trên mặt đất.","A compass needle swings to the north and settles there, anywhere on Earth."],["Cái gì kéo nó?","What pulls it?"],[["Sao Bắc Đẩu ở phía bắc bầu trời","The pole star in the northern sky"],["Từ trường do lõi sắt lỏng của Trái Đất sinh ra","A magnetic field made by the Earth’s liquid iron core"],["Băng ở Bắc Cực, vì băng hút sắt","The polar ice, because ice attracts iron"]],1,["Sâu bên trong Trái Đất là một lõi sắt nóng chảy đang cuộn chảy không ngừng, và sắt lỏng chuyển động thì sinh ra từ trường — đúng cái luật làm một cuộn dây có dòng điện chạy qua trở thành nam châm. Cái kim chỉ đơn giản nằm dọc theo từ trường ấy. Từ trường này không đứng yên: các cực từ trôi hàng chục cây số mỗi năm, và trong lịch sử Trái Đất nó đã đảo ngược bắc nam nhiều lần, chuyện đọc được trong các lớp đá cổ.","Deep inside the Earth a molten iron core churns endlessly, and moving liquid iron makes a magnetic field — the same law that turns a current-carrying coil into a magnet. The needle merely lies along that field. The field does not hold still: the magnetic poles wander tens of kilometres a year, and over the Earth’s history north and south have swapped many times, a story readable in ancient rock."]),n("nam-cham-roi-qua-ong-dong",3,"tp",["Thả một thanh nam châm mạnh rơi qua một ống đồng dựng đứng. Đồng không phải sắt, nam châm không hút đồng chút nào. Vậy mà nam châm rơi rất chậm, mất mấy giây mới ra khỏi ống.","Drop a strong magnet down a vertical copper tube. Copper is not iron and the magnet does not attract it at all. Yet the magnet falls slowly, taking seconds to emerge."],["Cái gì hãm nó lại?","What holds it back?"],[["Không khí bị nén trong ống đẩy ngược lên","Air trapped in the tube pushing back"],["Nam châm rơi làm sinh dòng điện trong đồng, và dòng ấy sinh từ chống lại nó","The falling magnet makes currents in the copper, and those currents oppose it"],["Đồng có từ tính yếu nên vẫn hút được nam châm","Copper is faintly magnetic after all"]],1,["Chỗ bẻ luật: đồng không hề bị nam châm hút, thí nghiệm nào cũng cho thấy thế. Nhưng một từ trường ĐANG ĐỔI thì sinh ra dòng điện trong kim loại, và dòng điện thì lại sinh ra từ trường của chính nó — và luôn theo chiều chống lại cái thay đổi vừa gây ra nó. Nam châm rơi càng nhanh thì dòng sinh ra càng mạnh và lực hãm càng lớn, nên nó đi xuống với một tốc độ đều đặn. Đây chính là cách phanh của tàu cao tốc và của máy chạy bộ hoạt động: phanh mà không có gì cọ vào gì cả.","Here the rule bends: copper is not attracted by magnets, as any test shows. But a CHANGING magnetic field drives currents in metal, and those currents make a field of their own — always in the direction that opposes the change which caused them. The faster the magnet falls, the stronger the currents and the stronger the braking, so it descends at a steady crawl. This is exactly how the brakes on high-speed trains and gym treadmills work: braking with nothing rubbing on anything."]),n("cuon-day-thanh-nam-cham",2,"te",["Quấn dây đồng thành cuộn quanh một cái đinh sắt rồi nối hai đầu vào pin. Cái đinh hút được kẹp giấy. Tháo pin ra thì nó thôi hút.","Wind copper wire round an iron nail and connect the ends to a battery. The nail picks up paper clips. Disconnect the battery and it stops."],["Cái gì làm cái đinh có từ tính?","What makes the nail magnetic?"],[["Pin truyền từ tính của nó sang cái đinh","The battery passes its own magnetism to the nail"],["Dòng điện chạy trong cuộn dây sinh ra từ trường","The current going round the coil creates a magnetic field"],["Dây đồng cọ vào đinh làm nó nhiễm từ","The copper rubbing the nail magnetises it"]],1,["Cứ có dòng điện chạy là quanh nó có từ trường, và quấn dây thành cuộn thì các vòng cộng dồn lại thành một từ trường mạnh dọc theo lòng cuộn. Lõi sắt bên trong khuếch đại thêm nhiều lần. Cắt dòng thì mất từ ngay — và chính cái tắt bật được ấy làm nó khác hẳn nam châm vĩnh cửu, đồng thời làm nên gần như mọi thứ trong nhà có phần chuyển động: quạt, máy bơm, ổ khoá điện, loa, và cái chuông cửa.","Wherever a current runs there is a magnetic field around it, and winding the wire into a coil adds the turns together into a strong field along the core. An iron core multiplies it further. Cut the current and the magnetism vanishes at once — and it is precisely that switchability which separates it from a permanent magnet, and which underlies almost everything in a house that moves: fans, pumps, door locks, loudspeakers, and the doorbell."]),n("quay-nam-cham-sinh-dien",2,"te",["Quay một nam châm trước một cuộn dây kín thì trong dây có dòng điện, dù không có pin nào cả. Đứng yên thì không có dòng.","Spin a magnet in front of a closed coil and a current appears in the wire, with no battery anywhere. Hold it still and there is none."],["Điều kiện để có dòng là gì?","What is the condition for a current?"],[["Từ trường qua cuộn dây phải đang thay đổi","The field through the coil must be changing"],["Nam châm phải chạm vào dây","The magnet must touch the wire"],["Nam châm phải đủ mạnh, đứng yên cũng được","The magnet must be strong enough; still is fine"]],0,["Từ trường đứng yên thì không sinh ra dòng nào, dù nam châm mạnh tới đâu. Phải có sự THAY ĐỔI. Đây là phát hiện của Faraday và là cái đẻ ra toàn bộ ngành điện: mọi nhà máy điện trên thế giới, dù đốt than, chạy nước hay chạy gió, đều chỉ làm đúng một việc là quay một nam châm trước một cuộn dây. Cái khác nhau giữa chúng chỉ là lấy đâu ra sức để quay.","A still field produces no current at all, however strong the magnet. There must be CHANGE. This was Faraday’s discovery and it founded the whole electrical world: every power station anywhere, whether it burns coal, drops water or catches wind, does the one same thing — turns a magnet in front of a coil. All that differs between them is where the turning comes from."])]),t("dien-trong-nha",["Điện Trong Nhà","Electricity Indoors"],["Cái làm chết người là dòng đi qua người, không phải con số vôn","What kills is the current through a person, not the number of volts"],[n("cau-chi-de-lam-gi",1,"te",["Cầu chì là một sợi kim loại mảnh cố ý làm cho dễ đứt, đặt ngay đầu đường điện vào nhà.","A fuse is a deliberately weak strand of metal placed at the point where power enters a house."],["Nó ở đó để làm gì?","What is it there for?"],[["Để đứt trước khi dòng quá lớn kịp làm nóng dây trong tường","To break before an excessive current can overheat the wiring in the walls"],["Để làm cho điện chạy đều hơn","To make the current flow more smoothly"],["Để đo xem nhà dùng bao nhiêu điện","To measure how much power the house uses"]],0,['Dây điện chôn trong tường mà tải quá nhiều dòng thì nóng lên, và nóng đủ lâu thì cháy nhà. Không ai đứng canh được, nên người ta cố ý đặt một chỗ yếu nhất ở đầu đường: khi dòng vượt ngưỡng, chính chỗ ấy đứt trước và cắt cả vòng. Vì thế thay cầu chì bằng một sợi dây đồng to là hành động nguy hiểm nhất trong nhà — nó không sửa gì cả, nó chỉ bỏ đi cái chốt an toàn duy nhất và giao việc "đứt trước" lại cho sợi dây trong tường.',"Wiring buried in a wall carrying too much current heats up, and heated long enough it burns the house down. Nobody can stand guard, so a deliberate weakest point is placed at the entrance: when the current passes its limit, that point fails first and cuts the loop. Which is why replacing a fuse with a thick copper wire is the most dangerous act in a household — it fixes nothing, removes the only safeguard, and hands the job of failing first to the wire inside the wall."]),n("von-hay-dong-lam-chet",2,"te",["Cái máy phát tĩnh điện ở phòng thí nghiệm cho ra hàng chục nghìn vôn, chạm vào chỉ thấy giật nảy người. Ổ cắm trong nhà 220 vôn thì có thể giết người.","A laboratory static generator makes tens of thousands of volts and merely makes you jump. A 220-volt socket can kill."],["Cái gì quyết định mức nguy hiểm?","What decides the danger?"],[["Số vôn, càng cao càng nguy hiểm","The number of volts — the higher the worse"],["Lượng dòng chạy qua người và chạy trong bao lâu","How much current passes through the body, and for how long"],["Màu của dây điện đang chạm vào","Which colour wire is being touched"]],1,["Vôn là mức đẩy; dòng mới là lượng thật sự chảy qua người. Máy tĩnh điện có mức đẩy rất cao nhưng chỉ đủ điện cho một tia nhỏ trong một phần triệu giây, nên nó làm mình giật mình chứ không làm hại. Ổ cắm trong nhà đẩy nhẹ hơn nhiều nhưng nguồn thì gần như vô tận, và nó duy trì dòng qua người suốt chừng nào còn chạm — mà chỉ cần một phần mười ampe qua lồng ngực là đủ làm tim loạn nhịp.","Volts are the push; current is what actually passes through the body. A static generator pushes very hard but has only enough charge for a spark lasting a millionth of a second, so it startles rather than harms. A wall socket pushes far less but draws on a practically endless supply, and sustains the current for as long as contact lasts — and a tenth of an amp across the chest is enough to throw the heart out of rhythm."]),n("den-led-tiet-kiem-o-cho-nao",2,"te",["Bóng đèn sợi đốt cũ và bóng LED mới cùng cho ra chừng ấy ánh sáng, nhưng bóng cũ ăn 60 oát còn bóng LED chỉ ăn 7 oát.","An old filament bulb and a new LED give about the same light, but the old one draws 60 watts and the LED just 7."],["Phần 53 oát kia đã đi đâu ở bóng cũ?","Where did the other 53 watts go in the old bulb?"],[["Thành nhiệt","Into heat"],["Bị mất trong dây dẫn trước khi tới bóng","Lost in the wiring before reaching the bulb"],["Thành ánh sáng mà mắt người không nhìn thấy","Into light the eye cannot see"]],0,["Bóng sợi đốt phát sáng bằng cách nung một sợi kim loại tới hơn hai nghìn độ, và một vật nóng thì toả ra chủ yếu là nhiệt, ánh sáng chỉ là phần rơi vãi — khoảng năm phần trăm. Nói cho đúng thì bóng đèn dây tóc là một cái lò sưởi nhỏ tình cờ phát sáng. LED thì tạo ánh sáng bằng một cách khác hẳn, không phải bằng cách nung nóng cái gì, nên phần nhiệt nhỏ hơn nhiều. Sờ hai bóng đang sáng là kiểm tra được ngay.","A filament bulb makes light by heating metal past two thousand degrees, and a hot object radiates mostly heat, with light as spillage — about five per cent of it. Strictly speaking a filament bulb is a small heater that happens to glow. An LED makes light by an entirely different route that does not involve heating anything, so far less is wasted as warmth. Touching the two while lit settles the matter at once."]),n("day-cao-the-vi-sao-cao-the",3,"te",["Điện từ nhà máy tới thành phố được đưa lên hàng trăm nghìn vôn để truyền đi, rồi hạ xuống 220 vôn ngay trước khi vào nhà. Việc nâng lên hạ xuống ấy tốn cả một hệ thống máy biến áp đắt tiền.","Power from a station is stepped up to hundreds of thousands of volts for the journey, then dropped to 220 just before entering houses. All that stepping requires an expensive system of transformers."],["Vì sao phải nâng lên cao thế?","Why raise the voltage at all?"],[["Vì điện thế cao thì chạy nhanh hơn trên đường dây","Because high voltage travels faster along the line"],["Vì cùng một công suất, điện thế cao thì dòng nhỏ, mà hao trên đường tính theo bình phương dòng","Because at the same power, high voltage means small current, and line loss grows as the square of current"],["Vì dây nhôm chỉ dẫn được điện thế cao","Because aluminium cable only conducts at high voltage"]],1,["Chỗ bẻ luật: nghe thì tưởng đẩy mạnh hơn là hao nhiều hơn, thật ra ngược lại. Cùng một lượng công suất, nâng điện thế lên gấp mười thì dòng chỉ còn một phần mười — mà phần hao dọc đường lại tỉ lệ với bình phương dòng, nên nó tụt còn một phần trăm. Đó là toàn bộ lý do tồn tại của những cột điện cao thế: không phải để đẩy điện đi xa, mà để đi xa mà không đốt mất phần lớn dọc đường. Không có nó thì nhà máy điện phải đặt ngay trong thành phố.","Here the rule bends: it sounds as though pushing harder must waste more, and the opposite is true. For a given power, raising the voltage tenfold cuts the current to a tenth — and the loss along the line goes as the square of the current, so it falls to a hundredth. That is the entire reason pylons exist: not to push power further, but to travel far without burning most of it on the way. Without them, power stations would have to stand inside the cities they serve."]),n("day-noi-dat-de-lam-gi",2,"te",["Nhiều thiết bị có vỏ kim loại được nối bằng một sợi dây riêng xuống một cọc chôn dưới đất. Bình thường sợi dây ấy không tải dòng nào cả.","Many metal-cased appliances have a separate wire running to a rod buried in the ground. In normal use that wire carries nothing."],["Sợi dây ấy để làm gì?","What is it for?"],[["Để thiết bị chạy êm hơn","To make the appliance run more smoothly"],["Để nếu dây điện chạm vỏ thì dòng chạy xuống đất chứ không qua người","So that if a live wire touches the case, the current goes to earth instead of through a person"],["Để hút sét khi trời giông","To attract lightning during storms"]],1,["Bình thường sợi dây tiếp đất chẳng làm gì cả, và đó chính là dấu hiệu nó đang làm đúng việc. Khi có hỏng hóc và dây nóng chạm vào vỏ, cái vỏ trở thành nguy hiểm. Sợi dây tiếp đất cho dòng một đường về đất dễ hơn hẳn đường đi qua người, nên dòng đổ hết vào đấy — và dòng lớn ấy làm cầu dao nhảy ngay. Đây là một thứ an toàn kiểu chờ sẵn: nó vô dụng suốt nhiều năm rồi có ích đúng một lần.","In ordinary use the earth wire does nothing, and that is the sign it is doing its job. When a fault brings a live wire against the case, the case becomes dangerous. The earth wire offers the current a road to ground far easier than the road through a person, so all of it goes that way — and that surge trips the breaker at once. It is safety of the waiting kind: useless for years, then useful exactly once."])])],C=[t("thau-kinh",["Thấu Kính","Lenses"],["Một thấu kính không phóng to cái gì — nó chỉ bẻ đường đi của ánh sáng","A lens enlarges nothing — it only bends the paths light takes"],[n("kinh-lup-dot-la-kho",1,"te",["Cầm kính lúp hứng nắng, rê tới rê lui cho tới khi trên chiếc lá khô hiện ra một chấm sáng thật nhỏ. Chỉ ở đúng chấm ấy lá mới cháy.","Hold a magnifying glass in the sun and move it until a very small bright dot appears on a dry leaf. Only at that dot does the leaf scorch."],["Vì sao phải đúng khoảng cách ấy?","Why must the distance be just right?"],[["Vì ở đó kính gom ánh sáng của cả mặt kính vào một điểm","Because there the glass gathers the light of its whole face into one point"],["Vì ở đó kính nóng nhất","Because the glass itself is hottest there"],["Vì ở đó kính phóng to tia nắng lên","Because there the glass magnifies the sunbeam"]],0,["Kính lúp không thêm một chút ánh sáng nào. Nó chỉ hứng lấy toàn bộ nắng rơi trên mặt kính rộng chừng một bàn tay rồi bẻ tất cả về một chấm bé bằng đầu kim. Cùng chừng ấy năng lượng dồn vào một diện tích nhỏ hơn hàng nghìn lần thì chỗ ấy nóng lên hàng nghìn lần. Rê ra xa hay lại gần thì các tia chưa gặp nhau hoặc đã đi quá chỗ gặp, và chấm sáng loang ra, không đủ nóng nữa.","The lens adds no light whatever. It catches all the sunshine landing on a palm-sized disc of glass and bends every bit of it to a dot the size of a pinhead. The same energy crowded into an area thousands of times smaller makes that spot thousands of times hotter. Move it nearer or further and the rays have not yet met, or have already passed their meeting place, so the dot spreads and cools."]),n("anh-nguoc-tren-tuong",2,"tp",["Đặt một cây nến trước một thấu kính lồi, đưa một tấm giấy trắng ra phía sau và rê cho tới khi hiện rõ hình ngọn nến trên giấy.","Stand a candle before a convex lens, hold a white card behind it, and slide the card until a clear image of the flame appears."],["Hình ngọn nến trên giấy trông thế nào?","How does the image look?"],[["Xuôi như thật, chỉ nhỏ hơn","The right way up, only smaller"],["Lộn ngược đầu xuống dưới","Upside down"],["Nghiêng đi chín mươi độ","Rotated by ninety degrees"]],1,["Hình luôn lộn ngược, và lý do đơn giản: tia sáng đi từ đỉnh ngọn lửa xuyên qua kính rồi chúc xuống dưới, còn tia từ chân nến thì đi lên trên — chúng chéo nhau ngay trong lòng thấu kính. Cái gì ở trên thì hiện ở dưới. Đây cũng chính là chuyện xảy ra trong mắt người: hình trên võng mạc của bạn ngay lúc này đang lộn ngược, và bộ não đã quen tới mức không ai để ý.","The image is always inverted, for a simple reason: a ray from the top of the flame passes through the glass and slopes downwards, while a ray from the base slopes up — they cross inside the lens itself. Whatever was above appears below. This is also what happens in a human eye: the image on your retina at this moment is upside down, and the brain is so used to it that nobody notices."]),n("che-mot-nua-thau-kinh",3,"tp",["Đang có hình ngọn nến hiện rõ trên tấm giấy. Bây giờ lấy một mảnh bìa che kín đúng nửa dưới của thấu kính.","A clear image of the candle stands on the card. Now cover exactly the lower half of the lens with a piece of board."],["Hình trên giấy ra sao?","What becomes of the image?"],[["Mất nửa trên của hình","The top half of the image disappears"],["Mất nửa dưới của hình","The bottom half disappears"],["Vẫn đủ cả hình, chỉ mờ đi","The whole image remains, merely dimmer"]],2,["Chỗ bẻ luật, và hầu như ai cũng đoán sai. Mỗi điểm trên ngọn nến gửi tia tới KHẮP mặt thấu kính, không phải chỉ tới một chỗ. Nên nửa kính còn lại vẫn nhận được ánh sáng từ mọi điểm của ngọn nến và vẫn dựng lại đủ cả hình — chỉ là gom được ít tia hơn nên hình tối đi chừng một nửa. Cũng vì thế mà một vết bẩn trên kính máy ảnh không in một vệt đen vào ảnh, và một cái kính vỡ đôi vẫn chụp được ảnh trọn vẹn.","Here the rule bends, and almost everybody guesses wrong. Every point of the candle sends rays to the WHOLE face of the lens, not to one part of it. So the uncovered half still receives light from every point of the flame and still assembles the complete image — it merely gathers fewer rays, so the picture dims by about half. It is also why a smudge on a camera lens prints no dark patch on the photograph, and why a lens broken in half still takes a whole picture."]),n("kinh-can-va-kinh-vien",2,"te",["Kính của người cận là thấu kính lõm, mỏng ở giữa. Kính của người viễn là thấu kính lồi, dày ở giữa.","Glasses for short sight use concave lenses, thin in the middle. Glasses for long sight use convex lenses, thick in the middle."],["Người cận nhìn xa bị mờ vì sao?","Why does a short-sighted person see distant things blurred?"],[["Vì con mắt gom ánh sáng lại quá sớm, hình hội tụ trước võng mạc","Because the eye brings the light together too soon, in front of the retina"],["Vì con mắt không đủ sáng khi nhìn xa","Because the eye lets in too little light at distance"],["Vì vật ở xa gửi tới quá ít tia","Because a distant object sends too few rays"]],0,["Con mắt là một thấu kính, và mọi chuyện chỉ là chỗ các tia gặp nhau có rơi đúng lên võng mạc hay không. Mắt cận thì nhãn cầu hơi dài hoặc thấu kính hơi khoẻ, nên tia gặp nhau trước võng mạc rồi loe ra lại — thành mờ. Kính lõm làm các tia loe ra một chút trước khi vào mắt, đẩy chỗ gặp lùi lại đúng vào võng mạc. Mắt viễn thì ngược lại, nên phải kính lồi. Không cái kính nào chữa mắt cả; chúng chỉ dời chỗ gặp về đúng chỗ.","The eye is a lens, and the whole matter is whether the rays meet exactly on the retina. In short sight the eyeball is slightly long or the lens slightly strong, so they meet in front of the retina and spread again — hence the blur. A concave lens spreads the rays a little before they enter, pushing the meeting point back onto the retina. Long sight is the reverse and needs a convex one. Neither cures an eye; they only move the meeting point to where it belongs."]),n("giot-nuoc-lam-kinh-lup",2,"tp",["Nhỏ một giọt nước lên mặt kính đồng hồ hay lên một tờ nhựa trong. Nhìn qua giọt nước ấy thì chữ bên dưới to lên.","Put a drop of water on a watch face or a sheet of clear plastic. Look through it and the print beneath appears enlarged."],["Vì sao giọt nước phóng to được?","Why does a water drop magnify?"],[["Vì nước làm chữ nở ra","Because water swells the print"],["Vì giọt nước cong lên hai mặt, đúng hình một thấu kính lồi","Because the drop bulges on both sides, in the shape of a convex lens"],["Vì nhìn qua nước thì mắt phải mở to hơn","Because looking through water forces the eye wider open"]],1,["Thấu kính không cần là thuỷ tinh. Cái quyết định chỉ là hình dạng và việc ánh sáng đi chậm lại khi vào một chất đặc hơn không khí — nước thoả cả hai. Sức căng mặt ngoài kéo giọt nước thành một khối phồng hai mặt, đúng hình thấu kính lồi, nên nó phóng to. Giọt càng nhỏ càng phồng và càng phóng to mạnh, và những chiếc kính hiển vi đầu tiên trong lịch sử thực chất chỉ là một hạt thuỷ tinh tròn rất bé.","A lens need not be glass. All that matters is the shape and the fact that light slows on entering something denser than air — water satisfies both. Surface tension pulls the drop into a bulge curved on both faces, exactly the form of a convex lens, so it magnifies. The smaller the drop the rounder it is and the more it magnifies, and the earliest microscopes in history were essentially one very small round bead of glass."])]),t("mat-nhin",["Mắt Nhìn","The Eye"],["Mắt không phóng ra gì cả — nó chỉ hứng thứ vật khác gửi tới","The eye sends nothing out — it only catches what other things send in"],[n("diem-mu-trong-mat",1,"tp",["Trong mỗi mắt có một chỗ trên võng mạc hoàn toàn không có tế bào cảm sáng: chỗ dây thần kinh chui ra. Ở đó mắt không thấy gì cả.","In each eye there is a patch of retina with no light-sensing cells at all: the place where the nerve leaves. There the eye sees nothing."],["Vì sao ta không thấy một lỗ đen trong tầm nhìn?","Why do we not notice a black hole in our vision?"],[["Vì cái lỗ ấy quá nhỏ để nhìn ra","Because the gap is too small to notice"],["Vì bộ não lấp chỗ ấy bằng những gì xung quanh","Because the brain fills it in with whatever surrounds it"],["Vì mắt kia nhìn thấy nên không cần mắt này","Because the other eye sees it, so this one need not"]],1,['Cái lỗ ấy không nhỏ chút nào — nó to cỡ bằng mấy cái mặt trăng đặt cạnh nhau trên bầu trời. Nhắm một mắt lại thì mắt kia vẫn không thấy lỗ nào, nên câu trả lời không nằm ở việc có hai mắt. Bộ não đơn giản là bịa nốt phần thiếu bằng màu và hoa văn của vùng xung quanh, và bịa khéo tới mức không ai ngờ. Đây là điều đáng nhớ nhất về thị giác: thứ mình "thấy" không phải ảnh chụp, nó là một bản dựng lại.',"The gap is not small at all — on the sky it would cover several moons side by side. Close one eye and the other still shows no hole, so having two eyes is not the answer. The brain simply invents the missing part from the colour and texture around it, and invents so smoothly that nobody suspects. This is the most worth-remembering fact about seeing: what you see is not a photograph, it is a reconstruction."]),n("dem-toi-khong-thay-mau",2,"tp",["Ngoài trời đêm không trăng, mọi thứ vẫn nhìn ra hình dạng nhưng gần như không còn màu. Ban ngày thì màu rực rỡ.","Outdoors on a moonless night, shapes remain visible but colour is nearly gone. By day the same scene is full of colour."],["Vì sao đêm mất màu?","Why does night drain the colour?"],[["Vì ban đêm ánh sáng không có màu","Because night light has no colour in it"],["Vì loại tế bào nhận màu cần nhiều sáng, còn loại nhận sáng yếu thì không phân biệt màu","Because the colour cells need bright light, and the dim-light cells cannot tell colours apart"],["Vì mắt mở to ra thì không nhận được màu","Because a wide-open pupil cannot register colour"]],1,["Võng mạc có hai loại tế bào. Loại nón nhận màu nhưng cần nhiều sáng mới hoạt động. Loại que nhạy hơn nhiều, làm việc được trong tối, nhưng nó chỉ đo mức sáng chứ không phân biệt bước sóng — nên trong tối ta nhìn bằng loại que và thế giới thành xám. Cũng vì que tập trung ở rìa võng mạc chứ không ở giữa, mà ban đêm nhìn chếch sang một bên lại thấy một ngôi sao mờ rõ hơn nhìn thẳng vào nó.","The retina has two kinds of cell. Cones register colour but need decent light to work. Rods are far more sensitive and work in the dark, but they only measure brightness and cannot distinguish wavelengths — so at night we see with rods and the world turns grey. And because rods cluster at the edge of the retina rather than the centre, a faint star at night shows up better when you look slightly to one side of it."]),n("hai-mat-do-xa",2,"te",["Che một mắt lại rồi thử rót nước vào cốc hoặc xỏ chỉ qua lỗ kim. Việc ấy khó hơn hẳn lúc mở cả hai mắt.","Cover one eye and try pouring water into a glass or threading a needle. It is markedly harder than with both eyes open."],["Hai mắt cho thêm cái gì?","What does the second eye add?"],[["Gấp đôi lượng ánh sáng nên nhìn rõ hơn","Twice the light, so a sharper view"],["Hai góc nhìn hơi lệch nhau, từ đó não tính ra khoảng cách","Two slightly different viewpoints, from which the brain works out distance"],["Một mắt nhìn màu, một mắt nhìn hình","One eye for colour, the other for shape"]],1,["Hai mắt cách nhau chừng sáu centimét, nên chúng thấy hai hình hơi khác nhau, và vật càng gần thì khác càng nhiều. Bộ não so hai hình ấy rồi suy ra khoảng cách. Đó là lý do các con thú đi săn có hai mắt nằm phía trước mặt — chúng cần đo đúng khoảng cách tới con mồi — còn các con thú bị săn thì mắt nằm hai bên đầu, đổi khả năng đo xa lấy tầm nhìn gần như trọn vòng.","The eyes sit about six centimetres apart, so they see slightly different pictures, and the nearer the object the greater the difference. The brain compares them and deduces distance. It is why hunting animals have both eyes at the front of the head — they must judge the range to their prey — while hunted animals have eyes on the sides, trading depth for a field of view that is nearly a full circle."]),n("nhin-lau-thi-quen-mui",3,"tp",["Vào một căn phòng tối, lúc đầu không thấy gì. Sau mười lăm phút thì nhìn ra khá rõ. Bật đèn lên một giây rồi tắt đi, lại phải chờ từ đầu.","Enter a dark room and at first you see nothing. After fifteen minutes you see fairly well. Switch a light on for one second and off again, and the wait starts over."],["Chuyện gì đã xảy ra trong mắt?","What has happened inside the eye?"],[["Con ngươi mở dần ra rồi bị đèn làm khép lại","The pupil slowly opened and the light closed it again"],["Một chất nhạy sáng tích dần lên trong tế bào, và một giây sáng đã đốt sạch nó","A light-sensitive substance built up in the cells, and one second of light destroyed it"],["Não quen dần với bóng tối rồi lại phải quen lại","The brain got used to the dark and must get used to it again"]],1,["Chỗ bẻ luật: con ngươi có mở ra thật, nhưng nó mở xong trong vài giây chứ không mất mười lăm phút, và nó cũng chỉ thay đổi được vài lần chứ không phải hàng nghìn lần. Cái thật sự diễn ra là các tế bào que tích dần một chất nhạy sáng, và chất ấy bị phân huỷ ngay khi gặp ánh sáng mạnh. Vì thế thuỷ thủ trực đêm và người soi ảnh trong buồng tối dùng đèn đỏ: loại que gần như không nhạy với ánh đỏ, nên nhìn được mà không mất công chờ lại từ đầu.","Here the rule bends: the pupil does open, but it finishes in seconds rather than fifteen minutes, and it can only change the light entering by a few times, not thousands. What really happens is that the rod cells build up a light-sensitive substance, and that substance is destroyed the moment bright light arrives. Which is why night watchkeepers and darkroom workers use red lamps: rods are nearly blind to red, so one can see without spending the adaptation all over again."]),n("mat-phong-ra-hay-hung-vao",1,"tp",["Trong một căn phòng kín hoàn toàn không có một tia sáng nào lọt vào, một người mắt rất tinh ngồi chờ hàng giờ.","In a room sealed against every trace of light, a person with excellent eyesight sits and waits for hours."],["Người ấy nhìn thấy gì?","What does that person see?"],[["Sau một lúc thì nhìn ra được đồ đạc trong phòng","After a while, the furniture in the room"],["Không gì cả, dù chờ bao lâu","Nothing at all, however long the wait"],["Thấy mờ mờ, vì mắt tự phát ra chút sáng","A faint outline, because the eye gives off a little light"]],1,["Không có ánh sáng thì không có gì để nhìn, và chờ bao lâu cũng thế. Điều này nghe hiển nhiên nhưng lại đánh trúng một hiểu lầm rất cũ và rất dai: nhiều người vẫn ngầm nghĩ mắt phóng ra một cái gì đó rồi chạm vào vật — đó đúng là điều người Hy Lạp cổ tin. Mắt chỉ là một cái hứng. Con mèo nhìn được trong tối không phải vì mắt nó phát sáng, mà vì nó cần ít ánh sáng hơn ta rất nhiều, và trong bóng tối tuyệt đối thì con mèo cũng chịu.","With no light there is nothing to see, and no amount of waiting changes it. This sounds obvious yet it strikes at a very old and very persistent error: many people half-assume the eye sends something out that touches the object — which is precisely what the ancient Greeks believed. The eye is only a catcher. A cat sees in the dark not because its eyes emit anything, but because it needs far less light than we do, and in true darkness a cat is as blind as anyone."])]),t("anh-va-that",["Ảnh & Thật","Image and Object"],["Chỗ mình tưởng vật đang nằm và chỗ nó thật sự nằm là hai chuyện khác nhau","Where a thing seems to be and where it is are two different questions"],[n("guong-doi-trai-phai",3,"tp",["Đứng trước gương giơ tay phải lên. Người trong gương giơ tay bên trái. Nhưng đầu vẫn ở trên và chân vẫn ở dưới, không hề đảo.","Stand before a mirror and raise your right hand. The figure in the glass raises its left. Yet the head is still up and the feet still down."],["Gương thật ra đảo chiều nào?","Which direction does a mirror actually reverse?"],[["Đảo trái với phải","Left and right"],["Đảo trước với sau, tức là chiều đâm vào gương","Front and back — the direction into the glass"],["Không đảo gì cả, chỉ là ảo giác","Nothing at all; it is an illusion"]],1,['Chỗ bẻ luật, và câu này làm người lớn cãi nhau cả buổi. Gương chỉ đảo đúng một chiều: chiều vuông góc với mặt gương. Mũi bạn chìa về phía gương, còn mũi cái ảnh thì chìa ngược về phía bạn. Cảm giác "đảo trái phải" là do chính mình: để so mình với cái ảnh, mình tưởng tượng xoay người mình nửa vòng — và cái xoay ấy mới là thứ tráo trái phải, chứ không phải tấm gương. Bằng chứng: nằm nghiêng người ra mà soi thì cái ảnh lập tức thành đảo trên dưới.',"Here the rule bends, and this question can keep a room of adults arguing. A mirror reverses exactly one direction: the one perpendicular to its surface. Your nose points towards the glass; your image’s nose points back at you. The feeling that left and right have swapped comes from you: to compare yourself with the image you imagine turning yourself around — and it is that turn, not the mirror, that exchanges left and right. The proof: lie down sideways in front of it and the image promptly seems to swap top and bottom instead."]),n("anh-nam-o-dau-sau-guong",2,"tp",["Bạn đứng cách một tấm gương phẳng đúng một mét. Bạn nhìn thấy ảnh của mình trong đó.","You stand exactly one metre from a flat mirror and see your own reflection in it."],["Cái ảnh ấy trông như đang ở cách bạn bao xa?","How far away does that image appear to be?"],[["Một mét, tức là ngay tại mặt gương","One metre — that is, at the surface of the glass"],["Hai mét, vì nó nằm sau gương thêm một mét nữa","Two metres, because it stands a further metre behind the glass"],["Nửa mét, vì ánh sáng đi tắt qua gương","Half a metre, the light taking a short cut"]],1,["Ánh sáng từ mặt bạn đi một mét tới gương rồi một mét quay lại, tổng là hai mét đường đi. Mắt thì cứ vẽ ngược tia sáng thành đường thẳng, nên nó kết luận cái ảnh đứng sau mặt gương đúng một mét nữa. Đây là lý do người cận phải đeo kính mới soi gương rõ dù đứng sát gương, và cũng là lý do một phòng nhỏ gắn gương lại trông sâu gấp đôi: cái gương không mở rộng căn phòng, nó chỉ đưa mắt đi thêm một quãng đường bằng đúng quãng đã đi.","Light travels a metre from your face to the glass and a metre back, two metres of path in all. The eye traces the rays back as straight lines and so places the image a full metre behind the surface. It is why a short-sighted person needs glasses to see their reflection sharply even standing close, and why a small room with a mirror looks twice as deep: the mirror enlarges nothing, it merely sends the eye a further journey equal to the one already made."]),n("cai-que-gay-trong-nuoc",2,"tp",["Cắm một cái que thẳng chếch vào chậu nước. Nhìn từ trên xuống, cái que trông như bị gãy gập ngay tại mặt nước.","Stand a straight stick at an angle in a basin of water. Seen from above, it appears to bend sharply at the surface."],["Vì sao trông như gãy?","Why does it look broken?"],[["Vì nước làm cái que cong thật","Because the water genuinely bends the stick"],["Vì ánh sáng đổi hướng khi ra khỏi nước, nên phần chìm trông như ở chỗ khác","Because light changes direction leaving the water, so the submerged part seems elsewhere"],["Vì mặt nước gợn sóng nên nhìn méo đi","Because ripples on the surface distort the view"]],1,["Ánh sáng đi trong nước chậm hơn trong không khí, nên khi ra khỏi mặt nước chếch góc thì nó bị bẻ hướng. Mắt thì không biết chuyện ấy: nó cứ vẽ ngược tia sáng thành một đường thẳng và kết luận cái que nằm ở chỗ khác chỗ thật. Vì thế đáy ao bao giờ cũng trông nông hơn thật — một hiểu lầm đã làm chết đuối không ít người — và vì thế người đi đâm cá phải nhắm thấp hơn chỗ mình nhìn thấy con cá.","Light travels more slowly in water than in air, so leaving the surface at a slant it is bent. The eye knows nothing of this: it traces the ray back as a straight line and concludes the stick is somewhere it is not. Which is why a pond always looks shallower than it is — a misjudgement that has drowned people — and why anyone spearing fish must aim below where the fish appears to be."]),n("bong-hai-cai-den",1,"tp",["Một người đứng giữa phòng có hai bóng đèn ở hai góc trần khác nhau. Trên sàn có hai cái bóng của người ấy.","A person stands in a room with two lamps in different corners of the ceiling. Two shadows of them lie on the floor."],["Ở chỗ hai cái bóng chồng lên nhau thì thế nào?","Where the two shadows overlap, what happens?"],[["Tối hơn hẳn hai chỗ bóng đơn","It is markedly darker than either shadow alone"],["Sáng lên vì hai bóng triệt tiêu nhau","It brightens, the two shadows cancelling"],["Đúng bằng độ tối của một cái bóng","It is exactly as dark as a single shadow"]],0,["Bóng không phải một thứ được phóng ra; nó là chỗ thiếu ánh sáng. Chỗ chỉ bị chắn mất một đèn thì vẫn còn đèn kia rọi tới, nên nó chỉ tối vừa. Chỗ bị chắn cả hai thì không còn nguồn nào tới được, và nó tối hẳn. Nên đếm số vùng tối trên sàn là biết trong phòng có mấy nguồn sáng — và cũng chính vì thế mà một cái đèn duy nhất cho bóng sắc lẻm, còn cả một trần đèn thì cho bóng mờ nhoè gần như không thấy.","A shadow is not something cast out; it is a place where light is missing. Where only one lamp is blocked, the other still reaches, so it is only moderately dark. Where both are blocked, no source arrives at all and it is fully dark. Counting the depths of shadow on a floor tells you how many sources the room has — and it is why a single lamp gives razor-edged shadows while a ceiling full of them gives shadows so soft as to be barely visible."]),n("cau-vong-nam-o-dau",2,"tp",["Hai người đứng cách nhau vài chục mét cùng nhìn một cái cầu vồng. Mỗi người chỉ tay về một chỗ hơi khác nhau trên bầu trời.","Two people standing tens of metres apart look at one rainbow. Each points to a slightly different place in the sky."],["Cầu vồng thật sự nằm ở đâu?","Where is the rainbow really?"],[["Ở một chỗ nhất định trên trời, chỉ là hai người nhìn lệch","At one fixed place in the sky; the two are simply misjudging"],["Không nằm ở đâu cả — mỗi người thấy một cầu vồng riêng của mình","Nowhere at all — each person sees a rainbow of their own"],["Ở ngay trên đám mây gần nhất","Just above the nearest cloud"]],1,["Cầu vồng không phải một vật treo trên trời. Nó là tập hợp các hướng mà từ đó ánh sáng mặt trời, sau khi bị bẻ và phản trong hàng triệu giọt mưa, đúng lúc đi vào mắt của một người cụ thể. Đổi chỗ đứng thì tập hợp giọt mưa ấy đổi hẳn — nên hai người bên cạnh nhau đang nhìn hai cầu vồng khác nhau, dựng bằng hai đám giọt khác nhau. Cũng vì thế không ai tới được chân cầu vồng: nó lùi đúng bằng bước chân mình.","A rainbow is not an object hanging in the sky. It is the set of directions from which sunlight, after bending and reflecting inside millions of raindrops, happens to arrive at one particular pair of eyes. Move and that set of drops changes entirely — so two people side by side are looking at two different rainbows built from two different populations of drops. It is also why nobody reaches the end of one: it retreats exactly as fast as you walk."])])],B=[t("dau-danh-lua",["Cái Đầu Đánh Lừa Mình","Where a Head Fools Itself"],["Mấy chỗ mà cái đầu nào cũng trượt như nhau — kể cả đầu người lớn","The places every head slips the same way — grown-up heads included"],[n("con-khi-dot",1,"gv",["Người xem được giao đúng một việc: đếm số lần nhóm áo trắng chuyền bóng cho nhau. Giữa đoạn phim, một người mặc bộ đồ khỉ đột đi thẳng vào giữa sân, đấm ngực, rồi đi ra. Xem xong mới hỏi có thấy gì lạ không.","Viewers get one job: count the passes made by the team in white. Halfway through, a person in a gorilla suit walks into the middle of the court, thumps their chest, and walks off. Only afterwards are they asked whether they saw anything odd."],["Bao nhiêu người xem không hề thấy con khỉ đột?","How many viewers never saw the gorilla at all?"],[["Gần như ai cũng thấy — nó to và ở ngay giữa","Nearly everyone sees it — it is large and dead centre"],["Chừng một nửa số người xem không thấy gì cả","About half of all viewers see nothing at all"],["Chỉ vài người lơ đãng là bỏ sót","Only a few daydreamers miss it"]],1,["Chừng một nửa. Không phải vì họ nhìn chỗ khác — máy đo mắt cho thấy nhiều người nhìn thẳng vào con khỉ đột mà vẫn không thấy nó. Chú ý không phải cái đèn pin rọi tới đâu thấy tới đó; nó là một cái cửa hẹp, và cái gì không nằm trong việc đang làm thì bị chặn lại ngay từ cửa. Đây là lý do một người vừa lái xe vừa nhắn tin có thể nhìn thẳng vào người sang đường mà không thấy. Và nó cũng nói một điều dễ chịu hơn: lúc mình bỏ sót một thứ rành rành, đó không phải bằng chứng mình kém — đó là cách cái cửa ấy được làm ra.","About half. Not because they looked elsewhere — eye-trackers show many of them looking straight at the gorilla and still not seeing it. Attention is not a torch that reveals whatever it points at; it is a narrow gate, and whatever is not part of the current job is stopped at that gate. This is why somebody texting while driving can look directly at a person crossing and not see them. It also says something kinder: missing something obvious is not evidence that you are dim — it is how the gate was built."]),n("nho-la-ke-lai",1,"tl",["Một đứa kể lại buổi đi chơi hồi năm ngoái, kể rất chắc chắn, chi tiết rõ ràng. Đem so với ảnh chụp hôm ấy thì vài chi tiết không khớp: sai màu áo, sai người có mặt, sai cả thứ tự.","A child recounts last year’s outing, confident and full of detail. Set against the photographs from the day, several details do not match: the wrong shirt colour, the wrong people present, even the wrong order of events."],["Chuyện gì đã xảy ra với trí nhớ ấy?","What has happened to that memory?"],[["Đứa bé đang bịa cho câu chuyện hay hơn","The child is embroidering to make a better story"],["Trí nhớ được dựng lại mỗi lần nhớ, nên mỗi lần lại đổi một ít","The memory is rebuilt each time it is recalled, and shifts a little each time"],["Cuốn băng trong đầu đã bị mờ đi vài chỗ","The tape in the head has faded in patches"]],1,["Trí nhớ không phải cuốn băng nằm yên chờ mở lại. Mỗi lần nhớ tới, cái đầu dựng lại cảnh ấy từ mấy mảnh còn giữ được, và những chỗ thiếu thì nó lấp bằng thứ hợp lý — rồi cất cái bản vừa dựng ấy đi thay cho bản cũ. Nên kể càng nhiều lần, câu chuyện càng gọn gàng và càng xa sự thật, mà người kể lại càng thấy chắc chắn hơn. Điều này có hậu quả rất thật: lời khai của nhân chứng thành thật vẫn sai được, và hai anh em cãi nhau về một buổi chiều có thể cả hai đều đang nhớ thật lòng.","A memory is not a tape lying still, waiting to be replayed. Each recall rebuilds the scene from the fragments that survive, filling the gaps with whatever is plausible — and then files the freshly built version in place of the old one. So the more often a story is told, the tidier it becomes and the further from the day itself, while the teller grows more certain. The consequences are real: an honest witness can be wrong, and two siblings arguing about one afternoon may both be remembering sincerely."]),n("doi-duoc-cai-keo",2,"tl",["Một đứa trẻ ngồi trước một cái kẹo. Luật: ăn ngay thì được một cái, chờ được mười lăm phút thì được hai. Người lớn đi ra, còn lại đứa bé với cái kẹo trên bàn.","A child sits in front of one sweet. The rule: eat it now and you get one, wait fifteen minutes and you get two. The grown-up leaves, and the child is alone with the sweet on the table."],["Đứa chờ được lâu nhất đã làm gì?","What did the children who waited longest actually do?"],[["Nhìn cái kẹo và tự nhủ phải cố gắng","Stared at the sweet and told themselves to be strong"],["Quay đi, che mắt, hát, nghĩ sang chuyện khác","Turned away, covered their eyes, sang, thought about something else"],["Nghĩ tới hai cái kẹo sẽ được để có động lực","Pictured the two sweets to keep their motivation up"]],1,["Đứa nào ngồi nhìn chằm chằm vào cái kẹo và gồng lên đều thua sớm. Đứa chờ được thì làm một việc khác hẳn: nó đổi cảnh đi — quay lưng lại, lấy tay che, hát nghêu ngao, tưởng cái kẹo là hòn sỏi. Nghĩa là chúng không thắng bằng ý chí, chúng thắng bằng cách sắp lại chỗ ngồi. Đây là cùng một bài học với cái điện thoại để trong phòng bên: ý chí là thứ hết dần trong vài phút, còn khoảng cách thì không mệt bao giờ. Ai muốn bỏ một thói quen thì việc đầu tiên nên làm là dọn cái kẹo đi, chứ không phải hứa với mình lần nữa.","Every child who sat staring at the sweet and gritting their teeth lost early. The ones who waited did something quite different: they changed the scene — turned their backs, covered their eyes, sang to themselves, pretended the sweet was a pebble. They did not win by willpower; they won by rearranging the room. It is the same lesson as the phone in the next room: willpower drains within minutes, while distance never tires. Anyone trying to drop a habit should start by moving the sweet, not by promising themselves once more."]),n("neo-mot-con-so",2,"tl",['Hai nhóm được hỏi cùng một câu: sông Nin dài bao nhiêu ki-lô-mét. Nhóm một được hỏi trước "có hơn hai nghìn không". Nhóm hai được hỏi trước "có hơn mười nghìn không". Rồi cả hai cùng đoán một con số.',"Two groups are asked the same question: how long is the Nile. The first is asked beforehand whether it is more than two thousand kilometres. The second, whether it is more than ten thousand. Then both groups give a number."],["Hai nhóm đoán ra sao?","How do the two groups answer?"],[["Nhóm nghe số nhỏ đoán thấp hơn hẳn nhóm kia","The group given the small number guesses markedly lower"],["Hai nhóm đoán như nhau, vì câu hỏi trước không liên quan","Both guess alike — the earlier question was irrelevant"],["Nhóm nghe số lớn đoán thấp hơn, vì họ thấy nó vô lý","The group given the big number guesses lower, finding it absurd"]],0,["Nhóm nghe con số nhỏ đoán thấp hơn hẳn, và chênh lệch thì rất lớn. Con số nghe được trước đó neo cái đầu lại: mọi ước lượng sau đều bò ra từ nó, kể cả khi ai cũng biết nó chỉ là một câu hỏi vu vơ. Người bán hàng dùng đúng cái neo ấy khi in giá gạch đi bên cạnh giá bán, và người mặc cả ngoài chợ dùng nó khi hô giá đầu tiên thật cao. Cách chống lại không phải là cố quên con số kia đi — quên không được — mà là tự đưa ra con số của mình TRƯỚC khi nghe của người ta.","The group given the small number guesses far lower, and the gap is large. The number heard first anchors the head: every later estimate crawls out from it, even when everyone knows the earlier question was idle. Sellers use exactly this anchor when they print a struck-through price beside the real one, and hagglers use it when they open absurdly high. The defence is not trying to forget the number — that does not work — but writing down your own figure before hearing theirs."]),n("biet-roi-van-dinh",3,"tl",["Người xem được cho biết trước hẳn hoi: hai đường thẳng dưới đây dài bằng nhau, chỉ khác cái mũi tên ở hai đầu. Rồi bảo họ nhìn lại và nói xem có thấy bằng nhau không.","Viewers are told plainly in advance: the two lines below are the same length, only the arrowheads differ. Then they are asked to look again and say whether the lines now look equal."],["Biết trước như thế thì có hết bị lừa không?","Does knowing beforehand cure the illusion?"],[["Có — biết rồi thì nhìn ra ngay là bằng nhau","Yes — once you know, they plainly look equal"],["Không — mắt vẫn thấy lệch, chỉ có phần biết nghĩ là biết đừng tin mắt","No — the eyes still see them unequal; only the thinking part knows not to trust them"],["Có, nếu nhìn đủ lâu thì ảo giác tan dần","Yes, if you look long enough the illusion fades"]],1,["Đây là chỗ bẻ luật của cả bộ. Mắt vẫn thấy hai đường lệch nhau, y hệt như trước, dù trong đầu đã biết chắc chúng bằng nhau — cái phần nhìn không nghe lời cái phần biết. Điều ấy nói một chuyện lớn hơn hẳn hai cái mũi tên: hiểu một cái bẫy KHÔNG làm cái bẫy biến mất. Biết về neo giá vẫn bị neo, biết về ấn tượng đầu vẫn bị ấn tượng đầu dắt đi. Nên thứ thật sự bảo vệ mình không phải là biết, mà là thói quen: viết con số của mình ra trước, đo lại bằng thước, hỏi người sẽ cãi mình. Cái đầu không tự sửa được mình từ bên trong — nó cần một cái thước đặt bên ngoài.","This is where the set breaks its own rule. The eyes go on seeing the lines as unequal, exactly as before, while the head knows with certainty that they match — the seeing part does not take orders from the knowing part. That says something far larger than two arrowheads: understanding a trap does not remove the trap. People who know about anchoring are still anchored; people who know about first impressions are still led by them. So what actually protects you is not knowledge but habit: write your own figure first, measure with a ruler, ask the person likely to disagree. A head cannot correct itself from the inside — it needs a measure placed outside it."])]),t("giua-nguoi-ta",["Giữa Người Ta","Among Other People"],["Chuyện gì xảy ra với một người khi có người khác đứng cạnh","What happens to one person once other people are standing nearby"],[n("bay-nguoi-noi-sai",1,"tl",["Tám người ngồi một hàng, lần lượt nói xem đường nào trong ba đường dài bằng đường mẫu. Câu trả lời rành rành. Bảy người đầu là người của thí nghiệm, cả bảy cùng nói to một đáp án sai. Người thứ tám là người thật.","Eight people sit in a row and say in turn which of three lines matches a sample. The answer is obvious. The first seven are in on the experiment, and all seven state the same wrong answer aloud. The eighth is the real subject."],["Người thật làm gì?","What does the real person do?"],[["Phần lớn nói theo cái sai ít nhất một lần","Most go along with the wrong answer at least once"],["Gần như ai cũng giữ đáp án đúng của mình","Almost all hold to their own correct answer"],["Phần lớn hỏi lại cho rõ rồi mới trả lời","Most ask for clarification before answering"]],0,["Khoảng ba phần tư người thật nói theo cái sai ít nhất một lần, và nhiều người sau đó kể rằng lúc ấy họ thật sự bắt đầu nghi ngờ chính mắt mình. Đứng một mình chống lại cả nhóm là việc khó tới mức đo được, và nó khó không phải vì người ta hèn — nó khó vì cái đầu coi việc bị cả nhóm bỏ lại là một mối nguy thật. Nhưng thí nghiệm ấy còn một nửa ít ai kể: chỉ cần MỘT người trong bảy người kia nói đúng, tỷ lệ nói theo cái sai tụt xuống gần hết. Một người dám nói khác không chỉ cứu mình, nó mở cửa cho tất cả những người đang im.","About three quarters of real subjects went along with the wrong answer at least once, and many said afterwards that they had genuinely begun to doubt their own eyes. Standing alone against a group is hard by measurement, and hard not out of cowardice — the head treats being left behind by the group as a real danger. But the experiment has a second half that is rarely retold: if just one of the seven gives the right answer, going along collapses almost to nothing. One person willing to differ does not only save themselves; it opens the door for everyone still silent."]),n("ai-cung-nhin-minh",1,"gv",["Một học sinh phải mặc cái áo mình thấy ngượng nhất rồi đi vào một lớp đông người. Trước khi vào, em ấy đoán xem bao nhiêu bạn trong phòng sẽ để ý tới cái áo. Sau đó người ta hỏi từng bạn trong phòng.","A student must wear the shirt they find most embarrassing and walk into a crowded classroom. Before going in, they estimate how many people in the room will notice the shirt. Afterwards, everyone in the room is asked."],["Con số đoán so với con số thật thế nào?","How does the estimate compare with the truth?"],[["Đoán cao hơn thật rất nhiều","The estimate is far higher than the truth"],["Đoán gần đúng — người ta để ý nhiều thật","The estimate is about right — people do notice"],["Đoán thấp hơn thật, vì ai cũng nhìn nhau","The estimate is too low, since everyone looks at everyone"]],0,["Người mặc đoán khoảng một nửa số người sẽ để ý. Thật ra chỉ chừng một phần tư, và nhiều lần còn ít hơn. Lý do rất đơn giản: mình là người duy nhất theo dõi mình cả ngày, nên mình tưởng người khác cũng đang theo dõi mình như thế — trong khi mỗi người trong phòng đang bận lo cái áo của chính họ. Biết con số ấy giúp được một việc rất cụ thể: cái giá thật của việc giơ tay hỏi một câu ngốc nghếch, hay của việc mặc sai áo, gần như luôn nhỏ hơn cái giá mình đang tưởng tượng.","The wearer expects around half the room to notice. In truth it is nearer a quarter, and often less. The reason is plain: you are the only person watching you all day, so you assume everyone else is watching just as closely — while each of them is busy worrying about their own shirt. Knowing the number buys something concrete: the real cost of putting your hand up with a silly question, or of wearing the wrong thing, is almost always smaller than the cost you are imagining."]),n("cang-dong-cang-it-giup",2,"gv",["Một người ngã ngoài phố. Cảnh một: chỉ có đúng một người đi qua nhìn thấy. Cảnh hai: có ba mươi người xung quanh cùng nhìn thấy.","Somebody collapses in the street. Scene one: exactly one passer-by sees it. Scene two: thirty people around them see it."],["Cảnh nào người ngã được giúp nhanh hơn?","In which scene does help arrive sooner?"],[["Cảnh hai — đông người thì nhiều người giúp hơn","Scene two — more people, more helpers"],["Cảnh một — một người thì hầu như luôn ra tay","Scene one — a lone witness almost always acts"],["Hai cảnh như nhau, vì ai tử tế thì vẫn tử tế","The same in both — kind people are kind either way"]],1,['Người đi một mình giúp gần như chắc chắn, còn trong đám ba mươi người thì việc giúp tới chậm hơn nhiều và có khi không tới. Không phải vì đám đông vô tâm: mỗi người đều thấy hai mươi chín người khác đang đứng yên, nên hiểu rằng chắc chuyện không nghiêm trọng, hoặc chắc đã có ai gọi rồi. Trách nhiệm bị chia nhỏ tới mức không ai còn cầm phần nào. Chỗ này có một cách chữa đơn giản mà dạy được cho trẻ con: đừng hét vào đám đông, hãy chỉ vào một người và gọi rõ — "anh áo xanh ơi, gọi cấp cứu giúp em". Việc có chủ thì việc được làm.','A lone witness helps almost every time, while in a crowd of thirty help comes far more slowly and sometimes not at all. It is not that crowds are heartless: each person sees twenty-nine others standing still and reads it as evidence that this is not serious, or that somebody has already called. Responsibility is divided until nobody is holding any of it. There is a simple repair, and it can be taught to a child: do not shout at the crowd, point at one person and name them — "you in the blue jacket, please ring for an ambulance". A job with an owner is a job that gets done.']),n("khen-vao-dau",2,"dw",['Hai nhóm trẻ cùng giải xong một bộ câu đố dễ. Nhóm một được khen "con thông minh quá". Nhóm hai được khen "con làm chăm thật đấy". Sau đó cho cả hai chọn: làm tiếp bộ dễ, hay thử một bộ khó hơn.','Two groups of children finish the same easy set of puzzles. The first is told "you must be clever". The second is told "you must have worked hard". Both are then offered a choice: another easy set, or a harder one.'],["Hai nhóm chọn thế nào?","How do the two groups choose?"],[["Nhóm được khen thông minh chọn bộ dễ nhiều hơn hẳn","The clever-praised group takes the easy set far more often"],["Hai nhóm chọn như nhau — một lời khen thì thay đổi được gì","Both choose alike — one sentence changes nothing"],["Nhóm được khen thông minh chọn bộ khó, vì tự tin hơn","The clever-praised group takes the harder set, being more confident"]],0,["Nhóm được khen thông minh né bài khó, còn nhóm được khen chăm chỉ phần lớn chọn bài khó — chỉ sau đúng một câu nói. Lý do nằm ở chỗ lời khen dán vào đâu. Khen vào một thứ có sẵn thì đứa trẻ hiểu rằng giá trị của nó nằm ở cái nhãn ấy, nên bài khó thành ra một mối đe doạ: làm không xong là mất nhãn. Khen vào việc đã làm thì bài khó chỉ là chỗ để làm tiếp. Người lớn nào cũng khen với ý tốt, nên chỗ này đáng nhớ: câu khen an toàn nhất là câu tả đúng việc đứa bé vừa làm, chứ không phải câu phong cho nó một danh hiệu.","The clever-praised group avoided the hard set; most of the effort-praised group chose it — after a single sentence. The reason is where the praise sticks. Praise aimed at something fixed teaches the child that their worth lives in that label, which turns a hard task into a threat: fail and the label goes. Praise aimed at what was done leaves the hard task as simply more work to do. Every grown-up praises with good intentions, so this is worth keeping: the safest praise describes what the child actually did, rather than awarding a title."]),n("co-nguoi-nhin-thi-lam-tot-hon",3,"tl",["Cùng một người, cùng một việc, chỉ khác chỗ có ai đứng xem hay không. Việc thứ nhất: đạp xe, thứ đã làm nghìn lần. Việc thứ hai: một bài toán mới, chưa từng gặp dạng.","One person, one task, differing only in whether anybody is watching. Task one: riding a bicycle, done a thousand times. Task two: a new kind of problem, never met before."],["Có người đứng xem thì hai việc ấy ra sao?","With somebody watching, what happens to the two tasks?"],[["Cả hai đều tốt lên — bị nhìn thì ai cũng cố hơn","Both improve — being watched makes anyone try harder"],["Việc quen thì tốt lên, việc mới thì kém đi","The familiar task improves; the new one gets worse"],["Cả hai đều kém đi vì mất tập trung","Both get worse, from the distraction"]],1,['Đây là chỗ bẻ luật. Câu "có người xem thì cố hơn" đúng một nửa và sai một nửa, và ranh giới không nằm ở người xem mà nằm ở việc đang làm. Có người nhìn thì người ta căng lên, mà căng lên chỉ giúp được những việc đã thành phản xạ — đạp xe, chạy, đọc bảng cửu chương. Với việc còn mới, việc phải dò từng bước, cái căng ấy chiếm mất đúng chỗ trong đầu mà việc dò đang cần, nên kết quả tệ đi. Từ đó ra hai lời khuyên trái ngược nhau mà đều đúng: tập bài mới thì tập một mình, còn tới lúc trình diễn thứ đã thuộc thì đông người lại là có lợi.','Here the rule bends. "People try harder when watched" is half true and half false, and the dividing line is not the audience but the task. Being watched raises arousal, and raised arousal helps only what has already become reflex — cycling, running, reciting times tables. For anything still new, anything worked out step by step, that same arousal occupies precisely the space in the head the working-out needs, and performance drops. From which follow two opposite pieces of advice, both correct: practise the new thing alone, and perform the well-learned thing in front of as many people as you like.'])])],g=[...y,...p,...b,...v,...k,...w,...f,...T,...x,...q,...N,...C,...B],r=h=>g.find(e=>e.id===h),l=g.flatMap(h=>h.hoi),W=h=>g.find(e=>e.hoi.some(a=>a.id===h)),A=new Set(l.filter(h=>h.bac===3).map(h=>h.id)),S=h=>A.has(h),I=h=>r(h)?.hoi.filter(e=>e.bac===3).length??0,H=h=>r(h)?.hoi.filter(e=>e.bac===3).map(e=>e.id)??[];function L(){const h=[0,0,0];for(const e of l)h[e.bac-1]++;return h}export{l as HOI,g as HOI_BO,A as NANG_CAO,M as NGUON,t as bo,W as boCua,n as cau,L as demBac,V as demTu,r as hoiOf,S as laNangCao,H as nangCaoTrongBo,I as soNangCao};
